INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('40', 'mat', 'Matius', 1, 1, 'Inilah silsilah Yesus Kristus, anak Daud, anak Abraham.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 2, 'Abraham memperanakkan Ishak, Ishak memperanakkan Yakub, Yakub memperanakkan Yehuda dan saudara-saudaranya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 3, 'Yehuda memperanakkan Peres dan Zerah dari Tamar, Peres memperanakkan Hezron, Hezron memperanakkan Ram,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 4, 'Ram memperanakkan Aminadab, Aminadab memperanakkan Nahason, Nahason memperanakkan Salmon,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 5, 'Salmon memperanakkan Boas dari Rahab, Boas memperanakkan Obed dari Rut, Obed memperanakkan Isai,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 6, 'Isai memperanakkan raja Daud. Daud memperanakkan Salomo dari isteri Uria,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 7, 'Salomo memperanakkan Rehabeam, Rehabeam memperanakkan Abia, Abia memperanakkan Asa,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 8, 'Asa memperanakkan Yosafat, Yosafat memperanakkan Yoram, Yoram memperanakkan Uzia,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 9, 'Uzia memperanakkan Yotam, Yotam memperanakkan Ahas, Ahas memperanakkan Hizkia,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 10, 'Hizkia memperanakkan Manasye, Manasye memperanakkan Amon, Amon memperanakkan Yosia,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 11, 'Yosia memperanakkan Yekhonya dan saudara-saudaranya pada waktu pembuangan ke Babel.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 12, 'Sesudah pembuangan ke Babel, Yekhonya memperanakkan Sealtiel, Sealtiel memperanakkan Zerubabel,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 13, 'Zerubabel memperanakkan Abihud, Abihud memperanakkan Elyakim, Elyakim memperanakkan Azor,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 14, 'Azor memperanakkan Zadok, Zadok memperanakkan Akhim, Akhim memperanakkan Eliud,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 15, 'Eliud memperanakkan Eleazar, Eleazar memperanakkan Matan, Matan memperanakkan Yakub,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 16, 'Yakub memperanakkan Yusuf suami Maria, yang melahirkan Yesus yang disebut Kristus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 17, 'Jadi seluruhnya ada: empat belas keturunan dari Abraham sampai Daud, empat belas keturunan dari Daud sampai pembuangan ke Babel, dan empat belas keturunan dari pembuangan ke Babel sampai Kristus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 18, 'Kelahiran Yesus Kristus adalah seperti berikut: Pada waktu Maria, ibu-Nya, bertunangan dengan Yusuf, ternyata ia mengandung dari Roh Kudus, sebelum mereka hidup sebagai suami isteri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 19, 'Karena Yusuf suaminya, seorang yang tulus hati dan tidak mau mencemarkan nama isterinya di muka umum, ia bermaksud menceraikannya dengan diam-diam.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 20, 'Tetapi ketika ia mempertimbangkan maksud itu, malaikat Tuhan nampak kepadanya dalam mimpi dan berkata: "Yusuf, anak Daud, janganlah engkau takut mengambil Maria sebagai isterimu, sebab anak yang di dalam kandungannya adalah dari Roh Kudus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 21, 'Ia akan melahirkan anak laki-laki dan engkau akan menamakan Dia Yesus, karena Dialah yang akan menyelamatkan umat-Nya dari dosa mereka."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 22, 'Hal itu terjadi supaya genaplah yang difirmankan Tuhan oleh nabi:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 23, '"Sesungguhnya, anak dara itu akan mengandung dan melahirkan seorang anak laki-laki, dan mereka akan menamakan Dia Imanuel" ?yang berarti: Allah menyertai kita.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 24, 'Sesudah bangun dari tidurnya, Yusuf berbuat seperti yang diperintahkan malaikat Tuhan itu kepadanya. Ia mengambil Maria sebagai isterinya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 1, 25, 'tetapi tidak bersetubuh dengan dia sampai ia melahirkan anaknya laki-laki dan Yusuf menamakan Dia Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 1, 'Sesudah Yesus dilahirkan di Betlehem di tanah Yudea pada zaman raja Herodes, datanglah orang-orang majus dari Timur ke Yerusalem', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 2, 'dan bertanya-tanya: "Di manakah Dia, raja orang Yahudi yang baru dilahirkan itu? Kami telah melihat bintang-Nya di Timur dan kami datang untuk menyembah Dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 3, 'Ketika raja Herodes mendengar hal itu terkejutlah ia beserta seluruh Yerusalem.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 4, 'Maka dikumpulkannya semua imam kepala dan ahli Taurat bangsa Yahudi, lalu dimintanya keterangan dari mereka, di mana Mesias akan dilahirkan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 5, 'Mereka berkata kepadanya: "Di Betlehem di tanah Yudea, karena demikianlah ada tertulis dalam kitab nabi:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 6, 'Dan engkau Betlehem, tanah Yehuda, engkau sekali-kali bukanlah yang terkecil di antara mereka yang memerintah Yehuda, karena dari padamulah akan bangkit seorang pemimpin, yang akan menggembalakan umat-Ku Israel."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 7, 'Lalu dengan diam-diam Herodes memanggil orang-orang majus itu dan dengan teliti bertanya kepada mereka, bilamana bintang itu nampak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 8, 'Kemudian ia menyuruh mereka ke Betlehem, katanya: "Pergi dan selidikilah dengan seksama hal-hal mengenai Anak itu dan segera sesudah kamu menemukan Dia, kabarkanlah kepadaku supaya akupun datang menyembah Dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 9, 'Setelah mendengar kata-kata raja itu, berangkatlah mereka. Dan lihatlah, bintang yang mereka lihat di Timur itu mendahului mereka hingga tiba dan berhenti di atas tempat, di mana Anak itu berada.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 10, 'Ketika mereka melihat bintang itu, sangat bersukacitalah mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 11, 'Maka masuklah mereka ke dalam rumah itu dan melihat Anak itu bersama Maria, ibu-Nya, lalu sujud menyembah Dia. Merekapun membuka tempat harta bendanya dan mempersembahkan persembahan kepada-Nya, yaitu emas, kemenyan dan mur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 12, 'Dan karena diperingatkan dalam mimpi, supaya jangan kembali kepada Herodes, maka pulanglah mereka ke negerinya melalui jalan lain.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 13, 'Setelah orang-orang majus itu berangkat, nampaklah malaikat Tuhan kepada Yusuf dalam mimpi dan berkata: "Bangunlah, ambillah Anak itu serta ibu-Nya, larilah ke Mesir dan tinggallah di sana sampai Aku berfirman kepadamu, karena Herodes akan mencari Anak itu untuk membunuh Dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 14, 'Maka Yusufpun bangunlah, diambilnya Anak itu serta ibu-Nya malam itu juga, lalu menyingkir ke Mesir,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 15, 'dan tinggal di sana hingga Herodes mati. Hal itu terjadi supaya genaplah yang difirmankan Tuhan oleh nabi: "Dari Mesir Kupanggil Anak-Ku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 16, 'Ketika Herodes tahu, bahwa ia telah diperdayakan oleh orang-orang majus itu, ia sangat marah. Lalu ia menyuruh membunuh semua anak di Betlehem dan sekitarnya, yaitu anak-anak yang berumur dua tahun ke bawah, sesuai dengan waktu yang dapat diketahuinya dari orang-orang majus itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 17, 'Dengan demikian genaplah firman yang disampaikan oleh nabi Yeremia:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 18, '"Terdengarlah suara di Rama, tangis dan ratap yang amat sedih; Rahel menangisi anak-anaknya dan ia tidak mau dihibur, sebab mereka tidak ada lagi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 19, 'Setelah Herodes mati, nampaklah malaikat Tuhan kepada Yusuf dalam mimpi di Mesir, katanya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 20, '"Bangunlah, ambillah Anak itu serta ibu-Nya dan berangkatlah ke tanah Israel, karena mereka yang hendak membunuh Anak itu, sudah mati."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 21, 'Lalu Yusufpun bangunlah, diambilnya Anak itu serta ibu-Nya dan pergi ke tanah Israel.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 22, 'Tetapi setelah didengarnya, bahwa Arkhelaus menjadi raja di Yudea menggantikan Herodes, ayahnya, ia takut ke sana. Karena dinasihati dalam mimpi, pergilah Yusuf ke daerah Galilea.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 2, 23, 'Setibanya di sana iapun tinggal di sebuah kota yang bernama Nazaret. Hal itu terjadi supaya genaplah firman yang disampaikan oleh nabi-nabi, bahwa Ia akan disebut: Orang Nazaret.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 1, 'Pada waktu itu tampillah Yohanes Pembaptis di padang gurun Yudea dan memberitakan:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 2, '"Bertobatlah, sebab Kerajaan Sorga sudah dekat!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 3, 'Sesungguhnya dialah yang dimaksudkan nabi Yesaya ketika ia berkata: "Ada suara orang yang berseru-seru di padang gurun: Persiapkanlah jalan untuk Tuhan, luruskanlah jalan bagi-Nya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 4, 'Yohanes memakai jubah bulu unta dan ikat pinggang kulit, dan makanannya belalang dan madu hutan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 5, 'Maka datanglah kepadanya penduduk dari Yerusalem, dari seluruh Yudea dan dari seluruh daerah sekitar Yordan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 6, 'Lalu sambil mengaku dosanya mereka dibaptis oleh Yohanes di sungai Yordan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 7, 'Tetapi waktu ia melihat banyak orang Farisi dan orang Saduki datang untuk dibaptis, berkatalah ia kepada mereka: "Hai kamu keturunan ular beludak. Siapakah yang mengatakan kepada kamu, bahwa kamu dapat melarikan diri dari murka yang akan datang?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 8, 'Jadi hasilkanlah buah yang sesuai dengan pertobatan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 9, 'Dan janganlah mengira, bahwa kamu dapat berkata dalam hatimu: Abraham adalah bapa kami! Karena aku berkata kepadamu: Allah dapat menjadikan anak-anak bagi Abraham dari batu-batu ini!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 10, 'Kapak sudah tersedia pada akar pohon dan setiap pohon yang tidak menghasilkan buah yang baik, pasti ditebang dan dibuang ke dalam api.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 11, 'Aku membaptis kamu dengan air sebagai tanda pertobatan, tetapi Ia yang datang kemudian dari padaku lebih berkuasa dari padaku dan aku tidak layak melepaskan kasut-Nya. Ia akan membaptiskan kamu dengan Roh Kudus dan dengan api.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 12, 'Alat penampi sudah ditangan-Nya. Ia akan membersihkan tempat pengirikan-Nya dan mengumpulkan gandum-Nya ke dalam lumbung, tetapi debu jerami itu akan dibakar-Nya dalam api yang tidak terpadamkan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 13, 'Maka datanglah Yesus dari Galilea ke Yordan kepada Yohanes untuk dibaptis olehnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 14, 'Tetapi Yohanes mencegah Dia, katanya: "Akulah yang perlu dibaptis oleh-Mu, dan Engkau yang datang kepadaku?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 15, 'Lalu Yesus menjawab, kata-Nya kepadanya: "Biarlah hal itu terjadi, karena demikianlah sepatutnya kita menggenapkan seluruh kehendak Allah." Dan Yohanespun menuruti-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 16, 'Sesudah dibaptis, Yesus segera keluar dari air dan pada waktu itu juga langit terbuka dan Ia melihat Roh Allah seperti burung merpati turun ke atas-Nya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 3, 17, 'lalu terdengarlah suara dari sorga yang mengatakan: "Inilah Anak-Ku yang Kukasihi, kepada-Nyalah Aku berkenan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 1, 'Maka Yesus dibawa oleh Roh ke padang gurun untuk dicobai Iblis.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 2, 'Dan setelah berpuasa empat puluh hari dan empat puluh malam, akhirnya laparlah Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 3, 'Lalu datanglah si pencoba itu dan berkata kepada-Nya: "Jika Engkau Anak Allah, perintahkanlah supaya batu-batu ini menjadi roti."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 4, 'Tetapi Yesus menjawab: "Ada tertulis: Manusia hidup bukan dari roti saja, tetapi dari setiap firman yang keluar dari mulut Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 5, 'Kemudian Iblis membawa-Nya ke Kota Suci dan menempatkan Dia di bubungan Bait Allah,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 6, 'lalu berkata kepada-Nya: "Jika Engkau Anak Allah, jatuhkanlah diri-Mu ke bawah, sebab ada tertulis: Mengenai Engkau Ia akan memerintahkan malaikat-malaikat-Nya dan mereka akan menatang Engkau di atas tangannya, supaya kaki-Mu jangan terantuk kepada batu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 7, 'Yesus berkata kepadanya: "Ada pula tertulis: Janganlah engkau mencobai Tuhan, Allahmu!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 8, 'Dan Iblis membawa-Nya pula ke atas gunung yang sangat tinggi dan memperlihatkan kepada-Nya semua kerajaan dunia dengan kemegahannya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 9, 'dan berkata kepada-Nya: "Semua itu akan kuberikan kepada-Mu, jika Engkau sujud menyembah aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 10, 'Maka berkatalah Yesus kepadanya: "Enyahlah, Iblis! Sebab ada tertulis: Engkau harus menyembah Tuhan, Allahmu, dan hanya kepada Dia sajalah engkau berbakti!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 11, 'Lalu Iblis meninggalkan Dia, dan lihatlah, malaikat-malaikat datang melayani Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 12, 'Tetapi waktu Yesus mendengar, bahwa Yohanes telah ditangkap, menyingkirlah Ia ke Galilea.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 13, 'Ia meninggalkan Nazaret dan diam di Kapernaum, di tepi danau, di daerah Zebulon dan Naftali,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 14, 'supaya genaplah firman yang disampaikan oleh nabi Yesaya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 15, '"Tanah Zebulon dan tanah Naftali, jalan ke laut, daerah seberang sungai Yordan, Galilea, wilayah bangsa-bangsa lain, ?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 16, 'bangsa yang diam dalam kegelapan, telah melihat Terang yang besar dan bagi mereka yang diam di negeri yang dinaungi maut, telah terbit Terang."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 17, 'Sejak waktu itulah Yesus memberitakan: "Bertobatlah, sebab Kerajaan Sorga sudah dekat!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 18, 'Dan ketika Yesus sedang berjalan menyusur danau Galilea, Ia melihat dua orang bersaudara, yaitu Simon yang disebut Petrus, dan Andreas, saudaranya. Mereka sedang menebarkan jala di danau, sebab mereka penjala ikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 19, 'Yesus berkata kepada mereka: "Mari, ikutlah Aku, dan kamu akan Kujadikan penjala manusia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 20, 'Lalu merekapun segera meninggalkan jalanya dan mengikuti Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 21, 'Dan setelah Yesus pergi dari sana, dilihat-Nya pula dua orang bersaudara, yaitu Yakobus anak Zebedeus dan Yohanes saudaranya, bersama ayah mereka, Zebedeus, sedang membereskan jala di dalam perahu. Yesus memanggil mereka', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 22, 'dan mereka segera meninggalkan perahu serta ayahnya, lalu mengikuti Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 23, 'Yesuspun berkeliling di seluruh Galilea; Ia mengajar dalam rumah-rumah ibadat dan memberitakan Injil Kerajaan Allah serta melenyapkan segala penyakit dan kelemahan di antara bangsa itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 24, 'Maka tersiarlah berita tentang Dia di seluruh Siria dan dibawalah kepada-Nya semua orang yang buruk keadaannya, yang menderita pelbagai penyakit dan sengsara, yang kerasukan, yang sakit ayan dan yang lumpuh, lalu Yesus menyembuhkan mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 4, 25, 'Maka orang banyak berbondong-bondong mengikuti Dia. Mereka datang dari Galilea dan dari Dekapolis, dari Yerusalem dan dari Yudea dan dari seberang Yordan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 1, 'Ketika Yesus melihat orang banyak itu, naiklah Ia ke atas bukit dan setelah Ia duduk, datanglah murid-murid-Nya kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 2, 'Maka Yesuspun mulai berbicara dan mengajar mereka, kata-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 3, '"Berbahagialah orang yang miskin di hadapan Allah, karena merekalah yang empunya Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 4, 'Berbahagialah orang yang berdukacita, karena mereka akan dihibur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 5, 'Berbahagialah orang yang lemah lembut, karena mereka akan memiliki bumi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 6, 'Berbahagialah orang yang lapar dan haus akan kebenaran, karena mereka akan dipuaskan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 7, 'Berbahagialah orang yang murah hatinya, karena mereka akan beroleh kemurahan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 8, 'Berbahagialah orang yang suci hatinya, karena mereka akan melihat Allah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 9, 'Berbahagialah orang yang membawa damai, karena mereka akan disebut anak-anak Allah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 10, 'Berbahagialah orang yang dianiaya oleh sebab kebenaran, karena merekalah yang empunya Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 11, 'Berbahagialah kamu, jika karena Aku kamu dicela dan dianiaya dan kepadamu difitnahkan segala yang jahat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 12, 'Bersukacita dan bergembiralah, karena upahmu besar di sorga, sebab demikian juga telah dianiaya nabi-nabi yang sebelum kamu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 13, '"Kamu adalah garam dunia. Jika garam itu menjadi tawar, dengan apakah ia diasinkan? Tidak ada lagi gunanya selain dibuang dan diinjak orang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 14, 'Kamu adalah terang dunia. Kota yang terletak di atas gunung tidak mungkin tersembunyi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 15, 'Lagipula orang tidak menyalakan pelita lalu meletakkannya di bawah gantang, melainkan di atas kaki dian sehingga menerangi semua orang di dalam rumah itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 16, 'Demikianlah hendaknya terangmu bercahaya di depan orang, supaya mereka melihat perbuatanmu yang baik dan memuliakan Bapamu yang di sorga."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 17, '"Janganlah kamu menyangka, bahwa Aku datang untuk meniadakan hukum Taurat atau kitab para nabi. Aku datang bukan untuk meniadakannya, melainkan untuk menggenapinya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 18, 'Karena Aku berkata kepadamu: Sesungguhnya selama belum lenyap langit dan bumi ini, satu iota atau satu titikpun tidak akan ditiadakan dari hukum Taurat, sebelum semuanya terjadi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 19, 'Karena itu siapa yang meniadakan salah satu perintah hukum Taurat sekalipun yang paling kecil, dan mengajarkannya demikian kepada orang lain, ia akan menduduki tempat yang paling rendah di dalam Kerajaan Sorga; tetapi siapa yang melakukan dan mengajarkan segala perintah-perintah hukum Taurat, ia akan menduduki tempat yang tinggi di dalam Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 20, 'Maka Aku berkata kepadamu: Jika hidup keagamaanmu tidak lebih benar dari pada hidup keagamaan ahli-ahli Taurat dan orang-orang Farisi, sesungguhnya kamu tidak akan masuk ke dalam Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 21, 'Kamu telah mendengar yang difirmankan kepada nenek moyang kita: Jangan membunuh; siapa yang membunuh harus dihukum.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 22, 'Tetapi Aku berkata kepadamu: Setiap orang yang marah terhadap saudaranya harus dihukum; siapa yang berkata kepada saudaranya: Kafir! harus dihadapkan ke Mahkamah Agama dan siapa yang berkata: Jahil! harus diserahkan ke dalam neraka yang menyala-nyala.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 23, 'Sebab itu, jika engkau mempersembahkan persembahanmu di atas mezbah dan engkau teringat akan sesuatu yang ada dalam hati saudaramu terhadap engkau,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 24, 'tinggalkanlah persembahanmu di depan mezbah itu dan pergilah berdamai dahulu dengan saudaramu, lalu kembali untuk mempersembahkan persembahanmu itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 25, 'Segeralah berdamai dengan lawanmu selama engkau bersama-sama dengan dia di tengah jalan, supaya lawanmu itu jangan menyerahkan engkau kepada hakim dan hakim itu menyerahkan engkau kepada pembantunya dan engkau dilemparkan ke dalam penjara.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 26, 'Aku berkata kepadamu: Sesungguhnya engkau tidak akan keluar dari sana, sebelum engkau membayar hutangmu sampai lunas.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 27, 'Kamu telah mendengar firman: Jangan berzinah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 28, 'Tetapi Aku berkata kepadamu: Setiap orang yang memandang perempuan serta menginginkannya, sudah berzinah dengan dia di dalam hatinya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 29, 'Maka jika matamu yang kanan menyesatkan engkau, cungkillah dan buanglah itu, karena lebih baik bagimu jika satu dari anggota tubuhmu binasa, dari pada tubuhmu dengan utuh dicampakkan ke dalam neraka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 30, 'Dan jika tanganmu yang kanan menyesatkan engkau, penggallah dan buanglah itu, karena lebih baik bagimu jika satu dari anggota tubuhmu binasa dari pada tubuhmu dengan utuh masuk neraka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 31, 'Telah difirmankan juga: Siapa yang menceraikan isterinya harus memberi surat cerai kepadanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 32, 'Tetapi Aku berkata kepadamu: Setiap orang yang menceraikan isterinya kecuali karena zinah, ia menjadikan isterinya berzinah; dan siapa yang kawin dengan perempuan yang diceraikan, ia berbuat zinah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 33, 'Kamu telah mendengar pula yang difirmankan kepada nenek moyang kita: Jangan bersumpah palsu, melainkan peganglah sumpahmu di depan Tuhan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 34, 'Tetapi Aku berkata kepadamu: Janganlah sekali-kali bersumpah, baik demi langit, karena langit adalah takhta Allah,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 35, 'maupun demi bumi, karena bumi adalah tumpuan kaki-Nya, ataupun demi Yerusalem, karena Yerusalem adalah kota Raja Besar;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 36, 'janganlah juga engkau bersumpah demi kepalamu, karena engkau tidak berkuasa memutihkan atau menghitamkan sehelai rambutpun.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 37, 'Jika ya, hendaklah kamu katakan: ya, jika tidak, hendaklah kamu katakan: tidak. Apa yang lebih dari pada itu berasal dari si jahat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 38, 'Kamu telah mendengar firman: Mata ganti mata dan gigi ganti gigi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 39, 'Tetapi Aku berkata kepadamu: Janganlah kamu melawan orang yang berbuat jahat kepadamu, melainkan siapapun yang menampar pipi kananmu, berilah juga kepadanya pipi kirimu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 40, 'Dan kepada orang yang hendak mengadukan engkau karena mengingini bajumu, serahkanlah juga jubahmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 41, 'Dan siapapun yang memaksa engkau berjalan sejauh satu mil, berjalanlah bersama dia sejauh dua mil.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 42, 'Berilah kepada orang yang meminta kepadamu dan janganlah menolak orang yang mau meminjam dari padamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 43, 'Kamu telah mendengar firman: Kasihilah sesamamu manusia dan bencilah musuhmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 44, 'Tetapi Aku berkata kepadamu: Kasihilah musuhmu dan berdoalah bagi mereka yang menganiaya kamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 45, 'Karena dengan demikianlah kamu menjadi anak-anak Bapamu yang di sorga, yang menerbitkan matahari bagi orang yang jahat dan orang yang baik dan menurunkan hujan bagi orang yang benar dan orang yang tidak benar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 46, 'Apabila kamu mengasihi orang yang mengasihi kamu, apakah upahmu? Bukankah pemungut cukai juga berbuat demikian?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 47, 'Dan apabila kamu hanya memberi salam kepada saudara-saudaramu saja, apakah lebihnya dari pada perbuatan orang lain? Bukankah orang yang tidak mengenal Allahpun berbuat demikian?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 5, 48, 'Karena itu haruslah kamu sempurna, sama seperti Bapamu yang di sorga adalah sempurna."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 1, '"Ingatlah, jangan kamu melakukan kewajiban agamamu di hadapan orang supaya dilihat mereka, karena jika demikian, kamu tidak beroleh upah dari Bapamu yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 2, 'Jadi apabila engkau memberi sedekah, janganlah engkau mencanangkan hal itu, seperti yang dilakukan orang munafik di rumah-rumah ibadat dan di lorong-lorong, supaya mereka dipuji orang. Aku berkata kepadamu: Sesungguhnya mereka sudah mendapat upahnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 3, 'Tetapi jika engkau memberi sedekah, janganlah diketahui tangan kirimu apa yang diperbuat tangan kananmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 4, 'Hendaklah sedekahmu itu diberikan dengan tersembunyi, maka Bapamu yang melihat yang tersembunyi akan membalasnya kepadamu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 5, '"Dan apabila kamu berdoa, janganlah berdoa seperti orang munafik. Mereka suka mengucapkan doanya dengan berdiri dalam rumah-rumah ibadat dan pada tikungan-tikungan jalan raya, supaya mereka dilihat orang. Aku berkata kepadamu: Sesungguhnya mereka sudah mendapat upahnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 6, 'Tetapi jika engkau berdoa, masuklah ke dalam kamarmu, tutuplah pintu dan berdoalah kepada Bapamu yang ada di tempat tersembunyi. Maka Bapamu yang melihat yang tersembunyi akan membalasnya kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 7, 'Lagipula dalam doamu itu janganlah kamu bertele-tele seperti kebiasaan orang yang tidak mengenal Allah. Mereka menyangka bahwa karena banyaknya kata-kata doanya akan dikabulkan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 8, 'Jadi janganlah kamu seperti mereka, karena Bapamu mengetahui apa yang kamu perlukan, sebelum kamu minta kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 9, 'Karena itu berdoalah demikian: Bapa kami yang di sorga, Dikuduskanlah nama-Mu,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 10, 'datanglah Kerajaan-Mu, jadilah kehendak-Mu di bumi seperti di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 11, 'Berikanlah kami pada hari ini makanan kami yang secukupnya', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 12, 'dan ampunilah kami akan kesalahan kami, seperti kami juga mengampuni orang yang bersalah kepada kami;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 13, 'dan janganlah membawa kami ke dalam pencobaan, tetapi lepaskanlah kami dari pada yang jahat. (Karena Engkaulah yang empunya Kerajaan dan kuasa dan kemuliaan sampai selama-lamanya. Amin.)', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 14, 'Karena jikalau kamu mengampuni kesalahan orang, Bapamu yang di sorga akan mengampuni kamu juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 15, 'Tetapi jikalau kamu tidak mengampuni orang, Bapamu juga tidak akan mengampuni kesalahanmu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 16, '"Dan apabila kamu berpuasa, janganlah muram mukamu seperti orang munafik. Mereka mengubah air mukanya, supaya orang melihat bahwa mereka sedang berpuasa. Aku berkata kepadamu: Sesungguhnya mereka sudah mendapat upahnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 17, 'Tetapi apabila engkau berpuasa, minyakilah kepalamu dan cucilah mukamu,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 18, 'supaya jangan dilihat oleh orang bahwa engkau sedang berpuasa, melainkan hanya oleh Bapamu yang ada di tempat tersembunyi. Maka Bapamu yang melihat yang tersembunyi akan membalasnya kepadamu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 19, '"Janganlah kamu mengumpulkan harta di bumi; di bumi ngengat dan karat merusakkannya dan pencuri membongkar serta mencurinya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 20, 'Tetapi kumpulkanlah bagimu harta di sorga; di sorga ngengat dan karat tidak merusakkannya dan pencuri tidak membongkar serta mencurinya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 21, 'Karena di mana hartamu berada, di situ juga hatimu berada.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 22, 'Mata adalah pelita tubuh. Jika matamu baik, teranglah seluruh tubuhmu;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 23, 'jika matamu jahat, gelaplah seluruh tubuhmu. Jadi jika terang yang ada padamu gelap, betapa gelapnya kegelapan itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 24, 'Tak seorangpun dapat mengabdi kepada dua tuan. Karena jika demikian, ia akan membenci yang seorang dan mengasihi yang lain, atau ia akan setia kepada yang seorang dan tidak mengindahkan yang lain. Kamu tidak dapat mengabdi kepada Allah dan kepada Mamon."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 25, '"Karena itu Aku berkata kepadamu: Janganlah kuatir akan hidupmu, akan apa yang hendak kamu makan atau minum, dan janganlah kuatir pula akan tubuhmu, akan apa yang hendak kamu pakai. Bukankah hidup itu lebih penting dari pada makanan dan tubuh itu lebih penting dari pada pakaian?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 26, 'Pandanglah burung-burung di langit, yang tidak menabur dan tidak menuai dan tidak mengumpulkan bekal dalam lumbung, namun diberi makan oleh Bapamu yang di sorga. Bukankah kamu jauh melebihi burung-burung itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 27, 'Siapakah di antara kamu yang karena kekuatirannya dapat menambahkan sehasta saja pada jalan hidupnya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 28, 'Dan mengapa kamu kuatir akan pakaian? Perhatikanlah bunga bakung di ladang, yang tumbuh tanpa bekerja dan tanpa memintal,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 29, 'namun Aku berkata kepadamu: Salomo dalam segala kemegahannyapun tidak berpakaian seindah salah satu dari bunga itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 30, 'Jadi jika demikian Allah mendandani rumput di ladang, yang hari ini ada dan besok dibuang ke dalam api, tidakkah Ia akan terlebih lagi mendandani kamu, hai orang yang kurang percaya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 31, 'Sebab itu janganlah kamu kuatir dan berkata: Apakah yang akan kami makan? Apakah yang akan kami minum? Apakah yang akan kami pakai?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 32, 'Semua itu dicari bangsa-bangsa yang tidak mengenal Allah. Akan tetapi Bapamu yang di sorga tahu, bahwa kamu memerlukan semuanya itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 33, 'Tetapi carilah dahulu Kerajaan Allah dan kebenarannya, maka semuanya itu akan ditambahkan kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 6, 34, 'Sebab itu janganlah kamu kuatir akan hari besok, karena hari besok mempunyai kesusahannya sendiri. Kesusahan sehari cukuplah untuk sehari."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 1, '"Jangan kamu menghakimi, supaya kamu tidak dihakimi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 2, 'Karena dengan penghakiman yang kamu pakai untuk menghakimi, kamu akan dihakimi dan ukuran yang kamu pakai untuk mengukur, akan diukurkan kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 3, 'Mengapakah engkau melihat selumbar di mata saudaramu, sedangkan balok di dalam matamu tidak engkau ketahui?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 4, 'Bagaimanakah engkau dapat berkata kepada saudaramu: Biarlah aku mengeluarkan selumbar itu dari matamu, padahal ada balok di dalam matamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 5, 'Hai orang munafik, keluarkanlah dahulu balok dari matamu, maka engkau akan melihat dengan jelas untuk mengeluarkan selumbar itu dari mata saudaramu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 6, '"Jangan kamu memberikan barang yang kudus kepada anjing dan jangan kamu melemparkan mutiaramu kepada babi, supaya jangan diinjak-injaknya dengan kakinya, lalu ia berbalik mengoyak kamu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 7, '"Mintalah, maka akan diberikan kepadamu; carilah, maka kamu akan mendapat; ketoklah, maka pintu akan dibukakan bagimu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 8, 'Karena setiap orang yang meminta, menerima dan setiap orang yang mencari, mendapat dan setiap orang yang mengetok, baginya pintu dibukakan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 9, 'Adakah seorang dari padamu yang memberi batu kepada anaknya, jika ia meminta roti,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 10, 'atau memberi ular, jika ia meminta ikan?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 11, 'Jadi jika kamu yang jahat tahu memberi pemberian yang baik kepada anak-anakmu, apalagi Bapamu yang di sorga! Ia akan memberikan yang baik kepada mereka yang meminta kepada-Nya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 12, '"Segala sesuatu yang kamu kehendaki supaya orang perbuat kepadamu, perbuatlah demikian juga kepada mereka. Itulah isi seluruh hukum Taurat dan kitab para nabi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 13, 'Masuklah melalui pintu yang sesak itu, karena lebarlah pintu dan luaslah jalan yang menuju kepada kebinasaan, dan banyak orang yang masuk melaluinya;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 14, 'karena sesaklah pintu dan sempitlah jalan yang menuju kepada kehidupan, dan sedikit orang yang mendapatinya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 15, '"Waspadalah terhadap nabi-nabi palsu yang datang kepadamu dengan menyamar seperti domba, tetapi sesungguhnya mereka adalah serigala yang buas.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 16, 'Dari buahnyalah kamu akan mengenal mereka. Dapatkah orang memetik buah anggur dari semak duri atau buah ara dari rumput duri?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 17, 'Demikianlah setiap pohon yang baik menghasilkan buah yang baik, sedang pohon yang tidak baik menghasilkan buah yang tidak baik.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 18, 'Tidak mungkin pohon yang baik itu menghasilkan buah yang tidak baik, ataupun pohon yang tidak baik itu menghasilkan buah yang baik.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 19, 'Dan setiap pohon yang tidak menghasilkan buah yang baik, pasti ditebang dan dibuang ke dalam api.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 20, 'Jadi dari buahnyalah kamu akan mengenal mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 21, 'Bukan setiap orang yang berseru kepada-Ku: Tuhan, Tuhan! akan masuk ke dalam Kerajaan Sorga, melainkan dia yang melakukan kehendak Bapa-Ku yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 22, 'Pada hari terakhir banyak orang akan berseru kepada-Ku: Tuhan, Tuhan, bukankah kami bernubuat demi nama-Mu, dan mengusir setan demi nama-Mu, dan mengadakan banyak mujizat demi nama-Mu juga?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 23, 'Pada waktu itulah Aku akan berterus terang kepada mereka dan berkata: Aku tidak pernah mengenal kamu! Enyahlah dari pada-Ku, kamu sekalian pembuat kejahatan!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 24, '"Setiap orang yang mendengar perkataan-Ku ini dan melakukannya, ia sama dengan orang yang bijaksana, yang mendirikan rumahnya di atas batu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 25, 'Kemudian turunlah hujan dan datanglah banjir, lalu angin melanda rumah itu, tetapi rumah itu tidak rubuh sebab didirikan di atas batu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 26, 'Tetapi setiap orang yang mendengar perkataan-Ku ini dan tidak melakukannya, ia sama dengan orang yang bodoh, yang mendirikan rumahnya di atas pasir.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 27, 'Kemudian turunlah hujan dan datanglah banjir, lalu angin melanda rumah itu, sehingga rubuhlah rumah itu dan hebatlah kerusakannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 28, 'Dan setelah Yesus mengakhiri perkataan ini, takjublah orang banyak itu mendengar pengajaran-Nya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 7, 29, 'sebab Ia mengajar mereka sebagai orang yang berkuasa, tidak seperti ahli-ahli Taurat mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 1, 'Setelah Yesus turun dari bukit, orang banyak berbondong-bondong mengikuti Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 2, 'Maka datanglah seorang yang sakit kusta kepada-Nya, lalu sujud menyembah Dia dan berkata: "Tuan, jika Tuan mau, Tuan dapat mentahirkan aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 3, 'Lalu Yesus mengulurkan tangan-Nya, menjamah orang itu dan berkata: "Aku mau, jadilah engkau tahir." Seketika itu juga tahirlah orang itu dari pada kustanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 4, 'Lalu Yesus berkata kepadanya: "Ingatlah, jangan engkau memberitahukan hal ini kepada siapapun, tetapi pergilah, perlihatkanlah dirimu kepada imam dan persembahkanlah persembahan yang diperintahkan Musa, sebagai bukti bagi mereka."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 5, 'Ketika Yesus masuk ke Kapernaum, datanglah seorang perwira mendapatkan Dia dan memohon kepada-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 6, '"Tuan, hambaku terbaring di rumah karena sakit lumpuh dan ia sangat menderita."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 7, 'Yesus berkata kepadanya: "Aku akan datang menyembuhkannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 8, 'Tetapi jawab perwira itu kepada-Nya: "Tuan, aku tidak layak menerima Tuan di dalam rumahku, katakan saja sepatah kata, maka hambaku itu akan sembuh.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 9, 'Sebab aku sendiri seorang bawahan, dan di bawahku ada pula prajurit. Jika aku berkata kepada salah seorang prajurit itu: Pergi!, maka ia pergi, dan kepada seorang lagi: Datang!, maka ia datang, ataupun kepada hambaku: Kerjakanlah ini!, maka ia mengerjakannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 10, 'Setelah Yesus mendengar hal itu, heranlah Ia dan berkata kepada mereka yang mengikuti-Nya: "Aku berkata kepadamu, sesungguhnya iman sebesar ini tidak pernah Aku jumpai pada seorangpun di antara orang Israel.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 11, 'Aku berkata kepadamu: Banyak orang akan datang dari Timur dan Barat dan duduk makan bersama-sama dengan Abraham, Ishak dan Yakub di dalam Kerajaan Sorga,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 12, 'sedangkan anak-anak Kerajaan itu akan dicampakkan ke dalam kegelapan yang paling gelap, di sanalah akan terdapat ratap dan kertak gigi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 13, 'Lalu Yesus berkata kepada perwira itu: "Pulanglah dan jadilah kepadamu seperti yang engkau percaya." Maka pada saat itu juga sembuhlah hambanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 14, 'Setibanya di rumah Petrus, Yesuspun melihat ibu mertua Petrus terbaring karena sakit demam.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 15, 'Maka dipegang-Nya tangan perempuan itu, lalu lenyaplah demamnya. Iapun bangunlah dan melayani Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 16, 'Menjelang malam dibawalah kepada Yesus banyak orang yang kerasukan setan dan dengan sepatah kata Yesus mengusir roh-roh itu dan menyembuhkan orang-orang yang menderita sakit.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 17, 'Hal itu terjadi supaya genaplah firman yang disampaikan oleh nabi Yesaya: "Dialah yang memikul kelemahan kita dan menanggung penyakit kita."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 18, 'Ketika Yesus melihat orang banyak mengelilingi-Nya, Ia menyuruh bertolak ke seberang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 19, 'Lalu datanglah seorang ahli Taurat dan berkata kepada-Nya: "Guru, aku akan mengikut Engkau, ke mana saja Engkau pergi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 20, 'Yesus berkata kepadanya: "Serigala mempunyai liang dan burung mempunyai sarang, tetapi Anak Manusia tidak mempunyai tempat untuk meletakkan kepala-Nya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 21, 'Seorang lain, yaitu salah seorang murid-Nya, berkata kepada-Nya: "Tuhan, izinkanlah aku pergi dahulu menguburkan ayahku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 22, 'Tetapi Yesus berkata kepadanya: "Ikutlah Aku dan biarlah orang-orang mati menguburkan orang-orang mati mereka."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 23, 'Lalu Yesus naik ke dalam perahu dan murid-murid-Nyapun mengikuti-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 24, 'Sekonyong-konyong mengamuklah angin ribut di danau itu, sehingga perahu itu ditimbus gelombang, tetapi Yesus tidur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 25, 'Maka datanglah murid-murid-Nya membangunkan Dia, katanya: "Tuhan, tolonglah, kita binasa."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 26, 'Ia berkata kepada mereka: "Mengapa kamu takut, kamu yang kurang percaya?" Lalu bangunlah Yesus menghardik angin dan danau itu, maka danau itu menjadi teduh sekali.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 27, 'Dan heranlah orang-orang itu, katanya: "Orang apakah Dia ini, sehingga angin dan danaupun taat kepada-Nya?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 28, 'Setibanya di seberang, yaitu di daerah orang Gadara, datanglah dari pekuburan dua orang yang kerasukan setan menemui Yesus. Mereka sangat berbahaya, sehingga tidak seorangpun yang berani melalui jalan itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 29, 'Dan mereka itupun berteriak, katanya: "Apa urusan-Mu dengan kami, hai Anak Allah? Adakah Engkau ke mari untuk menyiksa kami sebelum waktunya?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 30, 'Tidak jauh dari mereka itu sejumlah besar babi sedang mencari makan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 31, 'Maka setan-setan itu meminta kepada-Nya, katanya: "Jika Engkau mengusir kami, suruhlah kami pindah ke dalam kawanan babi itu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 32, 'Yesus berkata kepada mereka: "Pergilah!" Lalu keluarlah mereka dan masuk ke dalam babi-babi itu. Maka terjunlah seluruh kawanan babi itu dari tepi jurang ke dalam danau dan mati di dalam air.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 33, 'Maka larilah penjaga-penjaga babi itu dan setibanya di kota, diceriterakannyalah segala sesuatu, juga tentang orang-orang yang kerasukan setan itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 8, 34, 'Maka keluarlah seluruh kota mendapatkan Yesus dan setelah mereka berjumpa dengan Dia, merekapun mendesak, supaya Ia meninggalkan daerah mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 1, 'Sesudah itu naiklah Yesus ke dalam perahu lalu menyeberang. Kemudian sampailah Ia ke kota-Nya sendiri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 2, 'Maka dibawa oranglah kepada-Nya seorang lumpuh yang terbaring di tempat tidurnya. Ketika Yesus melihat iman mereka, berkatalah Ia kepada orang lumpuh itu: "Percayalah, hai anak-Ku, dosamu sudah diampuni."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 3, 'Maka berkatalah beberapa orang ahli Taurat dalam hatinya: "Ia menghujat Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 4, 'Tetapi Yesus mengetahui pikiran mereka, lalu berkata: "Mengapa kamu memikirkan hal-hal yang jahat di dalam hatimu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 5, 'Manakah lebih mudah, mengatakan: Dosamu sudah diampuni, atau mengatakan: Bangunlah dan berjalanlah?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 6, 'Tetapi supaya kamu tahu, bahwa di dunia ini Anak Manusia berkuasa mengampuni dosa" ?lalu berkatalah Ia kepada orang lumpuh itu?:"Bangunlah, angkatlah tempat tidurmu dan pulanglah ke rumahmu!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 7, 'Dan orang itupun bangun lalu pulang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 8, 'Maka orang banyak yang melihat hal itu takut lalu memuliakan Allah yang telah memberikan kuasa sedemikian itu kepada manusia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 9, 'Setelah Yesus pergi dari situ, Ia melihat seorang yang bernama Matius duduk di rumah cukai, lalu Ia berkata kepadanya: "Ikutlah Aku." Maka berdirilah Matius lalu mengikut Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 10, 'Kemudian ketika Yesus makan di rumah Matius, datanglah banyak pemungut cukai dan orang berdosa dan makan bersama-sama dengan Dia dan murid-murid-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 11, 'Pada waktu orang Farisi melihat hal itu, berkatalah mereka kepada murid-murid Yesus: "Mengapa gurumu makan bersama-sama dengan pemungut cukai dan orang berdosa?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 12, 'Yesus mendengarnya dan berkata: "Bukan orang sehat yang memerlukan tabib, tetapi orang sakit.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 13, 'Jadi pergilah dan pelajarilah arti firman ini: Yang Kukehendaki ialah belas kasihan dan bukan persembahan, karena Aku datang bukan untuk memanggil orang benar, melainkan orang berdosa."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 14, 'Kemudian datanglah murid-murid Yohanes kepada Yesus dan berkata: "Mengapa kami dan orang Farisi berpuasa, tetapi murid-murid-Mu tidak?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 15, 'Jawab Yesus kepada mereka: "Dapatkah sahabat-sahabat mempelai laki-laki berdukacita selama mempelai itu bersama mereka? Tetapi waktunya akan datang mempelai itu diambil dari mereka dan pada waktu itulah mereka akan berpuasa.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 16, 'Tidak seorangpun menambalkan secarik kain yang belum susut pada baju yang tua, karena jika demikian kain penambal itu akan mencabik baju itu, lalu makin besarlah koyaknya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 17, 'Begitu pula anggur yang baru tidak diisikan ke dalam kantong kulit yang tua, karena jika demikian kantong itu akan koyak sehingga anggur itu terbuang dan kantong itupun hancur. Tetapi anggur yang baru disimpan orang dalam kantong yang baru pula, dan dengan demikian terpeliharalah kedua-duanya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 18, 'Sementara Yesus berbicara demikian kepada mereka, datanglah seorang kepala rumah ibadat, lalu menyembah Dia dan berkata: "Anakku perempuan baru saja meninggal, tetapi datanglah dan letakkanlah tangan-Mu atasnya, maka ia akan hidup."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 19, 'Lalu Yesuspun bangunlah dan mengikuti orang itu bersama-sama dengan murid-murid-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 20, 'Pada waktu itu seorang perempuan yang sudah dua belas tahun lamanya menderita pendarahan maju mendekati Yesus dari belakang dan menjamah jumbai jubah-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 21, 'Karena katanya dalam hatinya: "Asal kujamah saja jubah-Nya, aku akan sembuh."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 22, 'Tetapi Yesus berpaling dan memandang dia serta berkata: "Teguhkanlah hatimu, hai anak-Ku, imanmu telah menyelamatkan engkau." Maka sejak saat itu sembuhlah perempuan itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 23, 'Ketika Yesus tiba di rumah kepala rumah ibadat itu dan melihat peniup-peniup seruling dan orang banyak ribut,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 24, 'berkatalah Ia: "Pergilah, karena anak ini tidak mati, tetapi tidur." Tetapi mereka menertawakan Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 25, 'Setelah orang banyak itu diusir, Yesus masuk dan memegang tangan anak itu, lalu bangkitlah anak itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 26, 'Maka tersiarlah kabar tentang hal itu ke seluruh daerah itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 27, 'Ketika Yesus meneruskan perjalanan-Nya dari sana, dua orang buta mengikuti-Nya sambil berseru-seru dan berkata: "Kasihanilah kami, hai Anak Daud."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 28, 'Setelah Yesus masuk ke dalam sebuah rumah, datanglah kedua orang buta itu kepada-Nya dan Yesus berkata kepada mereka: "Percayakah kamu, bahwa Aku dapat melakukannya?" Mereka menjawab: "Ya Tuhan, kami percaya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 29, 'Lalu Yesus menjamah mata mereka sambil berkata: "Jadilah kepadamu menurut imanmu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 30, 'Maka meleklah mata mereka. Dan Yesuspun dengan tegas berpesan kepada mereka, kata-Nya: "Jagalah supaya jangan seorangpun mengetahui hal ini."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 31, 'Tetapi mereka keluar dan memasyhurkan Dia ke seluruh daerah itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 32, 'Sedang kedua orang buta itu keluar, dibawalah kepada Yesus seorang bisu yang kerasukan setan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 33, 'Dan setelah setan itu diusir, dapatlah orang bisu itu berkata-kata. Maka heranlah orang banyak, katanya: "Yang demikian belum pernah dilihat orang di Israel."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 34, 'Tetapi orang Farisi berkata: "Dengan kuasa penghulu setan Ia mengusir setan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 35, 'Demikianlah Yesus berkeliling ke semua kota dan desa; Ia mengajar dalam rumah-rumah ibadat dan memberitakan Injil Kerajaan Sorga serta melenyapkan segala penyakit dan kelemahan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 36, 'Melihat orang banyak itu, tergeraklah hati Yesus oleh belas kasihan kepada mereka, karena mereka lelah dan terlantar seperti domba yang tidak bergembala.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 37, 'Maka kata-Nya kepada murid-murid-Nya: "Tuaian memang banyak, tetapi pekerja sedikit.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 9, 38, 'Karena itu mintalah kepada tuan yang empunya tuaian, supaya Ia mengirimkan pekerja-pekerja untuk tuaian itu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 1, 'Yesus memanggil kedua belas murid-Nya dan memberi kuasa kepada mereka untuk mengusir roh-roh jahat dan untuk melenyapkan segala penyakit dan segala kelemahan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 2, 'Inilah nama kedua belas rasul itu: Pertama Simon yang disebut Petrus dan Andreas saudaranya, dan Yakobus anak Zebedeus dan Yohanes saudaranya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 3, 'Filipus dan Bartolomeus, Tomas dan Matius pemungut cukai, Yakobus anak Alfeus, dan Tadeus,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 4, 'Simon orang Zelot dan Yudas Iskariot yang mengkhianati Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 5, 'Kedua belas murid itu diutus oleh Yesus dan Ia berpesan kepada mereka: "Janganlah kamu menyimpang ke jalan bangsa lain atau masuk ke dalam kota orang Samaria,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 6, 'melainkan pergilah kepada domba-domba yang hilang dari umat Israel.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 7, 'Pergilah dan beritakanlah: Kerajaan Sorga sudah dekat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 8, 'Sembuhkanlah orang sakit; bangkitkanlah orang mati; tahirkanlah orang kusta; usirlah setan-setan. Kamu telah memperolehnya dengan cuma-cuma, karena itu berikanlah pula dengan cuma-cuma.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 9, 'Janganlah kamu membawa emas atau perak atau tembaga dalam ikat pinggangmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 10, 'Janganlah kamu membawa bekal dalam perjalanan, janganlah kamu membawa baju dua helai, kasut atau tongkat, sebab seorang pekerja patut mendapat upahnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 11, 'Apabila kamu masuk kota atau desa, carilah di situ seorang yang layak dan tinggallah padanya sampai kamu berangkat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 12, 'Apabila kamu masuk rumah orang, berilah salam kepada mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 13, 'Jika mereka layak menerimanya, salammu itu turun ke atasnya, jika tidak, salammu itu kembali kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 14, 'Dan apabila seorang tidak menerima kamu dan tidak mendengar perkataanmu, keluarlah dan tinggalkanlah rumah atau kota itu dan kebaskanlah debunya dari kakimu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 15, 'Aku berkata kepadamu: Sesungguhnya pada hari penghakiman tanah Sodom dan Gomora akan lebih ringan tanggungannya dari pada kota itu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 16, '"Lihat, Aku mengutus kamu seperti domba ke tengah-tengah serigala, sebab itu hendaklah kamu cerdik seperti ular dan tulus seperti merpati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 17, 'Tetapi waspadalah terhadap semua orang; karena ada yang akan menyerahkan kamu kepada majelis agama dan mereka akan menyesah kamu di rumah ibadatnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 18, 'Dan karena Aku, kamu akan digiring ke muka penguasa-penguasa dan raja-raja sebagai suatu kesaksian bagi mereka dan bagi orang-orang yang tidak mengenal Allah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 19, 'Apabila mereka menyerahkan kamu, janganlah kamu kuatir akan bagaimana dan akan apa yang harus kamu katakan, karena semuanya itu akan dikaruniakan kepadamu pada saat itu juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 20, 'Karena bukan kamu yang berkata-kata, melainkan Roh Bapamu; Dia yang akan berkata-kata di dalam kamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 21, 'Orang akan menyerahkan saudaranya untuk dibunuh, demikian juga seorang ayah akan anaknya. Dan anak-anak akan memberontak terhadap orang tuanya dan akan membunuh mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 22, 'Dan kamu akan dibenci semua orang oleh karena nama-Ku; tetapi orang yang bertahan sampai pada kesudahannya akan selamat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 23, 'Apabila mereka menganiaya kamu dalam kota yang satu, larilah ke kota yang lain; karena Aku berkata kepadamu: Sesungguhnya sebelum kamu selesai mengunjungi kota-kota Israel, Anak Manusia sudah datang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 24, 'Seorang murid tidak lebih dari pada gurunya, atau seorang hamba dari pada tuannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 25, 'Cukuplah bagi seorang murid jika ia menjadi sama seperti gurunya dan bagi seorang hamba jika ia menjadi sama seperti tuannya. Jika tuan rumah disebut Beelzebul, apalagi seisi rumahnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 26, 'Jadi janganlah kamu takut terhadap mereka, karena tidak ada sesuatupun yang tertutup yang tidak akan dibuka dan tidak ada sesuatupun yang tersembunyi yang tidak akan diketahui.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 27, 'Apa yang Kukatakan kepadamu dalam gelap, katakanlah itu dalam terang; dan apa yang dibisikkan ke telingamu, beritakanlah itu dari atas atap rumah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 28, 'Dan janganlah kamu takut kepada mereka yang dapat membunuh tubuh, tetapi yang tidak berkuasa membunuh jiwa; takutlah terutama kepada Dia yang berkuasa membinasakan baik jiwa maupun tubuh di dalam neraka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 29, 'Bukankah burung pipit dijual dua ekor seduit? Namun seekorpun dari padanya tidak akan jatuh ke bumi di luar kehendak Bapamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 30, 'Dan kamu, rambut kepalamupun terhitung semuanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 31, 'Sebab itu janganlah kamu takut, karena kamu lebih berharga dari pada banyak burung pipit.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 32, 'Setiap orang yang mengakui Aku di depan manusia, Aku juga akan mengakuinya di depan Bapa-Ku yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 33, 'Tetapi barangsiapa menyangkal Aku di depan manusia, Aku juga akan menyangkalnya di depan Bapa-Ku yang di sorga."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 34, '"Jangan kamu menyangka, bahwa Aku datang untuk membawa damai di atas bumi; Aku datang bukan untuk membawa damai, melainkan pedang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 35, 'Sebab Aku datang untuk memisahkan orang dari ayahnya, anak perempuan dari ibunya, menantu perempuan dari ibu mertuanya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 36, 'dan musuh orang ialah orang-orang seisi rumahnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 37, 'Barangsiapa mengasihi bapa atau ibunya lebih dari pada-Ku, ia tidak layak bagi-Ku; dan barangsiapa mengasihi anaknya laki-laki atau perempuan lebih dari pada-Ku, ia tidak layak bagi-Ku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 38, 'Barangsiapa tidak memikul salibnya dan mengikut Aku, ia tidak layak bagi-Ku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 39, 'Barangsiapa mempertahankan nyawanya, ia akan kehilangan nyawanya, dan barangsiapa kehilangan nyawanya karena Aku, ia akan memperolehnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 40, 'Barangsiapa menyambut kamu, ia menyambut Aku, dan barangsiapa menyambut Aku, ia menyambut Dia yang mengutus Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 41, 'Barangsiapa menyambut seorang nabi sebagai nabi, ia akan menerima upah nabi, dan barangsiapa menyambut seorang benar sebagai orang benar, ia akan menerima upah orang benar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 10, 42, 'Dan barangsiapa memberi air sejuk secangkir sajapun kepada salah seorang yang kecil ini, karena ia murid-Ku, Aku berkata kepadamu: Sesungguhnya ia tidak akan kehilangan upahnya dari padanya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 1, 'Setelah Yesus selesai berpesan kepada kedua belas murid-Nya, pergilah Ia dari sana untuk mengajar dan memberitakan Injil di dalam kota-kota mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 2, 'Di dalam penjara Yohanes mendengar tentang pekerjaan Kristus,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 3, 'lalu menyuruh murid-muridnya bertanya kepada-Nya: "Engkaukah yang akan datang itu atau haruskah kami menantikan orang lain?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 4, 'Yesus menjawab mereka: "Pergilah dan katakanlah kepada Yohanes apa yang kamu dengar dan kamu lihat:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 5, 'orang buta melihat, orang lumpuh berjalan, orang kusta menjadi tahir, orang tuli mendengar, orang mati dibangkitkan dan kepada orang miskin diberitakan kabar baik.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 6, 'Dan berbahagialah orang yang tidak menjadi kecewa dan menolak Aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 7, 'Setelah murid-murid Yohanes pergi, mulailah Yesus berbicara kepada orang banyak itu tentang Yohanes: "Untuk apakah kamu pergi ke padang gurun? Melihat buluh yang digoyangkan angin kian ke mari?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 8, 'Atau untuk apakah kamu pergi? Melihat orang yang berpakaian halus? Orang yang berpakaian halus itu tempatnya di istana raja.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 9, 'Jadi untuk apakah kamu pergi? Melihat nabi? Benar, dan Aku berkata kepadamu, bahkan lebih dari pada nabi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 10, 'Karena tentang dia ada tertulis: Lihatlah, Aku menyuruh utusan-Ku mendahului Engkau, ia akan mempersiapkan jalan-Mu di hadapan-Mu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 11, 'Aku berkata kepadamu: Sesungguhnya di antara mereka yang dilahirkan oleh perempuan tidak pernah tampil seorang yang lebih besar dari pada Yohanes Pembaptis, namun yang terkecil dalam Kerajaan Sorga lebih besar dari padanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 12, 'Sejak tampilnya Yohanes Pembaptis hingga sekarang, Kerajaan Sorga diserong dan orang yang menyerongnya mencoba menguasainya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 13, 'Sebab semua nabi dan kitab Taurat bernubuat hingga tampilnya Yohanes', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 14, 'dan?jika kamu mau menerimanya?ialah Elia yang akan datang itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 15, 'Siapa bertelinga, hendaklah ia mendengar!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 16, 'Dengan apakah akan Kuumpamakan angkatan ini? Mereka itu seumpama anak-anak yang duduk di pasar dan berseru kepada teman-temannya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 17, 'Kami meniup seruling bagimu, tetapi kamu tidak menari, kami menyanyikan kidung duka, tetapi kamu tidak berkabung.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 18, 'Karena Yohanes datang, ia tidak makan, dan tidak minum, dan mereka berkata: Ia kerasukan setan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 19, 'Kemudian Anak Manusia datang, Ia makan dan minum, dan mereka berkata: Lihatlah, Ia seorang pelahap dan peminum, sahabat pemungut cukai dan orang berdosa. Tetapi hikmat Allah dibenarkan oleh perbuatannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 20, 'Lalu Yesus mulai mengecam kota-kota yang tidak bertobat, sekalipun di situ Ia paling banyak melakukan mujizat-mujizat-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 21, '"Celakalah engkau Khorazim! Celakalah engkau Betsaida! Karena jika di Tirus dan di Sidon terjadi mujizat-mujizat yang telah terjadi di tengah-tengah kamu, sudah lama mereka bertobat dan berkabung.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 22, 'Tetapi Aku berkata kepadamu: Pada hari penghakiman, tanggungan Tirus dan Sidon akan lebih ringan dari pada tanggunganmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 23, 'Dan engkau Kapernaum, apakah engkau akan dinaikkan sampai ke langit? Tidak, engkau akan diturunkan sampai ke dunia orang mati! Karena jika di Sodom terjadi mujizat-mujizat yang telah terjadi di tengah-tengah kamu, kota itu tentu masih berdiri sampai hari ini.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 24, 'Tetapi Aku berkata kepadamu: Pada hari penghakiman, tanggungan negeri Sodom akan lebih ringan dari pada tanggunganmu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 25, 'Pada waktu itu berkatalah Yesus: "Aku bersyukur kepada-Mu, Bapa, Tuhan langit dan bumi, karena semuanya itu Engkau sembunyikan bagi orang bijak dan orang pandai, tetapi Engkau nyatakan kepada orang kecil.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 26, 'Ya Bapa, itulah yang berkenan kepada-Mu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 27, 'Semua telah diserahkan kepada-Ku oleh Bapa-Ku dan tidak seorangpun mengenal Anak selain Bapa, dan tidak seorangpun mengenal Bapa selain Anak dan orang yang kepadanya Anak itu berkenan menyatakannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 28, 'Marilah kepada-Ku, semua yang letih lesu dan berbeban berat, Aku akan memberi kelegaan kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 29, 'Pikullah kuk yang Kupasang dan belajarlah pada-Ku, karena Aku lemah lembut dan rendah hati dan jiwamu akan mendapat ketenangan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 11, 30, 'Sebab kuk yang Kupasang itu enak dan beban-Kupun ringan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 1, 'Pada waktu itu, pada hari Sabat, Yesus berjalan di ladang gandum. Karena lapar, murid-murid-Nya memetik bulir gandum dan memakannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 2, 'Melihat itu, berkatalah orang-orang Farisi kepada-Nya: "Lihatlah, murid-murid-Mu berbuat sesuatu yang tidak diperbolehkan pada hari Sabat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 3, 'Tetapi jawab Yesus kepada mereka: "Tidakkah kamu baca apa yang dilakukan Daud, ketika ia dan mereka yang mengikutinya lapar,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 4, 'bagaimana ia masuk ke dalam Rumah Allah dan bagaimana mereka makan roti sajian yang tidak boleh dimakan, baik olehnya maupun oleh mereka yang mengikutinya, kecuali oleh imam-imam?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 5, 'Atau tidakkah kamu baca dalam kitab Taurat, bahwa pada hari-hari Sabat, imam-imam melanggar hukum Sabat di dalam Bait Allah, namun tidak bersalah?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 6, 'Aku berkata kepadamu: Di sini ada yang melebihi Bait Allah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 7, 'Jika memang kamu mengerti maksud firman ini: Yang Kukehendaki ialah belas kasihan dan bukan persembahan, tentu kamu tidak menghukum orang yang tidak bersalah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 8, 'Karena Anak Manusia adalah Tuhan atas hari Sabat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 9, 'Setelah pergi dari sana, Yesus masuk ke rumah ibadat mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 10, 'Di situ ada seorang yang mati sebelah tangannya. Mereka bertanya kepada-Nya: "Bolehkah menyembuhkan orang pada hari Sabat?" Maksud mereka ialah supaya dapat mempersalahkan Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 11, 'Tetapi Yesus berkata kepada mereka: "Jika seorang dari antara kamu mempunyai seekor domba dan domba itu terjatuh ke dalam lobang pada hari Sabat, tidakkah ia akan menangkapnya dan mengeluarkannya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 12, 'Bukankah manusia jauh lebih berharga dari pada domba? Karena itu boleh berbuat baik pada hari Sabat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 13, 'Lalu kata Yesus kepada orang itu: "Ulurkanlah tanganmu!" Dan ia mengulurkannya, maka pulihlah tangannya itu, dan menjadi sehat seperti tangannya yang lain.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 14, 'Lalu keluarlah orang-orang Farisi itu dan bersekongkol untuk membunuh Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 15, 'Tetapi Yesus mengetahui maksud mereka lalu menyingkir dari sana. (12-15b) Banyak orang mengikuti Yesus dan Ia menyembuhkan mereka semuanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 16, 'Ia dengan keras melarang mereka memberitahukan siapa Dia,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 17, 'supaya genaplah firman yang disampaikan oleh nabi Yesaya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 18, '"Lihatlah, itu Hamba-Ku yang Kupilih, yang Kukasihi, yang kepada-Nya jiwa-Ku berkenan; Aku akan menaruh roh-Ku ke atas-Nya, dan Ia akan memaklumkan hukum kepada bangsa-bangsa.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 19, 'Ia tidak akan berbantah dan tidak akan berteriak dan orang tidak akan mendengar suara-Nya di jalan-jalan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 20, 'Buluh yang patah terkulai tidak akan diputuskan-Nya, dan sumbu yang pudar nyalanya tidak akan dipadamkan-Nya, sampai Ia menjadikan hukum itu menang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 21, 'Dan pada-Nyalah bangsa-bangsa akan berharap."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 22, 'Kemudian dibawalah kepada Yesus seorang yang kerasukan setan. Orang itu buta dan bisu, lalu Yesus menyembuhkannya, sehingga si bisu itu berkata-kata dan melihat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 23, 'Maka takjublah sekalian orang banyak itu, katanya: "Ia ini agaknya Anak Daud."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 24, 'Tetapi ketika orang Farisi mendengarnya, mereka berkata: "Dengan Beelzebul, penghulu setan, Ia mengusir setan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 25, 'Tetapi Yesus mengetahui pikiran mereka lalu berkata kepada mereka: "Setiap kerajaan yang terpecah-pecah pasti binasa dan setiap kota atau rumah tangga yang terpecah-pecah tidak dapat bertahan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 26, 'Demikianlah juga kalau Iblis mengusir Iblis, iapun terbagi-bagi dan melawan dirinya sendiri; bagaimanakah kerajaannya dapat bertahan?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 27, 'Jadi jika Aku mengusir setan dengan kuasa Beelzebul, dengan kuasa siapakah pengikut-pengikutmu mengusirnya? Sebab itu merekalah yang akan menjadi hakimmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 28, 'Tetapi jika Aku mengusir setan dengan kuasa Roh Allah, maka sesungguhnya Kerajaan Allah sudah datang kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 29, 'Atau bagaimanakah orang dapat memasuki rumah seorang yang kuat dan merampas harta bendanya apabila tidak diikatnya dahulu orang kuat itu? Sesudah diikatnya barulah dapat ia merampok rumah itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 30, 'Siapa tidak bersama Aku, ia melawan Aku dan siapa tidak mengumpulkan bersama Aku, ia mencerai-beraikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 31, 'Sebab itu Aku berkata kepadamu: Segala dosa dan hujat manusia akan diampuni, tetapi hujat terhadap Roh Kudus tidak akan diampuni.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 32, 'Apabila seorang mengucapkan sesuatu menentang Anak Manusia, ia akan diampuni, tetapi jika ia menentang Roh Kudus, ia tidak akan diampuni, di dunia ini tidak, dan di dunia yang akan datangpun tidak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 33, 'Jikalau suatu pohon kamu katakan baik, maka baik pula buahnya; jikalau suatu pohon kamu katakan tidak baik, maka tidak baik pula buahnya. Sebab dari buahnya pohon itu dikenal.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 34, 'Hai kamu keturunan ular beludak, bagaimanakah kamu dapat mengucapkan hal-hal yang baik, sedangkan kamu sendiri jahat? Karena yang diucapkan mulut meluap dari hati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 35, 'Orang yang baik mengeluarkan hal-hal yang baik dari perbendaharaannya yang baik dan orang yang jahat mengeluarkan hal-hal yang jahat dari perbendaharaannya yang jahat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 36, 'Tetapi Aku berkata kepadamu: Setiap kata sia-sia yang diucapkan orang harus dipertanggungjawabkannya pada hari penghakiman.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 37, 'Karena menurut ucapanmu engkau akan dibenarkan, dan menurut ucapanmu pula engkau akan dihukum."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 38, 'Pada waktu itu berkatalah beberapa ahli Taurat dan orang Farisi kepada Yesus: "Guru, kami ingin melihat suatu tanda dari pada-Mu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 39, 'Tetapi jawab-Nya kepada mereka: "Angkatan yang jahat dan tidak setia ini menuntut suatu tanda. Tetapi kepada mereka tidak akan diberikan tanda selain tanda nabi Yunus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 40, 'Sebab seperti Yunus tinggal di dalam perut ikan tiga hari tiga malam, demikian juga Anak Manusia akan tinggal di dalam rahim bumi tiga hari tiga malam.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 41, 'Pada waktu penghakiman, orang-orang Niniwe akan bangkit bersama angkatan ini dan menghukumnya juga. Sebab orang-orang Niniwe itu bertobat setelah mendengar pemberitaan Yunus, dan sesungguhnya yang ada di sini lebih dari pada Yunus!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 42, 'Pada waktu penghakiman, ratu dari Selatan itu akan bangkit bersama angkatan ini dan ia akan menghukumnya juga. Sebab ratu ini datang dari ujung bumi untuk mendengar hikmat Salomo, dan sesungguhnya yang ada di sini lebih dari pada Salomo!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 43, '"Apabila roh jahat keluar dari manusia, iapun mengembara ke tempat-tempat yang tandus mencari perhentian. Tetapi ia tidak mendapatnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 44, 'Lalu ia berkata: Aku akan kembali ke rumah yang telah kutinggalkan itu. Maka pergilah ia dan mendapati rumah itu kosong, bersih tersapu dan rapih teratur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 45, 'Lalu ia keluar dan mengajak tujuh roh lain yang lebih jahat dari padanya dan mereka masuk dan berdiam di situ. Maka akhirnya keadaan orang itu lebih buruk dari pada keadaannya semula. Demikian juga akan berlaku atas angkatan yang jahat ini."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 46, 'Ketika Yesus masih berbicara dengan orang banyak itu, ibu-Nya dan saudara-saudara-Nya berdiri di luar dan berusaha menemui Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 47, 'Maka seorang berkata kepada-Nya: "Lihatlah, ibu-Mu dan saudara-saudara-Mu ada di luar dan berusaha menemui Engkau."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 48, 'Tetapi jawab Yesus kepada orang yang menyampaikan berita itu kepada-Nya: "Siapa ibu-Ku? Dan siapa saudara-saudara-Ku?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 49, 'Lalu kata-Nya, sambil menunjuk ke arah murid-murid-Nya: "Ini ibu-Ku dan saudara-saudara-Ku!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 12, 50, 'Sebab siapapun yang melakukan kehendak Bapa-Ku di sorga, dialah saudara-Ku laki-laki, dialah saudara-Ku perempuan, dialah ibu-Ku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 1, 'Pada hari itu keluarlah Yesus dari rumah itu dan duduk di tepi danau.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 2, 'Maka datanglah orang banyak berbondong-bondong lalu mengerumuni Dia, sehingga Ia naik ke perahu dan duduk di situ, sedangkan orang banyak semuanya berdiri di pantai.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 3, 'Dan Ia mengucapkan banyak hal dalam perumpamaan kepada mereka. Kata-Nya: "Adalah seorang penabur keluar untuk menabur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 4, 'Pada waktu ia menabur, sebagian benih itu jatuh di pinggir jalan, lalu datanglah burung dan memakannya sampai habis.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 5, 'Sebagian jatuh di tanah yang berbatu-batu, yang tidak banyak tanahnya, lalu benih itupun segera tumbuh, karena tanahnya tipis.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 6, 'Tetapi sesudah matahari terbit, layulah ia dan menjadi kering karena tidak berakar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 7, 'Sebagian lagi jatuh di tengah semak duri, lalu makin besarlah semak itu dan menghimpitnya sampai mati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 8, 'Dan sebagian jatuh di tanah yang baik lalu berbuah: ada yang seratus kali lipat, ada yang enam puluh kali lipat, ada yang tiga puluh kali lipat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 9, 'Siapa bertelinga, hendaklah ia mendengar!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 10, 'Maka datanglah murid-murid-Nya dan bertanya kepada-Nya: "Mengapa Engkau berkata-kata kepada mereka dalam perumpamaan?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 11, 'Jawab Yesus: "Kepadamu diberi karunia untuk mengetahui rahasia Kerajaan Sorga, tetapi kepada mereka tidak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 12, 'Karena siapa yang mempunyai, kepadanya akan diberi, sehingga ia berkelimpahan; tetapi siapa yang tidak mempunyai, apapun juga yang ada padanya akan diambil dari padanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 13, 'Itulah sebabnya Aku berkata-kata dalam perumpamaan kepada mereka; karena sekalipun melihat, mereka tidak melihat dan sekalipun mendengar, mereka tidak mendengar dan tidak mengerti.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 14, 'Maka pada mereka genaplah nubuat Yesaya, yang berbunyi: Kamu akan mendengar dan mendengar, namun tidak mengerti, kamu akan melihat dan melihat, namun tidak menanggap.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 15, 'Sebab hati bangsa ini telah menebal, dan telinganya berat mendengar, dan matanya melekat tertutup; supaya jangan mereka melihat dengan matanya dan mendengar dengan telinganya dan mengerti dengan hatinya, lalu berbalik sehingga Aku menyembuhkan mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 16, 'Tetapi berbahagialah matamu karena melihat dan telingamu karena mendengar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 17, 'Sebab Aku berkata kepadamu: Sesungguhnya banyak nabi dan orang benar ingin melihat apa yang kamu lihat, tetapi tidak melihatnya, dan ingin mendengar apa yang kamu dengar, tetapi tidak mendengarnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 18, 'Karena itu, dengarlah arti perumpamaan penabur itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 19, 'Kepada setiap orang yang mendengar firman tentang Kerajaan Sorga, tetapi tidak mengertinya, datanglah si jahat dan merampas yang ditaburkan dalam hati orang itu; itulah benih yang ditaburkan di pinggir jalan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 20, 'Benih yang ditaburkan di tanah yang berbatu-batu ialah orang yang mendengar firman itu dan segera menerimanya dengan gembira.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 21, 'Tetapi ia tidak berakar dan tahan sebentar saja. Apabila datang penindasan atau penganiayaan karena firman itu, orang itupun segera murtad.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 22, 'Yang ditaburkan di tengah semak duri ialah orang yang mendengar firman itu, lalu kekuatiran dunia ini dan tipu daya kekayaan menghimpit firman itu sehingga tidak berbuah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 23, 'Yang ditaburkan di tanah yang baik ialah orang yang mendengar firman itu dan mengerti, dan karena itu ia berbuah, ada yang seratus kali lipat, ada yang enam puluh kali lipat, ada yang tiga puluh kali lipat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 24, 'Yesus membentangkan suatu perumpamaan lain lagi kepada mereka, kata-Nya: "Hal Kerajaan Sorga itu seumpama orang yang menaburkan benih yang baik di ladangnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 25, 'Tetapi pada waktu semua orang tidur, datanglah musuhnya menaburkan benih lalang di antara gandum itu, lalu pergi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 26, 'Ketika gandum itu tumbuh dan mulai berbulir, nampak jugalah lalang itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 27, 'Maka datanglah hamba-hamba tuan ladang itu kepadanya dan berkata: Tuan, bukankah benih baik, yang tuan taburkan di ladang tuan? Dari manakah lalang itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 28, 'Jawab tuan itu: Seorang musuh yang melakukannya. Lalu berkatalah hamba-hamba itu kepadanya: Jadi maukah tuan supaya kami pergi mencabut lalang itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 29, 'Tetapi ia berkata: Jangan, sebab mungkin gandum itu ikut tercabut pada waktu kamu mencabut lalang itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 30, 'Biarkanlah keduanya tumbuh bersama sampai waktu menuai. Pada waktu itu aku akan berkata kepada para penuai: Kumpulkanlah dahulu lalang itu dan ikatlah berberkas-berkas untuk dibakar; kemudian kumpulkanlah gandum itu ke dalam lumbungku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 31, 'Yesus membentangkan suatu perumpamaan lain lagi kepada mereka, kata-Nya: "Hal Kerajaan Sorga itu seumpama biji sesawi, yang diambil dan ditaburkan orang di ladangnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 32, 'Memang biji itu yang paling kecil dari segala jenis benih, tetapi apabila sudah tumbuh, sesawi itu lebih besar dari pada sayuran yang lain, bahkan menjadi pohon, sehingga burung-burung di udara datang bersarang pada cabang-cabangnya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 33, 'Dan Ia menceriterakan perumpamaan ini juga kepada mereka: "Hal Kerajaan Sorga itu seumpama ragi yang diambil seorang perempuan dan diadukkan ke dalam tepung terigu tiga sukat sampai khamir seluruhnya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 34, 'Semuanya itu disampaikan Yesus kepada orang banyak dalam perumpamaan, dan tanpa perumpamaan suatupun tidak disampaikan-Nya kepada mereka,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 35, 'supaya genaplah firman yang disampaikan oleh nabi: "Aku mau membuka mulut-Ku mengatakan perumpamaan, Aku mau mengucapkan hal yang tersembunyi sejak dunia dijadikan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 36, 'Maka Yesuspun meninggalkan orang banyak itu, lalu pulang. Murid-murid-Nya datang dan berkata kepada-Nya: "Jelaskanlah kepada kami perumpamaan tentang lalang di ladang itu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 37, 'Ia menjawab, kata-Nya: "Orang yang menaburkan benih baik ialah Anak Manusia;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 38, 'ladang ialah dunia. Benih yang baik itu anak-anak Kerajaan dan lalang anak-anak si jahat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 39, 'Musuh yang menaburkan benih lalang ialah Iblis. Waktu menuai ialah akhir zaman dan para penuai itu malaikat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 40, 'Maka seperti lalang itu dikumpulkan dan dibakar dalam api, demikian juga pada akhir zaman.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 41, 'Anak Manusia akan menyuruh malaikat-malaikat-Nya dan mereka akan mengumpulkan segala sesuatu yang menyesatkan dan semua orang yang melakukan kejahatan dari dalam Kerajaan-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 42, 'Semuanya akan dicampakkan ke dalam dapur api; di sanalah akan terdapat ratapan dan kertakan gigi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 43, 'Pada waktu itulah orang-orang benar akan bercahaya seperti matahari dalam Kerajaan Bapa mereka. Siapa bertelinga, hendaklah ia mendengar!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 44, '"Hal Kerajaan Sorga itu seumpama harta yang terpendam di ladang, yang ditemukan orang, lalu dipendamkannya lagi. Oleh sebab sukacitanya pergilah ia menjual seluruh miliknya lalu membeli ladang itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 45, 'Demikian pula hal Kerajaan Sorga itu seumpama seorang pedagang yang mencari mutiara yang indah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 46, 'Setelah ditemukannya mutiara yang sangat berharga, iapun pergi menjual seluruh miliknya lalu membeli mutiara itu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 47, '"Demikian pula hal Kerajaan Sorga itu seumpama pukat yang dilabuhkan di laut, lalu mengumpulkan berbagai-bagai jenis ikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 48, 'Setelah penuh, pukat itupun diseret orang ke pantai, lalu duduklah mereka dan mengumpulkan ikan yang baik ke dalam pasu dan ikan yang tidak baik mereka buang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 49, 'Demikianlah juga pada akhir zaman: Malaikat-malaikat akan datang memisahkan orang jahat dari orang benar,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 50, 'lalu mencampakkan orang jahat ke dalam dapur api; di sanalah akan terdapat ratapan dan kertakan gigi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 51, 'Mengertikah kamu semuanya itu?" Mereka menjawab: "Ya, kami mengerti."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 52, 'Maka berkatalah Yesus kepada mereka: "Karena itu setiap ahli Taurat yang menerima pelajaran dari hal Kerajaan Sorga itu seumpama tuan rumah yang mengeluarkan harta yang baru dan yang lama dari perbendaharaannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 53, 'Setelah Yesus selesai menceriterakan perumpamaan-perumpamaan itu, Iapun pergi dari situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 54, 'Setibanya di tempat asal-Nya, Yesus mengajar orang-orang di situ di rumah ibadat mereka. Maka takjublah mereka dan berkata: "Dari mana diperoleh-Nya hikmat itu dan kuasa untuk mengadakan mujizat-mujizat itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 55, 'Bukankah Ia ini anak tukang kayu? Bukankah ibu-Nya bernama Maria dan saudara-saudara-Nya: Yakobus, Yusuf, Simon dan Yudas?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 56, 'Dan bukankah saudara-saudara-Nya perempuan semuanya ada bersama kita? Jadi dari mana diperoleh-Nya semuanya itu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 57, 'Lalu mereka kecewa dan menolak Dia. Maka Yesus berkata kepada mereka: "Seorang nabi dihormati di mana-mana, kecuali di tempat asalnya sendiri dan di rumahnya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 13, 58, 'Dan karena ketidakpercayaan mereka, tidak banyak mujizat diadakan-Nya di situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 1, 'Pada masa itu sampailah berita-berita tentang Yesus kepada Herodes, raja wilayah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 2, 'Lalu ia berkata kepada pegawai-pegawainya: "Inilah Yohanes Pembaptis; ia sudah bangkit dari antara orang mati dan itulah sebabnya kuasa-kuasa itu bekerja di dalam-Nya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 3, 'Sebab memang Herodes telah menyuruh menangkap Yohanes, membelenggunya dan memenjarakannya, berhubung dengan peristiwa Herodias, isteri Filipus saudaranya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 4, 'Karena Yohanes pernah menegornya, katanya: "Tidak halal engkau mengambil Herodias!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 5, 'Herodes ingin membunuhnya, tetapi ia takut akan orang banyak yang memandang Yohanes sebagai nabi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 6, 'Tetapi pada hari ulang tahun Herodes, menarilah anak perempuan Herodias di tengah-tengah mereka dan menyukakan hati Herodes,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 7, 'sehingga Herodes bersumpah akan memberikan kepadanya apa saja yang dimintanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 8, 'Maka setelah dihasut oleh ibunya, anak perempuan itu berkata: "Berikanlah aku di sini kepala Yohanes Pembaptis di sebuah talam."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 9, 'Lalu sedihlah hati raja, tetapi karena sumpahnya dan karena tamu-tamunya diperintahkannya juga untuk memberikannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 10, 'Disuruhnya memenggal kepala Yohanes di penjara', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 11, 'dan kepala Yohanes itupun dibawa orang di sebuah talam, lalu diberikan kepada gadis itu dan ia membawanya kepada ibunya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 12, 'Kemudian datanglah murid-murid Yohanes Pembaptis mengambil mayatnya dan menguburkannya. Lalu pergilah mereka memberitahukannya kepada Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 13, 'Setelah Yesus mendengar berita itu menyingkirlah Ia dari situ, dan hendak mengasingkan diri dengan perahu ke tempat yang sunyi. Tetapi orang banyak mendengarnya dan mengikuti Dia dengan mengambil jalan darat dari kota-kota mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 14, 'Ketika Yesus mendarat, Ia melihat orang banyak yang besar jumlahnya, maka tergeraklah hati-Nya oleh belas kasihan kepada mereka dan Ia menyembuhkan mereka yang sakit.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 15, 'Menjelang malam, murid-murid-Nya datang kepada-Nya dan berkata: "Tempat ini sunyi dan hari sudah mulai malam. Suruhlah orang banyak itu pergi supaya mereka dapat membeli makanan di desa-desa."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 16, 'Tetapi Yesus berkata kepada mereka: "Tidak perlu mereka pergi, kamu harus memberi mereka makan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 17, 'Jawab mereka: "Yang ada pada kami di sini hanya lima roti dan dua ikan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 18, 'Yesus berkata: "Bawalah ke mari kepada-Ku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 19, 'Lalu disuruh-Nya orang banyak itu duduk di rumput. Dan setelah diambil-Nya lima roti dan dua ikan itu, Yesus menengadah ke langit dan mengucap berkat, lalu memecah-mecahkan roti itu dan memberikannya kepada murid-murid-Nya, lalu murid-murid-Nya membagi-bagikannya kepada orang banyak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 20, 'Dan mereka semuanya makan sampai kenyang. Kemudian orang mengumpulkan potongan-potongan roti yang sisa, dua belas bakul penuh.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 21, 'Yang ikut makan kira-kira lima ribu laki-laki, tidak termasuk perempuan dan anak-anak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 22, 'Sesudah itu Yesus segera memerintahkan murid-murid-Nya naik ke perahu dan mendahului-Nya ke seberang, sementara itu Ia menyuruh orang banyak pulang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 23, 'Dan setelah orang banyak itu disuruh-Nya pulang, Yesus naik ke atas bukit untuk berdoa seorang diri. Ketika hari sudah malam, Ia sendirian di situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 24, 'Perahu murid-murid-Nya sudah beberapa mil jauhnya dari pantai dan diombang-ambingkan gelombang, karena angin sakal.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 25, 'Kira-kira jam tiga malam datanglah Yesus kepada mereka berjalan di atas air.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 26, 'Ketika murid-murid-Nya melihat Dia berjalan di atas air, mereka terkejut dan berseru: "Itu hantu!", lalu berteriak-teriak karena takut.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 27, 'Tetapi segera Yesus berkata kepada mereka: "Tenanglah! Aku ini, jangan takut!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 28, 'Lalu Petrus berseru dan menjawab Dia: "Tuhan, apabila Engkau itu, suruhlah aku datang kepada-Mu berjalan di atas air."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 29, 'Kata Yesus: "Datanglah!" Maka Petrus turun dari perahu dan berjalan di atas air mendapatkan Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 30, 'Tetapi ketika dirasanya tiupan angin, takutlah ia dan mulai tenggelam lalu berteriak: "Tuhan, tolonglah aku!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 31, 'Segera Yesus mengulurkan tangan-Nya, memegang dia dan berkata: "Hai orang yang kurang percaya, mengapa engkau bimbang?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 32, 'Lalu mereka naik ke perahu dan anginpun redalah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 33, 'Dan orang-orang yang ada di perahu menyembah Dia, katanya: "Sesungguhnya Engkau Anak Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 34, 'Setibanya di seberang mereka mendarat di Genesaret.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 35, 'Ketika Yesus dikenal oleh orang-orang di tempat itu, mereka memberitahukannya ke seluruh daerah itu. Maka semua orang yang sakit dibawa kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 14, 36, 'Mereka memohon supaya diperkenankan menjamah jumbai jubah-Nya. Dan semua orang yang menjamah-Nya menjadi sembuh.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 1, 'Kemudian datanglah beberapa orang Farisi dan ahli Taurat dari Yerusalem kepada Yesus dan berkata:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 2, '"Mengapa murid-murid-Mu melanggar adat istiadat nenek moyang kita? Mereka tidak membasuh tangan sebelum makan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 3, 'Tetapi jawab Yesus kepada mereka: "Mengapa kamupun melanggar perintah Allah demi adat istiadat nenek moyangmu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 4, 'Sebab Allah berfirman: Hormatilah ayahmu dan ibumu; dan lagi: Siapa yang mengutuki ayahnya atau ibunya pasti dihukum mati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 5, 'Tetapi kamu berkata: Barangsiapa berkata kepada bapanya atau kepada ibunya: Apa yang ada padaku yang dapat digunakan untuk pemeliharaanmu, sudah digunakan untuk persembahan kepada Allah,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 6, 'orang itu tidak wajib lagi menghormati bapanya atau ibunya. Dengan demikian firman Allah kamu nyatakan tidak berlaku demi adat istiadatmu sendiri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 7, 'Hai orang-orang munafik! Benarlah nubuat Yesaya tentang kamu:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 8, 'Bangsa ini memuliakan Aku dengan bibirnya, padahal hatinya jauh dari pada-Ku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 9, 'Percuma mereka beribadah kepada-Ku, sedangkan ajaran yang mereka ajarkan ialah perintah manusia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 10, 'Lalu Yesus memanggil orang banyak dan berkata kepada mereka:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 11, '"Dengar dan camkanlah: bukan yang masuk ke dalam mulut yang menajiskan orang, melainkan yang keluar dari mulut, itulah yang menajiskan orang."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 12, 'Maka datanglah murid-murid-Nya dan bertanya kepada-Nya: "Engkau tahu bahwa perkataan-Mu itu telah menjadi batu sandungan bagi orang-orang Farisi?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 13, 'Jawab Yesus: "Setiap tanaman yang tidak ditanam oleh Bapa-Ku yang di sorga akan dicabut dengan akar-akarnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 14, 'Biarkanlah mereka itu. Mereka orang buta yang menuntun orang buta. Jika orang buta menuntun orang buta, pasti keduanya jatuh ke dalam lobang."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 15, 'Lalu Petrus berkata kepada-Nya: "Jelaskanlah perumpamaan itu kepada kami."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 16, 'Jawab Yesus: "Kamupun masih belum dapat memahaminya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 17, 'Tidak tahukah kamu bahwa segala sesuatu yang masuk ke dalam mulut turun ke dalam perut lalu dibuang di jamban?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 18, 'Tetapi apa yang keluar dari mulut berasal dari hati dan itulah yang menajiskan orang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 19, 'Karena dari hati timbul segala pikiran jahat, pembunuhan, perzinahan, percabulan, pencurian, sumpah palsu dan hujat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 20, 'Itulah yang menajiskan orang. Tetapi makan dengan tangan yang tidak dibasuh tidak menajiskan orang."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 21, 'Lalu Yesus pergi dari situ dan menyingkir ke daerah Tirus dan Sidon.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 22, 'Maka datanglah seorang perempuan Kanaan dari daerah itu dan berseru: "Kasihanilah aku, ya Tuhan, Anak Daud, karena anakku perempuan kerasukan setan dan sangat menderita."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 23, 'Tetapi Yesus sama sekali tidak menjawabnya. Lalu murid-murid-Nya datang dan meminta kepada-Nya: "Suruhlah ia pergi, ia mengikuti kita dengan berteriak-teriak."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 24, 'Jawab Yesus: "Aku diutus hanya kepada domba-domba yang hilang dari umat Israel."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 25, 'Tetapi perempuan itu mendekat dan menyembah Dia sambil berkata: "Tuhan, tolonglah aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 26, 'Tetapi Yesus menjawab: "Tidak patut mengambil roti yang disediakan bagi anak-anak dan melemparkannya kepada anjing."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 27, 'Kata perempuan itu: "Benar Tuhan, namun anjing itu makan remah-remah yang jatuh dari meja tuannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 28, 'Maka Yesus menjawab dan berkata kepadanya: "Hai ibu, besar imanmu, maka jadilah kepadamu seperti yang kaukehendaki." Dan seketika itu juga anaknya sembuh.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 29, 'Setelah meninggalkan daerah itu, Yesus menyusur pantai danau Galilea dan naik ke atas bukit lalu duduk di situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 30, 'Kemudian orang banyak berbondong-bondong datang kepada-Nya membawa orang lumpuh, orang timpang, orang buta, orang bisu dan banyak lagi yang lain, lalu meletakkan mereka pada kaki Yesus dan Ia menyembuhkan mereka semuanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 31, 'Maka takjublah orang banyak itu melihat orang bisu berkata-kata, orang timpang sembuh, orang lumpuh berjalan, orang buta melihat, dan mereka memuliakan Allah Israel.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 32, 'Lalu Yesus memanggil murid-murid-Nya dan berkata: "Hati-Ku tergerak oleh belas kasihan kepada orang banyak itu. Sudah tiga hari mereka mengikuti Aku dan mereka tidak mempunyai makanan. Aku tidak mau menyuruh mereka pulang dengan lapar, nanti mereka pingsan di jalan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 33, 'Kata murid-murid-Nya kepada-Nya: "Bagaimana di tempat sunyi ini kita mendapat roti untuk mengenyangkan orang banyak yang begitu besar jumlahnya?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 34, 'Kata Yesus kepada mereka: "Berapa roti ada padamu?" "Tujuh," jawab mereka, "dan ada lagi beberapa ikan kecil."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 35, 'Lalu Yesus menyuruh orang banyak itu duduk di tanah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 36, 'Sesudah itu Ia mengambil ketujuh roti dan ikan-ikan itu, mengucap syukur, memecah-mecahkannya dan memberikannya kepada murid-murid-Nya, lalu murid-murid-Nya memberikannya pula kepada orang banyak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 37, 'Dan mereka semuanya makan sampai kenyang. Kemudian orang mengumpulkan potongan-potongan roti yang sisa, tujuh bakul penuh.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 38, 'Yang ikut makan ialah empat ribu laki-laki, tidak termasuk perempuan dan anak-anak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 15, 39, 'Lalu Yesus menyuruh orang banyak itu pulang. Ia naik perahu dan bertolak ke daerah Magadan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 1, 'Kemudian datanglah orang-orang Farisi dan Saduki hendak mencobai Yesus. Mereka meminta supaya Ia memperlihatkan suatu tanda dari sorga kepada mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 2, 'Tetapi jawab Yesus: "Pada petang hari karena langit merah, kamu berkata: Hari akan cerah,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 3, 'dan pada pagi hari, karena langit merah dan redup, kamu berkata: Hari buruk. Rupa langit kamu tahu membedakannya tetapi tanda-tanda zaman tidak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 4, 'Angkatan yang jahat dan tidak setia ini menuntut suatu tanda. Tetapi kepada mereka tidak akan diberikan tanda selain tanda nabi Yunus." Lalu Yesus meninggalkan mereka dan pergi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 5, 'Pada waktu murid-murid Yesus menyeberang danau, mereka lupa membawa roti.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 6, 'Yesus berkata kepada mereka: "Berjaga-jagalah dan waspadalah terhadap ragi orang Farisi dan Saduki."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 7, 'Maka mereka berpikir-pikir dan seorang berkata kepada yang lain: "Itu dikatakan-Nya karena kita tidak membawa roti."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 8, 'Dan ketika Yesus mengetahui apa yang mereka perbincangkan, Ia berkata: "Mengapa kamu memperbincangkan soal tidak ada roti? Hai orang-orang yang kurang percaya!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 9, 'Belum juga kamu mengerti? Tidak kamu ingat lagi akan lima roti untuk lima ribu orang itu dan berapa bakul roti kamu kumpulkan kemudian?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 10, 'Ataupun akan tujuh roti untuk empat ribu orang itu dan berapa bakul kamu kumpulkan kemudian?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 11, 'Bagaimana mungkin kamu tidak mengerti bahwa bukan roti yang Kumaksudkan. Aku berkata kepadamu: Waspadalah terhadap ragi orang Farisi dan Saduki."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 12, 'Ketika itu barulah mereka mengerti bahwa bukan maksud-Nya supaya mereka waspada terhadap ragi roti, melainkan terhadap ajaran orang Farisi dan Saduki.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 13, 'Setelah Yesus tiba di daerah Kaisarea Filipi, Ia bertanya kepada murid-murid-Nya: "Kata orang, siapakah Anak Manusia itu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 14, 'Jawab mereka: "Ada yang mengatakan: Yohanes Pembaptis, ada juga yang mengatakan: Elia dan ada pula yang mengatakan: Yeremia atau salah seorang dari para nabi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 15, 'Lalu Yesus bertanya kepada mereka: "Tetapi apa katamu, siapakah Aku ini?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 16, 'Maka jawab Simon Petrus: "Engkau adalah Mesias, Anak Allah yang hidup!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 17, 'Kata Yesus kepadanya: "Berbahagialah engkau Simon bin Yunus sebab bukan manusia yang menyatakan itu kepadamu, melainkan Bapa-Ku yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 18, 'Dan Akupun berkata kepadamu: Engkau adalah Petrus dan di atas batu karang ini Aku akan mendirikan jemaat-Ku dan alam maut tidak akan menguasainya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 19, 'Kepadamu akan Kuberikan kunci Kerajaan Sorga. Apa yang kauikat di dunia ini akan terikat di sorga dan apa yang kaulepaskan di dunia ini akan terlepas di sorga."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 20, 'Lalu Yesus melarang murid-murid-Nya supaya jangan memberitahukan kepada siapapun bahwa Ia Mesias.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 21, 'Sejak waktu itu Yesus mulai menyatakan kepada murid-murid-Nya bahwa Ia harus pergi ke Yerusalem dan menanggung banyak penderitaan dari pihak tua-tua, imam-imam kepala dan ahli-ahli Taurat, lalu dibunuh dan dibangkitkan pada hari ketiga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 22, 'Tetapi Petrus menarik Yesus ke samping dan menegor Dia, katanya: "Tuhan, kiranya Allah menjauhkan hal itu! Hal itu sekali-kali takkan menimpa Engkau."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 23, 'Maka Yesus berpaling dan berkata kepada Petrus: "Enyahlah Iblis. Engkau suatu batu sandungan bagi-Ku, sebab engkau bukan memikirkan apa yang dipikirkan Allah, melainkan apa yang dipikirkan manusia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 24, 'Lalu Yesus berkata kepada murid-murid-Nya: "Setiap orang yang mau mengikut Aku, ia harus menyangkal dirinya, memikul salibnya dan mengikut Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 25, 'Karena barangsiapa mau menyelamatkan nyawanya, ia akan kehilangan nyawanya; tetapi barangsiapa kehilangan nyawanya karena Aku, ia akan memperolehnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 26, 'Apa gunanya seorang memperoleh seluruh dunia tetapi kehilangan nyawanya? Dan apakah yang dapat diberikannya sebagai ganti nyawanya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 27, 'Sebab Anak Manusia akan datang dalam kemuliaan Bapa-Nya diiringi malaikat-malaikat-Nya; pada waktu itu Ia akan membalas setiap orang menurut perbuatannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 16, 28, 'Aku berkata kepadamu: Sesungguhnya di antara orang yang hadir di sini ada yang tidak akan mati sebelum mereka melihat Anak Manusia datang sebagai Raja dalam Kerajaan-Nya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 1, 'Enam hari kemudian Yesus membawa Petrus, Yakobus dan Yohanes saudaranya, dan bersama-sama dengan mereka Ia naik ke sebuah gunung yang tinggi. Di situ mereka sendiri saja.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 2, 'Lalu Yesus berubah rupa di depan mata mereka; wajah-Nya bercahaya seperti matahari dan pakaian-Nya menjadi putih bersinar seperti terang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 3, 'Maka nampak kepada mereka Musa dan Elia sedang berbicara dengan Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 4, 'Kata Petrus kepada Yesus: "Tuhan, betapa bahagianya kami berada di tempat ini. Jika Engkau mau, biarlah kudirikan di sini tiga kemah, satu untuk Engkau, satu untuk Musa dan satu untuk Elia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 5, 'Dan tiba-tiba sedang ia berkata-kata turunlah awan yang terang menaungi mereka dan dari dalam awan itu terdengar suara yang berkata: "Inilah Anak yang Kukasihi, kepada-Nyalah Aku berkenan, dengarkanlah Dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 6, 'Mendengar itu tersungkurlah murid-murid-Nya dan mereka sangat ketakutan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 7, 'Lalu Yesus datang kepada mereka dan menyentuh mereka sambil berkata: "Berdirilah, jangan takut!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 8, 'Dan ketika mereka mengangkat kepala, mereka tidak melihat seorangpun kecuali Yesus seorang diri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 9, 'Pada waktu mereka turun dari gunung itu, Yesus berpesan kepada mereka: "Jangan kamu ceriterakan penglihatan itu kepada seorangpun sebelum Anak Manusia dibangkitkan dari antara orang mati."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 10, 'Lalu murid-murid-Nya bertanya kepada-Nya: "Kalau demikian mengapa ahli-ahli Taurat berkata bahwa Elia harus datang dahulu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 11, 'Jawab Yesus: "Memang Elia akan datang dan memulihkan segala sesuatu', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 12, 'dan Aku berkata kepadamu: Elia sudah datang, tetapi orang tidak mengenal dia, dan memperlakukannya menurut kehendak mereka. Demikian juga Anak Manusia akan menderita oleh mereka."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 13, 'Pada waktu itu mengertilah murid-murid Yesus bahwa Ia berbicara tentang Yohanes Pembaptis.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 14, 'Ketika Yesus dan murid-murid-Nya kembali kepada orang banyak itu, datanglah seorang mendapatkan Yesus dan menyembah,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 15, 'katanya: "Tuhan, kasihanilah anakku. Ia sakit ayan dan sangat menderita. Ia sering jatuh ke dalam api dan juga sering ke dalam air.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 16, 'Aku sudah membawanya kepada murid-murid-Mu, tetapi mereka tidak dapat menyembuhkannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 17, 'Maka kata Yesus: "Hai kamu angkatan yang tidak percaya dan yang sesat, berapa lama lagi Aku harus tinggal di antara kamu? Berapa lama lagi Aku harus sabar terhadap kamu? Bawalah anak itu ke mari!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 18, 'Dengan keras Yesus menegor dia, lalu keluarlah setan itu dari padanya dan anak itupun sembuh seketika itu juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 19, 'Kemudian murid-murid Yesus datang dan ketika mereka sendirian dengan Dia, bertanyalah mereka: "Mengapa kami tidak dapat mengusir setan itu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 20, 'Ia berkata kepada mereka: "Karena kamu kurang percaya. Sebab Aku berkata kepadamu: Sesungguhnya sekiranya kamu mempunyai iman sebesar biji sesawi saja kamu dapat berkata kepada gunung ini: Pindah dari tempat ini ke sana, ?maka gunung ini akan pindah, dan takkan ada yang mustahil bagimu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 21, '(Jenis ini tidak dapat diusir kecuali dengan berdoa dan berpuasa.)"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 22, 'Pada waktu Yesus dan murid-murid-Nya bersama-sama di Galilea, Ia berkata kepada mereka: "Anak Manusia akan diserahkan ke dalam tangan manusia', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 23, 'dan mereka akan membunuh Dia dan pada hari ketiga Ia akan dibangkitkan." Maka hati murid-murid-Nya itupun sedih sekali.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 24, 'Ketika Yesus dan murid-murid-Nya tiba di Kapernaum datanglah pemungut bea Bait Allah kepada Petrus dan berkata: "Apakah gurumu tidak membayar bea dua dirham itu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 25, 'Jawabnya: "Memang membayar." Dan ketika Petrus masuk rumah, Yesus mendahuluinya dengan pertanyaan: "Apakah pendapatmu, Simon? Dari siapakah raja-raja dunia ini memungut bea dan pajak? Dari rakyatnya atau dari orang asing?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 26, 'Jawab Petrus: "Dari orang asing!" Maka kata Yesus kepadanya: "Jadi bebaslah rakyatnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 17, 27, 'Tetapi supaya jangan kita menjadi batu sandungan bagi mereka, pergilah memancing ke danau. Dan ikan pertama yang kaupancing, tangkaplah dan bukalah mulutnya, maka engkau akan menemukan mata uang empat dirham di dalamnya. Ambillah itu dan bayarkanlah kepada mereka, bagi-Ku dan bagimu juga."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 1, 'Pada waktu itu datanglah murid-murid itu kepada Yesus dan bertanya: "Siapakah yang terbesar dalam Kerajaan Sorga?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 2, 'Maka Yesus memanggil seorang anak kecil dan menempatkannya di tengah-tengah mereka', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 3, 'lalu berkata: "Aku berkata kepadamu, sesungguhnya jika kamu tidak bertobat dan menjadi seperti anak kecil ini, kamu tidak akan masuk ke dalam Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 4, 'Sedangkan barangsiapa merendahkan diri dan menjadi seperti anak kecil ini, dialah yang terbesar dalam Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 5, 'Dan barangsiapa menyambut seorang anak seperti ini dalam nama-Ku, ia menyambut Aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 6, '"Tetapi barangsiapa menyesatkan salah satu dari anak-anak kecil ini yang percaya kepada-Ku, lebih baik baginya jika sebuah batu kilangan diikatkan pada lehernya lalu ia ditenggelamkan ke dalam laut.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 7, 'Celakalah dunia dengan segala penyesatannya: memang penyesatan harus ada, tetapi celakalah orang yang mengadakannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 8, 'Jika tanganmu atau kakimu menyesatkan engkau, penggallah dan buanglah itu, karena lebih baik bagimu masuk ke dalam hidup dengan tangan kudung atau timpang dari pada dengan utuh kedua tangan dan kedua kakimu dicampakkan ke dalam api kekal.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 9, 'Dan jika matamu menyesatkan engkau, cungkillah dan buanglah itu, karena lebih baik bagimu masuk ke dalam hidup dengan bermata satu dari pada dicampakkan ke dalam api neraka dengan bermata dua.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 10, 'Ingatlah, jangan menganggap rendah seorang dari anak-anak kecil ini. Karena Aku berkata kepadamu: Ada malaikat mereka di sorga yang selalu memandang wajah Bapa-Ku yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 11, '(Karena Anak Manusia datang untuk menyelamatkan yang hilang.)"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 12, '"Bagaimana pendapatmu? Jika seorang mempunyai seratus ekor domba, dan seekor di antaranya sesat, tidakkah ia akan meninggalkan yang sembilan puluh sembilan ekor di pegunungan dan pergi mencari yang sesat itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 13, 'Dan Aku berkata kepadamu: Sesungguhnya jika ia berhasil menemukannya, lebih besar kegembiraannya atas yang seekor itu dari pada atas yang kesembilan puluh sembilan ekor yang tidak sesat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 14, 'Demikian juga Bapamu yang di sorga tidak menghendaki supaya seorangpun dari anak-anak ini hilang."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 15, '"Apabila saudaramu berbuat dosa, tegorlah dia di bawah empat mata. Jika ia mendengarkan nasihatmu engkau telah mendapatnya kembali.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 16, 'Jika ia tidak mendengarkan engkau, bawalah seorang atau dua orang lagi, supaya atas keterangan dua atau tiga orang saksi, perkara itu tidak disangsikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 17, 'Jika ia tidak mau mendengarkan mereka, sampaikanlah soalnya kepada jemaat. Dan jika ia tidak mau juga mendengarkan jemaat, pandanglah dia sebagai seorang yang tidak mengenal Allah atau seorang pemungut cukai.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 18, 'Aku berkata kepadamu: Sesungguhnya apa yang kamu ikat di dunia ini akan terikat di sorga dan apa yang kamu lepaskan di dunia ini akan terlepas di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 19, 'Dan lagi Aku berkata kepadamu: Jika dua orang dari padamu di dunia ini sepakat meminta apapun juga, permintaan mereka itu akan dikabulkan oleh Bapa-Ku yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 20, 'Sebab di mana dua atau tiga orang berkumpul dalam Nama-Ku, di situ Aku ada di tengah-tengah mereka."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 21, 'Kemudian datanglah Petrus dan berkata kepada Yesus: "Tuhan, sampai berapa kali aku harus mengampuni saudaraku jika ia berbuat dosa terhadap aku? Sampai tujuh kali?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 22, 'Yesus berkata kepadanya: "Bukan! Aku berkata kepadamu: Bukan sampai tujuh kali, melainkan sampai tujuh puluh kali tujuh kali.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 23, 'Sebab hal Kerajaan Sorga seumpama seorang raja yang hendak mengadakan perhitungan dengan hamba-hambanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 24, 'Setelah ia mulai mengadakan perhitungan itu, dihadapkanlah kepadanya seorang yang berhutang sepuluh ribu talenta.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 25, 'Tetapi karena orang itu tidak mampu melunaskan hutangnya, raja itu memerintahkan supaya ia dijual beserta anak isterinya dan segala miliknya untuk pembayar hutangnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 26, 'Maka sujudlah hamba itu menyembah dia, katanya: Sabarlah dahulu, segala hutangku akan kulunaskan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 27, 'Lalu tergeraklah hati raja itu oleh belas kasihan akan hamba itu, sehingga ia membebaskannya dan menghapuskan hutangnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 28, 'Tetapi ketika hamba itu keluar, ia bertemu dengan seorang hamba lain yang berhutang seratus dinar kepadanya. Ia menangkap dan mencekik kawannya itu, katanya: Bayar hutangmu!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 29, 'Maka sujudlah kawannya itu dan memohon kepadanya: Sabarlah dahulu, hutangku itu akan kulunaskan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 30, 'Tetapi ia menolak dan menyerahkan kawannya itu ke dalam penjara sampai dilunaskannya hutangnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 31, 'Melihat itu kawan-kawannya yang lain sangat sedih lalu menyampaikan segala yang terjadi kepada tuan mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 32, 'Raja itu menyuruh memanggil orang itu dan berkata kepadanya: Hai hamba yang jahat, seluruh hutangmu telah kuhapuskan karena engkau memohonkannya kepadaku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 33, 'Bukankah engkaupun harus mengasihani kawanmu seperti aku telah mengasihani engkau?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 34, 'Maka marahlah tuannya itu dan menyerahkannya kepada algojo-algojo, sampai ia melunaskan seluruh hutangnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 18, 35, 'Maka Bapa-Ku yang di sorga akan berbuat demikian juga terhadap kamu, apabila kamu masing-masing tidak mengampuni saudaramu dengan segenap hatimu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 1, 'Setelah Yesus selesai dengan pengajaran-Nya itu, berangkatlah Ia dari Galilea dan tiba di daerah Yudea yang di seberang sungai Yordan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 2, 'Orang banyak berbondong-bondong mengikuti Dia dan Iapun menyembuhkan mereka di sana.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 3, 'Maka datanglah orang-orang Farisi kepada-Nya untuk mencobai Dia. Mereka bertanya: "Apakah diperbolehkan orang menceraikan isterinya dengan alasan apa saja?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 4, 'Jawab Yesus: "Tidakkah kamu baca, bahwa Ia yang menciptakan manusia sejak semula menjadikan mereka laki-laki dan perempuan?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 5, 'Dan firman-Nya: Sebab itu laki-laki akan meninggalkan ayah dan ibunya dan bersatu dengan isterinya, sehingga keduanya itu menjadi satu daging.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 6, 'Demikianlah mereka bukan lagi dua, melainkan satu. Karena itu, apa yang telah dipersatukan Allah, tidak boleh diceraikan manusia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 7, 'Kata mereka kepada-Nya: "Jika demikian, apakah sebabnya Musa memerintahkan untuk memberikan surat cerai jika orang menceraikan isterinya?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 8, 'Kata Yesus kepada mereka: "Karena ketegaran hatimu Musa mengizinkan kamu menceraikan isterimu, tetapi sejak semula tidaklah demikian.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 9, 'Tetapi Aku berkata kepadamu: Barangsiapa menceraikan isterinya, kecuali karena zinah, lalu kawin dengan perempuan lain, ia berbuat zinah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 10, 'Murid-murid itu berkata kepada-Nya: "Jika demikian halnya hubungan antara suami dan isteri, lebih baik jangan kawin."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 11, 'Akan tetapi Ia berkata kepada mereka: "Tidak semua orang dapat mengerti perkataan itu, hanya mereka yang dikaruniai saja.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 12, 'Ada orang yang tidak dapat kawin karena ia memang lahir demikian dari rahim ibunya, dan ada orang yang dijadikan demikian oleh orang lain, dan ada orang yang membuat dirinya demikian karena kemauannya sendiri oleh karena Kerajaan Sorga. Siapa yang dapat mengerti hendaklah ia mengerti."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 13, 'Lalu orang membawa anak-anak kecil kepada Yesus, supaya Ia meletakkan tangan-Nya atas mereka dan mendoakan mereka; akan tetapi murid-murid-Nya memarahi orang-orang itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 14, 'Tetapi Yesus berkata: "Biarkanlah anak-anak itu, janganlah menghalang-halangi mereka datang kepada-Ku; sebab orang-orang yang seperti itulah yang empunya Kerajaan Sorga."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 15, 'Lalu Ia meletakkan tangan-Nya atas mereka dan kemudian Ia berangkat dari situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 16, 'Ada seorang datang kepada Yesus, dan berkata: "Guru, perbuatan baik apakah yang harus kuperbuat untuk memperoleh hidup yang kekal?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 17, 'Jawab Yesus: "Apakah sebabnya engkau bertanya kepada-Ku tentang apa yang baik? Hanya Satu yang baik. Tetapi jikalau engkau ingin masuk ke dalam hidup, turutilah segala perintah Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 18, 'Kata orang itu kepada-Nya: "Perintah yang mana?" Kata Yesus: "Jangan membunuh, jangan berzinah, jangan mencuri, jangan mengucapkan saksi dusta,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 19, 'hormatilah ayahmu dan ibumu dan kasihilah sesamamu manusia seperti dirimu sendiri."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 20, 'Kata orang muda itu kepada-Nya: "Semuanya itu telah kuturuti, apa lagi yang masih kurang?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 21, 'Kata Yesus kepadanya: "Jikalau engkau hendak sempurna, pergilah, juallah segala milikmu dan berikanlah itu kepada orang-orang miskin, maka engkau akan beroleh harta di sorga, kemudian datanglah ke mari dan ikutlah Aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 22, 'Ketika orang muda itu mendengar perkataan itu, pergilah ia dengan sedih, sebab banyak hartanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 23, 'Yesus berkata kepada murid-murid-Nya: "Aku berkata kepadamu, sesungguhnya sukar sekali bagi seorang kaya untuk masuk ke dalam Kerajaan Sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 24, 'Sekali lagi Aku berkata kepadamu, lebih mudah seekor unta masuk melalui lobang jarum dari pada seorang kaya masuk ke dalam Kerajaan Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 25, 'Ketika murid-murid mendengar itu, sangat gemparlah mereka dan berkata: "Jika demikian, siapakah yang dapat diselamatkan?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 26, 'Yesus memandang mereka dan berkata: "Bagi manusia hal ini tidak mungkin, tetapi bagi Allah segala sesuatu mungkin."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 27, 'Lalu Petrus menjawab dan berkata kepada Yesus: "Kami ini telah meninggalkan segala sesuatu dan mengikut Engkau; jadi apakah yang akan kami peroleh?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 28, 'Kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya pada waktu penciptaan kembali, apabila Anak Manusia bersemayam di takhta kemuliaan-Nya, kamu, yang telah mengikut Aku, akan duduk juga di atas dua belas takhta untuk menghakimi kedua belas suku Israel.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 29, 'Dan setiap orang yang karena nama-Ku meninggalkan rumahnya, saudaranya laki-laki atau saudaranya perempuan, bapa atau ibunya, anak-anak atau ladangnya, akan menerima kembali seratus kali lipat dan akan memperoleh hidup yang kekal.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 19, 30, 'Tetapi banyak orang yang terdahulu akan menjadi yang terakhir, dan yang terakhir akan menjadi yang terdahulu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 1, '"Adapun hal Kerajaan Sorga sama seperti seorang tuan rumah yang pagi-pagi benar keluar mencari pekerja-pekerja untuk kebun anggurnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 2, 'Setelah ia sepakat dengan pekerja-pekerja itu mengenai upah sedinar sehari, ia menyuruh mereka ke kebun anggurnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 3, 'Kira-kira pukul sembilan pagi ia keluar pula dan dilihatnya ada lagi orang-orang lain menganggur di pasar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 4, 'Katanya kepada mereka: Pergi jugalah kamu ke kebun anggurku dan apa yang pantas akan kuberikan kepadamu. Dan merekapun pergi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 5, 'Kira-kira pukul dua belas dan pukul tiga petang ia keluar pula dan melakukan sama seperti tadi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 6, 'Kira-kira pukul lima petang ia keluar lagi dan mendapati orang-orang lain pula, lalu katanya kepada mereka: Mengapa kamu menganggur saja di sini sepanjang hari?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 7, 'Kata mereka kepadanya: Karena tidak ada orang mengupah kami. Katanya kepada mereka: Pergi jugalah kamu ke kebun anggurku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 8, 'Ketika hari malam tuan itu berkata kepada mandurnya: Panggillah pekerja-pekerja itu dan bayarkan upah mereka, mulai dengan mereka yang masuk terakhir hingga mereka yang masuk terdahulu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 9, 'Maka datanglah mereka yang mulai bekerja kira-kira pukul lima dan mereka menerima masing-masing satu dinar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 10, 'Kemudian datanglah mereka yang masuk terdahulu, sangkanya akan mendapat lebih banyak, tetapi merekapun menerima masing-masing satu dinar juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 11, 'Ketika mereka menerimanya, mereka bersungut-sungut kepada tuan itu,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 12, 'katanya: Mereka yang masuk terakhir ini hanya bekerja satu jam dan engkau menyamakan mereka dengan kami yang sehari suntuk bekerja berat dan menanggung panas terik matahari.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 13, 'Tetapi tuan itu menjawab seorang dari mereka: Saudara, aku tidak berlaku tidak adil terhadap engkau. Bukankah kita telah sepakat sedinar sehari?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 14, 'Ambillah bagianmu dan pergilah; aku mau memberikan kepada orang yang masuk terakhir ini sama seperti kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 15, 'Tidakkah aku bebas mempergunakan milikku menurut kehendak hatiku? Atau iri hatikah engkau, karena aku murah hati?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 16, 'Demikianlah orang yang terakhir akan menjadi yang terdahulu dan yang terdahulu akan menjadi yang terakhir."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 17, 'Ketika Yesus akan pergi ke Yerusalem, Ia memanggil kedua belas murid-Nya tersendiri dan berkata kepada mereka di tengah jalan:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 18, '"Sekarang kita pergi ke Yerusalem dan Anak Manusia akan diserahkan kepada imam-imam kepala dan ahli-ahli Taurat, dan mereka akan menjatuhi Dia hukuman mati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 19, 'Dan mereka akan menyerahkan Dia kepada bangsa-bangsa yang tidak mengenal Allah, supaya Ia diolok-olokkan, disesah dan disalibkan, dan pada hari ketiga Ia akan dibangkitkan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 20, 'Maka datanglah ibu anak-anak Zebedeus serta anak-anaknya itu kepada Yesus, lalu sujud di hadapan-Nya untuk meminta sesuatu kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 21, 'Kata Yesus: "Apa yang kaukehendaki?" Jawabnya: "Berilah perintah, supaya kedua anakku ini boleh duduk kelak di dalam Kerajaan-Mu, yang seorang di sebelah kanan-Mu dan yang seorang lagi di sebelah kiri-Mu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 22, 'Tetapi Yesus menjawab, kata-Nya: "Kamu tidak tahu, apa yang kamu minta. Dapatkah kamu meminum cawan, yang harus Kuminum?" Kata mereka kepada-Nya: "Kami dapat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 23, 'Yesus berkata kepada mereka: "Cawan-Ku memang akan kamu minum, tetapi hal duduk di sebelah kanan-Ku atau di sebelah kiri-Ku, Aku tidak berhak memberikannya. Itu akan diberikan kepada orang-orang bagi siapa Bapa-Ku telah menyediakannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 24, 'Mendengar itu marahlah kesepuluh murid yang lain kepada kedua saudara itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 25, 'Tetapi Yesus memanggil mereka lalu berkata: "Kamu tahu, bahwa pemerintah-pemerintah bangsa-bangsa memerintah rakyatnya dengan tangan besi dan pembesar-pembesar menjalankan kuasanya dengan keras atas mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 26, 'Tidaklah demikian di antara kamu. Barangsiapa ingin menjadi besar di antara kamu, hendaklah ia menjadi pelayanmu,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 27, 'dan barangsiapa ingin menjadi terkemuka di antara kamu, hendaklah ia menjadi hambamu;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 28, 'sama seperti Anak Manusia datang bukan untuk dilayani, melainkan untuk melayani dan untuk memberikan nyawa-Nya menjadi tebusan bagi banyak orang."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 29, 'Dan ketika Yesus dan murid-murid-Nya keluar dari Yerikho, orang banyak berbondong-bondong mengikuti Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 30, 'Ada dua orang buta yang duduk di pinggir jalan mendengar, bahwa Yesus lewat, lalu mereka berseru: "Tuhan, Anak Daud, kasihanilah kami!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 31, 'Tetapi orang banyak itu menegor mereka supaya mereka diam. Namun mereka makin keras berseru, katanya: "Tuhan, Anak Daud, kasihanilah kami!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 32, 'Lalu Yesus berhenti dan memanggil mereka. Ia berkata: "Apa yang kamu kehendaki supaya Aku perbuat bagimu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 33, 'Jawab mereka: "Tuhan, supaya mata kami dapat melihat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 20, 34, 'Maka tergeraklah hati Yesus oleh belas kasihan, lalu Ia menjamah mata mereka dan seketika itu juga mereka melihat lalu mengikuti Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 1, 'Ketika Yesus dan murid-murid-Nya telah dekat Yerusalem dan tiba di Betfage yang terletak di Bukit Zaitun, Yesus menyuruh dua orang murid-Nya', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 2, 'dengan pesan: "Pergilah ke kampung yang di depanmu itu, dan di situ kamu akan segera menemukan seekor keledai betina tertambat dan anaknya ada dekatnya. Lepaskanlah keledai itu dan bawalah keduanya kepada-Ku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 3, 'Dan jikalau ada orang menegor kamu, katakanlah: Tuhan memerlukannya. Ia akan segera mengembalikannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 4, 'Hal itu terjadi supaya genaplah firman yang disampaikan oleh nabi:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 5, '"Katakanlah kepada puteri Sion: Lihat, Rajamu datang kepadamu, Ia lemah lembut dan mengendarai seekor keledai, seekor keledai beban yang muda."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 6, 'Maka pergilah murid-murid itu dan berbuat seperti yang ditugaskan Yesus kepada mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 7, 'Mereka membawa keledai betina itu bersama anaknya, lalu mengalasinya dengan pakaian mereka dan Yesuspun naik ke atasnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 8, 'Orang banyak yang sangat besar jumlahnya menghamparkan pakaiannya di jalan, ada pula yang memotong ranting-ranting dari pohon-pohon dan menyebarkannya di jalan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 9, 'Dan orang banyak yang berjalan di depan Yesus dan yang mengikuti-Nya dari belakang berseru, katanya: "Hosana bagi Anak Daud, diberkatilah Dia yang datang dalam nama Tuhan, hosana di tempat yang mahatinggi!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 10, 'Dan ketika Ia masuk ke Yerusalem, gemparlah seluruh kota itu dan orang berkata: "Siapakah orang ini?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 11, 'Dan orang banyak itu menyahut: "Inilah nabi Yesus dari Nazaret di Galilea."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 12, 'Lalu Yesus masuk ke Bait Allah dan mengusir semua orang yang berjual beli di halaman Bait Allah. Ia membalikkan meja-meja penukar uang dan bangku-bangku pedagang merpati', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 13, 'dan berkata kepada mereka: "Ada tertulis: Rumah-Ku akan disebut rumah doa. Tetapi kamu menjadikannya sarang penyamun."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 14, 'Maka datanglah orang-orang buta dan orang-orang timpang kepada-Nya dalam Bait Allah itu dan mereka disembuhkan-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 15, 'Tetapi ketika imam-imam kepala dan ahli-ahli Taurat melihat mujizat-mujizat yang dibuat-Nya itu dan anak-anak yang berseru dalam Bait Allah: "Hosana bagi Anak Daud!" hati mereka sangat jengkel,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 16, 'lalu mereka berkata kepada-Nya: "Engkau dengar apa yang dikatakan anak-anak ini?" Kata Yesus kepada mereka: "Aku dengar; belum pernahkah kamu baca: Dari mulut bayi-bayi dan anak-anak yang menyusu Engkau telah menyediakan puji-pujian?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 17, 'Lalu Ia meninggalkan mereka dan pergi ke luar kota ke Betania dan bermalam di situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 18, 'Pada pagi-pagi hari dalam perjalanan-Nya kembali ke kota, Yesus merasa lapar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 19, 'Dekat jalan Ia melihat pohon ara lalu pergi ke situ, tetapi Ia tidak mendapat apa-apa pada pohon itu selain daun-daun saja. Kata-Nya kepada pohon itu: "Engkau tidak akan berbuah lagi selama-lamanya!" Dan seketika itu juga keringlah pohon ara itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 20, 'Melihat kejadian itu tercenganglah murid-murid-Nya, lalu berkata: "Bagaimana mungkin pohon ara itu sekonyong-konyong menjadi kering?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 21, 'Yesus menjawab mereka: "Aku berkata kepadamu, sesungguhnya jika kamu percaya dan tidak bimbang, kamu bukan saja akan dapat berbuat apa yang Kuperbuat dengan pohon ara itu, tetapi juga jikalau kamu berkata kepada gunung ini: Beranjaklah dan tercampaklah ke dalam laut! hal itu akan terjadi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 22, 'Dan apa saja yang kamu minta dalam doa dengan penuh kepercayaan, kamu akan menerimanya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 23, 'Lalu Yesus masuk ke Bait Allah, dan ketika Ia mengajar di situ, datanglah imam-imam kepala serta tua-tua bangsa Yahudi kepada-Nya, dan bertanya: "Dengan kuasa manakah Engkau melakukan hal-hal itu? Dan siapakah yang memberikan kuasa itu kepada-Mu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 24, 'Jawab Yesus kepada mereka: "Aku juga akan mengajukan satu pertanyaan kepadamu dan jikalau kamu memberi jawabnya kepada-Ku, Aku akan mengatakan juga kepadamu dengan kuasa manakah Aku melakukan hal-hal itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 25, 'Dari manakah baptisan Yohanes? Dari sorga atau dari manusia?" Mereka memperbincangkannya di antara mereka, dan berkata: "Jikalau kita katakan: Dari sorga, Ia akan berkata kepada kita: Kalau begitu, mengapakah kamu tidak percaya kepadanya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 26, 'Tetapi jikalau kita katakan: Dari manusia, kita takut kepada orang banyak, sebab semua orang menganggap Yohanes ini nabi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 27, 'Lalu mereka menjawab Yesus: "Kami tidak tahu." Dan Yesuspun berkata kepada mereka: "Jika demikian, Aku juga tidak mengatakan kepadamu dengan kuasa manakah Aku melakukan hal-hal itu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 28, '"Tetapi apakah pendapatmu tentang ini: Seorang mempunyai dua anak laki-laki. Ia pergi kepada anak yang sulung dan berkata: Anakku, pergi dan bekerjalah hari ini dalam kebun anggur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 29, 'Jawab anak itu: Baik, bapa. Tetapi ia tidak pergi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 30, 'Lalu orang itu pergi kepada anak yang kedua dan berkata demikian juga. Dan anak itu menjawab: Aku tidak mau. Tetapi kemudian ia menyesal lalu pergi juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 31, 'Siapakah di antara kedua orang itu yang melakukan kehendak ayahnya?" Jawab mereka: "Yang terakhir." Kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya pemungut-pemungut cukai dan perempuan-perempuan sundal akan mendahului kamu masuk ke dalam Kerajaan Allah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 32, 'Sebab Yohanes datang untuk menunjukkan jalan kebenaran kepadamu, dan kamu tidak percaya kepadanya. Tetapi pemungut-pemungut cukai dan perempuan-perempuan sundal percaya kepadanya. Dan meskipun kamu melihatnya, tetapi kemudian kamu tidak menyesal dan kamu tidak juga percaya kepadanya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 33, '"Dengarkanlah suatu perumpamaan yang lain. Adalah seorang tuan tanah membuka kebun anggur dan menanam pagar sekelilingnya. Ia menggali lobang tempat memeras anggur dan mendirikan menara jaga di dalam kebun itu. Kemudian ia menyewakan kebun itu kepada penggarap-penggarap lalu berangkat ke negeri lain.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 34, 'Ketika hampir tiba musim petik, ia menyuruh hamba-hambanya kepada penggarap-penggarap itu untuk menerima hasil yang menjadi bagiannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 35, 'Tetapi penggarap-penggarap itu menangkap hamba-hambanya itu: mereka memukul yang seorang, membunuh yang lain dan melempari yang lain pula dengan batu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 36, 'Kemudian tuan itu menyuruh pula hamba-hamba yang lain, lebih banyak dari pada yang semula, tetapi merekapun diperlakukan sama seperti kawan-kawan mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 37, 'Akhirnya ia menyuruh anaknya kepada mereka, katanya: Anakku akan mereka segani.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 38, 'Tetapi ketika penggarap-penggarap itu melihat anaknya itu, mereka berkata seorang kepada yang lain: Ia adalah ahli waris, mari kita bunuh dia, supaya warisannya menjadi milik kita.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 39, 'Mereka menangkapnya dan melemparkannya ke luar kebun anggur itu, lalu membunuhnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 40, 'Maka apabila tuan kebun anggur itu datang, apakah yang akan dilakukannya dengan penggarap-penggarap itu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 41, 'Kata mereka kepada-Nya: "Ia akan membinasakan orang-orang jahat itu dan kebun anggurnya akan disewakannya kepada penggarap-penggarap lain, yang akan menyerahkan hasilnya kepadanya pada waktunya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 42, 'Kata Yesus kepada mereka: "Belum pernahkah kamu baca dalam Kitab Suci: Batu yang dibuang oleh tukang-tukang bangunan telah menjadi batu penjuru: hal itu terjadi dari pihak Tuhan, suatu perbuatan ajaib di mata kita.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 43, 'Sebab itu, Aku berkata kepadamu, bahwa Kerajaan Allah akan diambil dari padamu dan akan diberikan kepada suatu bangsa yang akan menghasilkan buah Kerajaan itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 44, '(Dan barangsiapa jatuh ke atas batu itu, ia akan hancur dan barangsiapa ditimpa batu itu, ia akan remuk.)"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 45, 'Ketika imam-imam kepala dan orang-orang Farisi mendengar perumpamaan-perumpamaan Yesus, mereka mengerti, bahwa merekalah yang dimaksudkan-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 21, 46, 'Dan mereka berusaha untuk menangkap Dia, tetapi mereka takut kepada orang banyak, karena orang banyak itu menganggap Dia nabi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 1, 'Lalu Yesus berbicara pula dalam perumpamaan kepada mereka:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 2, '"Hal Kerajaan Sorga seumpama seorang raja, yang mengadakan perjamuan kawin untuk anaknya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 3, 'Ia menyuruh hamba-hambanya memanggil orang-orang yang telah diundang ke perjamuan kawin itu, tetapi orang-orang itu tidak mau datang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 4, 'Ia menyuruh pula hamba-hamba lain, pesannya: Katakanlah kepada orang-orang yang diundang itu: Sesungguhnya hidangan, telah kusediakan, lembu-lembu jantan dan ternak piaraanku telah disembelih; semuanya telah tersedia, datanglah ke perjamuan kawin ini.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 5, 'Tetapi orang-orang yang diundang itu tidak mengindahkannya; ada yang pergi ke ladangnya, ada yang pergi mengurus usahanya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 6, 'dan yang lain menangkap hamba-hambanya itu, menyiksanya dan membunuhnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 7, 'Maka murkalah raja itu, lalu menyuruh pasukannya ke sana untuk membinasakan pembunuh-pembunuh itu dan membakar kota mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 8, 'Sesudah itu ia berkata kepada hamba-hambanya: Perjamuan kawin telah tersedia, tetapi orang-orang yang diundang tadi tidak layak untuk itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 9, 'Sebab itu pergilah ke persimpangan-persimpangan jalan dan undanglah setiap orang yang kamu jumpai di sana ke perjamuan kawin itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 10, 'Maka pergilah hamba-hamba itu dan mereka mengumpulkan semua orang yang dijumpainya di jalan-jalan, orang-orang jahat dan orang-orang baik, sehingga penuhlah ruangan perjamuan kawin itu dengan tamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 11, 'Ketika raja itu masuk untuk bertemu dengan tamu-tamu itu, ia melihat seorang yang tidak berpakaian pesta.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 12, 'Ia berkata kepadanya: Hai saudara, bagaimana engkau masuk ke mari dengan tidak mengenakan pakaian pesta? Tetapi orang itu diam saja.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 13, 'Lalu kata raja itu kepada hamba-hambanya: Ikatlah kaki dan tangannya dan campakkanlah orang itu ke dalam kegelapan yang paling gelap, di sanalah akan terdapat ratap dan kertak gigi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 14, 'Sebab banyak yang dipanggil, tetapi sedikit yang dipilih."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 15, 'Kemudian pergilah orang-orang Farisi; mereka berunding bagaimana mereka dapat menjerat Yesus dengan suatu pertanyaan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 16, 'Mereka menyuruh murid-murid mereka bersama-sama orang-orang Herodian bertanya kepada-Nya: "Guru, kami tahu, Engkau adalah seorang yang jujur dan dengan jujur mengajar jalan Allah dan Engkau tidak takut kepada siapapun juga, sebab Engkau tidak mencari muka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 17, 'Katakanlah kepada kami pendapat-Mu: Apakah diperbolehkan membayar pajak kepada Kaisar atau tidak?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 18, 'Tetapi Yesus mengetahui kejahatan hati mereka itu lalu berkata: "Mengapa kamu mencobai Aku, hai orang-orang munafik?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 19, 'Tunjukkanlah kepada-Ku mata uang untuk pajak itu." Mereka membawa suatu dinar kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 20, 'Maka Ia bertanya kepada mereka: "Gambar dan tulisan siapakah ini?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 21, 'Jawab mereka: "Gambar dan tulisan Kaisar." Lalu kata Yesus kepada mereka: "Berikanlah kepada Kaisar apa yang wajib kamu berikan kepada Kaisar dan kepada Allah apa yang wajib kamu berikan kepada Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 22, 'Mendengar itu heranlah mereka dan meninggalkan Yesus lalu pergi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 23, 'Pada hari itu datanglah kepada Yesus beberapa orang Saduki, yang berpendapat, bahwa tidak ada kebangkitan. Mereka bertanya kepada-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 24, '"Guru, Musa mengatakan, bahwa jika seorang mati dengan tiada meninggalkan anak, saudaranya harus kawin dengan isterinya itu dan membangkitkan keturunan bagi saudaranya itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 25, 'Tetapi di antara kami ada tujuh orang bersaudara. Yang pertama kawin, tetapi kemudian mati. Dan karena ia tidak mempunyai keturunan, ia meninggalkan isterinya itu bagi saudaranya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 26, 'Demikian juga yang kedua dan yang ketiga sampai dengan yang ketujuh.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 27, 'Dan akhirnya, sesudah mereka semua, perempuan itupun mati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 28, 'Siapakah di antara ketujuh orang itu yang menjadi suami perempuan itu pada hari kebangkitan? Sebab mereka semua telah beristerikan dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 29, 'Yesus menjawab mereka: "Kamu sesat, sebab kamu tidak mengerti Kitab Suci maupun kuasa Allah!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 30, 'Karena pada waktu kebangkitan orang tidak kawin dan tidak dikawinkan melainkan hidup seperti malaikat di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 31, 'Tetapi tentang kebangkitan orang-orang mati tidakkah kamu baca apa yang difirmankan Allah, ketika Ia bersabda:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 32, 'Akulah Allah Abraham, Allah Ishak dan Allah Yakub? Ia bukanlah Allah orang mati, melainkan Allah orang hidup."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 33, 'Orang banyak yang mendengar itu takjub akan pengajaran-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 34, 'Ketika orang-orang Farisi mendengar, bahwa Yesus telah membuat orang-orang Saduki itu bungkam, berkumpullah mereka', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 35, 'dan seorang dari mereka, seorang ahli Taurat, bertanya untuk mencobai Dia:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 36, '"Guru, hukum manakah yang terutama dalam hukum Taurat?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 37, 'Jawab Yesus kepadanya: "Kasihilah Tuhan, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu dan dengan segenap akal budimu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 38, 'Itulah hukum yang terutama dan yang pertama.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 39, 'Dan hukum yang kedua, yang sama dengan itu, ialah: Kasihilah sesamamu manusia seperti dirimu sendiri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 40, 'Pada kedua hukum inilah tergantung seluruh hukum Taurat dan kitab para nabi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 41, 'Ketika orang-orang Farisi sedang berkumpul, Yesus bertanya kepada mereka, kata-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 42, '"Apakah pendapatmu tentang Mesias? Anak siapakah Dia?" Kata mereka kepada-Nya: "Anak Daud."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 43, 'Kata-Nya kepada mereka: "Jika demikian, bagaimanakah Daud oleh pimpinan Roh dapat menyebut Dia Tuannya, ketika ia berkata:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 44, 'Tuhan telah berfirman kepada Tuanku: duduklah di sebelah kanan-Ku, sampai musuh-musuh-Mu Kutaruh di bawah kaki-Mu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 45, 'Jadi jika Daud menyebut Dia Tuannya, bagaimana mungkin Ia anaknya pula?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 22, 46, 'Tidak ada seorangpun yang dapat menjawab-Nya, dan sejak hari itu tidak ada seorangpun juga yang berani menanyakan sesuatu kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 1, 'Maka berkatalah Yesus kepada orang banyak dan kepada murid-murid-Nya, kata-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 2, '"Ahli-ahli Taurat dan orang-orang Farisi telah menduduki kursi Musa.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 3, 'Sebab itu turutilah dan lakukanlah segala sesuatu yang mereka ajarkan kepadamu, tetapi janganlah kamu turuti perbuatan-perbuatan mereka, karena mereka mengajarkannya tetapi tidak melakukannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 4, 'Mereka mengikat beban-beban berat, lalu meletakkannya di atas bahu orang, tetapi mereka sendiri tidak mau menyentuhnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 5, 'Semua pekerjaan yang mereka lakukan hanya dimaksud supaya dilihat orang; mereka memakai tali sembahyang yang lebar dan jumbai yang panjang;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 6, 'mereka suka duduk di tempat terhormat dalam perjamuan dan di tempat terdepan di rumah ibadat;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 7, 'mereka suka menerima penghormatan di pasar dan suka dipanggil Rabi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 8, 'Tetapi kamu, janganlah kamu disebut Rabi; karena hanya satu Rabimu dan kamu semua adalah saudara.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 9, 'Dan janganlah kamu menyebut siapapun bapa di bumi ini, karena hanya satu Bapamu, yaitu Dia yang di sorga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 10, 'Janganlah pula kamu disebut pemimpin, karena hanya satu Pemimpinmu, yaitu Mesias.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 11, 'Barangsiapa terbesar di antara kamu, hendaklah ia menjadi pelayanmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 12, 'Dan barangsiapa meninggikan diri, ia akan direndahkan dan barangsiapa merendahkan diri, ia akan ditinggikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 13, 'Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, karena kamu menutup pintu-pintu Kerajaan Sorga di depan orang. Sebab kamu sendiri tidak masuk dan kamu merintangi mereka yang berusaha untuk masuk.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 14, '(Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, sebab kamu menelan rumah janda-janda sedang kamu mengelabui mata orang dengan doa yang panjang-panjang. Sebab itu kamu pasti akan menerima hukuman yang lebih berat.)', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 15, 'Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, sebab kamu mengarungi lautan dan menjelajah daratan, untuk mentobatkan satu orang saja menjadi penganut agamamu dan sesudah ia bertobat, kamu menjadikan dia orang neraka, yang dua kali lebih jahat dari pada kamu sendiri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 16, 'Celakalah kamu, hai pemimpin-pemimpin buta, yang berkata: Bersumpah demi Bait Suci, sumpah itu tidak sah; tetapi bersumpah demi emas Bait Suci, sumpah itu mengikat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 17, 'Hai kamu orang-orang bodoh dan orang-orang buta, apakah yang lebih penting, emas atau Bait Suci yang menguduskan emas itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 18, 'Bersumpah demi mezbah, sumpah itu tidak sah; tetapi bersumpah demi persembahan yang ada di atasnya, sumpah itu mengikat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 19, 'Hai kamu orang-orang buta, apakah yang lebih penting, persembahan atau mezbah yang menguduskan persembahan itu?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 20, 'Karena itu barangsiapa bersumpah demi mezbah, ia bersumpah demi mezbah dan juga demi segala sesuatu yang terletak di atasnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 21, 'Dan barangsiapa bersumpah demi Bait Suci, ia bersumpah demi Bait Suci dan juga demi Dia, yang diam di situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 22, 'Dan barangsiapa bersumpah demi sorga, ia bersumpah demi takhta Allah dan juga demi Dia, yang bersemayam di atasnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 23, 'Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, sebab persepuluhan dari selasih, adas manis dan jintan kamu bayar, tetapi yang terpenting dalam hukum Taurat kamu abaikan, yaitu: keadilan dan belas kasihan dan kesetiaan. Yang satu harus dilakukan dan yang lain jangan diabaikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 24, 'Hai kamu pemimpin-pemimpin buta, nyamuk kamu tapiskan dari dalam minumanmu, tetapi unta yang di dalamnya kamu telan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 25, 'Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, sebab cawan dan pinggan kamu bersihkan sebelah luarnya, tetapi sebelah dalamnya penuh rampasan dan kerakusan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 26, 'Hai orang Farisi yang buta, bersihkanlah dahulu sebelah dalam cawan itu, maka sebelah luarnya juga akan bersih.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 27, 'Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, sebab kamu sama seperti kuburan yang dilabur putih, yang sebelah luarnya memang bersih tampaknya, tetapi yang sebelah dalamnya penuh tulang belulang dan pelbagai jenis kotoran.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 28, 'Demikian jugalah kamu, di sebelah luar kamu tampaknya benar di mata orang, tetapi di sebelah dalam kamu penuh kemunafikan dan kedurjanaan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 29, 'Celakalah kamu, hai ahli-ahli Taurat dan orang-orang Farisi, hai kamu orang-orang munafik, sebab kamu membangun makam nabi-nabi dan memperindah tugu orang-orang saleh', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 30, 'dan berkata: Jika kami hidup di zaman nenek moyang kita, tentulah kami tidak ikut dengan mereka dalam pembunuhan nabi-nabi itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 31, 'Tetapi dengan demikian kamu bersaksi terhadap diri kamu sendiri, bahwa kamu adalah keturunan pembunuh nabi-nabi itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 32, 'Jadi, penuhilah juga takaran nenek moyangmu!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 33, 'Hai kamu ular-ular, hai kamu keturunan ular beludak! Bagaimanakah mungkin kamu dapat meluputkan diri dari hukuman neraka?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 34, 'Sebab itu, lihatlah, Aku mengutus kepadamu nabi-nabi, orang-orang bijaksana dan ahli-ahli Taurat: separuh di antara mereka akan kamu bunuh dan kamu salibkan, yang lain akan kamu sesah di rumah-rumah ibadatmu dan kamu aniaya dari kota ke kota,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 35, 'supaya kamu menanggung akibat penumpahan darah orang yang tidak bersalah mulai dari Habel, orang benar itu, sampai kepada Zakharia anak Berekhya, yang kamu bunuh di antara tempat kudus dan mezbah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 36, 'Aku berkata kepadamu: Sesungguhnya semuanya ini akan ditanggung angkatan ini!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 37, '"Yerusalem, Yerusalem, engkau yang membunuh nabi-nabi dan melempari dengan batu orang-orang yang diutus kepadamu! Berkali-kali Aku rindu mengumpulkan anak-anakmu, sama seperti induk ayam mengumpulkan anak-anaknya di bawah sayapnya, tetapi kamu tidak mau.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 38, 'Lihatlah rumahmu ini akan ditinggalkan dan menjadi sunyi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 23, 39, 'Dan Aku berkata kepadamu: Mulai sekarang kamu tidak akan melihat Aku lagi, hingga kamu berkata: Diberkatilah Dia yang datang dalam nama Tuhan!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 1, 'Sesudah itu Yesus keluar dari Bait Allah, lalu pergi. Maka datanglah murid-murid-Nya dan menunjuk kepada bangunan-bangunan Bait Allah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 2, 'Ia berkata kepada mereka: "Kamu melihat semuanya itu? Aku berkata kepadamu, sesungguhnya tidak satu batupun di sini akan dibiarkan terletak di atas batu yang lain; semuanya akan diruntuhkan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 3, 'Ketika Yesus duduk di atas Bukit Zaitun, datanglah murid-murid-Nya kepada-Nya untuk bercakap-cakap sendirian dengan Dia. Kata mereka: "Katakanlah kepada kami, bilamanakah itu akan terjadi dan apakah tanda kedatangan-Mu dan tanda kesudahan dunia?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 4, 'Jawab Yesus kepada mereka: "Waspadalah supaya jangan ada orang yang menyesatkan kamu!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 5, 'Sebab banyak orang akan datang dengan memakai nama-Ku dan berkata: Akulah Mesias, dan mereka akan menyesatkan banyak orang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 6, 'Kamu akan mendengar deru perang atau kabar-kabar tentang perang. Namun berawas-awaslah jangan kamu gelisah; sebab semuanya itu harus terjadi, tetapi itu belum kesudahannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 7, 'Sebab bangsa akan bangkit melawan bangsa, dan kerajaan melawan kerajaan. Akan ada kelaparan dan gempa bumi di berbagai tempat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 8, 'Akan tetapi semuanya itu barulah permulaan penderitaan menjelang zaman baru.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 9, 'Pada waktu itu kamu akan diserahkan supaya disiksa, dan kamu akan dibunuh dan akan dibenci semua bangsa oleh karena nama-Ku,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 10, 'dan banyak orang akan murtad dan mereka akan saling menyerahkan dan saling membenci.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 11, 'Banyak nabi palsu akan muncul dan menyesatkan banyak orang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 12, 'Dan karena makin bertambahnya kedurhakaan, maka kasih kebanyakan orang akan menjadi dingin.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 13, 'Tetapi orang yang bertahan sampai pada kesudahannya akan selamat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 14, 'Dan Injil Kerajaan ini akan diberitakan di seluruh dunia menjadi kesaksian bagi semua bangsa, sesudah itu barulah tiba kesudahannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 15, '"Jadi apabila kamu melihat Pembinasa keji berdiri di tempat kudus, menurut firman yang disampaikan oleh nabi Daniel?para pembaca hendaklah memperhatikannya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 16, 'maka orang-orang yang di Yudea haruslah melarikan diri ke pegunungan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 17, 'Orang yang sedang di peranginan di atas rumah janganlah ia turun untuk mengambil barang-barang dari rumahnya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 18, 'dan orang yang sedang di ladang janganlah ia kembali untuk mengambil pakaiannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 19, 'Celakalah ibu-ibu yang sedang hamil atau yang menyusukan bayi pada masa itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 20, 'Berdoalah, supaya waktu kamu melarikan diri itu jangan jatuh pada musim dingin dan jangan pada hari Sabat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 21, 'Sebab pada masa itu akan terjadi siksaan yang dahsyat seperti yang belum pernah terjadi sejak awal dunia sampai sekarang dan yang tidak akan terjadi lagi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 22, 'Dan sekiranya waktunya tidak dipersingkat, maka dari segala yang hidup tidak akan ada yang selamat; akan tetapi oleh karena orang-orang pilihan waktu itu akan dipersingkat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 23, 'Pada waktu itu jika orang berkata kepada kamu: Lihat, Mesias ada di sini, atau Mesias ada di sana, jangan kamu percaya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 24, 'Sebab Mesias-mesias palsu dan nabi-nabi palsu akan muncul dan mereka akan mengadakan tanda-tanda yang dahsyat dan mujizat-mujizat, sehingga sekiranya mungkin, mereka menyesatkan orang-orang pilihan juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 25, 'Camkanlah, Aku sudah mengatakannya terlebih dahulu kepadamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 26, 'Jadi, apabila orang berkata kepadamu: Lihat, Ia ada di padang gurun, janganlah kamu pergi ke situ; atau: Lihat, Ia ada di dalam bilik, janganlah kamu percaya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 27, 'Sebab sama seperti kilat memancar dari sebelah timur dan melontarkan cahayanya sampai ke barat, demikian pulalah kelak kedatangan Anak Manusia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 28, 'Di mana ada bangkai, di situ burung nazar berkerumun."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 29, '"Segera sesudah siksaan pada masa itu, matahari akan menjadi gelap dan bulan tidak bercahaya dan bintang-bintang akan berjatuhan dari langit dan kuasa-kuasa langit akan goncang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 30, 'Pada waktu itu akan tampak tanda Anak Manusia di langit dan semua bangsa di bumi akan meratap dan mereka akan melihat Anak Manusia itu datang di atas awan-awan di langit dengan segala kekuasaan dan kemuliaan-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 31, 'Dan Ia akan menyuruh keluar malaikat-malaikat-Nya dengan meniup sangkakala yang dahsyat bunyinya dan mereka akan mengumpulkan orang-orang pilihan-Nya dari keempat penjuru bumi, dari ujung langit yang satu ke ujung langit yang lain.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 32, 'Tariklah pelajaran dari perumpamaan tentang pohon ara: Apabila ranting-rantingnya melembut dan mulai bertunas, kamu tahu, bahwa musim panas sudah dekat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 33, 'Demikian juga, jika kamu melihat semuanya ini, ketahuilah, bahwa waktunya sudah dekat, sudah di ambang pintu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 34, 'Aku berkata kepadamu: Sesungguhnya angkatan ini tidak akan berlalu, sebelum semuanya ini terjadi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 35, 'Langit dan bumi akan berlalu, tetapi perkataan-Ku tidak akan berlalu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 36, 'Tetapi tentang hari dan saat itu tidak seorangpun yang tahu, malaikat-malaikat di sorga tidak, dan Anakpun tidak, hanya Bapa sendiri."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 37, '"Sebab sebagaimana halnya pada zaman Nuh, demikian pula halnya kelak pada kedatangan Anak Manusia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 38, 'Sebab sebagaimana mereka pada zaman sebelum air bah itu makan dan minum, kawin dan mengawinkan, sampai kepada hari Nuh masuk ke dalam bahtera,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 39, 'dan mereka tidak tahu akan sesuatu, sebelum air bah itu datang dan melenyapkan mereka semua, demikian pulalah halnya kelak pada kedatangan Anak Manusia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 40, 'Pada waktu itu kalau ada dua orang di ladang, yang seorang akan dibawa dan yang lain akan ditinggalkan;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 41, 'kalau ada dua orang perempuan sedang memutar batu kilangan, yang seorang akan dibawa dan yang lain akan ditinggalkan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 42, 'Karena itu berjaga-jagalah, sebab kamu tidak tahu pada hari mana Tuhanmu datang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 43, 'Tetapi ketahuilah ini: Jika tuan rumah tahu pada waktu mana pada malam hari pencuri akan datang, sudahlah pasti ia berjaga-jaga, dan tidak akan membiarkan rumahnya dibongkar.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 44, 'Sebab itu, hendaklah kamu juga siap sedia, karena Anak Manusia datang pada saat yang tidak kamu duga."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 45, '"Siapakah hamba yang setia dan bijaksana, yang diangkat oleh tuannya atas orang-orangnya untuk memberikan mereka makanan pada waktunya?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 46, 'Berbahagialah hamba, yang didapati tuannya melakukan tugasnya itu, ketika tuannya itu datang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 47, 'Aku berkata kepadamu: Sesungguhnya tuannya itu akan mengangkat dia menjadi pengawas segala miliknya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 48, 'Akan tetapi apabila hamba itu jahat dan berkata di dalam hatinya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 49, 'Tuanku tidak datang-datang, lalu ia mulai memukul hamba-hamba lain, dan makan minum bersama-sama pemabuk-pemabuk,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 50, 'maka tuan hamba itu akan datang pada hari yang tidak disangkakannya, dan pada saat yang tidak diketahuinya,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 24, 51, 'dan akan membunuh dia dan membuat dia senasib dengan orang-orang munafik. Di sanalah akan terdapat ratapan dan kertakan gigi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 1, '"Pada waktu itu hal Kerajaan Sorga seumpama sepuluh gadis, yang mengambil pelitanya dan pergi menyongsong mempelai laki-laki.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 2, 'Lima di antaranya bodoh dan lima bijaksana.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 3, 'Gadis-gadis yang bodoh itu membawa pelitanya, tetapi tidak membawa minyak,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 4, 'sedangkan gadis-gadis yang bijaksana itu membawa pelitanya dan juga minyak dalam buli-buli mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 5, 'Tetapi karena mempelai itu lama tidak datang-datang juga, mengantuklah mereka semua lalu tertidur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 6, 'Waktu tengah malam terdengarlah suara orang berseru: Mempelai datang! Songsonglah dia!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 7, 'Gadis-gadis itupun bangun semuanya lalu membereskan pelita mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 8, 'Gadis-gadis yang bodoh berkata kepada gadis-gadis yang bijaksana: Berikanlah kami sedikit dari minyakmu itu, sebab pelita kami hampir padam.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 9, 'Tetapi jawab gadis-gadis yang bijaksana itu: Tidak, nanti tidak cukup untuk kami dan untuk kamu. Lebih baik kamu pergi kepada penjual minyak dan beli di situ.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 10, 'Akan tetapi, waktu mereka sedang pergi untuk membelinya, datanglah mempelai itu dan mereka yang telah siap sedia masuk bersama-sama dengan dia ke ruang perjamuan kawin, lalu pintu ditutup.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 11, 'Kemudian datang juga gadis-gadis yang lain itu dan berkata: Tuan, tuan, bukakanlah kami pintu!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 12, 'Tetapi ia menjawab: Aku berkata kepadamu, sesungguhnya aku tidak mengenal kamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 13, 'Karena itu, berjaga-jagalah, sebab kamu tidak tahu akan hari maupun akan saatnya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 14, '"Sebab hal Kerajaan Sorga sama seperti seorang yang mau bepergian ke luar negeri, yang memanggil hamba-hambanya dan mempercayakan hartanya kepada mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 15, 'Yang seorang diberikannya lima talenta, yang seorang lagi dua dan yang seorang lain lagi satu, masing-masing menurut kesanggupannya, lalu ia berangkat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 16, 'Segera pergilah hamba yang menerima lima talenta itu. Ia menjalankan uang itu lalu beroleh laba lima talenta.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 17, 'Hamba yang menerima dua talenta itupun berbuat demikian juga dan berlaba dua talenta.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 18, 'Tetapi hamba yang menerima satu talenta itu pergi dan menggali lobang di dalam tanah lalu menyembunyikan uang tuannya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 19, 'Lama sesudah itu pulanglah tuan hamba-hamba itu lalu mengadakan perhitungan dengan mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 20, 'Hamba yang menerima lima talenta itu datang dan ia membawa laba lima talenta, katanya: Tuan, lima talenta tuan percayakan kepadaku; lihat, aku telah beroleh laba lima talenta.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 21, 'Maka kata tuannya itu kepadanya: Baik sekali perbuatanmu itu, hai hambaku yang baik dan setia; engkau telah setia dalam perkara kecil, aku akan memberikan kepadamu tanggung jawab dalam perkara yang besar. Masuklah dan turutlah dalam kebahagiaan tuanmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 22, 'Lalu datanglah hamba yang menerima dua talenta itu, katanya: Tuan, dua talenta tuan percayakan kepadaku; lihat, aku telah beroleh laba dua talenta.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 23, 'Maka kata tuannya itu kepadanya: Baik sekali perbuatanmu itu, hai hambaku yang baik dan setia, engkau telah setia memikul tanggung jawab dalam perkara yang kecil, aku akan memberikan kepadamu tanggung jawab dalam perkara yang besar. Masuklah dan turutlah dalam kebahagiaan tuanmu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 24, 'Kini datanglah juga hamba yang menerima satu talenta itu dan berkata: Tuan, aku tahu bahwa tuan adalah manusia yang kejam yang menuai di tempat di mana tuan tidak menabur dan yang memungut dari tempat di mana tuan tidak menanam.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 25, 'Karena itu aku takut dan pergi menyembunyikan talenta tuan itu di dalam tanah: Ini, terimalah kepunyaan tuan!', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 26, 'Maka jawab tuannya itu: Hai kamu, hamba yang jahat dan malas, jadi kamu sudah tahu, bahwa aku menuai di tempat di mana aku tidak menabur dan memungut dari tempat di mana aku tidak menanam?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 27, 'Karena itu sudahlah seharusnya uangku itu kauberikan kepada orang yang menjalankan uang, supaya sekembaliku aku menerimanya serta dengan bunganya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 28, 'Sebab itu ambillah talenta itu dari padanya dan berikanlah kepada orang yang mempunyai sepuluh talenta itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 29, 'Karena setiap orang yang mempunyai, kepadanya akan diberi, sehingga ia berkelimpahan. Tetapi siapa yang tidak mempunyai, apapun juga yang ada padanya akan diambil dari padanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 30, 'Dan campakkanlah hamba yang tidak berguna itu ke dalam kegelapan yang paling gelap. Di sanalah akan terdapat ratap dan kertak gigi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 31, '"Apabila Anak Manusia datang dalam kemuliaan-Nya dan semua malaikat bersama-sama dengan Dia, maka Ia akan bersemayam di atas takhta kemuliaan-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 32, 'Lalu semua bangsa akan dikumpulkan di hadapan-Nya dan Ia akan memisahkan mereka seorang dari pada seorang, sama seperti gembala memisahkan domba dari kambing,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 33, 'dan Ia akan menempatkan domba-domba di sebelah kanan-Nya dan kambing-kambing di sebelah kiri-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 34, 'Dan Raja itu akan berkata kepada mereka yang di sebelah kanan-Nya: Mari, hai kamu yang diberkati oleh Bapa-Ku, terimalah Kerajaan yang telah disediakan bagimu sejak dunia dijadikan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 35, 'Sebab ketika Aku lapar, kamu memberi Aku makan; ketika Aku haus, kamu memberi Aku minum; ketika Aku seorang asing, kamu memberi Aku tumpangan;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 36, 'ketika Aku telanjang, kamu memberi Aku pakaian; ketika Aku sakit, kamu melawat Aku; ketika Aku di dalam penjara, kamu mengunjungi Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 37, 'Maka orang-orang benar itu akan menjawab Dia, katanya: Tuhan, bilamanakah kami melihat Engkau lapar dan kami memberi Engkau makan, atau haus dan kami memberi Engkau minum?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 38, 'Bilamanakah kami melihat Engkau sebagai orang asing, dan kami memberi Engkau tumpangan, atau telanjang dan kami memberi Engkau pakaian?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 39, 'Bilamanakah kami melihat Engkau sakit atau dalam penjara dan kami mengunjungi Engkau?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 40, 'Dan Raja itu akan menjawab mereka: Aku berkata kepadamu, sesungguhnya segala sesuatu yang kamu lakukan untuk salah seorang dari saudara-Ku yang paling hina ini, kamu telah melakukannya untuk Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 41, 'Dan Ia akan berkata juga kepada mereka yang di sebelah kiri-Nya: Enyahlah dari hadapan-Ku, hai kamu orang-orang terkutuk, enyahlah ke dalam api yang kekal yang telah sedia untuk Iblis dan malaikat-malaikatnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 42, 'Sebab ketika Aku lapar, kamu tidak memberi Aku makan; ketika Aku haus, kamu tidak memberi Aku minum;', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 43, 'ketika Aku seorang asing, kamu tidak memberi Aku tumpangan; ketika Aku telanjang, kamu tidak memberi Aku pakaian; ketika Aku sakit dan dalam penjara, kamu tidak melawat Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 44, 'Lalu merekapun akan menjawab Dia, katanya: Tuhan, bilamanakah kami melihat Engkau lapar, atau haus, atau sebagai orang asing, atau telanjang atau sakit, atau dalam penjara dan kami tidak melayani Engkau?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 45, 'Maka Ia akan menjawab mereka: Aku berkata kepadamu, sesungguhnya segala sesuatu yang tidak kamu lakukan untuk salah seorang dari yang paling hina ini, kamu tidak melakukannya juga untuk Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 25, 46, 'Dan mereka ini akan masuk ke tempat siksaan yang kekal, tetapi orang benar ke dalam hidup yang kekal."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 1, 'Setelah Yesus selesai dengan segala pengajaran-Nya itu, berkatalah Ia kepada murid-murid-Nya:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 2, '"Kamu tahu, bahwa dua hari lagi akan dirayakan Paskah, maka Anak Manusia akan diserahkan untuk disalibkan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 3, 'Pada waktu itu berkumpullah imam-imam kepala dan tua-tua bangsa Yahudi di istana Imam Besar yang bernama Kayafas,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 4, 'dan mereka merundingkan suatu rencana untuk menangkap Yesus dengan tipu muslihat dan untuk membunuh Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 5, 'Tetapi mereka berkata: "Jangan pada waktu perayaan, supaya jangan timbul keributan di antara rakyat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 6, 'Ketika Yesus berada di Betania, di rumah Simon si kusta,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 7, 'datanglah seorang perempuan kepada-Nya membawa sebuah buli-buli pualam berisi minyak wangi yang mahal. Minyak itu dicurahkannya ke atas kepala Yesus, yang sedang duduk makan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 8, 'Melihat itu murid-murid gusar dan berkata: "Untuk apa pemborosan ini?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 9, 'Sebab minyak itu dapat dijual dengan mahal dan uangnya dapat diberikan kepada orang-orang miskin."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 10, 'Tetapi Yesus mengetahui pikiran mereka lalu berkata: "Mengapa kamu menyusahkan perempuan ini? Sebab ia telah melakukan suatu perbuatan yang baik pada-Ku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 11, 'Karena orang-orang miskin selalu ada padamu, tetapi Aku tidak akan selalu bersama-sama kamu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 12, 'Sebab dengan mencurahkan minyak itu ke tubuh-Ku, ia membuat suatu persiapan untuk penguburan-Ku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 13, 'Aku berkata kepadamu: Sesungguhnya di mana saja Injil ini diberitakan di seluruh dunia, apa yang dilakukannya ini akan disebut juga untuk mengingat dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 14, 'Kemudian pergilah seorang dari kedua belas murid itu, yang bernama Yudas Iskariot, kepada imam-imam kepala.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 15, 'Ia berkata: "Apa yang hendak kamu berikan kepadaku, supaya aku menyerahkan Dia kepada kamu?" Mereka membayar tiga puluh uang perak kepadanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 16, 'Dan mulai saat itu ia mencari kesempatan yang baik untuk menyerahkan Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 17, 'Pada hari pertama dari hari raya Roti Tidak Beragi datanglah murid-murid Yesus kepada-Nya dan berkata: "Di mana Engkau kehendaki kami mempersiapkan perjamuan Paskah bagi-Mu?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 18, 'Jawab Yesus: "Pergilah ke kota kepada si Anu dan katakan kepadanya: Pesan Guru: waktu-Ku hampir tiba; di dalam rumahmulah Aku mau merayakan Paskah bersama-sama dengan murid-murid-Ku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 19, 'Lalu murid-murid-Nya melakukan seperti yang ditugaskan Yesus kepada mereka dan mempersiapkan Paskah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 20, 'Setelah hari malam, Yesus duduk makan bersama-sama dengan kedua belas murid itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 21, 'Dan ketika mereka sedang makan, Ia berkata: "Aku berkata kepadamu, sesungguhnya seorang di antara kamu akan menyerahkan Aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 22, 'Dan dengan hati yang sangat sedih berkatalah mereka seorang demi seorang kepada-Nya: "Bukan aku, ya Tuhan?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 23, 'Ia menjawab: "Dia yang bersama-sama dengan Aku mencelupkan tangannya ke dalam pinggan ini, dialah yang akan menyerahkan Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 24, 'Anak Manusia memang akan pergi sesuai dengan yang ada tertulis tentang Dia, akan tetapi celakalah orang yang olehnya Anak Manusia itu diserahkan. Adalah lebih baik bagi orang itu sekiranya ia tidak dilahirkan."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 25, 'Yudas, yang hendak menyerahkan Dia itu menjawab, katanya: "Bukan aku, ya Rabi?" Kata Yesus kepadanya: "Engkau telah mengatakannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 26, 'Dan ketika mereka sedang makan, Yesus mengambil roti, mengucap berkat, memecah-mecahkannya lalu memberikannya kepada murid-murid-Nya dan berkata: "Ambillah, makanlah, inilah tubuh-Ku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 27, 'Sesudah itu Ia mengambil cawan, mengucap syukur lalu memberikannya kepada mereka dan berkata: "Minumlah, kamu semua, dari cawan ini.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 28, 'Sebab inilah darah-Ku, darah perjanjian, yang ditumpahkan bagi banyak orang untuk pengampunan dosa.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 29, 'Akan tetapi Aku berkata kepadamu: mulai dari sekarang Aku tidak akan minum lagi hasil pokok anggur ini sampai pada hari Aku meminumnya, yaitu yang baru, bersama-sama dengan kamu dalam Kerajaan Bapa-Ku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 30, 'Sesudah menyanyikan nyanyian pujian, pergilah Yesus dan murid-murid-Nya ke Bukit Zaitun.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 31, 'Maka berkatalah Yesus kepada mereka: "Malam ini kamu semua akan tergoncang imanmu karena Aku. Sebab ada tertulis: Aku akan membunuh gembala dan kawanan domba itu akan tercerai-berai.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 32, 'Akan tetapi sesudah Aku bangkit, Aku akan mendahului kamu ke Galilea."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 33, 'Petrus menjawab-Nya: "Biarpun mereka semua tergoncang imannya karena Engkau, aku sekali-kali tidak."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 34, 'Yesus berkata kepadanya: "Aku berkata kepadamu, sesungguhnya malam ini, sebelum ayam berkokok, engkau telah menyangkal Aku tiga kali."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 35, 'Kata Petrus kepada-Nya: "Sekalipun aku harus mati bersama-sama Engkau, aku takkan menyangkal Engkau." Semua murid yang lainpun berkata demikian juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 36, 'Maka sampailah Yesus bersama-sama murid-murid-Nya ke suatu tempat yang bernama Getsemani. Lalu Ia berkata kepada murid-murid-Nya: "Duduklah di sini, sementara Aku pergi ke sana untuk berdoa."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 37, 'Dan Ia membawa Petrus dan kedua anak Zebedeus serta-Nya. Maka mulailah Ia merasa sedih dan gentar,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 38, 'lalu kata-Nya kepada mereka: "Hati-Ku sangat sedih, seperti mau mati rasanya. Tinggallah di sini dan berjaga-jagalah dengan Aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 39, 'Maka Ia maju sedikit, lalu sujud dan berdoa, kata-Nya: "Ya Bapa-Ku, jikalau sekiranya mungkin, biarlah cawan ini lalu dari pada-Ku, tetapi janganlah seperti yang Kukehendaki, melainkan seperti yang Engkau kehendaki."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 40, 'Setelah itu Ia kembali kepada murid-murid-Nya itu dan mendapati mereka sedang tidur. Dan Ia berkata kepada Petrus: "Tidakkah kamu sanggup berjaga-jaga satu jam dengan Aku?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 41, 'Berjaga-jagalah dan berdoalah, supaya kamu jangan jatuh ke dalam pencobaan: roh memang penurut, tetapi daging lemah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 42, 'Lalu Ia pergi untuk kedua kalinya dan berdoa, kata-Nya: "Ya Bapa-Ku jikalau cawan ini tidak mungkin lalu, kecuali apabila Aku meminumnya, jadilah kehendak-Mu!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 43, 'Dan ketika Ia kembali pula, Ia mendapati mereka sedang tidur, sebab mata mereka sudah berat.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 44, 'Ia membiarkan mereka di situ lalu pergi dan berdoa untuk ketiga kalinya dan mengucapkan doa yang itu juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 45, 'Sesudah itu Ia datang kepada murid-murid-Nya dan berkata kepada mereka: "Tidurlah sekarang dan istirahatlah. Lihat, saatnya sudah tiba, bahwa Anak Manusia diserahkan ke tangan orang-orang berdosa.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 46, 'Bangunlah, marilah kita pergi. Dia yang menyerahkan Aku sudah dekat."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 47, 'Waktu Yesus masih berbicara datanglah Yudas, salah seorang dari kedua belas murid itu, dan bersama-sama dia serombongan besar orang yang membawa pedang dan pentung, disuruh oleh imam-imam kepala dan tua-tua bangsa Yahudi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 48, 'Orang yang menyerahkan Dia telah memberitahukan tanda ini kepada mereka: "Orang yang akan kucium, itulah Dia, tangkaplah Dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 49, 'Dan segera ia maju mendapatkan Yesus dan berkata: "Salam Rabi," lalu mencium Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 50, 'Tetapi Yesus berkata kepadanya: "Hai teman, untuk itukah engkau datang?" Maka majulah mereka memegang Yesus dan menangkap-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 51, 'Tetapi seorang dari mereka yang menyertai Yesus mengulurkan tangannya, menghunus pedangnya dan menetakkannya kepada hamba Imam Besar sehingga putus telinganya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 52, 'Maka kata Yesus kepadanya: "Masukkan pedang itu kembali ke dalam sarungnya, sebab barangsiapa menggunakan pedang, akan binasa oleh pedang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 53, 'Atau kausangka, bahwa Aku tidak dapat berseru kepada Bapa-Ku, supaya Ia segera mengirim lebih dari dua belas pasukan malaikat membantu Aku?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 54, 'Jika begitu, bagaimanakah akan digenapi yang tertulis dalam Kitab Suci, yang mengatakan, bahwa harus terjadi demikian?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 55, 'Pada saat itu Yesus berkata kepada orang banyak: "Sangkamu Aku ini penyamun, maka kamu datang lengkap dengan pedang dan pentung untuk menangkap Aku? Padahal tiap-tiap hari Aku duduk mengajar di Bait Allah, dan kamu tidak menangkap Aku.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 56, 'Akan tetapi semua ini terjadi supaya genap yang ada tertulis dalam kitab nabi-nabi." Lalu semua murid itu meninggalkan Dia dan melarikan diri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 57, 'Sesudah mereka menangkap Yesus, mereka membawa-Nya menghadap Kayafas, Imam Besar. Di situ telah berkumpul ahli-ahli Taurat dan tua-tua.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 58, 'Dan Petrus mengikuti Dia dari jauh sampai ke halaman Imam Besar, dan setelah masuk ke dalam, ia duduk di antara pengawal-pengawal untuk melihat kesudahan perkara itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 59, 'Imam-imam kepala, malah seluruh Mahkamah Agama mencari kesaksian palsu terhadap Yesus, supaya Ia dapat dihukum mati,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 26, 60, 'tetapi mereka tidak memperolehnya, walaupun tampil banyak saksi dusta. Tetapi akhirnya tampillah dua orang,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 1, 'Ketika hari mulai siang, semua imam kepala dan tua-tua bangsa Yahudi berkumpul dan mengambil keputusan untuk membunuh Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 2, 'Mereka membelenggu Dia, lalu membawa-Nya dan menyerahkan-Nya kepada Pilatus, wali negeri itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 3, 'Pada waktu Yudas, yang menyerahkan Dia, melihat, bahwa Yesus telah dijatuhi hukuman mati, menyesallah ia. Lalu ia mengembalikan uang yang tiga puluh perak itu kepada imam-imam kepala dan tua-tua,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 4, 'dan berkata: "Aku telah berdosa karena menyerahkan darah orang yang tak bersalah." Tetapi jawab mereka: "Apa urusan kami dengan itu? Itu urusanmu sendiri!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 5, 'Maka iapun melemparkan uang perak itu ke dalam Bait Suci, lalu pergi dari situ dan menggantung diri.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 6, 'Imam-imam kepala mengambil uang perak itu dan berkata: "Tidak diperbolehkan memasukkan uang ini ke dalam peti persembahan, sebab ini uang darah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 7, 'Sesudah berunding mereka membeli dengan uang itu tanah yang disebut Tanah Tukang Periuk untuk dijadikan tempat pekuburan orang asing.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 8, 'Itulah sebabnya tanah itu sampai pada hari ini disebut Tanah Darah.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 9, 'Dengan demikian genaplah firman yang disampaikan oleh nabi Yeremia: "Mereka menerima tiga puluh uang perak, yaitu harga yang ditetapkan untuk seorang menurut penilaian yang berlaku di antara orang Israel,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 10, 'dan mereka memberikan uang itu untuk tanah tukang periuk, seperti yang dipesankan Tuhan kepadaku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 11, 'Lalu Yesus dihadapkan kepada wali negeri. Dan wali negeri bertanya kepada-Nya: "Engkaukah raja orang Yahudi?" Jawab Yesus: "Engkau sendiri mengatakannya."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 12, 'Tetapi atas tuduhan yang diajukan imam-imam kepala dan tua-tua terhadap Dia, Ia tidak memberi jawab apapun.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 13, 'Maka kata Pilatus kepada-Nya: "Tidakkah Engkau dengar betapa banyaknya tuduhan saksi-saksi ini terhadap Engkau?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 14, 'Tetapi Ia tidak menjawab suatu katapun, sehingga wali negeri itu sangat heran.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 15, 'Telah menjadi kebiasaan bagi wali negeri untuk membebaskan satu orang hukuman pada tiap-tiap hari raya itu atas pilihan orang banyak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 16, 'Dan pada waktu itu ada dalam penjara seorang yang terkenal kejahatannya yang bernama Yesus Barabas.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 17, 'Karena mereka sudah berkumpul di sana, Pilatus berkata kepada mereka: "Siapa yang kamu kehendaki kubebaskan bagimu, Yesus Barabas atau Yesus, yang disebut Kristus?"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 18, 'Ia memang mengetahui, bahwa mereka telah menyerahkan Yesus karena dengki.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 19, 'Ketika Pilatus sedang duduk di kursi pengadilan, isterinya mengirim pesan kepadanya: "Jangan engkau mencampuri perkara orang benar itu, sebab karena Dia aku sangat menderita dalam mimpi tadi malam."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 20, 'Tetapi oleh hasutan imam-imam kepala dan tua-tua, orang banyak bertekad untuk meminta supaya Barabas dibebaskan dan Yesus dihukum mati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 21, 'Wali negeri menjawab dan berkata kepada mereka: "Siapa di antara kedua orang itu yang kamu kehendaki kubebaskan bagimu?" Kata mereka: "Barabas."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 22, 'Kata Pilatus kepada mereka: "Jika begitu, apakah yang harus kuperbuat dengan Yesus, yang disebut Kristus?" Mereka semua berseru: "Ia harus disalibkan!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 23, 'Katanya: "Tetapi kejahatan apakah yang telah dilakukan-Nya?" Namun mereka makin keras berteriak: "Ia harus disalibkan!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 24, 'Ketika Pilatus melihat bahwa segala usaha akan sia-sia, malah sudah mulai timbul kekacauan, ia mengambil air dan membasuh tangannya di hadapan orang banyak dan berkata: "Aku tidak bersalah terhadap darah orang ini; itu urusan kamu sendiri!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 25, 'Dan seluruh rakyat itu menjawab: "Biarlah darah-Nya ditanggungkan atas kami dan atas anak-anak kami!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 26, 'Lalu ia membebaskan Barabas bagi mereka, tetapi Yesus disesahnya lalu diserahkannya untuk disalibkan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 27, 'Kemudian serdadu-serdadu wali negeri membawa Yesus ke gedung pengadilan, lalu memanggil seluruh pasukan berkumpul sekeliling Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 28, 'Mereka menanggalkan pakaian-Nya dan mengenakan jubah ungu kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 29, 'Mereka menganyam sebuah mahkota duri dan menaruhnya di atas kepala-Nya, lalu memberikan Dia sebatang buluh di tangan kanan-Nya. Kemudian mereka berlutut di hadapan-Nya dan mengolok-olokkan Dia, katanya: "Salam, hai Raja orang Yahudi!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 30, 'Mereka meludahi-Nya dan mengambil buluh itu dan memukulkannya ke kepala-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 31, 'Sesudah mengolok-olokkan Dia mereka menanggalkan jubah itu dari pada-Nya dan mengenakan pula pakaian-Nya kepada-Nya. Kemudian mereka membawa Dia ke luar untuk disalibkan.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 32, 'Ketika mereka berjalan ke luar kota, mereka berjumpa dengan seorang dari Kirene yang bernama Simon. Orang itu mereka paksa untuk memikul salib Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 33, 'Maka sampailah mereka di suatu tempat yang bernama Golgota, artinya: Tempat Tengkorak.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 34, 'Lalu mereka memberi Dia minum anggur bercampur empedu. Setelah Ia mengecapnya, Ia tidak mau meminumnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 35, 'Sesudah menyalibkan Dia mereka membagi-bagi pakaian-Nya dengan membuang undi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 36, 'Lalu mereka duduk di situ menjaga Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 37, 'Dan di atas kepala-Nya terpasang tulisan yang menyebut alasan mengapa Ia dihukum: "Inilah Yesus Raja orang Yahudi."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 38, 'Bersama dengan Dia disalibkan dua orang penyamun, seorang di sebelah kanan dan seorang di sebelah kiri-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 39, 'Orang-orang yang lewat di sana menghujat Dia dan sambil menggelengkan kepala,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 40, 'mereka berkata: "Hai Engkau yang mau merubuhkan Bait Suci dan mau membangunnya kembali dalam tiga hari, selamatkanlah diri-Mu jikalau Engkau Anak Allah, turunlah dari salib itu!"', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 41, 'Demikian juga imam-imam kepala bersama-sama ahli-ahli Taurat dan tua-tua mengolok-olokkan Dia dan mereka berkata:', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 42, '"Orang lain Ia selamatkan, tetapi diri-Nya sendiri tidak dapat Ia selamatkan! Ia Raja Israel? Baiklah Ia turun dari salib itu dan kami akan percaya kepada-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 43, 'Ia menaruh harapan-Nya pada Allah: baiklah Allah menyelamatkan Dia, jikalau Allah berkenan kepada-Nya! Karena Ia telah berkata: Aku adalah Anak Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 44, 'Bahkan penyamun-penyamun yang disalibkan bersama-sama dengan Dia mencela-Nya demikian juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 45, 'Mulai dari jam dua belas kegelapan meliputi seluruh daerah itu sampai jam tiga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 46, 'Kira-kira jam tiga berserulah Yesus dengan suara nyaring: "Eli, Eli, lama sabakhtani?" Artinya: Allah-Ku, Allah-Ku, mengapa Engkau meninggalkan Aku?', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 47, 'Mendengar itu, beberapa orang yang berdiri di situ berkata: "Ia memanggil Elia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 48, 'Dan segeralah datang seorang dari mereka; ia mengambil bunga karang, mencelupkannya ke dalam anggur asam, lalu mencucukkannya pada sebatang buluh dan memberi Yesus minum.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 49, 'Tetapi orang-orang lain berkata: "Jangan, baiklah kita lihat, apakah Elia datang untuk menyelamatkan Dia."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 50, 'Yesus berseru pula dengan suara nyaring lalu menyerahkan nyawa-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 51, 'Dan lihatlah, tabir Bait Suci terbelah dua dari atas sampai ke bawah dan terjadilah gempa bumi, dan bukit-bukit batu terbelah,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 52, 'dan kuburan-kuburan terbuka dan banyak orang kudus yang telah meninggal bangkit.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 53, 'Dan sesudah kebangkitan Yesus, merekapun keluar dari kubur, lalu masuk ke kota kudus dan menampakkan diri kepada banyak orang.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 54, 'Kepala pasukan dan prajurit-prajuritnya yang menjaga Yesus menjadi sangat takut ketika mereka melihat gempa bumi dan apa yang telah terjadi, lalu berkata: "Sungguh, Ia ini adalah Anak Allah."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 55, 'Dan ada di situ banyak perempuan yang melihat dari jauh, yaitu perempuan-perempuan yang mengikuti Yesus dari Galilea untuk melayani Dia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 56, 'Di antara mereka terdapat Maria Magdalena, dan Maria ibu Yakobus dan Yusuf, dan ibu anak-anak Zebedeus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 57, 'Menjelang malam datanglah seorang kaya, orang Arimatea, yang bernama Yusuf dan yang telah menjadi murid Yesus juga.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 58, 'Ia pergi menghadap Pilatus dan meminta mayat Yesus. Pilatus memerintahkan untuk menyerahkannya kepadanya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 59, 'Dan Yusufpun mengambil mayat itu, mengapaninya dengan kain lenan yang putih bersih,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 27, 60, 'lalu membaringkannya di dalam kuburnya yang baru, yang digalinya di dalam bukit batu, dan sesudah menggulingkan sebuah batu besar ke pintu kubur itu, pergilah ia.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 1, 'Setelah hari Sabat lewat, menjelang menyingsingnya fajar pada hari pertama minggu itu, pergilah Maria Magdalena dan Maria yang lain, menengok kubur itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 2, 'Maka terjadilah gempa bumi yang hebat sebab seorang malaikat Tuhan turun dari langit dan datang ke batu itu dan menggulingkannya lalu duduk di atasnya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 3, 'Wajahnya bagaikan kilat dan pakaiannya putih bagaikan salju.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 4, 'Dan penjaga-penjaga itu gentar ketakutan dan menjadi seperti orang-orang mati.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 5, 'Akan tetapi malaikat itu berkata kepada perempuan-perempuan itu: "Janganlah kamu takut; sebab aku tahu kamu mencari Yesus yang disalibkan itu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 6, 'Ia tidak ada di sini, sebab Ia telah bangkit, sama seperti yang telah dikatakan-Nya. Mari, lihatlah tempat Ia berbaring.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 7, 'Dan segeralah pergi dan katakanlah kepada murid-murid-Nya bahwa Ia telah bangkit dari antara orang mati. Ia mendahului kamu ke Galilea; di sana kamu akan melihat Dia. Sesungguhnya aku telah mengatakannya kepadamu."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 8, 'Mereka segera pergi dari kubur itu, dengan takut dan dengan sukacita yang besar dan berlari cepat-cepat untuk memberitahukannya kepada murid-murid Yesus.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 9, 'Tiba-tiba Yesus berjumpa dengan mereka dan berkata: "Salam bagimu." Mereka mendekati-Nya dan memeluk kaki-Nya serta menyembah-Nya.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 10, 'Maka kata Yesus kepada mereka: "Jangan takut. Pergi dan katakanlah kepada saudara-saudara-Ku, supaya mereka pergi ke Galilea, dan di sanalah mereka akan melihat Aku."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 11, 'Ketika mereka di tengah jalan, datanglah beberapa orang dari penjaga itu ke kota dan memberitahukan segala yang terjadi itu kepada imam-imam kepala.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 12, 'Dan sesudah berunding dengan tua-tua, mereka mengambil keputusan lalu memberikan sejumlah besar uang kepada serdadu-serdadu itu', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 13, 'dan berkata: "Kamu harus mengatakan, bahwa murid-murid-Nya datang malam-malam dan mencuri-Nya ketika kamu sedang tidur.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 14, 'Dan apabila hal ini kedengaran oleh wali negeri, kami akan berbicara dengan dia, sehingga kamu tidak beroleh kesulitan apa-apa."', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 15, 'Mereka menerima uang itu dan berbuat seperti yang dipesankan kepada mereka. Dan ceritera ini tersiar di antara orang Yahudi sampai sekarang ini.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 16, 'Dan kesebelas murid itu berangkat ke Galilea, ke bukit yang telah ditunjukkan Yesus kepada mereka.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 17, 'Ketika melihat Dia mereka menyembah-Nya, tetapi beberapa orang ragu-ragu.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 18, 'Yesus mendekati mereka dan berkata: "Kepada-Ku telah diberikan segala kuasa di sorga dan di bumi.', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 19, 'Karena itu pergilah, jadikanlah semua bangsa murid-Ku dan baptislah mereka dalam nama Bapa dan Anak dan Roh Kudus,', 'id', 'TB'),
  ('40', 'mat', 'Matius', 28, 20, 'dan ajarlah mereka melakukan segala sesuatu yang telah Kuperintahkan kepadamu. Dan ketahuilah, Aku menyertai kamu senantiasa sampai kepada akhir zaman."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 1, 'Inilah permulaan Injil tentang Yesus Kristus, Anak Allah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 2, 'Seperti ada tertulis dalam kitab nabi Yesaya: "Lihatlah, Aku menyuruh utusan-Ku mendahului Engkau, ia akan mempersiapkan jalan bagi-Mu;', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 3, 'ada suara orang yang berseru-seru di padang gurun: Persiapkanlah jalan untuk Tuhan, luruskanlah jalan bagi-Nya",', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 4, 'demikianlah Yohanes Pembaptis tampil di padang gurun dan menyerukan: "Bertobatlah dan berilah dirimu dibaptis dan Allah akan mengampuni dosamu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 5, 'Lalu datanglah kepadanya orang-orang dari seluruh daerah Yudea dan semua penduduk Yerusalem, dan sambil mengaku dosanya mereka dibaptis di sungai Yordan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 6, 'Yohanes memakai jubah bulu unta dan ikat pinggang kulit, dan makanannya belalang dan madu hutan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 7, 'Inilah yang diberitakannya: "Sesudah aku akan datang Ia yang lebih berkuasa dari padaku; membungkuk dan membuka tali kasut-Nyapun aku tidak layak.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 8, 'Aku membaptis kamu dengan air, tetapi Ia akan membaptis kamu dengan Roh Kudus."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 9, 'Pada waktu itu datanglah Yesus dari Nazaret di tanah Galilea, dan Ia dibaptis di sungai Yordan oleh Yohanes.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 10, 'Pada saat Ia keluar dari air, Ia melihat langit terkoyak, dan Roh seperti burung merpati turun ke atas-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 11, 'Lalu terdengarlah suara dari sorga: "Engkaulah Anak-Ku yang Kukasihi, kepada-Mulah Aku berkenan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 12, 'Segera sesudah itu Roh memimpin Dia ke padang gurun.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 13, 'Di padang gurun itu Ia tinggal empat puluh hari lamanya, dicobai oleh Iblis. Ia berada di sana di antara binatang-binatang liar dan malaikat-malaikat melayani Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 14, 'Sesudah Yohanes ditangkap datanglah Yesus ke Galilea memberitakan Injil Allah,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 15, 'kata-Nya: "Waktunya telah genap; Kerajaan Allah sudah dekat. Bertobatlah dan percayalah kepada Injil!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 16, 'Ketika Yesus sedang berjalan menyusur danau Galilea, Ia melihat Simon dan Andreas, saudara Simon. Mereka sedang menebarkan jala di danau, sebab mereka penjala ikan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 17, 'Yesus berkata kepada mereka: "Mari, ikutlah Aku dan kamu akan Kujadikan penjala manusia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 18, 'Lalu merekapun segera meninggalkan jalanya dan mengikuti Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 19, 'Dan setelah Yesus meneruskan perjalanan-Nya sedikit lagi, dilihat-Nya Yakobus, anak Zebedeus, dan Yohanes, saudaranya, sedang membereskan jala di dalam perahu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 20, 'Yesus segera memanggil mereka dan mereka meninggalkan ayahnya, Zebedeus, di dalam perahu bersama orang-orang upahannya lalu mengikuti Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 21, 'Mereka tiba di Kapernaum. Setelah hari Sabat mulai, Yesus segera masuk ke dalam rumah ibadat dan mengajar.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 22, 'Mereka takjub mendengar pengajaran-Nya, sebab Ia mengajar mereka sebagai orang yang berkuasa, tidak seperti ahli-ahli Taurat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 23, 'Pada waktu itu di dalam rumah ibadat itu ada seorang yang kerasukan roh jahat. Orang itu berteriak:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 24, '"Apa urusan-Mu dengan kami, hai Yesus orang Nazaret? Engkau datang hendak membinasakan kami? Aku tahu siapa Engkau: Yang Kudus dari Allah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 25, 'Tetapi Yesus menghardiknya, kata-Nya: "Diam, keluarlah dari padanya!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 26, 'Roh jahat itu menggoncang-goncang orang itu, dan sambil menjerit dengan suara nyaring ia keluar dari padanya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 27, 'Mereka semua takjub, sehingga mereka memperbincangkannya, katanya: "Apa ini? Suatu ajaran baru. Ia berkata-kata dengan kuasa. Roh-roh jahatpun diperintah-Nya dan mereka taat kepada-Nya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 28, 'Lalu tersebarlah dengan cepat kabar tentang Dia ke segala penjuru di seluruh Galilea.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 29, 'Sekeluarnya dari rumah ibadat itu Yesus dengan Yakobus dan Yohanes pergi ke rumah Simon dan Andreas.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 30, 'Ibu mertua Simon terbaring karena sakit demam. Mereka segera memberitahukan keadaannya kepada Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 31, 'Ia pergi ke tempat perempuan itu, dan sambil memegang tangannya Ia membangunkan dia, lalu lenyaplah demamnya. Kemudian perempuan itu melayani mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 32, 'Menjelang malam, sesudah matahari terbenam, dibawalah kepada Yesus semua orang yang menderita sakit dan yang kerasukan setan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 33, 'Maka berkerumunlah seluruh penduduk kota itu di depan pintu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 34, 'Ia menyembuhkan banyak orang yang menderita bermacam-macam penyakit dan mengusir banyak setan; Ia tidak memperbolehkan setan-setan itu berbicara, sebab mereka mengenal Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 35, 'Pagi-pagi benar, waktu hari masih gelap, Ia bangun dan pergi ke luar. Ia pergi ke tempat yang sunyi dan berdoa di sana.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 36, 'Tetapi Simon dan kawan-kawannya menyusul Dia;', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 37, 'waktu menemukan Dia mereka berkata: "Semua orang mencari Engkau."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 38, 'Jawab-Nya: "Marilah kita pergi ke tempat lain, ke kota-kota yang berdekatan, supaya di sana juga Aku memberitakan Injil, karena untuk itu Aku telah datang."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 39, 'Lalu pergilah Ia ke seluruh Galilea dan memberitakan Injil dalam rumah-rumah ibadat mereka dan mengusir setan-setan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 40, 'Seorang yang sakit kusta datang kepada Yesus, dan sambil berlutut di hadapan-Nya ia memohon bantuan-Nya, katanya: "Kalau Engkau mau, Engkau dapat mentahirkan aku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 41, 'Maka tergeraklah hati-Nya oleh belas kasihan, lalu Ia mengulurkan tangan-Nya, menjamah orang itu dan berkata kepadanya: "Aku mau, jadilah engkau tahir."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 42, 'Seketika itu juga lenyaplah penyakit kusta orang itu, dan ia menjadi tahir.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 43, 'Segera Ia menyuruh orang itu pergi dengan peringatan keras:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 44, '"Ingatlah, janganlah engkau memberitahukan apa-apa tentang hal ini kepada siapapun, tetapi pergilah, perlihatkanlah dirimu kepada imam dan persembahkanlah untuk pentahiranmu persembahan, yang diperintahkan oleh Musa, sebagai bukti bagi mereka."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 1, 45, 'Tetapi orang itu pergi memberitakan peristiwa itu dan menyebarkannya kemana-mana, sehingga Yesus tidak dapat lagi terang-terangan masuk ke dalam kota. Ia tinggal di luar di tempat-tempat yang sepi; namun orang terus juga datang kepada-Nya dari segala penjuru.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 1, 'Kemudian, sesudah lewat beberapa hari, waktu Yesus datang lagi ke Kapernaum, tersiarlah kabar, bahwa Ia ada di rumah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 2, 'Maka datanglah orang-orang berkerumun sehingga tidak ada lagi tempat, bahkan di muka pintupun tidak. Sementara Ia memberitakan firman kepada mereka,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 3, 'ada orang-orang datang membawa kepada-Nya seorang lumpuh, digotong oleh empat orang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 4, 'Tetapi mereka tidak dapat membawanya kepada-Nya karena orang banyak itu, lalu mereka membuka atap yang di atas-Nya; sesudah terbuka mereka menurunkan tilam, tempat orang lumpuh itu terbaring.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 5, 'Ketika Yesus melihat iman mereka, berkatalah Ia kepada orang lumpuh itu: "Hai anak-Ku, dosamu sudah diampuni!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 6, 'Tetapi di situ ada juga duduk beberapa ahli Taurat, mereka berpikir dalam hatinya:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 7, '"Mengapa orang ini berkata begitu? Ia menghujat Allah. Siapa yang dapat mengampuni dosa selain dari pada Allah sendiri?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 8, 'Tetapi Yesus segera mengetahui dalam hati-Nya, bahwa mereka berpikir demikian, lalu Ia berkata kepada mereka: "Mengapa kamu berpikir begitu dalam hatimu?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 9, 'Manakah lebih mudah, mengatakan kepada orang lumpuh ini: Dosamu sudah diampuni, atau mengatakan: Bangunlah, angkatlah tilammu dan berjalan?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 10, 'Tetapi supaya kamu tahu, bahwa di dunia ini Anak Manusia berkuasa mengampuni dosa" ?berkatalah Ia kepada orang lumpuh itu?:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 11, '"Kepadamu Kukatakan, bangunlah, angkatlah tempat tidurmu dan pulanglah ke rumahmu!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 12, 'Dan orang itupun bangun, segera mengangkat tempat tidurnya dan pergi ke luar di hadapan orang-orang itu, sehingga mereka semua takjub lalu memuliakan Allah, katanya: "Yang begini belum pernah kita lihat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 13, 'Sesudah itu Yesus pergi lagi ke pantai danau, dan seluruh orang banyak datang kepada-Nya, lalu Ia mengajar mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 14, 'Kemudian ketika Ia berjalan lewat di situ, Ia melihat Lewi anak Alfeus duduk di rumah cukai lalu Ia berkata kepadanya: "Ikutlah Aku!" Maka berdirilah Lewi lalu mengikuti Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 15, 'Kemudian ketika Yesus makan di rumah orang itu, banyak pemungut cukai dan orang berdosa makan bersama-sama dengan Dia dan murid-murid-Nya, sebab banyak orang yang mengikuti Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 16, 'Pada waktu ahli-ahli Taurat dari golongan Farisi melihat, bahwa Ia makan dengan pemungut cukai dan orang berdosa itu, berkatalah mereka kepada murid-murid-Nya: "Mengapa Ia makan bersama-sama dengan pemungut cukai dan orang berdosa?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 17, 'Yesus mendengarnya dan berkata kepada mereka: "Bukan orang sehat yang memerlukan tabib, tetapi orang sakit; Aku datang bukan untuk memanggil orang benar, melainkan orang berdosa."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 18, 'Pada suatu kali ketika murid-murid Yohanes dan orang-orang Farisi sedang berpuasa, datanglah orang-orang dan mengatakan kepada Yesus: "Mengapa murid-murid Yohanes dan murid-murid orang Farisi berpuasa, tetapi murid-murid-Mu tidak?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 19, 'Jawab Yesus kepada mereka: "Dapatkah sahabat-sahabat mempelai laki-laki berpuasa sedang mempelai itu bersama mereka? Selama mempelai itu bersama mereka, mereka tidak dapat berpuasa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 20, 'Tetapi waktunya akan datang mempelai itu diambil dari mereka, dan pada waktu itulah mereka akan berpuasa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 21, 'Tidak seorangpun menambalkan secarik kain yang belum susut pada baju yang tua, karena jika demikian kain penambal itu akan mencabiknya, yang baru mencabik yang tua, lalu makin besarlah koyaknya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 22, 'Demikian juga tidak seorangpun mengisikan anggur yang baru ke dalam kantong kulit yang tua, karena jika demikian anggur itu akan mengoyakkan kantong itu, sehingga anggur itu dan kantongnya dua-duanya terbuang. Tetapi anggur yang baru hendaknya disimpan dalam kantong yang baru pula."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 23, 'Pada suatu kali, pada hari Sabat, Yesus berjalan di ladang gandum, dan sementara berjalan murid-murid-Nya memetik bulir gandum.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 24, 'Maka kata orang-orang Farisi kepada-Nya: "Lihat! Mengapa mereka berbuat sesuatu yang tidak diperbolehkan pada hari Sabat?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 25, 'Jawab-Nya kepada mereka: "Belum pernahkah kamu baca apa yang dilakukan Daud, ketika ia dan mereka yang mengikutinya kekurangan dan kelaparan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 26, 'bagaimana ia masuk ke dalam Rumah Allah waktu Abyatar menjabat sebagai Imam Besar lalu makan roti sajian itu?yang tidak boleh dimakan kecuali oleh imam-imam?dan memberinya juga kepada pengikut-pengikutn', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 27, 'Lalu kata Yesus kepada mereka: "Hari Sabat diadakan untuk manusia dan bukan manusia untuk hari Sabat,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 2, 28, 'jadi Anak Manusia adalah juga Tuhan atas hari Sabat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 1, 'Kemudian Yesus masuk lagi ke rumah ibadat. Di situ ada seorang yang mati sebelah tangannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 2, 'Mereka mengamat-amati Yesus, kalau-kalau Ia menyembuhkan orang itu pada hari Sabat, supaya mereka dapat mempersalahkan Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 3, 'Kata Yesus kepada orang yang mati sebelah tangannya itu: "Mari, berdirilah di tengah!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 4, 'Kemudian kata-Nya kepada mereka: "Manakah yang diperbolehkan pada hari Sabat, berbuat baik atau berbuat jahat, menyelamatkan nyawa orang atau membunuh orang?" Tetapi mereka itu diam saja.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 5, 'Ia berdukacita karena kedegilan mereka dan dengan marah Ia memandang sekeliling-Nya kepada mereka lalu Ia berkata kepada orang itu: "Ulurkanlah tanganmu!" Dan ia mengulurkannya, maka sembuhlah tangannya itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 6, 'Lalu keluarlah orang-orang Farisi dan segera bersekongkol dengan orang-orang Herodian untuk membunuh Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 7, 'Kemudian Yesus dengan murid-murid-Nya menyingkir ke danau, dan banyak orang dari Galilea mengikuti-Nya. Juga dari Yudea,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 8, 'dari Yerusalem, dari Idumea, dari seberang Yordan, dan dari daerah Tirus dan Sidon datang banyak orang kepada-Nya, sesudah mereka mendengar segala yang dilakukan-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 9, 'Ia menyuruh murid-murid-Nya menyediakan sebuah perahu bagi-Nya karena orang banyak itu, supaya mereka jangan sampai menghimpit-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 10, 'Sebab Ia menyembuhkan banyak orang, sehingga semua penderita penyakit berdesak-desakan kepada-Nya hendak menjamah-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 11, 'Bilamana roh-roh jahat melihat Dia, mereka jatuh tersungkur di hadapan-Nya dan berteriak: "Engkaulah Anak Allah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 12, 'Tetapi Ia dengan keras melarang mereka memberitahukan siapa Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 13, 'Kemudian naiklah Yesus ke atas bukit. Ia memanggil orang-orang yang dikehendaki-Nya dan merekapun datang kepada-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 14, 'Ia menetapkan dua belas orang untuk menyertai Dia dan untuk diutus-Nya memberitakan Injil', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 15, 'dan diberi-Nya kuasa untuk mengusir setan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 16, 'Kedua belas orang yang ditetapkan-Nya itu ialah: Simon, yang diberi-Nya nama Petrus,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 17, 'Yakobus anak Zebedeus, dan Yohanes saudara Yakobus, yang keduanya diberi-Nya nama Boanerges, yang berarti anak-anak guruh,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 18, 'selanjutnya Andreas, Filipus, Bartolomeus, Matius, Tomas, Yakobus anak Alfeus, Tadeus, Simon orang Zelot,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 19, 'dan Yudas Iskariot, yang mengkhianati Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 20, 'Kemudian Yesus masuk ke sebuah rumah. Maka datanglah orang banyak berkerumun pula, sehingga makanpun mereka tidak dapat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 21, 'Waktu kaum keluarga-Nya mendengar hal itu, mereka datang hendak mengambil Dia, sebab kata mereka Ia tidak waras lagi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 22, 'Dan ahli-ahli Taurat yang datang dari Yerusalem berkata: "Ia kerasukan Beelzebul," dan: "Dengan penghulu setan Ia mengusir setan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 23, 'Yesus memanggil mereka, lalu berkata kepada mereka dalam perumpamaan: "Bagaimana Iblis dapat mengusir Iblis?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 24, 'Kalau suatu kerajaan terpecah-pecah, kerajaan itu tidak dapat bertahan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 25, 'dan jika suatu rumah tangga terpecah-pecah, rumah tangga itu tidak dapat bertahan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 26, 'Demikianlah juga kalau Iblis berontak melawan dirinya sendiri dan kalau ia terbagi-bagi, ia tidak dapat bertahan, melainkan sudahlah tiba kesudahannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 27, 'Tetapi tidak seorangpun dapat memasuki rumah seorang yang kuat untuk merampas harta bendanya apabila tidak diikatnya dahulu orang kuat itu. Sesudah itu barulah dapat ia merampok rumah itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 28, 'Aku berkata kepadamu: Sesungguhnya semua dosa dan hujat anak-anak manusia akan diampuni, ya, semua hujat yang mereka ucapkan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 29, 'Tetapi apabila seorang menghujat Roh Kudus, ia tidak mendapat ampun selama-lamanya, melainkan bersalah karena berbuat dosa kekal."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 30, 'Ia berkata demikian karena mereka katakan bahwa Ia kerasukan roh jahat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 31, 'Lalu datanglah ibu dan saudara-saudara Yesus. Sementara mereka berdiri di luar, mereka menyuruh orang memanggil Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 32, 'Ada orang banyak duduk mengelilingi Dia, mereka berkata kepada-Nya: "Lihat, ibu dan saudara-saudara-Mu ada di luar, dan berusaha menemui Engkau."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 33, 'Jawab Yesus kepada mereka: "Siapa ibu-Ku dan siapa saudara-saudara-Ku?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 34, 'Ia melihat kepada orang-orang yang duduk di sekeliling-Nya itu dan berkata: "Ini ibu-Ku dan saudara-saudara-Ku!', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 3, 35, 'Barangsiapa melakukan kehendak Allah, dialah saudara-Ku laki-laki, dialah saudara-Ku perempuan, dialah ibu-Ku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 1, 'Pada suatu kali Yesus mulai pula mengajar di tepi danau. Maka datanglah orang banyak yang sangat besar jumlahnya mengerumuni Dia, sehingga Ia naik ke sebuah perahu yang sedang berlabuh lalu duduk di situ, sedangkan semua orang banyak itu di darat, di tepi danau itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 2, 'Dan Ia mengajarkan banyak hal dalam perumpamaan kepada mereka. Dalam ajaran-Nya itu Ia berkata kepada mereka:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 3, '"Dengarlah! Adalah seorang penabur keluar untuk menabur.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 4, 'Pada waktu ia menabur sebagian benih itu jatuh di pinggir jalan, lalu datanglah burung dan memakannya sampai habis.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 5, 'Sebagian jatuh di tanah yang berbatu-batu, yang tidak banyak tanahnya, lalu benih itupun segera tumbuh, karena tanahnya tipis.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 6, 'Tetapi sesudah matahari terbit, layulah ia dan menjadi kering karena tidak berakar.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 7, 'Sebagian lagi jatuh di tengah semak duri, lalu makin besarlah semak itu dan menghimpitnya sampai mati, sehingga ia tidak berbuah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 8, 'Dan sebagian jatuh di tanah yang baik, ia tumbuh dengan suburnya dan berbuah, hasilnya ada yang tiga puluh kali lipat, ada yang enam puluh kali lipat, ada yang seratus kali lipat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 9, 'Dan kata-Nya: "Siapa mempunyai telinga untuk mendengar, hendaklah ia mendengar!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 10, 'Ketika Ia sendirian, pengikut-pengikut-Nya dan kedua belas murid itu menanyakan Dia tentang perumpamaan itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 11, 'Jawab-Nya: "Kepadamu telah diberikan rahasia Kerajaan Allah, tetapi kepada orang-orang luar segala sesuatu disampaikan dalam perumpamaan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 12, 'supaya: Sekalipun melihat, mereka tidak menanggap, sekalipun mendengar, mereka tidak mengerti, supaya mereka jangan berbalik dan mendapat ampun."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 13, 'Lalu Ia berkata kepada mereka: "Tidakkah kamu mengerti perumpamaan ini? Kalau demikian bagaimana kamu dapat memahami semua perumpamaan yang lain?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 14, 'Penabur itu menaburkan firman.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 15, 'Orang-orang yang di pinggir jalan, tempat firman itu ditaburkan, ialah mereka yang mendengar firman, lalu datanglah Iblis dan mengambil firman yang baru ditaburkan di dalam mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 16, 'Demikian juga yang ditaburkan di tanah yang berbatu-batu, ialah orang-orang yang mendengar firman itu dan segera menerimanya dengan gembira,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 17, 'tetapi mereka tidak berakar dan tahan sebentar saja. Apabila kemudian datang penindasan atau penganiayaan karena firman itu, mereka segera murtad.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 18, 'Dan yang lain ialah yang ditaburkan di tengah semak duri, itulah yang mendengar firman itu,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 19, 'lalu kekuatiran dunia ini dan tipu daya kekayaan dan keinginan-keinginan akan hal yang lain masuklah menghimpit firman itu sehingga tidak berbuah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 20, 'Dan akhirnya yang ditaburkan di tanah yang baik, ialah orang yang mendengar dan menyambut firman itu lalu berbuah, ada yang tiga puluh kali lipat, ada yang enam puluh kali lipat, dan ada yang seratus kali lipat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 21, 'Lalu Yesus berkata kepada mereka: "Orang membawa pelita bukan supaya ditempatkan di bawah gantang atau di bawah tempat tidur, melainkan supaya ditaruh di atas kaki dian.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 22, 'Sebab tidak ada sesuatu yang tersembunyi yang tidak akan dinyatakan, dan tidak ada sesuatu yang rahasia yang tidak akan tersingkap.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 23, 'Barangsiapa mempunyai telinga untuk mendengar, hendaklah ia mendengar!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 24, 'Lalu Ia berkata lagi: "Camkanlah apa yang kamu dengar! Ukuran yang kamu pakai untuk mengukur akan diukurkan kepadamu, dan di samping itu akan ditambah lagi kepadamu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 25, 'Karena siapa yang mempunyai, kepadanya akan diberi, tetapi siapa yang tidak mempunyai, apapun juga yang ada padanya akan diambil dari padanya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 26, 'Lalu kata Yesus: "Beginilah hal Kerajaan Allah itu: seumpama orang yang menaburkan benih di tanah,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 27, 'lalu pada malam hari ia tidur dan pada siang hari ia bangun, dan benih itu mengeluarkan tunas dan tunas itu makin tinggi, bagaimana terjadinya tidak diketahui orang itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 28, 'Bumi dengan sendirinya mengeluarkan buah, mula-mula tangkainya, lalu bulirnya, kemudian butir-butir yang penuh isinya dalam bulir itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 29, 'Apabila buah itu sudah cukup masak, orang itu segera menyabit, sebab musim menuai sudah tiba."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 30, 'Kata-Nya lagi: "Dengan apa hendak kita membandingkan Kerajaan Allah itu, atau dengan perumpamaan manakah hendaknya kita menggambarkannya?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 31, 'Hal Kerajaan itu seumpama biji sesawi yang ditaburkan di tanah. Memang biji itu yang paling kecil dari pada segala jenis benih yang ada di bumi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 32, 'Tetapi apabila ia ditaburkan, ia tumbuh dan menjadi lebih besar dari pada segala sayuran yang lain dan mengeluarkan cabang-cabang yang besar, sehingga burung-burung di udara dapat bersarang dalam naungannya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 33, 'Dalam banyak perumpamaan yang semacam itu Ia memberitakan firman kepada mereka sesuai dengan pengertian mereka,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 34, 'dan tanpa perumpamaan Ia tidak berkata-kata kepada mereka, tetapi kepada murid-murid-Nya Ia menguraikan segala sesuatu secara tersendiri.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 35, 'Pada hari itu, waktu hari sudah petang, Yesus berkata kepada mereka: "Marilah kita bertolak ke seberang."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 36, 'Mereka meninggalkan orang banyak itu lalu bertolak dan membawa Yesus beserta dengan mereka dalam perahu di mana Yesus telah duduk dan perahu-perahu lain juga menyertai Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 37, 'Lalu mengamuklah taufan yang sangat dahsyat dan ombak menyembur masuk ke dalam perahu, sehingga perahu itu mulai penuh dengan air.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 38, 'Pada waktu itu Yesus sedang tidur di buritan di sebuah tilam. Maka murid-murid-Nya membangunkan Dia dan berkata kepada-Nya: "Guru, Engkau tidak perduli kalau kita binasa?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 39, 'Iapun bangun, menghardik angin itu dan berkata kepada danau itu: "Diam! Tenanglah!" Lalu angin itu reda dan danau itu menjadi teduh sekali.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 40, 'Lalu Ia berkata kepada mereka: "Mengapa kamu begitu takut? Mengapa kamu tidak percaya?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 4, 41, 'Mereka menjadi sangat takut dan berkata seorang kepada yang lain: "Siapa gerangan orang ini, sehingga angin dan danaupun taat kepada-Nya?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 1, 'Lalu sampailah mereka di seberang danau, di daerah orang Gerasa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 2, 'Baru saja Yesus turun dari perahu, datanglah seorang yang kerasukan roh jahat dari pekuburan menemui Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 3, 'Orang itu diam di sana dan tidak ada seorangpun lagi yang sanggup mengikatnya, sekalipun dengan rantai,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 4, 'karena sudah sering ia dibelenggu dan dirantai, tetapi rantainya diputuskannya dan belenggunya dimusnahkannya, sehingga tidak ada seorangpun yang cukup kuat untuk menjinakkannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 5, 'Siang malam ia berkeliaran di pekuburan dan di bukit-bukit sambil berteriak-teriak dan memukuli dirinya dengan batu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 6, 'Ketika ia melihat Yesus dari jauh, berlarilah ia mendapatkan-Nya lalu menyembah-Nya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 7, 'dan dengan keras ia berteriak: "Apa urusan-Mu dengan aku, hai Yesus, Anak Allah Yang Mahatinggi? Demi Allah, jangan siksa aku!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 8, 'Karena sebelumnya Yesus mengatakan kepadanya: "Hai engkau roh jahat! Keluar dari orang ini!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 9, 'Kemudian Ia bertanya kepada orang itu: "Siapa namamu?" Jawabnya: "Namaku Legion, karena kami banyak."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 10, 'Ia memohon dengan sangat supaya Yesus jangan mengusir roh-roh itu keluar dari daerah itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 11, 'Adalah di sana di lereng bukit sejumlah besar babi sedang mencari makan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 12, 'lalu roh-roh itu meminta kepada-Nya, katanya: "Suruhlah kami pindah ke dalam babi-babi itu, biarkanlah kami memasukinya!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 13, 'Yesus mengabulkan permintaan mereka. Lalu keluarlah roh-roh jahat itu dan memasuki babi-babi itu. Kawanan babi yang kira-kira dua ribu jumlahnya itu terjun dari tepi jurang ke dalam danau dan mati lemas di dalamnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 14, 'Maka larilah penjaga-penjaga babi itu dan menceriterakan hal itu di kota dan di kampung-kampung sekitarnya. Lalu keluarlah orang untuk melihat apa yang terjadi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 15, 'Mereka datang kepada Yesus dan melihat orang yang kerasukan itu duduk, sudah berpakaian dan sudah waras, orang yang tadinya kerasukan legion itu. Maka takutlah mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 16, 'Orang-orang yang telah melihat sendiri hal itu menceriterakan kepada mereka tentang apa yang telah terjadi atas orang yang kerasukan setan itu, dan tentang babi-babi itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 17, 'Lalu mereka mendesak Yesus supaya Ia meninggalkan daerah mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 18, 'Pada waktu Yesus naik lagi ke dalam perahu, orang yang tadinya kerasukan setan itu meminta, supaya ia diperkenankan menyertai Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 19, 'Yesus tidak memperkenankannya, tetapi Ia berkata kepada orang itu: "Pulanglah ke rumahmu, kepada orang-orang sekampungmu, dan beritahukanlah kepada mereka segala sesuatu yang telah diperbuat oleh Tuhan atasmu dan bagaimana Ia telah mengasihani engkau!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 20, 'Orang itupun pergilah dan mulai memberitakan di daerah Dekapolis segala apa yang telah diperbuat Yesus atas dirinya dan mereka semua menjadi heran.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 21, 'Sesudah Yesus menyeberang lagi dengan perahu, orang banyak berbondong-bondong datang lalu mengerumuni Dia. Sedang Ia berada di tepi danau,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 22, 'datanglah seorang kepala rumah ibadat yang bernama Yairus. Ketika ia melihat Yesus, tersungkurlah ia di depan kaki-Nya', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 23, 'dan memohon dengan sangat kepada-Nya: "Anakku perempuan sedang sakit, hampir mati, datanglah kiranya dan letakkanlah tangan-Mu atasnya, supaya ia selamat dan tetap hidup."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 24, 'Lalu pergilah Yesus dengan orang itu. Orang banyak berbondong-bondong mengikuti Dia dan berdesak-desakan di dekat-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 25, 'Adalah di situ seorang perempuan yang sudah dua belas tahun lamanya menderita pendarahan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 26, 'Ia telah berulang-ulang diobati oleh berbagai tabib, sehingga telah dihabiskannya semua yang ada padanya, namun sama sekali tidak ada faedahnya malah sebaliknya keadaannya makin memburuk.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 27, 'Dia sudah mendengar berita-berita tentang Yesus, maka di tengah-tengah orang banyak itu ia mendekati Yesus dari belakang dan menjamah jubah-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 28, 'Sebab katanya: "Asal kujamah saja jubah-Nya, aku akan sembuh."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 29, 'Seketika itu juga berhentilah pendarahannya dan ia merasa, bahwa badannya sudah sembuh dari penyakitnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 30, 'Pada ketika itu juga Yesus mengetahui, bahwa ada tenaga yang keluar dari diri-Nya, lalu Ia berpaling di tengah orang banyak dan bertanya: "Siapa yang menjamah jubah-Ku?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 31, 'Murid-murid-Nya menjawab: "Engkau melihat bagaimana orang-orang ini berdesak-desakan dekat-Mu, dan Engkau bertanya: Siapa yang menjamah Aku?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 32, 'Lalu Ia memandang sekeliling-Nya untuk melihat siapa yang telah melakukan hal itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 33, 'Perempuan itu, yang menjadi takut dan gemetar ketika mengetahui apa yang telah terjadi atas dirinya, tampil dan tersungkur di depan Yesus dan dengan tulus memberitahukan segala sesuatu kepada-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 34, 'Maka kata-Nya kepada perempuan itu: "Hai anak-Ku, imanmu telah menyelamatkan engkau. Pergilah dengan selamat dan sembuhlah dari penyakitmu!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 35, 'Ketika Yesus masih berbicara datanglah orang dari keluarga kepala rumah ibadat itu dan berkata: "Anakmu sudah mati, apa perlunya lagi engkau menyusah-nyusahkan Guru?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 36, 'Tetapi Yesus tidak menghiraukan perkataan mereka dan berkata kepada kepala rumah ibadat: "Jangan takut, percaya saja!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 37, 'Lalu Yesus tidak memperbolehkan seorangpun ikut serta, kecuali Petrus, Yakobus dan Yohanes, saudara Yakobus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 38, 'Mereka tiba di rumah kepala rumah ibadat, dan di sana dilihat-Nya orang-orang ribut, menangis dan meratap dengan suara nyaring.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 39, 'Sesudah Ia masuk Ia berkata kepada orang-orang itu: "Mengapa kamu ribut dan menangis? Anak ini tidak mati, tetapi tidur!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 40, 'Tetapi mereka menertawakan Dia. Maka diusir-Nya semua orang itu, lalu dibawa-Nya ayah dan ibu anak itu dan mereka yang bersama-sama dengan Dia masuk ke kamar anak itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 41, 'Lalu dipegang-Nya tangan anak itu, kata-Nya: "Talita kum," yang berarti: "Hai anak, Aku berkata kepadamu, bangunlah!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 42, 'Seketika itu juga anak itu bangkit berdiri dan berjalan, sebab umurnya sudah dua belas tahun. Semua orang yang hadir sangat takjub.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 5, 43, 'Dengan sangat Ia berpesan kepada mereka, supaya jangan seorangpun mengetahui hal itu, lalu Ia menyuruh mereka memberi anak itu makan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 1, 'Kemudian Yesus berangkat dari situ dan tiba di tempat asal-Nya, sedang murid-murid-Nya mengikuti Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 2, 'Pada hari Sabat Ia mulai mengajar di rumah ibadat dan jemaat yang besar takjub ketika mendengar Dia dan mereka berkata: "Dari mana diperoleh-Nya semuanya itu? Hikmat apa pulakah yang diberikan kepada-Nya? Dan mujizat-mujizat yang demikian bagaimanakah dapat diadakan oleh tangan-Nya?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 3, 'Bukankah Ia ini tukang kayu, anak Maria, saudara Yakobus, Yoses, Yudas dan Simon? Dan bukankah saudara-saudara-Nya yang perempuan ada bersama kita?" Lalu mereka kecewa dan menolak Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 4, 'Maka Yesus berkata kepada mereka: "Seorang nabi dihormati di mana-mana kecuali di tempat asalnya sendiri, di antara kaum keluarganya dan di rumahnya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 5, 'Ia tidak dapat mengadakan satu mujizatpun di sana, kecuali menyembuhkan beberapa orang sakit dengan meletakkan tangan-Nya atas mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 6, 'Ia merasa heran atas ketidakpercayaan mereka. (6-6b) Lalu Yesus berjalan keliling dari desa ke desa sambil mengajar.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 7, 'Ia memanggil kedua belas murid itu dan mengutus mereka berdua-dua. Ia memberi mereka kuasa atas roh-roh jahat,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 8, 'dan berpesan kepada mereka supaya jangan membawa apa-apa dalam perjalanan mereka, kecuali tongkat, rotipun jangan, bekalpun jangan, uang dalam ikat pinggangpun jangan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 9, 'boleh memakai alas kaki, tetapi jangan memakai dua baju.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 10, 'Kata-Nya selanjutnya kepada mereka: "Kalau di suatu tempat kamu sudah diterima dalam suatu rumah, tinggallah di situ sampai kamu berangkat dari tempat itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 11, 'Dan kalau ada suatu tempat yang tidak mau menerima kamu dan kalau mereka tidak mau mendengarkan kamu, keluarlah dari situ dan kebaskanlah debu yang di kakimu sebagai peringatan bagi mereka."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 12, 'Lalu pergilah mereka memberitakan bahwa orang harus bertobat,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 13, 'dan mereka mengusir banyak setan, dan mengoles banyak orang sakit dengan minyak dan menyembuhkan mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 14, 'Raja Herodes juga mendengar tentang Yesus, sebab nama-Nya sudah terkenal dan orang mengatakan: "Yohanes Pembaptis sudah bangkit dari antara orang mati dan itulah sebabnya kuasa-kuasa itu bekerja di dalam Dia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 15, 'Yang lain mengatakan: "Dia itu Elia!" Yang lain lagi mengatakan: "Dia itu seorang nabi sama seperti nabi-nabi yang dahulu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 16, 'Waktu Herodes mendengar hal itu, ia berkata: "Bukan, dia itu Yohanes yang sudah kupenggal kepalanya, dan yang bangkit lagi."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 17, 'Sebab memang Herodeslah yang menyuruh orang menangkap Yohanes dan membelenggunya di penjara berhubung dengan peristiwa Herodias, isteri Filipus saudaranya, karena Herodes telah mengambilnya sebagai isteri.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 18, 'Karena Yohanes pernah menegor Herodes: "Tidak halal engkau mengambil isteri saudaramu!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 19, 'Karena itu Herodias menaruh dendam pada Yohanes dan bermaksud untuk membunuh dia, tetapi tidak dapat,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 20, 'sebab Herodes segan akan Yohanes karena ia tahu, bahwa Yohanes adalah orang yang benar dan suci, jadi ia melindunginya. Tetapi apabila ia mendengarkan Yohanes, hatinya selalu terombang-ambing, namun ia merasa senang juga mendengarkan dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 21, 'Akhirnya tiba juga kesempatan yang baik bagi Herodias, ketika Herodes pada hari ulang tahunnya mengadakan perjamuan untuk pembesar-pembesarny perwira-perwiranya dan orang-orang terkemuka di Galilea.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 22, 'Pada waktu itu anak perempuan Herodias tampil lalu menari, dan ia menyukakan hati Herodes dan tamu-tamunya. Raja berkata kepada gadis itu: "Minta dari padaku apa saja yang kauingini, maka akan kuberikan kepadamu!",', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 23, 'lalu bersumpah kepadanya: "Apa saja yang kauminta akan kuberikan kepadamu, sekalipun setengah dari kerajaanku!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 24, 'Anak itu pergi dan menanyakan ibunya: "Apa yang harus kuminta?" Jawabnya: "Kepala Yohanes Pembaptis!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 25, 'Maka cepat-cepat ia pergi kepada raja dan meminta: "Aku mau, supaya sekarang juga engkau berikan kepadaku kepala Yohanes Pembaptis di sebuah talam!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 26, 'Lalu sangat sedihlah hati raja, tetapi karena sumpahnya dan karena tamu-tamunya ia tidak mau menolaknya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 27, 'Raja segera menyuruh seorang pengawal dengan perintah supaya mengambil kepala Yohanes. Orang itu pergi dan memenggal kepala Yohanes di penjara.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 28, 'Ia membawa kepala itu di sebuah talam dan memberikannya kepada gadis itu dan gadis itu memberikannya pula kepada ibunya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 29, 'Ketika murid-murid Yohanes mendengar hal itu mereka datang dan mengambil mayatnya, lalu membaringkannya dalam kuburan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 30, 'Kemudian rasul-rasul itu kembali berkumpul dengan Yesus dan memberitahukan kepada-Nya semua yang mereka kerjakan dan ajarkan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 31, 'Lalu Ia berkata kepada mereka: "Marilah ke tempat yang sunyi, supaya kita sendirian, dan beristirahatlah seketika!" Sebab memang begitu banyaknya orang yang datang dan yang pergi, sehingga makanpun mereka tidak sempat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 32, 'Maka berangkatlah mereka untuk mengasingkan diri dengan perahu ke tempat yang sunyi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 33, 'Tetapi pada waktu mereka bertolak banyak orang melihat mereka dan mengetahui tujuan mereka. Dengan mengambil jalan darat segeralah datang orang dari semua kota ke tempat itu sehingga mendahului mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 34, 'Ketika Yesus mendarat, Ia melihat sejumlah besar orang banyak, maka tergeraklah hati-Nya oleh belas kasihan kepada mereka, karena mereka seperti domba yang tidak mempunyai gembala. Lalu mulailah Ia mengajarkan banyak hal kepada mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 35, 'Pada waktu hari sudah mulai malam, datanglah murid-murid-Nya kepada-Nya dan berkata: "Tempat ini sunyi dan hari sudah mulai malam.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 36, 'Suruhlah mereka pergi, supaya mereka dapat membeli makanan di desa-desa dan di kampung-kampung di sekitar ini."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 37, 'Tetapi jawab-Nya: "Kamu harus memberi mereka makan!" Kata mereka kepada-Nya: "Jadi haruskah kami membeli roti seharga dua ratus dinar untuk memberi mereka makan?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 38, 'Tetapi Ia berkata kepada mereka: "Berapa banyak roti yang ada padamu? Cobalah periksa!" Sesudah memeriksanya mereka berkata: "Lima roti dan dua ikan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 39, 'Lalu Ia menyuruh orang-orang itu, supaya semua duduk berkelompok-kelompok di atas rumput hijau.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 40, 'Maka duduklah mereka berkelompok-kelompok, ada yang seratus, ada yang lima puluh orang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 41, 'Dan setelah Ia mengambil lima roti dan dua ikan itu, Ia menengadah ke langit dan mengucap berkat, lalu memecah-mecahkan roti itu dan memberikannya kepada murid-murid-Nya, supaya dibagi-bagikan kepada orang-orang itu; begitu juga kedua ikan itu dibagi-bagikan-Nya kepada semua mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 42, 'Dan mereka semuanya makan sampai kenyang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 43, 'Kemudian orang mengumpulkan potongan-potongan roti dua belas bakul penuh, selain dari pada sisa-sisa ikan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 44, 'Yang ikut makan roti itu ada lima ribu orang laki-laki.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 45, 'Sesudah itu Yesus segera memerintahkan murid-murid-Nya naik ke perahu dan berangkat lebih dulu ke seberang, ke Betsaida, sementara itu Ia menyuruh orang banyak pulang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 46, 'Setelah Ia berpisah dari mereka, Ia pergi ke bukit untuk berdoa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 47, 'Ketika hari sudah malam perahu itu sudah di tengah danau, sedang Yesus tinggal sendirian di darat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 48, 'Ketika Ia melihat betapa payahnya mereka mendayung karena angin sakal, maka kira-kira jam tiga malam Ia datang kepada mereka berjalan di atas air dan Ia hendak melewati mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 49, 'Ketika mereka melihat Dia berjalan di atas air, mereka mengira bahwa Ia adalah hantu, lalu mereka berteriak-teriak,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 50, 'sebab mereka semua melihat Dia dan merekapun sangat terkejut. Tetapi segera Ia berkata kepada mereka: "Tenanglah! Aku ini, jangan takut!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 51, 'Lalu Ia naik ke perahu mendapatkan mereka, dan anginpun redalah. Mereka sangat tercengang dan bingung,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 52, 'sebab sesudah peristiwa roti itu mereka belum juga mengerti, dan hati mereka tetap degil.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 53, 'Setibanya di seberang Yesus dan murid-murid-Nya mendarat di Genesaret dan berlabuh di situ.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 54, 'Ketika mereka keluar dari perahu, orang segera mengenal Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 55, 'Maka berlari-larilah mereka ke seluruh daerah itu dan mulai mengusung orang-orang sakit di atas tilamnya kepada Yesus, di mana saja kabarnya Ia berada.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 6, 56, 'Ke manapun Ia pergi, ke desa-desa, ke kota-kota, atau ke kampung-kampung, orang meletakkan orang-orang sakit di pasar dan memohon kepada-Nya, supaya mereka diperkenankan hanya menjamah jumbai jubah-Nya saja. Dan semua orang yang menjamah-Nya menjadi sembuh.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 1, 'Pada suatu kali serombongan orang Farisi dan beberapa ahli Taurat dari Yerusalem datang menemui Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 2, 'Mereka melihat, bahwa beberapa orang murid-Nya makan dengan tangan najis, yaitu dengan tangan yang tidak dibasuh.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 3, 'Sebab orang-orang Farisi seperti orang-orang Yahudi lainnya tidak makan kalau tidak melakukan pembasuhan tangan lebih dulu, karena mereka berpegang pada adat istiadat nenek moyang mereka;', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 4, 'dan kalau pulang dari pasar mereka juga tidak makan kalau tidak lebih dahulu membersihkan dirinya. Banyak warisan lain lagi yang mereka pegang, umpamanya hal mencuci cawan, kendi dan perkakas-perkakas tembaga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 5, 'Karena itu orang-orang Farisi dan ahli-ahli Taurat itu bertanya kepada-Nya: "Mengapa murid-murid-Mu tidak hidup menurut adat istiadat nenek moyang kita, tetapi makan dengan tangan najis?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 6, 'Jawab-Nya kepada mereka: "Benarlah nubuat Yesaya tentang kamu, hai orang-orang munafik! Sebab ada tertulis: Bangsa ini memuliakan Aku dengan bibirnya, padahal hatinya jauh dari pada-Ku.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 7, 'Percuma mereka beribadah kepada-Ku, sedangkan ajaran yang mereka ajarkan ialah perintah manusia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 8, 'Perintah Allah kamu abaikan untuk berpegang pada adat istiadat manusia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 9, 'Yesus berkata pula kepada mereka: "Sungguh pandai kamu mengesampingkan perintah Allah, supaya kamu dapat memelihara adat istiadatmu sendiri.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 10, 'Karena Musa telah berkata: Hormatilah ayahmu dan ibumu! dan: Siapa yang mengutuki ayahnya atau ibunya harus mati.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 11, 'Tetapi kamu berkata: Kalau seorang berkata kepada bapanya atau ibunya: Apa yang ada padaku, yang dapat digunakan untuk pemeliharaanmu, sudah digunakan untuk korban?yaitu persembahan kepada Allah?,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 12, 'maka kamu tidak membiarkannya lagi berbuat sesuatupun untuk bapanya atau ibunya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 13, 'Dengan demikian firman Allah kamu nyatakan tidak berlaku demi adat istiadat yang kamu ikuti itu. Dan banyak hal lain seperti itu yang kamu lakukan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 14, 'Lalu Yesus memanggil lagi orang banyak dan berkata kepada mereka: "Kamu semua, dengarlah kepada-Ku dan camkanlah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 15, 'Apapun dari luar, yang masuk ke dalam seseorang, tidak dapat menajiskannya, tetapi apa yang keluar dari seseorang, itulah yang menajiskannya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 16, '(Barangsiapa bertelinga untuk mendengar hendaklah ia mendengar!)', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 17, 'Sesudah Ia masuk ke sebuah rumah untuk menyingkir dari orang banyak, murid-murid-Nya bertanya kepada-Nya tentang arti perumpamaan itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 18, 'Maka jawab-Nya: "Apakah kamu juga tidak dapat memahaminya? Tidak tahukah kamu bahwa segala sesuatu dari luar yang masuk ke dalam seseorang tidak dapat menajiskannya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 19, 'karena bukan masuk ke dalam hati tetapi ke dalam perutnya, lalu dibuang di jamban?" Dengan demikian Ia menyatakan semua makanan halal.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 20, 'Kata-Nya lagi: "Apa yang keluar dari seseorang, itulah yang menajiskannya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 21, 'sebab dari dalam, dari hati orang, timbul segala pikiran jahat, percabulan, pencurian, pembunuhan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 22, 'perzinahan, keserakahan, kejahatan, kelicikan, hawa nafsu, iri hati, hujat, kesombongan, kebebalan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 23, 'Semua hal-hal jahat ini timbul dari dalam dan menajiskan orang."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 24, 'Lalu Yesus berangkat dari situ dan pergi ke daerah Tirus. Ia masuk ke sebuah rumah dan tidak mau bahwa ada orang yang mengetahuinya, tetapi kedatangan-Nya tidak dapat dirahasiakan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 25, 'Malah seorang ibu, yang anaknya perempuan kerasukan roh jahat, segera mendengar tentang Dia, lalu datang dan tersungkur di depan kaki-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 26, 'Perempuan itu seorang Yunani bangsa Siro-Fenisia. Ia memohon kepada Yesus untuk mengusir setan itu dari anaknya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 27, 'Lalu Yesus berkata kepadanya: "Biarlah anak-anak kenyang dahulu, sebab tidak patut mengambil roti yang disediakan bagi anak-anak dan melemparkannya kepada anjing."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 28, 'Tetapi perempuan itu menjawab: "Benar, Tuhan. Tetapi anjing yang di bawah meja juga makan remah-remah yang dijatuhkan anak-anak."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 29, 'Maka kata Yesus kepada perempuan itu: "Karena kata-katamu itu, pergilah sekarang sebab setan itu sudah keluar dari anakmu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 30, 'Perempuan itu pulang ke rumahnya, lalu didapatinya anak itu berbaring di tempat tidur, sedang setan itu sudah keluar.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 31, 'Kemudian Yesus meninggalkan pula daerah Tirus dan dengan melalui Sidon pergi ke danau Galilea, di tengah-tengah daerah Dekapolis.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 32, 'Di situ orang membawa kepada-Nya seorang yang tuli dan yang gagap dan memohon kepada-Nya, supaya Ia meletakkan tangan-Nya atas orang itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 33, 'Dan sesudah Yesus memisahkan dia dari orang banyak, sehingga mereka sendirian, Ia memasukkan jari-Nya ke telinga orang itu, lalu Ia meludah dan meraba lidah orang itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 34, 'Kemudian sambil menengadah ke langit Yesus menarik nafas dan berkata kepadanya: "Efata!", artinya: Terbukalah!', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 35, 'Maka terbukalah telinga orang itu dan seketika itu terlepas pulalah pengikat lidahnya, lalu ia berkata-kata dengan baik.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 36, 'Yesus berpesan kepada orang-orang yang ada di situ supaya jangan menceriterakannya kepada siapapun juga. Tetapi makin dilarang-Nya mereka, makin luas mereka memberitakannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 7, 37, 'Mereka takjub dan tercengang dan berkata: "Ia menjadikan segala-galanya baik, yang tuli dijadikan-Nya mendengar, yang bisu dijadikan-Nya berkata-kata."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 1, 'Pada waktu itu ada pula orang banyak di situ yang besar jumlahnya, dan karena mereka tidak mempunyai makanan, Yesus memanggil murid-murid-Nya dan berkata:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 2, '"Hati-Ku tergerak oleh belas kasihan kepada orang banyak ini. Sudah tiga hari mereka mengikuti Aku dan mereka tidak mempunyai makanan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 3, 'Dan jika mereka Kusuruh pulang ke rumahnya dengan lapar, mereka akan rebah di jalan, sebab ada yang datang dari jauh."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 4, 'Murid-murid-Nya menjawab: "Bagaimana di tempat yang sunyi ini orang dapat memberi mereka roti sampai kenyang?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 5, 'Yesus bertanya kepada mereka: "Berapa roti ada padamu?" Jawab mereka: "Tujuh."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 6, 'Lalu Ia menyuruh orang banyak itu duduk di tanah. Sesudah itu Ia mengambil ketujuh roti itu, mengucap syukur, memecah-mecahkannya dan memberikannya kepada murid-murid-Nya untuk dibagi-bagikan, dan mereka memberikannya kepada orang banyak.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 7, 'Mereka juga mempunyai beberapa ikan, dan sesudah mengucap berkat atasnya, Ia menyuruh supaya ikan itu juga dibagi-bagikan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 8, 'Dan mereka makan sampai kenyang. Kemudian orang mengumpulkan potongan-potongan roti yang sisa, sebanyak tujuh bakul.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 9, 'Mereka itu ada kira-kira empat ribu orang. Lalu Yesus menyuruh mereka pulang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 10, 'Ia segera naik ke perahu dengan murid-murid-Nya dan bertolak ke daerah Dalmanuta.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 11, 'Lalu muncullah orang-orang Farisi dan bersoal jawab dengan Yesus. Untuk mencobai Dia mereka meminta dari pada-Nya suatu tanda dari sorga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 12, 'Maka mengeluhlah Ia dalam hati-Nya dan berkata: "Mengapa angkatan ini meminta tanda? Aku berkata kepadamu, sesungguhnya kepada angkatan ini sekali-kali tidak akan diberi tanda."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 13, 'Ia meninggalkan mereka; Ia naik pula ke perahu dan bertolak ke seberang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 14, 'Kemudian ternyata murid-murid Yesus lupa membawa roti, hanya sebuah saja yang ada pada mereka dalam perahu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 15, 'Lalu Yesus memperingatkan mereka, kata-Nya: "Berjaga-jagalah dan awaslah terhadap ragi orang Farisi dan ragi Herodes."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 16, 'Maka mereka berpikir-pikir dan seorang berkata kepada yang lain: "Itu dikatakan-Nya karena kita tidak mempunyai roti."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 17, 'Dan ketika Yesus mengetahui apa yang mereka perbincangkan, Ia berkata: "Mengapa kamu memperbincangkan soal tidak ada roti? Belum jugakah kamu faham dan mengerti? Telah degilkah hatimu?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 18, 'Kamu mempunyai mata, tidakkah kamu melihat dan kamu mempunyai telinga, tidakkah kamu mendengar? Tidakkah kamu ingat lagi,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 19, 'pada waktu Aku memecah-mecahkan lima roti untuk lima ribu orang itu, berapa bakul penuh potongan-potongan roti kamu kumpulkan?" Jawab mereka: "Dua belas bakul."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 20, '"Dan pada waktu tujuh roti untuk empat ribu orang itu, berapa bakul penuh potongan-potongan roti kamu kumpulkan?" Jawab mereka: "Tujuh bakul."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 21, 'Lalu kata-Nya kepada mereka: "Masihkah kamu belum mengerti?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 22, 'Kemudian tibalah Yesus dan murid-murid-Nya di Betsaida. Di situ orang membawa kepada Yesus seorang buta dan mereka memohon kepada-Nya, supaya Ia menjamah dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 23, 'Yesus memegang tangan orang buta itu dan membawa dia ke luar kampung. Lalu Ia meludahi mata orang itu dan meletakkan tangan-Nya atasnya, dan bertanya: "Sudahkah kaulihat sesuatu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 24, 'Orang itu memandang ke depan, lalu berkata: "Aku melihat orang, sebab melihat mereka berjalan-jalan, tetapi tampaknya seperti pohon-pohon."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 25, 'Yesus meletakkan lagi tangan-Nya pada mata orang itu, maka orang itu sungguh-sungguh melihat dan telah sembuh, sehingga ia dapat melihat segala sesuatu dengan jelas.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 26, 'Sesudah itu Yesus menyuruh dia pulang ke rumahnya dan berkata: "Jangan masuk ke kampung!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 27, 'Kemudian Yesus beserta murid-murid-Nya berangkat ke kampung-kampung di sekitar Kaisarea Filipi. Di tengah jalan Ia bertanya kepada murid-murid-Nya, kata-Nya: "Kata orang, siapakah Aku ini?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 28, 'Jawab mereka: "Ada yang mengatakan: Yohanes Pembaptis, ada juga yang mengatakan: Elia, ada pula yang mengatakan: seorang dari para nabi."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 29, 'Ia bertanya kepada mereka: "Tetapi apa katamu, siapakah Aku ini?" Maka jawab Petrus: "Engkau adalah Mesias!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 30, 'Lalu Yesus melarang mereka dengan keras supaya jangan memberitahukan kepada siapapun tentang Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 31, 'Kemudian mulailah Yesus mengajarkan kepada mereka, bahwa Anak Manusia harus menanggung banyak penderitaan dan ditolak oleh tua-tua, imam-imam kepala dan ahli-ahli Taurat, lalu dibunuh dan bangkit sesudah tiga hari.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 32, 'Hal ini dikatakan-Nya dengan terus terang. Tetapi Petrus menarik Yesus ke samping dan menegor Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 33, 'Maka berpalinglah Yesus dan sambil memandang murid-murid-Nya Ia memarahi Petrus, kata-Nya: "Enyahlah Iblis, sebab engkau bukan memikirkan apa yang dipikirkan Allah, melainkan apa yang dipikirkan manusia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 34, 'Lalu Yesus memanggil orang banyak dan murid-murid-Nya dan berkata kepada mereka: "Setiap orang yang mau mengikut Aku, ia harus menyangkal dirinya, memikul salibnya dan mengikut Aku.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 35, 'Karena siapa yang mau menyelamatkan nyawanya, ia akan kehilangan nyawanya; tetapi barangsiapa kehilangan nyawanya karena Aku dan karena Injil, ia akan menyelamatkannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 36, 'Apa gunanya seorang memperoleh seluruh dunia, tetapi ia kehilangan nyawanya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 37, 'Karena apakah yang dapat diberikannya sebagai ganti nyawanya?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 8, 38, 'Sebab barangsiapa malu karena Aku dan karena perkataan-Ku di tengah-tengah angkatan yang tidak setia dan berdosa ini, Anak Manusiapun akan malu karena orang itu apabila Ia datang kelak dalam kemuliaan Bapa-Nya, diiringi malaikat-malaikat kudus."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 1, 'Kata-Nya lagi kepada mereka: "Aku berkata kepadamu, sesungguhnya di antara orang yang hadir di sini ada yang tidak akan mati sebelum mereka melihat bahwa Kerajaan Allah telah datang dengan kuasa."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 2, 'Enam hari kemudian Yesus membawa Petrus, Yakobus dan Yohanes dan bersama-sama dengan mereka Ia naik ke sebuah gunung yang tinggi. Di situ mereka sendirian saja. Lalu Yesus berubah rupa di depan mata mereka,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 3, 'dan pakaian-Nya sangat putih berkilat-kilat. Tidak ada seorangpun di dunia ini yang dapat mengelantang pakaian seperti itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 4, 'Maka nampaklah kepada mereka Elia bersama dengan Musa, keduanya sedang berbicara dengan Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 5, 'Kata Petrus kepada Yesus: "Rabi, betapa bahagianya kami berada di tempat ini. Baiklah kami dirikan tiga kemah, satu untuk Engkau, satu untuk Musa dan satu untuk Elia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 6, 'Ia berkata demikian, sebab tidak tahu apa yang harus dikatakannya, karena mereka sangat ketakutan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 7, 'Maka datanglah awan menaungi mereka dan dari dalam awan itu terdengar suara: "Inilah Anak yang Kukasihi, dengarkanlah Dia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 8, 'Dan sekonyong-konyong waktu mereka memandang sekeliling mereka, mereka tidak melihat seorangpun lagi bersama mereka, kecuali Yesus seorang diri.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 9, 'Pada waktu mereka turun dari gunung itu, Yesus berpesan kepada mereka, supaya mereka jangan menceriterakan kepada seorangpun apa yang telah mereka lihat itu, sebelum Anak Manusia bangkit dari antara orang mati.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 10, 'Mereka memegang pesan tadi sambil mempersoalkan di antara mereka apa yang dimaksud dengan "bangkit dari antara orang mati."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 11, 'Lalu mereka bertanya kepada-Nya: "Mengapa ahli-ahli Taurat berkata, bahwa Elia harus datang dahulu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 12, 'Jawab Yesus: "Memang Elia akan datang dahulu dan memulihkan segala sesuatu. Hanya, bagaimanakah dengan yang ada tertulis mengenai Anak Manusia, bahwa Ia akan banyak menderita dan akan dihinakan?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 13, 'Tetapi Aku berkata kepadamu: Memang Elia sudah datang dan orang memperlakukan dia menurut kehendak mereka, sesuai dengan yang ada tertulis tentang dia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 14, 'Ketika Yesus, Petrus, Yakobus dan Yohanes kembali pada murid-murid lain, mereka melihat orang banyak mengerumuni murid-murid itu, dan beberapa ahli Taurat sedang mempersoalkan sesuatu dengan mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 15, 'Pada waktu orang banyak itu melihat Yesus, tercenganglah mereka semua dan bergegas menyambut Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 16, 'Lalu Yesus bertanya kepada mereka: "Apa yang kamu persoalkan dengan mereka?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 17, 'Kata seorang dari orang banyak itu: "Guru, anakku ini kubawa kepada-Mu, karena ia kerasukan roh yang membisukan dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 18, 'Dan setiap kali roh itu menyerang dia, roh itu membantingkannya ke tanah; lalu mulutnya berbusa, giginya bekertakan dan tubuhnya menjadi kejang. Aku sudah meminta kepada murid-murid-Mu, supaya mereka mengusir roh itu, tetapi mereka tidak dapat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 19, 'Maka kata Yesus kepada mereka: "Hai kamu angkatan yang tidak percaya, berapa lama lagi Aku harus tinggal di antara kamu? Berapa lama lagi Aku harus sabar terhadap kamu? Bawalah anak itu ke mari!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 20, 'Lalu mereka membawanya kepada-Nya. Waktu roh itu melihat Yesus, anak itu segera digoncang-goncangnya, dan anak itu terpelanting ke tanah dan terguling-guling, sedang mulutnya berbusa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 21, 'Lalu Yesus bertanya kepada ayah anak itu: "Sudah berapa lama ia mengalami ini?" Jawabnya: "Sejak masa kecilnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 22, 'Dan seringkali roh itu menyeretnya ke dalam api ataupun ke dalam air untuk membinasakannya. Sebab itu jika Engkau dapat berbuat sesuatu, tolonglah kami dan kasihanilah kami."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 23, 'Jawab Yesus: "Katamu: jika Engkau dapat? Tidak ada yang mustahil bagi orang yang percaya!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 24, 'Segera ayah anak itu berteriak: "Aku percaya. Tolonglah aku yang tidak percaya ini!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 25, 'Ketika Yesus melihat orang banyak makin datang berkerumun, Ia menegor roh jahat itu dengan keras, kata-Nya: "Hai kau roh yang menyebabkan orang menjadi bisu dan tuli, Aku memerintahkan engkau, keluarlah dari pada anak ini dan jangan memasukinya lagi!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 26, 'Lalu keluarlah roh itu sambil berteriak dan menggoncang-goncang anak itu dengan hebatnya. Anak itu kelihatannya seperti orang mati, sehingga banyak orang yang berkata: "Ia sudah mati."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 27, 'Tetapi Yesus memegang tangan anak itu dan membangunkannya, lalu ia bangkit sendiri.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 28, 'Ketika Yesus sudah di rumah, dan murid-murid-Nya sendirian dengan Dia, bertanyalah mereka: "Mengapa kami tidak dapat mengusir roh itu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 29, 'Jawab-Nya kepada mereka: "Jenis ini tidak dapat diusir kecuali dengan berdoa."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 30, 'Yesus dan murid-murid-Nya berangkat dari situ dan melewati Galilea, dan Yesus tidak mau hal itu diketahui orang;', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 31, 'sebab Ia sedang mengajar murid-murid-Nya. Ia berkata kepada mereka: "Anak Manusia akan diserahkan ke dalam tangan manusia, dan mereka akan membunuh Dia, dan tiga hari sesudah Ia dibunuh Ia akan bangkit."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 32, 'Mereka tidak mengerti perkataan itu, namun segan menanyakannya kepada-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 33, 'Kemudian tibalah Yesus dan murid-murid-Nya di Kapernaum. Ketika Yesus sudah di rumah, Ia bertanya kepada murid-murid-Nya: "Apa yang kamu perbincangkan tadi di tengah jalan?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 34, 'Tetapi mereka diam, sebab di tengah jalan tadi mereka mempertengkarkan siapa yang terbesar di antara mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 35, 'Lalu Yesus duduk dan memanggil kedua belas murid itu. Kata-Nya kepada mereka: "Jika seseorang ingin menjadi yang terdahulu, hendaklah ia menjadi yang terakhir dari semuanya dan pelayan dari semuanya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 36, 'Maka Yesus mengambil seorang anak kecil dan menempatkannya di tengah-tengah mereka, kemudian Ia memeluk anak itu dan berkata kepada mereka:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 37, '"Barangsiapa menyambut seorang anak seperti ini dalam nama-Ku, ia menyambut Aku. Dan barangsiapa menyambut Aku, bukan Aku yang disambutnya, tetapi Dia yang mengutus Aku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 38, 'Kata Yohanes kepada Yesus: "Guru, kami lihat seorang yang bukan pengikut kita mengusir setan demi nama-Mu, lalu kami cegah orang itu, karena ia bukan pengikut kita."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 39, 'Tetapi kata Yesus: "Jangan kamu cegah dia! Sebab tidak seorangpun yang telah mengadakan mujizat demi nama-Ku, dapat seketika itu juga mengumpat Aku.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 40, 'Barangsiapa tidak melawan kita, ia ada di pihak kita.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 41, 'Aku berkata kepadamu: Sesungguhnya barangsiapa memberi kamu minum secangkir air oleh karena kamu adalah pengikut Kristus, ia tidak akan kehilangan upahnya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 42, '"Barangsiapa menyesatkan salah satu dari anak-anak kecil yang percaya ini, lebih baik baginya jika sebuah batu kilangan diikatkan pada lehernya lalu ia dibuang ke dalam laut.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 43, 'Dan jika tanganmu menyesatkan engkau, penggallah, karena lebih baik engkau masuk ke dalam hidup dengan tangan kudung dari pada dengan utuh kedua tanganmu dibuang ke dalam neraka, ke dalam api yang tak terpadamkan;', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 44, '(di tempat itu ulatnya tidak akan mati, dan apinya tidak akan padam.)', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 45, 'Dan jika kakimu menyesatkan engkau, penggallah, karena lebih baik engkau masuk ke dalam hidup dengan timpang, dari pada dengan utuh kedua kakimu dicampakkan ke dalam neraka;', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 46, '(di tempat itu ulatnya tidak akan mati, dan apinya tidak akan padam.)', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 47, 'Dan jika matamu menyesatkan engkau, cungkillah, karena lebih baik engkau masuk ke dalam Kerajaan Allah dengan bermata satu dari pada dengan bermata dua dicampakkan ke dalam neraka,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 48, 'di mana ulat-ulat bangkai tidak mati dan api tidak padam.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 49, 'Karena setiap orang akan digarami dengan api.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 9, 50, 'Garam memang baik, tetapi jika garam menjadi hambar, dengan apakah kamu mengasinkannya? Hendaklah kamu selalu mempunyai garam dalam dirimu dan selalu hidup berdamai yang seorang dengan yang lain."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 1, 'Dari situ Yesus berangkat ke daerah Yudea dan ke daerah seberang sungai Yordan dan di situpun orang banyak datang mengerumuni Dia; dan seperti biasa Ia mengajar mereka pula.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 2, 'Maka datanglah orang-orang Farisi, dan untuk mencobai Yesus mereka bertanya kepada-Nya: "Apakah seorang suami diperbolehkan menceraikan isterinya?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 3, 'Tetapi jawab-Nya kepada mereka: "Apa perintah Musa kepada kamu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 4, 'Jawab mereka: "Musa memberi izin untuk menceraikannya dengan membuat surat cerai."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 5, 'Lalu kata Yesus kepada mereka: "Justru karena ketegaran hatimulah maka Musa menuliskan perintah ini untuk kamu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 6, 'Sebab pada awal dunia, Allah menjadikan mereka laki-laki dan perempuan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 7, 'sebab itu laki-laki akan meninggalkan ayahnya dan ibunya dan bersatu dengan isterinya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 8, 'sehingga keduanya itu menjadi satu daging. Demikianlah mereka bukan lagi dua, melainkan satu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 9, 'Karena itu, apa yang telah dipersatukan Allah, tidak boleh diceraikan manusia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 10, 'Ketika mereka sudah di rumah, murid-murid itu bertanya pula kepada Yesus tentang hal itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 11, 'Lalu kata-Nya kepada mereka: "Barangsiapa menceraikan isterinya lalu kawin dengan perempuan lain, ia hidup dalam perzinahan terhadap isterinya itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 12, 'Dan jika si isteri menceraikan suaminya dan kawin dengan laki-laki lain, ia berbuat zinah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 13, 'Lalu orang membawa anak-anak kecil kepada Yesus, supaya Ia menjamah mereka; akan tetapi murid-murid-Nya memarahi orang-orang itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 14, 'Ketika Yesus melihat hal itu, Ia marah dan berkata kepada mereka: "Biarkan anak-anak itu datang kepada-Ku, jangan menghalang-halangi mereka, sebab orang-orang yang seperti itulah yang empunya Kerajaan Allah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 15, 'Aku berkata kepadamu: Sesungguhnya barangsiapa tidak menyambut Kerajaan Allah seperti seorang anak kecil, ia tidak akan masuk ke dalamnya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 16, 'Lalu Ia memeluk anak-anak itu dan sambil meletakkan tangan-Nya atas mereka Ia memberkati mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 17, 'Pada waktu Yesus berangkat untuk meneruskan perjalanan-Nya, datanglah seorang berlari-lari mendapatkan Dia dan sambil bertelut di hadapan-Nya ia bertanya: "Guru yang baik, apa yang harus kuperbuat untuk memperoleh hidup yang kekal?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 18, 'Jawab Yesus: "Mengapa kaukatakan Aku baik? Tak seorangpun yang baik selain dari pada Allah saja.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 19, 'Engkau tentu mengetahui segala perintah Allah: Jangan membunuh, jangan berzinah, jangan mencuri, jangan mengucapkan saksi dusta, jangan mengurangi hak orang, hormatilah ayahmu dan ibumu!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 20, 'Lalu kata orang itu kepada-Nya: "Guru, semuanya itu telah kuturuti sejak masa mudaku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 21, 'Tetapi Yesus memandang dia dan menaruh kasih kepadanya, lalu berkata kepadanya: "Hanya satu lagi kekuranganmu: pergilah, juallah apa yang kaumiliki dan berikanlah itu kepada orang-orang miskin, maka engkau akan beroleh harta di sorga, kemudian datanglah ke mari dan ikutlah Aku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 22, 'Mendengar perkataan itu ia menjadi kecewa, lalu pergi dengan sedih, sebab banyak hartanya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 23, 'Lalu Yesus memandang murid-murid-Nya di sekeliling-Nya dan berkata kepada mereka: "Alangkah sukarnya orang yang beruang masuk ke dalam Kerajaan Allah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 24, 'Murid-murid-Nya tercengang mendengar perkataan-Nya itu. Tetapi Yesus menyambung lagi: "Anak-anak-Ku, alangkah sukarnya masuk ke dalam Kerajaan Allah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 25, 'Lebih mudah seekor unta melewati lobang jarum dari pada seorang kaya masuk ke dalam Kerajaan Allah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 26, 'Mereka makin gempar dan berkata seorang kepada yang lain: "Jika demikian, siapakah yang dapat diselamatkan?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 27, 'Yesus memandang mereka dan berkata: "Bagi manusia hal itu tidak mungkin, tetapi bukan demikian bagi Allah. Sebab segala sesuatu adalah mungkin bagi Allah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 28, 'Berkatalah Petrus kepada Yesus: "Kami ini telah meninggalkan segala sesuatu dan mengikut Engkau!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 29, 'Jawab Yesus: "Aku berkata kepadamu, sesungguhnya setiap orang yang karena Aku dan karena Injil meninggalkan rumahnya, saudaranya laki-laki atau saudaranya perempuan, ibunya atau bapanya, anak-anaknya atau ladangnya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 30, 'orang itu sekarang pada masa ini juga akan menerima kembali seratus kali lipat: rumah, saudara laki-laki, saudara perempuan, ibu, anak dan ladang, sekalipun disertai berbagai penganiayaan, dan pada zaman yang akan datang ia akan menerima hidup yang kekal.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 31, 'Tetapi banyak orang yang terdahulu akan menjadi yang terakhir dan yang terakhir akan menjadi yang terdahulu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 32, 'Yesus dan murid-murid-Nya sedang dalam perjalanan ke Yerusalem dan Yesus berjalan di depan. Murid-murid merasa cemas dan juga orang-orang yang mengikuti Dia dari belakang merasa takut. Sekali lagi Yesus memanggil kedua belas murid-Nya dan Ia mulai mengatakan kepada mereka apa yang akan terjadi atas diri-Nya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 33, 'kata-Nya: "Sekarang kita pergi ke Yerusalem dan Anak Manusia akan diserahkan kepada imam-imam kepala dan ahli-ahli Taurat, dan mereka akan menjatuhi Dia hukuman mati. Dan mereka akan menyerahkan Dia kepada bangsa-bangsa yang tidak mengenal Allah,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 34, 'dan Ia akan diolok-olokkan, diludahi, disesah dan dibunuh, dan sesudah tiga hari Ia akan bangkit."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 35, 'Lalu Yakobus dan Yohanes, anak-anak Zebedeus, mendekati Yesus dan berkata kepada-Nya: "Guru, kami harap supaya Engkau kiranya mengabulkan suatu permintaan kami!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 36, 'Jawab-Nya kepada mereka: "Apa yang kamu kehendaki Aku perbuat bagimu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 37, 'Lalu kata mereka: "Perkenankanlah kami duduk dalam kemuliaan-Mu kelak, yang seorang lagi di sebelah kanan-Mu dan yang seorang di sebelah kiri-Mu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 38, 'Tetapi kata Yesus kepada mereka: "Kamu tidak tahu apa yang kamu minta. Dapatkah kamu meminum cawan yang harus Kuminum dan dibaptis dengan baptisan yang harus Kuterima?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 39, 'Jawab mereka: "Kami dapat." Yesus berkata kepada mereka: "Memang, kamu akan meminum cawan yang harus Kuminum dan akan dibaptis dengan baptisan yang harus Kuterima.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 40, 'Tetapi hal duduk di sebelah kanan-Ku atau di sebelah kiri-Ku, Aku tidak berhak memberikannya. Itu akan diberikan kepada orang-orang bagi siapa itu telah disediakan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 41, 'Mendengar itu kesepuluh murid yang lain menjadi marah kepada Yakobus dan Yohanes.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 42, 'Tetapi Yesus memanggil mereka lalu berkata: "Kamu tahu, bahwa mereka yang disebut pemerintah bangsa-bangsa memerintah rakyatnya dengan tangan besi, dan pembesar-pembesarnya menjalankan kuasanya dengan keras atas mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 43, 'Tidaklah demikian di antara kamu. Barangsiapa ingin menjadi besar di antara kamu, hendaklah ia menjadi pelayanmu,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 44, 'dan barangsiapa ingin menjadi yang terkemuka di antara kamu, hendaklah ia menjadi hamba untuk semuanya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 45, 'Karena Anak Manusia juga datang bukan untuk dilayani, melainkan untuk melayani dan untuk memberikan nyawa-Nya menjadi tebusan bagi banyak orang."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 46, 'Lalu tibalah Yesus dan murid-murid-Nya di Yerikho. Dan ketika Yesus keluar dari Yerikho, bersama-sama dengan murid-murid-Nya dan orang banyak yang berbondong-bondong, ada seorang pengemis yang buta, bernama Bartimeus, anak Timeus, duduk di pinggir jalan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 47, 'Ketika didengarnya, bahwa itu adalah Yesus orang Nazaret, mulailah ia berseru: "Yesus, Anak Daud, kasihanilah aku!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 48, 'Banyak orang menegornya supaya ia diam. Namun semakin keras ia berseru: "Anak Daud, kasihanilah aku!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 49, 'Lalu Yesus berhenti dan berkata: "Panggillah dia!" Mereka memanggil orang buta itu dan berkata kepadanya: "Kuatkan hatimu, berdirilah, Ia memanggil engkau."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 50, 'Lalu ia menanggalkan jubahnya, ia segera berdiri dan pergi mendapatkan Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 51, 'Tanya Yesus kepadanya: "Apa yang kaukehendaki supaya Aku perbuat bagimu?" Jawab orang buta itu: "Rabuni, supaya aku dapat melihat!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 10, 52, 'Lalu kata Yesus kepadanya: "Pergilah, imanmu telah menyelamatkan engkau!" Pada saat itu juga melihatlah ia, lalu ia mengikuti Yesus dalam perjalanan-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 1, 'Ketika Yesus dan murid-murid-Nya telah dekat Yerusalem, dekat Betfage dan Betania yang terletak di Bukit Zaitun, Yesus menyuruh dua orang murid-Nya', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 2, 'dengan pesan: "Pergilah ke kampung yang di depanmu itu. Pada waktu kamu masuk di situ, kamu akan segera menemukan seekor keledai muda tertambat, yang belum pernah ditunggangi orang. Lepaskan keledai itu dan bawalah ke mari.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 3, 'Dan jika ada orang mengatakan kepadamu: Mengapa kamu lakukan itu, jawablah: Tuhan memerlukannya. Ia akan segera mengembalikannya ke sini."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 4, 'Merekapun pergi, dan menemukan seekor keledai muda tertambat di depan pintu di luar, di pinggir jalan, lalu melepaskannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 5, 'Dan beberapa orang yang ada di situ berkata kepada mereka: "Apa maksudnya kamu melepaskan keledai itu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 6, 'Lalu mereka menjawab seperti yang sudah dikatakan Yesus. Maka orang-orang itu membiarkan mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 7, 'Lalu mereka membawa keledai itu kepada Yesus, dan mengalasinya dengan pakaian mereka, kemudian Yesus naik ke atasnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 8, 'Banyak orang yang menghamparkan pakaiannya di jalan, ada pula yang menyebarkan ranting-ranting hijau yang mereka ambil dari ladang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 9, 'Orang-orang yang berjalan di depan dan mereka yang mengikuti dari belakang berseru: "Hosana! Diberkatilah Dia yang datang dalam nama Tuhan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 10, 'diberkatilah Kerajaan yang datang, Kerajaan bapak kita Daud, hosana di tempat yang maha tinggi!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 11, 'Sesampainya di Yerusalem Ia masuk ke Bait Allah. Di sana Ia meninjau semuanya, tetapi sebab hari sudah hampir malam Ia keluar ke Betania bersama dengan kedua belas murid-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 12, 'Keesokan harinya sesudah Yesus dan kedua belas murid-Nya meninggalkan Betania, Yesus merasa lapar.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 13, 'Dan dari jauh Ia melihat pohon ara yang sudah berdaun. Ia mendekatinya untuk melihat kalau-kalau Ia mendapat apa-apa pada pohon itu. Tetapi waktu Ia tiba di situ, Ia tidak mendapat apa-apa selain daun-daun saja, sebab memang bukan musim buah ara.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 14, 'Maka kata-Nya kepada pohon itu: "Jangan lagi seorangpun makan buahmu selama-lamanya!" Dan murid-murid-Nyapun mendengarnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 15, 'Lalu tibalah Yesus dan murid-murid-Nya di Yerusalem. Sesudah Yesus masuk ke Bait Allah, mulailah Ia mengusir orang-orang yang berjual beli di halaman Bait Allah. Meja-meja penukar uang dan bangku-bangku pedagang merpati dibalikkan-Nya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 16, 'dan Ia tidak memperbolehkan orang membawa barang-barang melintasi halaman Bait Allah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 17, 'Lalu Ia mengajar mereka, kata-Nya: "Bukankah ada tertulis: Rumah-Ku akan disebut rumah doa bagi segala bangsa? Tetapi kamu ini telah menjadikannya sarang penyamun!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 18, 'Imam-imam kepala dan ahli-ahli Taurat mendengar tentang peristiwa itu, dan mereka berusaha untuk membinasakan Dia, sebab mereka takut kepada-Nya, melihat seluruh orang banyak takjub akan pengajaran-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 19, 'Menjelang malam mereka keluar lagi dari kota.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 20, 'Pagi-pagi ketika Yesus dan murid-murid-Nya lewat, mereka melihat pohon ara tadi sudah kering sampai ke akar-akarnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 21, 'Maka teringatlah Petrus akan apa yang telah terjadi, lalu ia berkata kepada Yesus: "Rabi, lihatlah, pohon ara yang Kaukutuk itu sudah kering."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 22, 'Yesus menjawab mereka: "Percayalah kepada Allah!', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 23, 'Aku berkata kepadamu: Sesungguhnya barangsiapa berkata kepada gunung ini: Beranjaklah dan tercampaklah ke dalam laut! asal tidak bimbang hatinya, tetapi percaya, bahwa apa yang dikatakannya itu akan terjadi, maka hal itu akan terjadi baginya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 24, 'Karena itu Aku berkata kepadamu: apa saja yang kamu minta dan doakan, percayalah bahwa kamu telah menerimanya, maka hal itu akan diberikan kepadamu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 25, 'Dan jika kamu berdiri untuk berdoa, ampunilah dahulu sekiranya ada barang sesuatu dalam hatimu terhadap seseorang, supaya juga Bapamu yang di sorga mengampuni kesalahan-kesalahanmu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 26, '(Tetapi jika kamu tidak mengampuni, maka Bapamu yang di sorga juga tidak akan mengampuni kesalahan-kesalahanmu.)', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 27, 'Lalu Yesus dan murid-murid-Nya tiba pula di Yerusalem. Ketika Yesus berjalan di halaman Bait Allah, datanglah kepada-Nya imam-imam kepala, ahli-ahli Taurat dan tua-tua,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 28, 'dan bertanya kepada-Nya: "Dengan kuasa manakah Engkau melakukan hal-hal itu? Dan siapakah yang memberikan kuasa itu kepada-Mu, sehingga Engkau melakukan hal-hal itu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 29, 'Jawab Yesus kepada mereka: "Aku akan mengajukan satu pertanyaan kepadamu. Berikanlah Aku jawabnya, maka Aku akan mengatakan kepadamu dengan kuasa manakah Aku melakukan hal-hal itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 30, 'Baptisan Yohanes itu, dari sorga atau dari manusia? Berikanlah Aku jawabnya!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 31, 'Mereka memperbincangkannya di antara mereka, dan berkata: "Jikalau kita katakan: Dari sorga, Ia akan berkata: Kalau begitu, mengapakah kamu tidak percaya kepadanya?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 32, 'Tetapi, masakan kita katakan: Dari manusia!" Sebab mereka takut kepada orang banyak, karena semua orang menganggap bahwa Yohanes betul-betul seorang nabi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 11, 33, 'Lalu mereka menjawab Yesus: "Kami tidak tahu." Maka kata Yesus kepada mereka: "Jika demikian, Aku juga tidak mengatakan kepadamu dengan kuasa manakah Aku melakukan hal-hal itu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 1, 'Lalu Yesus mulai berbicara kepada mereka dalam perumpamaan: "Adalah seorang membuka kebun anggur dan menanam pagar sekelilingnya. Ia menggali lobang tempat memeras anggur dan mendirikan menara jaga. Kemudian ia menyewakan kebun itu kepada penggarap-penggarap lalu berangkat ke negeri lain.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 2, 'Dan ketika sudah tiba musimnya, ia menyuruh seorang hamba kepada penggarap-penggarap itu untuk menerima sebagian dari hasil kebun itu dari mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 3, 'Tetapi mereka menangkap hamba itu dan memukulnya, lalu menyuruhnya pergi dengan tangan hampa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 4, 'Kemudian ia menyuruh pula seorang hamba lain kepada mereka. Orang ini mereka pukul sampai luka kepalanya dan sangat mereka permalukan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 5, 'Lalu ia menyuruh seorang hamba lain lagi, dan orang ini mereka bunuh. Dan banyak lagi yang lain, ada yang mereka pukul dan ada yang mereka bunuh.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 6, 'Sekarang tinggal hanya satu orang anaknya yang kekasih. Akhirnya ia menyuruh dia kepada mereka, katanya: Anakku akan mereka segani.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 7, 'Tetapi penggarap-penggarap itu berkata seorang kepada yang lain: Ia adalah ahli waris, mari kita bunuh dia, maka warisan ini menjadi milik kita.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 8, 'Mereka menangkapnya dan membunuhnya, lalu melemparkannya ke luar kebun anggur itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 9, 'Sekarang apa yang akan dilakukan oleh tuan kebun anggur itu? Ia akan datang dan membinasakan penggarap-penggarap itu, lalu mempercayakan kebun anggur itu kepada orang-orang lain.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 10, 'Tidak pernahkah kamu membaca nas ini: Batu yang dibuang oleh tukang-tukang bangunan telah menjadi batu penjuru:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 11, 'hal itu terjadi dari pihak Tuhan, suatu perbuatan ajaib di mata kita."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 12, 'Lalu mereka berusaha untuk menangkap Yesus, karena mereka tahu, bahwa merekalah yang dimaksudkan-Nya dengan perumpamaan itu. Tetapi mereka takut kepada orang banyak, jadi mereka pergi dan membiarkan Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 13, 'Kemudian disuruh beberapa orang Farisi dan Herodian kepada Yesus untuk menjerat Dia dengan suatu pertanyaan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 14, 'Orang-orang itu datang dan berkata kepada-Nya: "Guru, kami tahu, Engkau adalah seorang yang jujur, dan Engkau tidak takut kepada siapapun juga, sebab Engkau tidak mencari muka, melainkan dengan jujur mengajar jalan Allah dengan segala kejujuran. Apakah diperbolehkan membayar pajak kepada Kaisar atau tidak? Haruskah kami bayar atau tidak?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 15, 'Tetapi Yesus mengetahui kemunafikan mereka, lalu berkata kepada mereka: "Mengapa kamu mencobai Aku? Bawalah ke mari suatu dinar supaya Kulihat!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 16, 'Lalu mereka bawa. Maka Ia bertanya kepada mereka: "Gambar dan tulisan siapakah ini?" Jawab mereka: "Gambar dan tulisan Kaisar."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 17, 'Lalu kata Yesus kepada mereka: "Berikanlah kepada Kaisar apa yang wajib kamu berikan kepada Kaisar dan kepada Allah apa yang wajib kamu berikan kepada Allah!" Mereka sangat heran mendengar Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 18, 'Datanglah kepada Yesus beberapa orang Saduki, yang berpendapat, bahwa tidak ada kebangkitan. Mereka bertanya kepada-Nya:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 19, '"Guru, Musa menuliskan perintah ini untuk kita: Jika seorang, yang mempunyai saudara laki-laki, mati dengan meninggalkan seorang isteri tetapi tidak meninggalkan anak, saudaranya harus kawin dengan isterinya itu dan membangkitkan keturunan bagi saudaranya itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 20, 'Adalah tujuh orang bersaudara. Yang pertama kawin dengan seorang perempuan dan mati dengan tidak meninggalkan keturunan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 21, 'Lalu yang kedua juga mengawini dia dan mati dengan tidak meninggalkan keturunan. Demikian juga dengan yang ketiga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 22, 'Dan begitulah seterusnya, ketujuhnya tidak meninggalkan keturunan. Dan akhirnya, sesudah mereka semua, perempuan itupun mati.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 23, 'Pada hari kebangkitan, bilamana mereka bangkit, siapakah yang menjadi suami perempuan itu? Sebab ketujuhnya telah beristerikan dia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 24, 'Jawab Yesus kepada mereka: "Kamu sesat, justru karena kamu tidak mengerti Kitab Suci maupun kuasa Allah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 25, 'Sebab apabila orang bangkit dari antara orang mati, orang tidak kawin dan tidak dikawinkan melainkan hidup seperti malaikat di sorga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 26, 'Dan juga tentang bangkitnya orang-orang mati, tidakkah kamu baca dalam kitab Musa, dalam ceritera tentang semak duri, bagaimana bunyi firman Allah kepadanya: Akulah Allah Abraham, Allah Ishak dan Allah Yakub?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 27, 'Ia bukanlah Allah orang mati, melainkan Allah orang hidup. Kamu benar-benar sesat!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 28, 'Lalu seorang ahli Taurat, yang mendengar Yesus dan orang-orang Saduki bersoal jawab dan tahu, bahwa Yesus memberi jawab yang tepat kepada orang-orang itu, datang kepada-Nya dan bertanya: "Hukum manakah yang paling utama?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 29, 'Jawab Yesus: "Hukum yang terutama ialah: Dengarlah, hai orang Israel, Tuhan Allah kita, Tuhan itu esa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 30, 'Kasihilah Tuhan, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu dan dengan segenap akal budimu dan dengan segenap kekuatanmu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 31, 'Dan hukum yang kedua ialah: Kasihilah sesamamu manusia seperti dirimu sendiri. Tidak ada hukum lain yang lebih utama dari pada kedua hukum ini."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 32, 'Lalu kata ahli Taurat itu kepada Yesus: "Tepat sekali, Guru, benar kata-Mu itu, bahwa Dia esa, dan bahwa tidak ada yang lain kecuali Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 33, 'Memang mengasihi Dia dengan segenap hati dan dengan segenap pengertian dan dengan segenap kekuatan, dan juga mengasihi sesama manusia seperti diri sendiri adalah jauh lebih utama dari pada semua korban bakaran dan korban sembelihan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 34, 'Yesus melihat, bagaimana bijaksananya jawab orang itu, dan Ia berkata kepadanya: "Engkau tidak jauh dari Kerajaan Allah!" Dan seorangpun tidak berani lagi menanyakan sesuatu kepada Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 35, 'Pada suatu kali ketika Yesus mengajar di Bait Allah, Ia berkata: "Bagaimana ahli-ahli Taurat dapat mengatakan, bahwa Mesias adalah anak Daud?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 36, 'Daud sendiri oleh pimpinan Roh Kudus berkata: Tuhan telah berfirman kepada Tuanku: duduklah di sebelah kanan-Ku, sampai musuh-musuh-Mu Kutaruh di bawah kaki-Mu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 37, 'Daud sendiri menyebut Dia Tuannya, bagaimana mungkin Ia anaknya pula?" Orang banyak yang besar jumlahnya mendengarkan Dia dengan penuh minat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 38, 'Dalam pengajaran-Nya Yesus berkata: "Hati-hatilah terhadap ahli-ahli Taurat yang suka berjalan-jalan memakai jubah panjang dan suka menerima penghormatan di pasar,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 39, 'yang suka duduk di tempat terdepan di rumah ibadat dan di tempat terhormat dalam perjamuan,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 40, 'yang menelan rumah janda-janda, sedang mereka mengelabui mata orang dengan doa yang panjang-panjang. Mereka ini pasti akan menerima hukuman yang lebih berat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 41, 'Pada suatu kali Yesus duduk menghadapi peti persembahan dan memperhatikan bagaimana orang banyak memasukkan uang ke dalam peti itu. Banyak orang kaya memberi jumlah yang besar.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 42, 'Lalu datanglah seorang janda yang miskin dan ia memasukkan dua peser, yaitu satu duit.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 43, 'Maka dipanggil-Nya murid-murid-Nya dan berkata kepada mereka: "Aku berkata kepadamu, sesungguhnya janda miskin ini memberi lebih banyak dari pada semua orang yang memasukkan uang ke dalam peti persembahan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 12, 44, 'Sebab mereka semua memberi dari kelimpahannya, tetapi janda ini memberi dari kekurangannya, semua yang ada padanya, yaitu seluruh nafkahnya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 1, 'Ketika Yesus keluar dari Bait Allah, seorang murid-Nya berkata kepada-Nya: "Guru, lihatlah betapa kokohnya batu-batu itu dan betapa megahnya gedung-gedung itu!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 2, 'Lalu Yesus berkata kepadanya: "Kaulihat gedung-gedung yang hebat ini? Tidak satu batupun akan dibiarkan terletak di atas batu yang lain, semuanya akan diruntuhkan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 3, 'Ketika Yesus duduk di atas Bukit Zaitun, berhadapan dengan Bait Allah, Petrus, Yakobus, Yohanes dan Andreas bertanya sendirian kepada-Nya:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 4, '"Katakanlah kepada kami, bilamanakah itu akan terjadi, dan apakah tandanya, kalau semuanya itu akan sampai kepada kesudahannya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 5, 'Maka mulailah Yesus berkata kepada mereka: "Waspadalah supaya jangan ada orang yang menyesatkan kamu!', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 6, 'Akan datang banyak orang dengan memakai nama-Ku dan berkata: Akulah dia, dan mereka akan menyesatkan banyak orang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 7, 'Dan apabila kamu mendengar deru perang atau kabar-kabar tentang perang, janganlah kamu gelisah. Semuanya itu harus terjadi, tetapi itu belum kesudahannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 8, 'Sebab bangsa akan bangkit melawan bangsa dan kerajaan melawan kerajaan. Akan terjadi gempa bumi di berbagai tempat, dan akan ada kelaparan. Semua itu barulah permulaan penderitaan menjelang zaman baru.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 9, 'Tetapi kamu ini, hati-hatilah! Kamu akan diserahkan kepada majelis agama dan kamu akan dipukul di rumah ibadat dan kamu akan dihadapkan ke muka penguasa-penguasa dan raja-raja karena Aku, sebagai kesaksian bagi mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 10, 'Tetapi Injil harus diberitakan dahulu kepada semua bangsa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 11, 'Dan jika kamu digiring dan diserahkan, janganlah kamu kuatir akan apa yang harus kamu katakan, tetapi katakanlah apa yang dikaruniakan kepadamu pada saat itu juga, sebab bukan kamu yang berkata-kata, melainkan Roh Kudus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 12, 'Seorang saudara akan menyerahkan saudaranya untuk dibunuh, demikian juga seorang ayah terhadap anaknya. Dan anak-anak akan memberontak terhadap orang tuanya dan akan membunuh mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 13, 'Kamu akan dibenci semua orang oleh karena nama-Ku. Tetapi orang yang bertahan sampai pada kesudahannya ia akan selamat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 14, '"Apabila kamu melihat Pembinasa keji berdiri di tempat yang tidak sepatutnya?para pembaca hendaklah memperhatikannya?maka orang-orang yang di Yudea haruslah melarikan diri ke pegunungan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 15, 'Orang yang sedang di peranginan di atas rumah janganlah ia turun dan masuk untuk mengambil sesuatu dari rumahnya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 16, 'dan orang yang sedang di ladang janganlah ia kembali untuk mengambil pakaiannya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 17, 'Celakalah ibu-ibu yang sedang hamil atau yang menyusukan bayi pada masa itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 18, 'Berdoalah, supaya semuanya itu jangan terjadi pada musim dingin.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 19, 'Sebab pada masa itu akan terjadi siksaan seperti yang belum pernah terjadi sejak awal dunia, yang diciptakan Allah, sampai sekarang dan yang tidak akan terjadi lagi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 20, 'Dan sekiranya Tuhan tidak mempersingkat waktunya, maka dari segala yang hidup tidak akan ada yang selamat; akan tetapi oleh karena orang-orang pilihan yang telah dipilih-Nya, Tuhan mempersingkat waktunya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 21, 'Pada waktu itu jika orang berkata kepada kamu: Lihat, Mesias ada di sini, atau: Lihat, Mesias ada di sana, jangan kamu percaya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 22, 'Sebab Mesias-mesias palsu dan nabi-nabi palsu akan muncul dan mereka akan mengadakan tanda-tanda dan mujizat-mujizat dengan maksud, sekiranya mungkin, menyesatkan orang-orang pilihan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 23, 'Hati-hatilah kamu! Aku sudah terlebih dahulu mengatakan semuanya ini kepada kamu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 24, '"Tetapi pada masa itu, sesudah siksaan itu, matahari akan menjadi gelap dan bulan tidak bercahaya', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 25, 'dan bintang-bintang akan berjatuhan dari langit, dan kuasa-kuasa langit akan goncang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 26, 'Pada waktu itu orang akan melihat Anak Manusia datang dalam awan-awan dengan segala kekuasaan dan kemuliaan-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 27, 'Dan pada waktu itupun Ia akan menyuruh keluar malaikat-malaikat-Nya dan akan mengumpulkan orang-orang pilihan-Nya dari keempat penjuru bumi, dari ujung bumi sampai ke ujung langit.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 28, 'Tariklah pelajaran dari perumpamaan tentang pohon ara. Apabila ranting-rantingnya melembut dan mulai bertunas, kamu tahu, bahwa musim panas sudah dekat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 29, 'Demikian juga, jika kamu lihat hal-hal itu terjadi, ketahuilah bahwa waktunya sudah dekat, sudah di ambang pintu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 30, 'Aku berkata kepadamu: Sesungguhnya angkatan ini tidak akan berlalu, sebelum semuanya itu terjadi.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 31, 'Langit dan bumi akan berlalu, tetapi perkataan-Ku tidak akan berlalu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 32, 'Tetapi tentang hari atau saat itu tidak seorangpun yang tahu, malaikat-malaikat di sorga tidak, dan Anakpun tidak, hanya Bapa saja."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 33, '"Hati-hatilah dan berjaga-jagalah! Sebab kamu tidak tahu bilamanakah waktunya tiba.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 34, 'Dan halnya sama seperti seorang yang bepergian, yang meninggalkan rumahnya dan menyerahkan tanggung jawab kepada hamba-hambanya, masing-masing dengan tugasnya, dan memerintahkan penunggu pintu supaya berjaga-jaga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 35, 'Karena itu berjaga-jagalah, sebab kamu tidak tahu bilamanakah tuan rumah itu pulang, menjelang malam, atau tengah malam, atau larut malam, atau pagi-pagi buta,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 36, 'supaya kalau ia tiba-tiba datang jangan kamu didapatinya sedang tidur.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 13, 37, 'Apa yang Kukatakan kepada kamu, Kukatakan kepada semua orang: berjaga-jagalah!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 1, 'Hari raya Paskah dan hari raya Roti Tidak Beragi akan mulai dua hari lagi. Imam-imam kepala dan ahli-ahli Taurat mencari jalan untuk menangkap dan membunuh Yesus dengan tipu muslihat,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 2, 'sebab mereka berkata: "Jangan pada waktu perayaan, supaya jangan timbul keributan di antara rakyat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 3, 'Ketika Yesus berada di Betania, di rumah Simon si kusta, dan sedang duduk makan, datanglah seorang perempuan membawa suatu buli-buli pualam berisi minyak narwastu murni yang mahal harganya. Setelah dipecahkannya leher buli-buli itu, dicurahkannya minyak itu ke atas kepala Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 4, 'Ada orang yang menjadi gusar dan berkata seorang kepada yang lain: "Untuk apa pemborosan minyak narwastu ini?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 5, 'Sebab minyak ini dapat dijual tiga ratus dinar lebih dan uangnya dapat diberikan kepada orang-orang miskin." Lalu mereka memarahi perempuan itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 6, 'Tetapi Yesus berkata: "Biarkanlah dia. Mengapa kamu menyusahkan dia? Ia telah melakukan suatu perbuatan yang baik pada-Ku.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 7, 'Karena orang-orang miskin selalu ada padamu, dan kamu dapat menolong mereka, bilamana kamu menghendakinya, tetapi Aku tidak akan selalu bersama-sama kamu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 8, 'Ia telah melakukan apa yang dapat dilakukannya. Tubuh-Ku telah diminyakinya sebagai persiapan untuk penguburan-Ku.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 9, 'Aku berkata kepadamu: Sesungguhnya di mana saja Injil diberitakan di seluruh dunia, apa yang dilakukannya ini akan disebut juga untuk mengingat dia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 10, 'Lalu pergilah Yudas Iskariot, salah seorang dari kedua belas murid itu, kepada imam-imam kepala dengan maksud untuk menyerahkan Yesus kepada mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 11, 'Mereka sangat gembira waktu mendengarnya dan mereka berjanji akan memberikan uang kepadanya. Kemudian ia mencari kesempatan yang baik untuk menyerahkan Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 12, 'Pada hari pertama dari hari raya Roti Tidak Beragi, pada waktu orang menyembelih domba Paskah, murid-murid Yesus berkata kepada-Nya: "Ke tempat mana Engkau kehendaki kami pergi untuk mempersiapkan perjamuan Paskah bagi-Mu?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 13, 'Lalu Ia menyuruh dua orang murid-Nya dengan pesan: "Pergilah ke kota; di sana kamu akan bertemu dengan seorang yang membawa kendi berisi air. Ikutilah dia', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 14, 'dan katakanlah kepada pemilik rumah yang dimasukinya: Pesan Guru: di manakah ruangan yang disediakan bagi-Ku untuk makan Paskah bersama-sama dengan murid-murid-Ku?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 15, 'Lalu orang itu akan menunjukkan kamu sebuah ruangan atas yang besar, yang sudah lengkap dan tersedia. Di situlah kamu harus mempersiapkan perjamuan Paskah untuk kita!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 16, 'Maka berangkatlah kedua murid itu dan setibanya di kota, didapati mereka semua seperti yang dikatakan Yesus kepada mereka. Lalu mereka mempersiapkan Paskah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 17, 'Setelah hari malam, datanglah Yesus bersama-sama dengan kedua belas murid itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 18, 'Ketika mereka duduk di situ dan sedang makan, Yesus berkata: "Aku berkata kepadamu, sesungguhnya seorang di antara kamu akan menyerahkan Aku, yaitu dia yang makan dengan Aku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 19, 'Maka sedihlah hati mereka dan seorang demi seorang berkata kepada-Nya: "Bukan aku, ya Tuhan?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 20, 'Ia menjawab: "Orang itu ialah salah seorang dari kamu yang dua belas ini, dia yang mencelupkan roti ke dalam satu pinggan dengan Aku.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 21, 'Anak Manusia memang akan pergi sesuai dengan yang ada tertulis tentang Dia, akan tetapi celakalah orang yang olehnya Anak Manusia itu diserahkan. Adalah lebih baik bagi orang itu sekiranya ia tidak dilahirkan."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 22, 'Dan ketika Yesus dan murid-murid-Nya sedang makan, Yesus mengambil roti, mengucap berkat, memecah-mecahkannya lalu memberikannya kepada mereka dan berkata: "Ambillah, inilah tubuh-Ku."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 23, 'Sesudah itu Ia mengambil cawan, mengucap syukur lalu memberikannya kepada mereka, dan mereka semuanya minum dari cawan itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 24, 'Dan Ia berkata kepada mereka: "Inilah darah-Ku, darah perjanjian, yang ditumpahkan bagi banyak orang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 25, 'Aku berkata kepadamu: Sesungguhnya Aku tidak akan minum lagi hasil pokok anggur sampai pada hari Aku meminumnya, yaitu yang baru, dalam Kerajaan Allah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 26, 'Sesudah mereka menyanyikan nyanyian pujian, pergilah mereka ke Bukit Zaitun.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 27, 'Lalu Yesus berkata kepada mereka: "Kamu semua akan tergoncang imanmu. Sebab ada tertulis: Aku akan memukul gembala dan domba-domba itu akan tercerai-berai.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 28, 'Akan tetapi sesudah Aku bangkit, Aku akan mendahului kamu ke Galilea."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 29, 'Kata Petrus kepada-Nya: "Biarpun mereka semua tergoncang imannya, aku tidak."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 30, 'Lalu kata Yesus kepadanya: "Aku berkata kepadamu, sesungguhnya pada hari ini, malam ini juga, sebelum ayam berkokok dua kali, engkau telah menyangkal Aku tiga kali."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 31, 'Tetapi dengan lebih bersungguh-sungguh Petrus berkata: "Sekalipun aku harus mati bersama-sama Engkau, aku takkan menyangkal Engkau." Semua yang lainpun berkata demikian juga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 32, 'Lalu sampailah Yesus dan murid-murid-Nya ke suatu tempat yang bernama Getsemani. Kata Yesus kepada murid-murid-Nya: "Duduklah di sini, sementara Aku berdoa."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 33, 'Dan Ia membawa Petrus, Yakobus dan Yohanes serta-Nya. Ia sangat takut dan gentar,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 34, 'lalu kata-Nya kepada mereka: "Hati-Ku sangat sedih, seperti mau mati rasanya. Tinggallah di sini dan berjaga-jagalah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 35, 'Ia maju sedikit, merebahkan diri ke tanah dan berdoa supaya, sekiranya mungkin, saat itu lalu dari pada-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 36, 'Kata-Nya: "Ya Abba, ya Bapa, tidak ada yang mustahil bagi-Mu, ambillah cawan ini dari pada-Ku, tetapi janganlah apa yang Aku kehendaki, melainkan apa yang Engkau kehendaki."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 37, 'Setelah itu Ia datang kembali, dan mendapati ketiganya sedang tidur. Dan Ia berkata kepada Petrus: "Simon, sedang tidurkah engkau? Tidakkah engkau sanggup berjaga-jaga satu jam?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 38, 'Berjaga-jagalah dan berdoalah, supaya kamu jangan jatuh ke dalam pencobaan; roh memang penurut, tetapi daging lemah."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 39, 'Lalu Ia pergi lagi dan mengucapkan doa yang itu juga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 40, 'Dan ketika Ia kembali pula, Ia mendapati mereka sedang tidur, sebab mata mereka sudah berat dan mereka tidak tahu jawab apa yang harus mereka berikan kepada-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 41, 'Kemudian Ia kembali untuk ketiga kalinya dan berkata kepada mereka: "Tidurlah sekarang dan istirahatlah. Cukuplah. Saatnya sudah tiba, lihat, Anak Manusia diserahkan ke tangan orang-orang berdosa.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 42, 'Bangunlah, marilah kita pergi. Dia yang menyerahkan Aku sudah dekat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 43, 'Waktu Yesus masih berbicara, muncullah Yudas, salah seorang dari kedua belas murid itu, dan bersama-sama dia serombongan orang yang membawa pedang dan pentung, disuruh oleh imam-imam kepala, ahli-ahli Taurat dan tua-tua.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 44, 'Orang yang menyerahkan Dia telah memberitahukan tanda ini kepada mereka: "Orang yang akan kucium, itulah Dia, tangkaplah Dia dan bawalah Dia dengan selamat."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 45, 'Dan ketika ia sampai di situ ia segera maju mendapatkan Yesus dan berkata: "Rabi," lalu mencium Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 46, 'Maka mereka memegang Yesus dan menangkap-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 47, 'Salah seorang dari mereka yang ada di situ menghunus pedangnya, lalu menetakkannya kepada hamba Imam Besar sehingga putus telinganya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 48, 'Kata Yesus kepada mereka: "Sangkamu Aku ini penyamun, maka kamu datang lengkap dengan pedang dan pentung untuk menangkap Aku?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 49, 'Padahal tiap-tiap hari Aku ada di tengah-tengah kamu mengajar di Bait Allah, dan kamu tidak menangkap Aku. Tetapi haruslah digenapi yang tertulis dalam Kitab Suci."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 50, 'Lalu semua murid itu meninggalkan Dia dan melarikan diri.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 51, 'Ada seorang muda, yang pada waktu itu hanya memakai sehelai kain lenan untuk menutup badannya, mengikuti Dia. Mereka hendak menangkapnya,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 52, 'tetapi ia melepaskan kainnya dan lari dengan telanjang.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 53, 'Kemudian Yesus dibawa menghadap Imam Besar. Lalu semua imam kepala, tua-tua dan ahli Taurat berkumpul di situ.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 54, 'Dan Petrus mengikuti Dia dari jauh, sampai ke dalam halaman Imam Besar, dan di sana ia duduk di antara pengawal-pengawal sambil berdiang dekat api.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 55, 'Imam-imam kepala, malah seluruh Mahkamah Agama mencari kesaksian terhadap Yesus supaya Ia dapat dihukum mati, tetapi mereka tidak memperolehnya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 56, 'Banyak juga orang yang mengucapkan kesaksian palsu terhadap Dia, tetapi kesaksian-kesaksian itu tidak sesuai yang satu dengan yang lain.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 57, 'Lalu beberapa orang naik saksi melawan Dia dengan tuduhan palsu ini:', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 58, '"Kami sudah mendengar orang ini berkata: Aku akan merubuhkan Bait Suci buatan tangan manusia ini dan dalam tiga hari akan Kudirikan yang lain, yang bukan buatan tangan manusia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 59, 'Dalam hal inipun kesaksian mereka tidak sesuai yang satu dengan yang lain.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 14, 60, 'Maka Imam Besar bangkit berdiri di tengah-tengah sidang dan bertanya kepada Yesus, katanya: "Tidakkah Engkau memberi jawab atas tuduhan-tuduhan saksi-saksi ini terhadap Engkau?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 1, 'Pagi-pagi benar imam-imam kepala bersama tua-tua dan ahli-ahli Taurat dan seluruh Mahkamah Agama sudah bulat mupakatnya. Mereka membelenggu Yesus lalu membawa-Nya dan menyerahkan-Nya kepada Pilatus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 2, 'Pilatus bertanya kepada-Nya: "Engkaukah raja orang Yahudi?" Jawab Yesus: "Engkau sendiri mengatakannya."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 3, 'Lalu imam-imam kepala mengajukan banyak tuduhan terhadap Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 4, 'Pilatus bertanya pula kepada-Nya, katanya: "Tidakkah Engkau memberi jawab? Lihatlah betapa banyaknya tuduhan mereka terhadap Engkau!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 5, 'Tetapi Yesus sama sekali tidak menjawab lagi, sehingga Pilatus merasa heran.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 6, 'Telah menjadi kebiasaan untuk membebaskan satu orang hukuman pada tiap-tiap hari raya itu menurut permintaan orang banyak.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 7, 'Dan pada waktu itu adalah seorang yang bernama Barabas sedang dipenjarakan bersama beberapa orang pemberontak lainnya. Mereka telah melakukan pembunuhan dalam pemberontakan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 8, 'Maka datanglah orang banyak dan meminta supaya sekarang kebiasaan itu diikuti juga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 9, 'Pilatus menjawab mereka dan bertanya: "Apakah kamu menghendaki supaya kubebaskan raja orang Yahudi ini?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 10, 'Ia memang mengetahui, bahwa imam-imam kepala telah menyerahkan Yesus karena dengki.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 11, 'Tetapi imam-imam kepala menghasut orang banyak untuk meminta supaya Barabaslah yang dibebaskannya bagi mereka.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 12, 'Pilatus sekali lagi menjawab dan bertanya kepada mereka: "Jika begitu, apakah yang harus kuperbuat dengan orang yang kamu sebut raja orang Yahudi ini?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 13, 'Maka mereka berteriak lagi, katanya: "Salibkanlah Dia!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 14, 'Lalu Pilatus berkata kepada mereka: "Tetapi kejahatan apakah yang telah dilakukan-Nya?" Namun mereka makin keras berteriak: "Salibkanlah Dia!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 15, 'Dan oleh karena Pilatus ingin memuaskan hati orang banyak itu, ia membebaskan Barabas bagi mereka. Tetapi Yesus disesahnya lalu diserahkannya untuk disalibkan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 16, 'Kemudian serdadu-serdadu membawa Yesus ke dalam istana, yaitu gedung pengadilan, dan memanggil seluruh pasukan berkumpul.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 17, 'Mereka mengenakan jubah ungu kepada-Nya, menganyam sebuah mahkota duri dan menaruhnya di atas kepala-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 18, 'Kemudian mereka mulai memberi hormat kepada-Nya, katanya: "Salam, hai raja orang Yahudi!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 19, 'Mereka memukul kepala-Nya dengan buluh, dan meludahi-Nya dan berlutut menyembah-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 20, 'Sesudah mengolok-olokkan Dia mereka menanggalkan jubah ungu itu dari pada-Nya dan mengenakan pula pakaian-Nya kepada-Nya. (15-20b) Kemudian Yesus dibawa ke luar untuk disalibkan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 21, 'Pada waktu itu lewat seorang yang bernama Simon, orang Kirene, ayah Aleksander dan Rufus, yang baru datang dari luar kota, dan orang itu mereka paksa untuk memikul salib Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 22, 'Mereka membawa Yesus ke tempat yang bernama Golgota, yang berarti: Tempat Tengkorak.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 23, 'Lalu mereka memberi anggur bercampur mur kepada-Nya, tetapi Ia menolaknya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 24, 'Kemudian mereka menyalibkan Dia, lalu mereka membagi pakaian-Nya dengan membuang undi atasnya untuk menentukan bagian masing-masing.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 25, 'Hari jam sembilan ketika Ia disalibkan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 26, 'Dan alasan mengapa Ia dihukum disebut pada tulisan yang terpasang di situ: "Raja orang Yahudi".', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 27, 'Bersama dengan Dia disalibkan dua orang penyamun, seorang di sebelah kanan-Nya dan seorang di sebelah kiri-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 28, '(Demikian genaplah nas Alkitab yang berbunyi: "Ia akan terhitung di antara orang-orang durhaka.")', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 29, 'Orang-orang yang lewat di sana menghujat Dia, dan sambil menggelengkan kepala mereka berkata: "Hai Engkau yang mau merubuhkan Bait Suci dan mau membangunnya kembali dalam tiga hari,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 30, 'turunlah dari salib itu dan selamatkan diri-Mu!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 31, 'Demikian juga imam-imam kepala bersama-sama ahli Taurat mengolok-olokkan Dia di antara mereka sendiri dan mereka berkata: "Orang lain Ia selamatkan, tetapi diri-Nya sendiri tidak dapat Ia selamatkan!', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 32, 'Baiklah Mesias, Raja Israel itu, turun dari salib itu, supaya kita lihat dan percaya." Bahkan kedua orang yang disalibkan bersama-sama dengan Dia mencela Dia juga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 33, 'Pada jam dua belas, kegelapan meliputi seluruh daerah itu dan berlangsung sampai jam tiga.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 34, 'Dan pada jam tiga berserulah Yesus dengan suara nyaring: "Eloi, Eloi, lama sabakhtani?", yang berarti: Allahku, Allahku, mengapa Engkau meninggalkan Aku?', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 35, 'Mendengar itu, beberapa orang yang berdiri di situ berkata: "Lihat, Ia memanggil Elia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 36, 'Maka datanglah seorang dengan bunga karang, mencelupkannya ke dalam anggur asam lalu mencucukkannya pada sebatang buluh dan memberi Yesus minum serta berkata: "Baiklah kita tunggu dan melihat apakah Elia datang untuk menurunkan Dia."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 37, 'Lalu berserulah Yesus dengan suara nyaring dan menyerahkan nyawa-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 38, 'Ketika itu tabir Bait Suci terbelah dua dari atas sampai ke bawah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 39, 'Waktu kepala pasukan yang berdiri berhadapan dengan Dia melihat mati-Nya demikian, berkatalah ia: "Sungguh, orang ini adalah Anak Allah!"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 40, 'Ada juga beberapa perempuan yang melihat dari jauh, di antaranya Maria Magdalena, Maria ibu Yakobus Muda dan Yoses, serta Salome.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 41, 'Mereka semuanya telah mengikut Yesus dan melayani-Nya waktu Ia di Galilea. Dan ada juga di situ banyak perempuan lain yang telah datang ke Yerusalem bersama-sama dengan Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 42, 'Sementara itu hari mulai malam, dan hari itu adalah hari persiapan, yaitu hari menjelang Sabat.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 43, 'Karena itu Yusuf, orang Arimatea, seorang anggota Majelis Besar yang terkemuka, yang juga menanti-nantikan Kerajaan Allah, memberanikan diri menghadap Pilatus dan meminta mayat Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 44, 'Pilatus heran waktu mendengar bahwa Yesus sudah mati. Maka ia memanggil kepala pasukan dan bertanya kepadanya apakah Yesus sudah mati.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 45, 'Sesudah didengarnya keterangan kepala pasukan, ia berkenan memberikan mayat itu kepada Yusuf.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 46, 'Yusufpun membeli kain lenan, kemudian ia menurunkan mayat Yesus dari salib dan mengapaninya dengan kain lenan itu. Lalu ia membaringkan Dia di dalam kubur yang digali di dalam bukit batu. Kemudian digulingkannya sebuah batu ke pintu kubur itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 15, 47, 'Maria Magdalena dan Maria ibu Yoses melihat di mana Yesus dibaringkan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 1, 'Setelah lewat hari Sabat, Maria Magdalena dan Maria ibu Yakobus, serta Salome membeli rempah-rempah untuk pergi ke kubur dan meminyaki Yesus.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 2, 'Dan pagi-pagi benar pada hari pertama minggu itu, setelah matahari terbit, pergilah mereka ke kubur.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 3, 'Mereka berkata seorang kepada yang lain: "Siapa yang akan menggulingkan batu itu bagi kita dari pintu kubur?"', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 4, 'Tetapi ketika mereka melihat dari dekat, tampaklah, batu yang memang sangat besar itu sudah terguling.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 5, 'Lalu mereka masuk ke dalam kubur dan mereka melihat seorang muda yang memakai jubah putih duduk di sebelah kanan. Merekapun sangat terkejut,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 6, 'tetapi orang muda itu berkata kepada mereka: "Jangan takut! Kamu mencari Yesus orang Nazaret, yang disalibkan itu. Ia telah bangkit. Ia tidak ada di sini. Lihat! Inilah tempat mereka membaringkan Dia.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 7, 'Tetapi sekarang pergilah, katakanlah kepada murid-murid-Nya dan kepada Petrus: Ia mendahului kamu ke Galilea; di sana kamu akan melihat Dia, seperti yang sudah dikatakan-Nya kepada kamu."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 8, 'Lalu mereka keluar dan lari meninggalkan kubur itu, sebab gentar dan dahsyat menimpa mereka. Mereka tidak mengatakan apa-apa kepada siapapun juga karena takut. Dengan singkat mereka sampaikan semua pesan itu kepada Petrus dan teman-temannya. Sesudah itu Yesus sendiri dengan perantaraan murid-murid-Nya memberitakan dari Timur ke Barat berita yang kudus dan tak terbinasakan tentang keselamatan yang kekal itu.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 9, 'Setelah Yesus bangkit pagi-pagi pada hari pertama minggu itu, Ia mula-mula menampakkan diri-Nya kepada Maria Magdalena. Dari padanya Yesus pernah mengusir tujuh setan.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 10, 'Lalu perempuan itu pergi memberitahukannya kepada mereka yang selalu mengiringi Yesus, dan yang pada waktu itu sedang berkabung dan menangis.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 11, 'Tetapi ketika mereka mendengar, bahwa Yesus hidup dan telah dilihat olehnya, mereka tidak percaya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 12, 'Sesudah itu Ia menampakkan diri dalam rupa yang lain kepada dua orang dari mereka, ketika keduanya dalam perjalanan ke luar kota.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 13, 'Lalu kembalilah mereka dan memberitahukannya kepada teman-teman yang lain, tetapi kepada merekapun teman-teman itu tidak percaya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 14, 'Akhirnya Ia menampakkan diri kepada kesebelas orang itu ketika mereka sedang makan, dan Ia mencela ketidakpercayaan dan kedegilan hati mereka, oleh karena mereka tidak percaya kepada orang-orang yang telah melihat Dia sesudah kebangkitan-Nya.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 15, 'Lalu Ia berkata kepada mereka: "Pergilah ke seluruh dunia, beritakanlah Injil kepada segala makhluk.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 16, 'Siapa yang percaya dan dibaptis akan diselamatkan, tetapi siapa yang tidak percaya akan dihukum.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 17, 'Tanda-tanda ini akan menyertai orang-orang yang percaya: mereka akan mengusir setan-setan demi nama-Ku, mereka akan berbicara dalam bahasa-bahasa yang baru bagi mereka,', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 18, 'mereka akan memegang ular, dan sekalipun mereka minum racun maut, mereka tidak akan mendapat celaka; mereka akan meletakkan tangannya atas orang sakit, dan orang itu akan sembuh."', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 19, 'Sesudah Tuhan Yesus berbicara demikian kepada mereka, terangkatlah Ia ke sorga, lalu duduk di sebelah kanan Allah.', 'id', 'TB'),
  ('41', 'mrk', 'Markus', 16, 20, 'Merekapun pergilah memberitakan Injil ke segala penjuru, dan Tuhan turut bekerja dan meneguhkan firman itu dengan tanda-tanda yang menyertainya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 1, 'Teofilus yang mulia, Banyak orang telah berusaha menyusun suatu berita tentang peristiwa-peristiwa yang telah terjadi di antara kita,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 2, 'seperti yang disampaikan kepada kita oleh mereka, yang dari semula adalah saksi mata dan pelayan Firman.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 3, 'Karena itu, setelah aku menyelidiki segala peristiwa itu dengan seksama dari asal mulanya, aku mengambil keputusan untuk membukukannya dengan teratur bagimu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 4, 'supaya engkau dapat mengetahui, bahwa segala sesuatu yang diajarkan kepadamu sungguh benar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 5, 'Pada zaman Herodes, raja Yudea, adalah seorang imam yang bernama Zakharia dari rombongan Abia. Isterinya juga berasal dari keturunan Harun, namanya Elisabet.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 6, 'Keduanya adalah benar di hadapan Allah dan hidup menurut segala perintah dan ketetapan Tuhan dengan tidak bercacat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 7, 'Tetapi mereka tidak mempunyai anak, sebab Elisabet mandul dan keduanya telah lanjut umurnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 8, 'Pada suatu kali, waktu tiba giliran rombongannya, Zakharia melakukan tugas keimaman di hadapan Tuhan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 9, 'Sebab ketika diundi, sebagaimana lazimnya, untuk menentukan imam yang bertugas, dialah yang ditunjuk untuk masuk ke dalam Bait Suci dan membakar ukupan di situ.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 10, 'Sementara itu seluruh umat berkumpul di luar dan sembahyang. Waktu itu adalah waktu pembakaran ukupan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 11, 'Maka tampaklah kepada Zakharia seorang malaikat Tuhan berdiri di sebelah kanan mezbah pembakaran ukupan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 12, 'Melihat hal itu ia terkejut dan menjadi takut.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 13, 'Tetapi malaikat itu berkata kepadanya: "Jangan takut, hai Zakharia, sebab doamu telah dikabulkan dan Elisabet, isterimu, akan melahirkan seorang anak laki-laki bagimu dan haruslah engkau menamai dia Yohanes.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 14, 'Engkau akan bersukacita dan bergembira, bahkan banyak orang akan bersukacita atas kelahirannya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 15, 'Sebab ia akan besar di hadapan Tuhan dan ia tidak akan minum anggur atau minuman keras dan ia akan penuh dengan Roh Kudus mulai dari rahim ibunya;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 16, 'ia akan membuat banyak orang Israel berbalik kepada Tuhan, Allah mereka,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 17, 'dan ia akan berjalan mendahului Tuhan dalam roh dan kuasa Elia untuk membuat hati bapa-bapa berbalik kepada anak-anaknya dan hati orang-orang durhaka kepada pikiran orang-orang benar dan dengan demikian menyiapkan bagi Tuhan suatu umat yang layak bagi-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 18, 'Lalu kata Zakharia kepada malaikat itu: "Bagaimanakah aku tahu, bahwa hal ini akan terjadi? Sebab aku sudah tua dan isteriku sudah lanjut umurnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 19, 'Jawab malaikat itu kepadanya: "Akulah Gabriel yang melayani Allah dan aku telah diutus untuk berbicara dengan engkau dan untuk menyampaikan kabar baik ini kepadamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 20, 'Sesungguhnya engkau akan menjadi bisu dan tidak dapat berkata-kata sampai kepada hari, di mana semuanya ini terjadi, karena engkau tidak percaya akan perkataanku yang akan nyata kebenarannya pada waktunya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 21, 'Sementara itu orang banyak menanti-nantikan Zakharia. Mereka menjadi heran, bahwa ia begitu lama berada dalam Bait Suci.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 22, 'Ketika ia keluar, ia tidak dapat berkata-kata kepada mereka dan mengertilah mereka, bahwa ia telah melihat suatu penglihatan di dalam Bait Suci. Lalu ia memberi isyarat kepada mereka, sebab ia tetap bisu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 23, 'Ketika selesai jangka waktu tugas jabatannya, ia pulang ke rumah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 24, 'Beberapa lama kemudian Elisabet, isterinya, mengandung dan selama lima bulan ia tidak menampakkan diri, katanya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 25, '"Inilah suatu perbuatan Tuhan bagiku, dan sekarang Ia berkenan menghapuskan aibku di depan orang."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 26, 'Dalam bulan yang keenam Allah menyuruh malaikat Gabriel pergi ke sebuah kota di Galilea bernama Nazaret,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 27, 'kepada seorang perawan yang bertunangan dengan seorang bernama Yusuf dari keluarga Daud; nama perawan itu Maria.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 28, 'Ketika malaikat itu masuk ke rumah Maria, ia berkata: "Salam, hai engkau yang dikaruniai, Tuhan menyertai engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 29, 'Maria terkejut mendengar perkataan itu, lalu bertanya di dalam hatinya, apakah arti salam itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 30, 'Kata malaikat itu kepadanya: "Jangan takut, hai Maria, sebab engkau beroleh kasih karunia di hadapan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 31, 'Sesungguhnya engkau akan mengandung dan akan melahirkan seorang anak laki-laki dan hendaklah engkau menamai Dia Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 32, 'Ia akan menjadi besar dan akan disebut Anak Allah Yang Mahatinggi. Dan Tuhan Allah akan mengaruniakan kepada-Nya takhta Daud, bapa leluhur-Nya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 33, 'dan Ia akan menjadi raja atas kaum keturunan Yakub sampai selama-lamanya dan Kerajaan-Nya tidak akan berkesudahan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 34, 'Kata Maria kepada malaikat itu: "Bagaimana hal itu mungkin terjadi, karena aku belum bersuami?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 35, 'Jawab malaikat itu kepadanya: "Roh Kudus akan turun atasmu dan kuasa Allah Yang Mahatinggi akan menaungi engkau; sebab itu anak yang akan kaulahirkan itu akan disebut kudus, Anak Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 36, 'Dan sesungguhnya, Elisabet, sanakmu itu, iapun sedang mengandung seorang anak laki-laki pada hari tuanya dan inilah bulan yang keenam bagi dia, yang disebut mandul itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 37, 'Sebab bagi Allah tidak ada yang mustahil."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 38, 'Kata Maria: "Sesungguhnya aku ini adalah hamba Tuhan; jadilah padaku menurut perkataanmu itu." Lalu malaikat itu meninggalkan dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 39, 'Beberapa waktu kemudian berangkatlah Maria dan langsung berjalan ke pegunungan menuju sebuah kota di Yehuda.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 40, 'Di situ ia masuk ke rumah Zakharia dan memberi salam kepada Elisabet.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 41, 'Dan ketika Elisabet mendengar salam Maria, melonjaklah anak yang di dalam rahimnya dan Elisabetpun penuh dengan Roh Kudus,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 42, 'lalu berseru dengan suara nyaring: "Diberkatilah engkau di antara semua perempuan dan diberkatilah buah rahimmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 43, 'Siapakah aku ini sampai ibu Tuhanku datang mengunjungi aku?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 44, 'Sebab sesungguhnya, ketika salammu sampai kepada telingaku, anak yang di dalam rahimku melonjak kegirangan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 45, 'Dan berbahagialah ia, yang telah percaya, sebab apa yang dikatakan kepadanya dari Tuhan, akan terlaksana."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 46, 'Lalu kata Maria: "Jiwaku memuliakan Tuhan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 47, 'dan hatiku bergembira karena Allah, Juruselamatku,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 48, 'sebab Ia telah memperhatikan kerendahan hamba-Nya. Sesungguhnya, mulai dari sekarang segala keturunan akan menyebut aku berbahagia,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 49, 'karena Yang Mahakuasa telah melakukan perbuatan-perbuatan besar kepadaku dan nama-Nya adalah kudus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 50, 'Dan rahmat-Nya turun-temurun atas orang yang takut akan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 51, 'Ia memperlihatkan kuasa-Nya dengan perbuatan tangan-Nya dan mencerai-beraikan orang-orang yang congkak hatinya;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 52, 'Ia menurunkan orang-orang yang berkuasa dari takhtanya dan meninggikan orang-orang yang rendah;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 53, 'Ia melimpahkan segala yang baik kepada orang yang lapar, dan menyuruh orang yang kaya pergi dengan tangan hampa;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 54, 'Ia menolong Israel, hamba-Nya, karena Ia mengingat rahmat-Nya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 55, 'seperti yang dijanjikan-Nya kepada nenek moyang kita, kepada Abraham dan keturunannya untuk selama-lamanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 56, 'Dan Maria tinggal kira-kira tiga bulan lamanya bersama dengan Elisabet, lalu pulang kembali ke rumahnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 57, 'Kemudian genaplah bulannya bagi Elisabet untuk bersalin dan iapun melahirkan seorang anak laki-laki.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 58, 'Ketika tetangga-tetangganya serta sanak saudaranya mendengar, bahwa Tuhan telah menunjukkan rahmat-Nya yang begitu besar kepadanya, bersukacitalah mereka bersama-sama dengan dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 59, 'Maka datanglah mereka pada hari yang kedelapan untuk menyunatkan anak itu dan mereka hendak menamai dia Zakharia menurut nama bapanya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 1, 60, 'tetapi ibunya berkata: "Jangan, ia harus dinamai Yohanes."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 1, 'Pada waktu itu Kaisar Agustus mengeluarkan suatu perintah, menyuruh mendaftarkan semua orang di seluruh dunia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 2, 'Inilah pendaftaran yang pertama kali diadakan sewaktu Kirenius menjadi wali negeri di Siria.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 3, 'Maka pergilah semua orang mendaftarkan diri, masing-masing di kotanya sendiri.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 4, 'Demikian juga Yusuf pergi dari kota Nazaret di Galilea ke Yudea, ke kota Daud yang bernama Betlehem, ?karena ia berasal dari keluarga dan keturunan Daud?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 5, 'supaya didaftarkan bersama-sama dengan Maria, tunangannya, yang sedang mengandung.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 6, 'Ketika mereka di situ tibalah waktunya bagi Maria untuk bersalin,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 7, 'dan ia melahirkan seorang anak laki-laki, anaknya yang sulung, lalu dibungkusnya dengan lampin dan dibaringkannya di dalam palungan, karena tidak ada tempat bagi mereka di rumah penginapan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 8, 'Di daerah itu ada gembala-gembala yang tinggal di padang menjaga kawanan ternak mereka pada waktu malam.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 9, 'Tiba-tiba berdirilah seorang malaikat Tuhan di dekat mereka dan kemuliaan Tuhan bersinar meliputi mereka dan mereka sangat ketakutan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 10, 'Lalu kata malaikat itu kepada mereka: "Jangan takut, sebab sesungguhnya aku memberitakan kepadamu kesukaan besar untuk seluruh bangsa:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 11, 'Hari ini telah lahir bagimu Juruselamat, yaitu Kristus, Tuhan, di kota Daud.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 12, 'Dan inilah tandanya bagimu: Kamu akan menjumpai seorang bayi dibungkus dengan lampin dan terbaring di dalam palungan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 13, 'Dan tiba-tiba tampaklah bersama-sama dengan malaikat itu sejumlah besar bala tentara sorga yang memuji Allah, katanya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 14, '"Kemuliaan bagi Allah di tempat yang mahatinggi dan damai sejahtera di bumi di antara manusia yang berkenan kepada-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 15, 'Setelah malaikat-malaikat itu meninggalkan mereka dan kembali ke sorga, gembala-gembala itu berkata seorang kepada yang lain: "Marilah kita pergi ke Betlehem untuk melihat apa yang terjadi di sana, seperti yang diberitahukan Tuhan kepada kita."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 16, 'Lalu mereka cepat-cepat berangkat dan menjumpai Maria dan Yusuf dan bayi itu, yang sedang berbaring di dalam palungan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 17, 'Dan ketika mereka melihat-Nya, mereka memberitahukan apa yang telah dikatakan kepada mereka tentang Anak itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 18, 'Dan semua orang yang mendengarnya heran tentang apa yang dikatakan gembala-gembala itu kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 19, 'Tetapi Maria menyimpan segala perkara itu di dalam hatinya dan merenungkannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 20, 'Maka kembalilah gembala-gembala itu sambil memuji dan memuliakan Allah karena segala sesuatu yang mereka dengar dan mereka lihat, semuanya sesuai dengan apa yang telah dikatakan kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 21, 'Dan ketika genap delapan hari dan Ia harus disunatkan, Ia diberi nama Yesus, yaitu nama yang disebut oleh malaikat sebelum Ia dikandung ibu-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 22, 'Dan ketika genap waktu pentahiran, menurut hukum Taurat Musa, mereka membawa Dia ke Yerusalem untuk menyerahkan-Nya kepada Tuhan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 23, 'seperti ada tertulis dalam hukum Tuhan: "Semua anak laki-laki sulung harus dikuduskan bagi Allah",', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 24, 'dan untuk mempersembahkan korban menurut apa yang difirmankan dalam hukum Tuhan, yaitu sepasang burung tekukur atau dua ekor anak burung merpati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 25, 'Adalah di Yerusalem seorang bernama Simeon. Ia seorang yang benar dan saleh yang menantikan penghiburan bagi Israel. Roh Kudus ada di atasnya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 26, 'dan kepadanya telah dinyatakan oleh Roh Kudus, bahwa ia tidak akan mati sebelum ia melihat Mesias, yaitu Dia yang diurapi Tuhan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 27, 'Ia datang ke Bait Allah oleh Roh Kudus. Ketika Yesus, Anak itu, dibawa masuk oleh orang tua-Nya untuk melakukan kepada-Nya apa yang ditentukan hukum Taurat,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 28, 'ia menyambut Anak itu dan menatang-Nya sambil memuji Allah, katanya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 29, '"Sekarang, Tuhan, biarkanlah hamba-Mu ini pergi dalam damai sejahtera, sesuai dengan firman-Mu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 30, 'sebab mataku telah melihat keselamatan yang dari pada-Mu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 31, 'yang telah Engkau sediakan di hadapan segala bangsa,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 32, 'yaitu terang yang menjadi penyataan bagi bangsa-bangsa lain dan menjadi kemuliaan bagi umat-Mu, Israel."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 33, 'Dan bapa serta ibu-Nya amat heran akan segala apa yang dikatakan tentang Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 34, 'Lalu Simeon memberkati mereka dan berkata kepada Maria, ibu Anak itu: "Sesungguhnya Anak ini ditentukan untuk menjatuhkan atau membangkitkan banyak orang di Israel dan untuk menjadi suatu tanda yang menimbulkan perbantahan', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 35, '?dan suatu pedang akan menembus jiwamu sendiri?,supaya menjadi nyata pikiran hati banyak orang."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 36, 'Lagipula di situ ada Hana, seorang nabi perempuan, anak Fanuel dari suku Asyer. Ia sudah sangat lanjut umurnya. Sesudah kawin ia hidup tujuh tahun lamanya bersama suaminya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 37, 'dan sekarang ia janda dan berumur delapan puluh empat tahun. Ia tidak pernah meninggalkan Bait Allah dan siang malam beribadah dengan berpuasa dan berdoa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 38, 'Dan pada ketika itu juga datanglah ia ke situ dan mengucap syukur kepada Allah dan berbicara tentang Anak itu kepada semua orang yang menantikan kelepasan untuk Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 39, 'Dan setelah selesai semua yang harus dilakukan menurut hukum Tuhan, kembalilah mereka ke kota kediamannya, yaitu kota Nazaret di Galilea.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 40, 'Anak itu bertambah besar dan menjadi kuat, penuh hikmat, dan kasih karunia Allah ada pada-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 41, 'Tiap-tiap tahun orang tua Yesus pergi ke Yerusalem pada hari raya Paskah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 42, 'Ketika Yesus telah berumur dua belas tahun pergilah mereka ke Yerusalem seperti yang lazim pada hari raya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 43, 'Sehabis hari-hari perayaan itu, ketika mereka berjalan pulang, tinggallah Yesus di Yerusalem tanpa diketahui orang tua-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 44, 'Karena mereka menyangka bahwa Ia ada di antara orang-orang seperjalanan mereka, berjalanlah mereka sehari perjalanan jauhnya, lalu mencari Dia di antara kaum keluarga dan kenalan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 45, 'Karena mereka tidak menemukan Dia, kembalilah mereka ke Yerusalem sambil terus mencari Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 46, 'Sesudah tiga hari mereka menemukan Dia dalam Bait Allah; Ia sedang duduk di tengah-tengah alim ulama, sambil mendengarkan mereka dan mengajukan pertanyaan-pertanyaan kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 47, 'Dan semua orang yang mendengar Dia sangat heran akan kecerdasan-Nya dan segala jawab yang diberikan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 48, 'Dan ketika orang tua-Nya melihat Dia, tercenganglah mereka, lalu kata ibu-Nya kepada-Nya: "Nak, mengapakah Engkau berbuat demikian terhadap kami? Bapa-Mu dan aku dengan cemas mencari Engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 49, 'Jawab-Nya kepada mereka: "Mengapa kamu mencari Aku? Tidakkah kamu tahu, bahwa Aku harus berada di dalam rumah Bapa-Ku?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 50, 'Tetapi mereka tidak mengerti apa yang dikatakan-Nya kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 51, 'Lalu Ia pulang bersama-sama mereka ke Nazaret; dan Ia tetap hidup dalam asuhan mereka. Dan ibu-Nya menyimpan semua perkara itu di dalam hatinya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 2, 52, 'Dan Yesus makin bertambah besar dan bertambah hikmat-Nya dan besar-Nya, dan makin dikasihi oleh Allah dan manusia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 1, 'Dalam tahun kelima belas dari pemerintahan Kaisar Tiberius, ketika Pontius Pilatus menjadi wali negeri Yudea, dan Herodes raja wilayah Galilea, Filipus, saudaranya, raja wilayah Iturea dan Trakhonitis, dan Lisanias raja wilayah Abilene,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 2, 'pada waktu Hanas dan Kayafas menjadi Imam Besar, datanglah firman Allah kepada Yohanes, anak Zakharia, di padang gurun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 3, 'Maka datanglah Yohanes ke seluruh daerah Yordan dan menyerukan: "Bertobatlah dan berilah dirimu dibaptis dan Allah akan mengampuni dosamu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 4, 'seperti ada tertulis dalam kitab nubuat-nubuat Yesaya: Ada suara yang berseru-seru di padang gurun: Persiapkanlah jalan untuk Tuhan, luruskanlah jalan bagi-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 5, 'Setiap lembah akan ditimbun dan setiap gunung dan bukit akan menjadi rata, yang berliku-liku akan diluruskan, yang berlekuk-lekuk akan diratakan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 6, 'dan semua orang akan melihat keselamatan yang dari Tuhan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 7, 'Lalu ia berkata kepada orang banyak yang datang kepadanya untuk dibaptis, katanya: "Hai kamu keturunan ular beludak! Siapakah yang mengatakan kepada kamu melarikan diri dari murka yang akan datang?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 8, 'Jadi hasilkanlah buah-buah yang sesuai dengan pertobatan. Dan janganlah berpikir dalam hatimu: Abraham adalah bapa kami! Karena aku berkata kepadamu: Allah dapat menjadikan anak-anak bagi Abraham dari batu-batu ini!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 9, 'Kapak sudah tersedia pada akar pohon dan setiap pohon yang tidak menghasilkan buah yang baik, akan ditebang dan dibuang ke dalam api."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 10, 'Orang banyak bertanya kepadanya: "Jika demikian, apakah yang harus kami perbuat?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 11, 'Jawabnya: "Barangsiapa mempunyai dua helai baju, hendaklah ia membaginya dengan yang tidak punya, dan barangsiapa mempunyai makanan, hendaklah ia berbuat juga demikian."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 12, 'Ada datang juga pemungut-pemungut cukai untuk dibaptis dan mereka bertanya kepadanya: "Guru, apakah yang harus kami perbuat?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 13, 'Jawabnya: "Jangan menagih lebih banyak dari pada yang telah ditentukan bagimu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 14, 'Dan prajurit-prajurit bertanya juga kepadanya: "Dan kami, apakah yang harus kami perbuat?" Jawab Yohanes kepada mereka: "Jangan merampas dan jangan memeras dan cukupkanlah dirimu dengan gajimu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 15, 'Tetapi karena orang banyak sedang menanti dan berharap, dan semuanya bertanya dalam hatinya tentang Yohanes, kalau-kalau ia adalah Mesias,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 16, 'Yohanes menjawab dan berkata kepada semua orang itu: "Aku membaptis kamu dengan air, tetapi Ia yang lebih berkuasa dari padaku akan datang dan membuka tali kasut-Nyapun aku tidak layak. Ia akan membaptis kamu dengan Roh Kudus dan dengan api.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 17, 'Alat penampi sudah di tangan-Nya untuk membersihkan tempat pengirikan-Nya dan untuk mengumpulkan gandum-Nya ke dalam lumbung-Nya, tetapi debu jerami itu akan dibakar-Nya dalam api yang tidak terpadamkan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 18, 'Dengan banyak nasihat lain Yohanes memberitakan Injil kepada orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 19, 'Akan tetapi setelah ia menegor raja wilayah Herodes karena peristiwa Herodias, isteri saudaranya, dan karena segala kejahatan lain yang dilakukannya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 20, 'raja itu menambah kejahatannya dengan memasukkan Yohanes ke dalam penjara.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 21, 'Ketika seluruh orang banyak itu telah dibaptis dan ketika Yesus juga dibaptis dan sedang berdoa, terbukalah langit', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 22, 'dan turunlah Roh Kudus dalam rupa burung merpati ke atas-Nya. Dan terdengarlah suara dari langit: "Engkaulah Anak-Ku yang Kukasihi, kepada-Mulah Aku berkenan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 23, 'Ketika Yesus memulai pekerjaan-Nya, Ia berumur kira-kira tiga puluh tahun dan menurut anggapan orang, Ia adalah anak Yusuf, anak Eli,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 24, 'anak Matat, anak Lewi, anak Malkhi, anak Yanai, anak Yusuf,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 25, 'anak Matica, anak Amos, anak Nahum, anak Hesli, anak Nagai,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 26, 'anak Maat, anak Matica, anak Simei, anak Yosekh, anak Yoda,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 27, 'anak Yohanan, anak Resa, anak Zerubabel, anak Sealtiel, anak Neri,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 28, 'anak Malkhi, anak Adi, anak Kosam, anak Elmadam, anak Er,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 29, 'anak Yesua, anak Eliezer, anak Yorim, anak Matat, anak Lewi,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 30, 'anak Simeon, anak Yehuda, anak Yusuf, anak Yonam, anak Elyakim,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 31, 'anak Melea, anak Mina, anak Matata, anak Natan, anak Daud,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 32, 'anak Isai, anak Obed, anak Boas, anak Salmon, anak Nahason,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 33, 'anak Aminadab, anak Admin, anak Arni, anak Hezron, anak Peres, anak Yehuda,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 34, 'anak Yakub, anak Ishak, anak Abraham, anak Terah, anak Nahor,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 35, 'anak Serug, anak Rehu, anak Peleg, anak Eber, anak Salmon,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 36, 'anak Kenan, anak Arpakhsad, anak Sem, anak Nuh, anak Lamekh,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 37, 'anak Metusalah, anak Henokh, anak Yared, anak Mahalaleel, anak Kenan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 3, 38, 'anak Enos, anak Set, anak Adam, anak Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 1, 'Yesus, yang penuh dengan Roh Kudus, kembali dari sungai Yordan, lalu dibawa oleh Roh Kudus ke padang gurun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 2, 'Di situ Ia tinggal empat puluh hari lamanya dan dicobai Iblis. Selama di situ Ia tidak makan apa-apa dan sesudah waktu itu Ia lapar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 3, 'Lalu berkatalah Iblis kepada-Nya: "Jika Engkau Anak Allah, suruhlah batu ini menjadi roti."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 4, 'Jawab Yesus kepadanya: "Ada tertulis: Manusia hidup bukan dari roti saja."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 5, 'Kemudian ia membawa Yesus ke suatu tempat yang tinggi dan dalam sekejap mata ia memperlihatkan kepada-Nya semua kerajaan dunia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 6, 'Kata Iblis kepada-Nya: "Segala kuasa itu serta kemuliaannya akan kuberikan kepada-Mu, sebab semuanya itu telah diserahkan kepadaku dan aku memberikannya kepada siapa saja yang kukehendaki.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 7, 'Jadi jikalau Engkau menyembah aku, seluruhnya itu akan menjadi milik-Mu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 8, 'Tetapi Yesus berkata kepadanya: "Ada tertulis: Engkau harus menyembah Tuhan, Allahmu, dan hanya kepada Dia sajalah engkau berbakti!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 9, 'Kemudian ia membawa Yesus ke Yerusalem dan menempatkan Dia di bubungan Bait Allah, lalu berkata kepada-Nya: "Jika Engkau Anak Allah, jatuhkanlah diri-Mu dari sini ke bawah,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 10, 'sebab ada tertulis: Mengenai Engkau, Ia akan memerintahkan malaikat-malaikat-Nya untuk melindungi Engkau,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 11, 'dan mereka akan menatang Engkau di atas tangannya, supaya kaki-Mu jangan terantuk kepada batu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 12, 'Yesus menjawabnya, kata-Nya: "Ada firman: Jangan engkau mencobai Tuhan, Allahmu!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 13, 'Sesudah Iblis mengakhiri semua pencobaan itu, ia mundur dari pada-Nya dan menunggu waktu yang baik.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 14, 'Dalam kuasa Roh kembalilah Yesus ke Galilea. Dan tersiarlah kabar tentang Dia di seluruh daerah itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 15, 'Sementara itu Ia mengajar di rumah-rumah ibadat di situ dan semua orang memuji Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 16, 'Ia datang ke Nazaret tempat Ia dibesarkan, dan menurut kebiasaan-Nya pada hari Sabat Ia masuk ke rumah ibadat, lalu berdiri hendak membaca dari Alkitab.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 17, 'Kepada-Nya diberikan kitab nabi Yesaya dan setelah dibuka-Nya, Ia menemukan nas, di mana ada tertulis:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 18, '"Roh Tuhan ada pada-Ku, oleh sebab Ia telah mengurapi Aku, untuk menyampaikan kabar baik kepada orang-orang miskin; dan Ia telah mengutus Aku', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 19, 'untuk memberitakan pembebasan kepada orang-orang tawanan, dan penglihatan bagi orang-orang buta, untuk membebaskan orang-orang yang tertindas, untuk memberitakan tahun rahmat Tuhan telah datang."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 20, 'Kemudian Ia menutup kitab itu, memberikannya kembali kepada pejabat, lalu duduk; dan mata semua orang dalam rumah ibadat itu tertuju kepada-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 21, 'Lalu Ia memulai mengajar mereka, kata-Nya: "Pada hari ini genaplah nas ini sewaktu kamu mendengarnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 22, 'Dan semua orang itu membenarkan Dia dan mereka heran akan kata-kata yang indah yang diucapkan-Nya, lalu kata mereka: "Bukankah Ia ini anak Yusuf?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 23, 'Maka berkatalah Ia kepada mereka: "Tentu kamu akan mengatakan pepatah ini kepada-Ku: Hai tabib, sembuhkanlah diri-Mu sendiri. Perbuatlah di sini juga, di tempat asal-Mu ini, segala yang kami dengar yang telah terjadi di Kapernaum!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 24, 'Dan kata-Nya lagi: "Aku berkata kepadamu, sesungguhnya tidak ada nabi yang dihargai di tempat asalnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 25, 'Dan Aku berkata kepadamu, dan kata-Ku ini benar: Pada zaman Elia terdapat banyak perempuan janda di Israel ketika langit tertutup selama tiga tahun dan enam bulan dan ketika bahaya kelaparan yang hebat menimpa seluruh negeri.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 26, 'Tetapi Elia diutus bukan kepada salah seorang dari mereka, melainkan kepada seorang perempuan janda di Sarfat, di tanah Sidon.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 27, 'Dan pada zaman nabi Elisa banyak orang kusta di Israel dan tidak ada seorangpun dari mereka yang ditahirkan, selain dari pada Naaman, orang Siria itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 28, 'Mendengar itu sangat marahlah semua orang yang di rumah ibadat itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 29, 'Mereka bangun, lalu menghalau Yesus ke luar kota dan membawa Dia ke tebing gunung, tempat kota itu terletak, untuk melemparkan Dia dari tebing itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 30, 'Tetapi Ia berjalan lewat dari tengah-tengah mereka, lalu pergi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 31, 'Kemudian Yesus pergi ke Kapernaum, sebuah kota di Galilea, lalu mengajar di situ pada hari-hari Sabat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 32, 'Mereka takjub mendengar pengajaran-Nya, sebab perkataan-Nya penuh kuasa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 33, 'Di dalam rumah ibadat itu ada seorang yang kerasukan setan dan ia berteriak dengan suara keras:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 34, '"Hai Engkau, Yesus orang Nazaret, apa urusan-Mu dengan kami? Engkau datang hendak membinasakan kami? Aku tahu siapa Engkau: Yang Kudus dari Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 35, 'Tetapi Yesus menghardiknya, kata-Nya: "Diam, keluarlah dari padanya!" Dan setan itupun menghempaskan orang itu ke tengah-tengah orang banyak, lalu keluar dari padanya dan sama sekali tidak menyakitinya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 36, 'Dan semua orang takjub, lalu berkata seorang kepada yang lain, katanya: "Alangkah hebatnya perkataan ini! Sebab dengan penuh wibawa dan kuasa Ia memberi perintah kepada roh-roh jahat dan merekapun keluar."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 37, 'Dan tersebarlah berita tentang Dia ke mana-mana di daerah itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 38, 'Kemudian Ia meninggalkan rumah ibadat itu dan pergi ke rumah Simon. Adapun ibu mertua Simon demam keras dan mereka meminta kepada Yesus supaya menolong dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 39, 'Maka Ia berdiri di sisi perempuan itu, lalu menghardik demam itu, dan penyakit itupun meninggalkan dia. Perempuan itu segera bangun dan melayani mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 40, 'Ketika matahari terbenam, semua orang membawa kepada-Nya orang-orang sakitnya, yang menderita bermacam-macam penyakit. Iapun meletakkan tangan-Nya atas mereka masing-masing dan menyembuhkan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 41, 'Dari banyak orang keluar juga setan-setan sambil berteriak: "Engkau adalah Anak Allah." Lalu Ia dengan keras melarang mereka dan tidak memperbolehkan mereka berbicara, karena mereka tahu bahwa Ia adalah Mesias.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 42, 'Ketika hari siang, Yesus berangkat dan pergi ke suatu tempat yang sunyi. Tetapi orang banyak mencari Dia, lalu menemukan-Nya dan berusaha menahan Dia supaya jangan meninggalkan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 43, 'Tetapi Ia berkata kepada mereka: "Juga di kota-kota lain Aku harus memberitakan Injil Kerajaan Allah sebab untuk itulah Aku diutus."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 4, 44, 'Dan Ia memberitakan Injil dalam rumah-rumah ibadat di Yudea.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 1, 'Pada suatu kali Yesus berdiri di pantai danau Genesaret, sedang orang banyak mengerumuni Dia hendak mendengarkan firman Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 2, 'Ia melihat dua perahu di tepi pantai. Nelayan-nelayannya telah turun dan sedang membasuh jalanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 3, 'Ia naik ke dalam salah satu perahu itu, yaitu perahu Simon, dan menyuruh dia supaya menolakkan perahunya sedikit jauh dari pantai. Lalu Ia duduk dan mengajar orang banyak dari atas perahu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 4, 'Setelah selesai berbicara, Ia berkata kepada Simon: "Bertolaklah ke tempat yang dalam dan tebarkanlah jalamu untuk menangkap ikan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 5, 'Simon menjawab: "Guru, telah sepanjang malam kami bekerja keras dan kami tidak menangkap apa-apa, tetapi karena Engkau menyuruhnya, aku akan menebarkan jala juga."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 6, 'Dan setelah mereka melakukannya, mereka menangkap sejumlah besar ikan, sehingga jala mereka mulai koyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 7, 'Lalu mereka memberi isyarat kepada teman-temannya di perahu yang lain supaya mereka datang membantunya. Dan mereka itu datang, lalu mereka bersama-sama mengisi kedua perahu itu dengan ikan hingga hampir tenggelam.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 8, 'Ketika Simon Petrus melihat hal itu iapun tersungkur di depan Yesus dan berkata: "Tuhan, pergilah dari padaku, karena aku ini seorang berdosa."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 9, 'Sebab ia dan semua orang yang bersama-sama dengan dia takjub oleh karena banyaknya ikan yang mereka tangkap;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 10, 'demikian juga Yakobus dan Yohanes, anak-anak Zebedeus, yang menjadi teman Simon. Kata Yesus kepada Simon: "Jangan takut, mulai dari sekarang engkau akan menjala manusia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 11, 'Dan sesudah mereka menghela perahu-perahunya ke darat, merekapun meninggalkan segala sesuatu, lalu mengikut Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 12, 'Pada suatu kali Yesus berada dalam sebuah kota. Di situ ada seorang yang penuh kusta. Ketika ia melihat Yesus, tersungkurlah ia dan memohon: "Tuan, jika Tuan mau, Tuan dapat mentahirkan aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 13, 'Lalu Yesus mengulurkan tangan-Nya, menjamah orang itu, dan berkata: "Aku mau, jadilah engkau tahir." Seketika itu juga lenyaplah penyakit kustanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 14, 'Yesus melarang orang itu memberitahukannya kepada siapapun juga dan berkata: "Pergilah, perlihatkanlah dirimu kepada imam dan persembahkanlah untuk pentahiranmu persembahan seperti yang diperintahkan Musa, sebagai bukti bagi mereka."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 15, 'Tetapi kabar tentang Yesus makin jauh tersiar dan datanglah orang banyak berbondong-bondong kepada-Nya untuk mendengar Dia dan untuk disembuhkan dari penyakit mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 16, 'Akan tetapi Ia mengundurkan diri ke tempat-tempat yang sunyi dan berdoa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 17, 'Pada suatu hari ketika Yesus mengajar, ada beberapa orang Farisi dan ahli Taurat duduk mendengarkan-Nya. Mereka datang dari semua desa di Galilea dan Yudea dan dari Yerusalem. Kuasa Tuhan menyertai Dia, sehingga Ia dapat menyembuhkan orang sakit.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 18, 'Lalu datanglah beberapa orang mengusung seorang lumpuh di atas tempat tidur; mereka berusaha membawa dia masuk dan meletakkannya di hadapan Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 19, 'Karena mereka tidak dapat membawanya masuk berhubung dengan banyaknya orang di situ, naiklah mereka ke atap rumah, lalu membongkar atap itu, dan menurunkan orang itu dengan tempat tidurnya ke tengah-tengah orang banyak tepat di depan Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 20, 'Ketika Yesus melihat iman mereka, berkatalah Ia: "Hai saudara, dosamu sudah diampuni."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 21, 'Tetapi ahli-ahli Taurat dan orang-orang Farisi berpikir dalam hatinya: "Siapakah orang yang menghujat Allah ini? Siapa yang dapat mengampuni dosa selain dari pada Allah sendiri?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 22, 'Akan tetapi Yesus mengetahui pikiran mereka, lalu berkata kepada mereka: "Apakah yang kamu pikirkan dalam hatimu?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 23, 'Manakah lebih mudah, mengatakan: Dosamu sudah diampuni, atau mengatakan: Bangunlah, dan berjalanlah?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 24, 'Tetapi supaya kamu tahu, bahwa di dunia ini Anak Manusia berkuasa mengampuni dosa" ?berkatalah Ia kepada orang lumpuh itu?:"Kepadamu Kukatakan, bangunlah, angkatlah tempat tidurmu dan pulanglah ke rumahmu!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 25, 'Dan seketika itu juga bangunlah ia, di depan mereka, lalu mengangkat tempat tidurnya dan pulang ke rumahnya sambil memuliakan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 26, 'Semua orang itu takjub, lalu memuliakan Allah, dan mereka sangat takut, katanya: "Hari ini kami telah menyaksikan hal-hal yang sangat mengherankan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 27, 'Kemudian, ketika Yesus pergi ke luar, Ia melihat seorang pemungut cukai, yang bernama Lewi, sedang duduk di rumah cukai. Yesus berkata kepadanya: "Ikutlah Aku!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 28, 'Maka berdirilah Lewi dan meninggalkan segala sesuatu, lalu mengikut Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 29, 'Dan Lewi mengadakan suatu perjamuan besar untuk Dia di rumahnya dan sejumlah besar pemungut cukai dan orang-orang lain turut makan bersama-sama dengan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 30, 'Orang-orang Farisi dan ahli-ahli Taurat bersungut-sungut kepada murid-murid Yesus, katanya: "Mengapa kamu makan dan minum bersama-sama dengan pemungut cukai dan orang berdosa?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 31, 'Lalu jawab Yesus kepada mereka, kata-Nya: "Bukan orang sehat yang memerlukan tabib, tetapi orang sakit;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 32, 'Aku datang bukan untuk memanggil orang benar, tetapi orang berdosa, supaya mereka bertobat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 33, 'Orang-orang Farisi itu berkata pula kepada Yesus: "Murid-murid Yohanes sering berpuasa dan sembahyang, demikian juga murid-murid orang Farisi, tetapi murid-murid-Mu makan dan minum."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 34, 'Jawab Yesus kepada mereka: "Dapatkah sahabat mempelai laki-laki disuruh berpuasa, sedang mempelai itu bersama mereka?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 35, 'Tetapi akan datang waktunya, apabila mempelai itu diambil dari mereka, pada waktu itulah mereka akan berpuasa."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 36, 'Ia mengatakan juga suatu perumpamaan kepada mereka: "Tidak seorangpun mengoyakkan secarik kain dari baju yang baru untuk menambalkannya pada baju yang tua. Jika demikian, yang baru itu juga akan koyak dan pada yang tua itu tidak akan cocok kain penambal yang dikoyakkan dari yang baru itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 37, 'Demikian juga tidak seorangpun mengisikan anggur yang baru ke dalam kantong kulit yang tua, karena jika demikian, anggur yang baru itu akan mengoyakkan kantong itu dan anggur itu akan terbuang dan kantong itupun hancur.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 38, 'Tetapi anggur yang baru harus disimpan dalam kantong yang baru pula.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 5, 39, 'Dan tidak seorangpun yang telah minum anggur tua ingin minum anggur yang baru, sebab ia akan berkata: Anggur yang tua itu baik."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 1, 'Pada suatu hari Sabat, ketika Yesus berjalan di ladang gandum, murid-murid-Nya memetik bulir gandum dan memakannya, sementara mereka menggisarnya dengan tangannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 2, 'Tetapi beberapa orang Farisi berkata: "Mengapa kamu berbuat sesuatu yang tidak diperbolehkan pada hari Sabat?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 3, 'Lalu Yesus menjawab mereka: "Tidakkah kamu baca apa yang dilakukan oleh Daud, ketika ia dan mereka yang mengikutinya lapar,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 4, 'bagaimana ia masuk ke dalam Rumah Allah dan mengambil roti sajian, lalu memakannya dan memberikannya kepada pengikut-pengikutnya, padahal roti itu tidak boleh dimakan kecuali oleh imam-imam?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 5, 'Kata Yesus lagi kepada mereka: "Anak Manusia adalah Tuhan atas hari Sabat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 6, 'Pada suatu hari Sabat lain, Yesus masuk ke rumah ibadat, lalu mengajar. Di situ ada seorang yang mati tangan kanannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 7, 'Ahli-ahli Taurat dan orang-orang Farisi mengamat-amati Yesus, kalau-kalau Ia menyembuhkan orang pada hari Sabat, supaya mereka dapat alasan untuk mempersalahkan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 8, 'Tetapi Ia mengetahui pikiran mereka, lalu berkata kepada orang yang mati tangannya itu: "Bangunlah dan berdirilah di tengah!" Maka bangunlah orang itu dan berdiri.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 9, 'Lalu Yesus berkata kepada mereka: "Aku bertanya kepada kamu: Manakah yang diperbolehkan pada hari Sabat, berbuat baik atau berbuat jahat, menyelamatkan nyawa orang atau membinasakannya?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 10, 'Sesudah itu Ia memandang keliling kepada mereka semua, lalu berkata kepada orang sakit itu: "Ulurkanlah tanganmu!" Orang itu berbuat demikian dan sembuhlah tangannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 11, 'Maka meluaplah amarah mereka, lalu mereka berunding, apakah yang akan mereka lakukan terhadap Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 12, 'Pada waktu itu pergilah Yesus ke bukit untuk berdoa dan semalam-malaman Ia berdoa kepada Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 13, 'Ketika hari siang, Ia memanggil murid-murid-Nya kepada-Nya, lalu memilih dari antara mereka dua belas orang, yang disebut-Nya rasul:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 14, 'Simon yang juga diberi-Nya nama Petrus, dan Andreas saudara Simon, Yakobus dan Yohanes, Filipus dan Bartolomeus,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 15, 'Matius dan Tomas, Yakobus anak Alfeus, dan Simon yang disebut orang Zelot,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 16, 'Yudas anak Yakobus, dan Yudas Iskariot yang kemudian menjadi pengkhianat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 17, 'Lalu Ia turun dengan mereka dan berhenti pada suatu tempat yang datar: di situ berkumpul sejumlah besar dari murid-murid-Nya dan banyak orang lain yang datang dari seluruh Yudea dan dari Yerusalem dan dari daerah pantai Tirus dan Sidon.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 18, 'Mereka datang untuk mendengarkan Dia dan untuk disembuhkan dari penyakit mereka; juga mereka yang dirasuk oleh roh-roh jahat beroleh kesembuhan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 19, 'Dan semua orang banyak itu berusaha menjamah Dia, karena ada kuasa yang keluar dari pada-Nya dan semua orang itu disembuhkan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 20, 'Lalu Yesus memandang murid-murid-Nya dan berkata: "Berbahagialah, hai kamu yang miskin, karena kamulah yang empunya Kerajaan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 21, 'Berbahagialah, hai kamu yang sekarang ini lapar, karena kamu akan dipuaskan. Berbahagialah, hai kamu yang sekarang ini menangis, karena kamu akan tertawa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 22, 'Berbahagialah kamu, jika karena Anak Manusia orang membenci kamu, dan jika mereka mengucilkan kamu, dan mencela kamu serta menolak namamu sebagai sesuatu yang jahat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 23, 'Bersukacitalah pada waktu itu dan bergembiralah, sebab sesungguhnya, upahmu besar di sorga; karena secara demikian juga nenek moyang mereka telah memperlakukan para nabi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 24, 'Tetapi celakalah kamu, hai kamu yang kaya, karena dalam kekayaanmu kamu telah memperoleh penghiburanmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 25, 'Celakalah kamu, yang sekarang ini kenyang, karena kamu akan lapar. Celakalah kamu, yang sekarang ini tertawa, karena kamu akan berdukacita dan menangis.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 26, 'Celakalah kamu, jika semua orang memuji kamu; karena secara demikian juga nenek moyang mereka telah memperlakukan nabi-nabi palsu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 27, '"Tetapi kepada kamu, yang mendengarkan Aku, Aku berkata: Kasihilah musuhmu, berbuatlah baik kepada orang yang membenci kamu;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 28, 'mintalah berkat bagi orang yang mengutuk kamu; berdoalah bagi orang yang mencaci kamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 29, 'Barangsiapa menampar pipimu yang satu, berikanlah juga kepadanya pipimu yang lain, dan barangsiapa yang mengambil jubahmu, biarkan juga ia mengambil bajumu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 30, 'Berilah kepada setiap orang yang meminta kepadamu; dan janganlah meminta kembali kepada orang yang mengambil kepunyaanmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 31, 'Dan sebagaimana kamu kehendaki supaya orang perbuat kepadamu, perbuatlah juga demikian kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 32, 'Dan jikalau kamu mengasihi orang yang mengasihi kamu, apakah jasamu? Karena orang-orang berdosapun mengasihi juga orang-orang yang mengasihi mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 33, 'Sebab jikalau kamu berbuat baik kepada orang yang berbuat baik kepada kamu, apakah jasamu? Orang-orang berdosapun berbuat demikian.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 34, 'Dan jikalau kamu meminjamkan sesuatu kepada orang, karena kamu berharap akan menerima sesuatu dari padanya, apakah jasamu? Orang-orang berdosapun meminjamkan kepada orang-orang berdosa, supaya mereka menerima kembali sama banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 35, 'Tetapi kamu, kasihilah musuhmu dan berbuatlah baik kepada mereka dan pinjamkan dengan tidak mengharapkan balasan, maka upahmu akan besar dan kamu akan menjadi anak-anak Allah Yang Mahatinggi, sebab Ia baik terhadap orang-orang yang tidak tahu berterima kasih dan terhadap orang-orang jahat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 36, 'Hendaklah kamu murah hati, sama seperti Bapamu adalah murah hati."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 37, '"Janganlah kamu menghakimi, maka kamupun tidak akan dihakimi. Dan janganlah kamu menghukum, maka kamupun tidak akan dihukum; ampunilah dan kamu akan diampuni.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 38, 'Berilah dan kamu akan diberi: suatu takaran yang baik, yang dipadatkan, yang digoncang dan yang tumpah ke luar akan dicurahkan ke dalam ribaanmu. Sebab ukuran yang kamu pakai untuk mengukur, akan diukurkan kepadamu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 39, 'Yesus mengatakan pula suatu perumpamaan kepada mereka: "Dapatkah orang buta menuntun orang buta? Bukankah keduanya akan jatuh ke dalam lobang?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 40, 'Seorang murid tidak lebih dari pada gurunya, tetapi barangsiapa yang telah tamat pelajarannya akan sama dengan gurunya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 41, 'Mengapakah engkau melihat selumbar di dalam mata saudaramu, sedangkan balok di dalam matamu sendiri tidak engkau ketahui?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 42, 'Bagaimanakah engkau dapat berkata kepada saudaramu: Saudara, biarlah aku mengeluarkan selumbar yang ada di dalam matamu, padahal balok yang di dalam matamu tidak engkau lihat? Hai orang munafik, keluarkanlah dahulu balok dari matamu, maka engkau akan melihat dengan jelas untuk mengeluarkan selumbar itu dari mata saudaramu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 43, '"Karena tidak ada pohon yang baik yang menghasilkan buah yang tidak baik, dan juga tidak ada pohon yang tidak baik yang menghasilkan buah yang baik.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 44, 'Sebab setiap pohon dikenal pada buahnya. Karena dari semak duri orang tidak memetik buah ara dan dari duri-duri tidak memetik buah anggur.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 45, 'Orang yang baik mengeluarkan barang yang baik dari perbendaharaan hatinya yang baik dan orang yang jahat mengeluarkan barang yang jahat dari perbendaharaannya yang jahat. Karena yang diucapkan mulutnya, meluap dari hatinya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 46, '"Mengapa kamu berseru kepada-Ku: Tuhan, Tuhan, padahal kamu tidak melakukan apa yang Aku katakan?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 47, 'Setiap orang yang datang kepada-Ku dan mendengarkan perkataan-Ku serta melakukannya?Aku akan menyatakan kepadamu dengan siapa ia dapat disamakan?,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 48, 'ia sama dengan seorang yang mendirikan rumah: Orang itu menggali dalam-dalam dan meletakkan dasarnya di atas batu. Ketika datang air bah dan banjir melanda rumah itu, rumah itu tidak dapat digoyahkan, karena rumah itu kokoh dibangun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 6, 49, 'Akan tetapi barangsiapa mendengar perkataan-Ku, tetapi tidak melakukannya, ia sama dengan seorang yang mendirikan rumah di atas tanah tanpa dasar. Ketika banjir melandanya, rumah itu segera rubuh dan hebatlah kerusakannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 1, 'Setelah Yesus selesai berbicara di depan orang banyak, masuklah Ia ke Kapernaum.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 2, 'Di situ ada seorang perwira yang mempunyai seorang hamba, yang sangat dihargainya. Hamba itu sedang sakit keras dan hampir mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 3, 'Ketika perwira itu mendengar tentang Yesus, ia menyuruh beberapa orang tua-tua Yahudi kepada-Nya untuk meminta, supaya Ia datang dan menyembuhkan hambanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 4, 'Mereka datang kepada Yesus dan dengan sangat mereka meminta pertolongan-Nya, katanya: "Ia layak Engkau tolong,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 5, 'sebab ia mengasihi bangsa kita dan dialah yang menanggung pembangunan rumah ibadat kami."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 6, 'Lalu Yesus pergi bersama-sama dengan mereka. Ketika Ia tidak jauh lagi dari rumah perwira itu, perwira itu menyuruh sahabat-sahabatnya untuk mengatakan kepada-Nya: "Tuan, janganlah bersusah-susah, sebab aku tidak layak menerima Tuan di dalam rumahku;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 7, 'sebab itu aku juga menganggap diriku tidak layak untuk datang kepada-Mu. Tetapi katakan saja sepatah kata, maka hambaku itu akan sembuh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 8, 'Sebab aku sendiri seorang bawahan, dan di bawahku ada pula prajurit. Jika aku berkata kepada salah seorang prajurit itu: Pergi!, maka ia pergi, dan kepada seorang lagi: Datang!, maka ia datang, ataupun kepada hambaku: Kerjakanlah ini!, maka ia mengerjakannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 9, 'Setelah Yesus mendengar perkataan itu, Ia heran akan dia, dan sambil berpaling kepada orang banyak yang mengikuti Dia, Ia berkata: "Aku berkata kepadamu, iman sebesar ini tidak pernah Aku jumpai, sekalipun di antara orang Israel!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 10, 'Dan setelah orang-orang yang disuruh itu kembali ke rumah, didapatinyalah hamba itu telah sehat kembali.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 11, 'Kemudian Yesus pergi ke suatu kota yang bernama Nain. Murid-murid-Nya pergi bersama-sama dengan Dia, dan juga orang banyak menyertai-Nya berbondong-bondong.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 12, 'Setelah Ia dekat pintu gerbang kota, ada orang mati diusung ke luar, anak laki-laki, anak tunggal ibunya yang sudah janda, dan banyak orang dari kota itu menyertai janda itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 13, 'Dan ketika Tuhan melihat janda itu, tergeraklah hati-Nya oleh belas kasihan, lalu Ia berkata kepadanya: "Jangan menangis!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 14, 'Sambil menghampiri usungan itu Ia menyentuhnya, dan sedang para pengusung berhenti, Ia berkata: "Hai anak muda, Aku berkata kepadamu, bangkitlah!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 15, 'Maka bangunlah orang itu dan duduk dan mulai berkata-kata, dan Yesus menyerahkannya kepada ibunya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 16, 'Semua orang itu ketakutan dan mereka memuliakan Allah, sambil berkata: "Seorang nabi besar telah muncul di tengah-tengah kita," dan "Allah telah melawat umat-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 17, 'Maka tersiarlah kabar tentang Yesus di seluruh Yudea dan di seluruh daerah sekitarnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 18, 'Ketika Yohanes mendapat kabar tentang segala peristiwa itu dari murid-muridnya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 19, 'ia memanggil dua orang dari antaranya dan menyuruh mereka bertanya kepada Tuhan: "Engkaukah yang akan datang itu atau haruskah kami menantikan seorang lain?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 20, 'Ketika kedua orang itu sampai kepada Yesus, mereka berkata: "Yohanes Pembaptis menyuruh kami bertanya kepada-Mu: Engkaukah yang akan datang itu atau haruskah kami menantikan seorang lain?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 21, 'Pada saat itu Yesus menyembuhkan banyak orang dari segala penyakit dan penderitaan dan dari roh-roh jahat, dan Ia mengaruniakan penglihatan kepada banyak orang buta.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 22, 'Dan Yesus menjawab mereka: "Pergilah, dan katakanlah kepada Yohanes apa yang kamu lihat dan kamu dengar: Orang buta melihat, orang lumpuh berjalan, orang kusta menjadi tahir, orang tuli mendengar, orang mati dibangkitkan dan kepada orang miskin diberitakan kabar baik.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 23, 'Dan berbahagialah orang yang tidak menjadi kecewa dan menolak Aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 24, 'Setelah suruhan Yohanes itu pergi, mulailah Yesus berbicara kepada orang banyak itu tentang Yohanes: "Untuk apakah kamu pergi ke padang gurun? Melihat buluh yang digoyangkan angin kian ke mari?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 25, 'Atau untuk apakah kamu pergi? Melihat orang yang berpakaian halus? Orang yang berpakaian indah dan yang hidup mewah, tempatnya di istana raja.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 26, 'Jadi untuk apakah kamu pergi? Melihat nabi? Benar, dan Aku berkata kepadamu, bahkan lebih dari pada nabi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 27, 'Karena tentang dia ada tertulis: Lihatlah, Aku menyuruh utusan-Ku mendahului Engkau, ia akan mempersiapkan jalan-Mu di hadapan-Mu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 28, 'Aku berkata kepadamu: Di antara mereka yang dilahirkan oleh perempuan tidak ada seorangpun yang lebih besar dari pada Yohanes, namun yang terkecil dalam Kerajaan Allah lebih besar dari padanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 29, 'Seluruh orang banyak yang mendengar perkataan-Nya, termasuk para pemungut cukai, mengakui kebenaran Allah, karena mereka telah memberi diri dibaptis oleh Yohanes.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 30, 'Tetapi orang-orang Farisi dan ahli-ahli Taurat menolak maksud Allah terhadap diri mereka, karena mereka tidak mau dibaptis oleh Yohanes.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 31, 'Kata Yesus: "Dengan apakah akan Kuumpamakan orang-orang dari angkatan ini dan dengan apakah mereka itu sama?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 32, 'Mereka itu seumpama anak-anak yang duduk di pasar dan yang saling menyerukan: Kami meniup seruling bagimu, tetapi kamu tidak menari, kami menyanyikan kidung duka, tetapi kamu tidak menangis.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 33, 'Karena Yohanes Pembaptis datang, ia tidak makan roti dan tidak minum anggur, dan kamu berkata: Ia kerasukan setan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 34, 'Kemudian Anak Manusia datang, Ia makan dan minum, dan kamu berkata: Lihatlah, Ia seorang pelahap dan peminum, sahabat pemungut cukai dan orang berdosa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 35, 'Tetapi hikmat dibenarkan oleh semua orang yang menerimanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 36, 'Seorang Farisi mengundang Yesus untuk datang makan di rumahnya. Yesus datang ke rumah orang Farisi itu, lalu duduk makan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 37, 'Di kota itu ada seorang perempuan yang terkenal sebagai seorang berdosa. Ketika perempuan itu mendengar, bahwa Yesus sedang makan di rumah orang Farisi itu, datanglah ia membawa sebuah buli-buli pualam berisi minyak wangi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 38, 'Sambil menangis ia pergi berdiri di belakang Yesus dekat kaki-Nya, lalu membasahi kaki-Nya itu dengan air matanya dan menyekanya dengan rambutnya, kemudian ia mencium kaki-Nya dan meminyakinya dengan minyak wangi itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 39, 'Ketika orang Farisi yang mengundang Yesus melihat hal itu, ia berkata dalam hatinya: "Jika Ia ini nabi, tentu Ia tahu, siapakah dan orang apakah perempuan yang menjamah-Nya ini; tentu Ia tahu, bahwa perempuan itu adalah seorang berdosa."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 40, 'Lalu Yesus berkata kepadanya: "Simon, ada yang hendak Kukatakan kepadamu." Sahut Simon: "Katakanlah, Guru."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 41, '"Ada dua orang yang berhutang kepada seorang pelepas uang. Yang seorang berhutang lima ratus dinar, yang lain lima puluh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 42, 'Karena mereka tidak sanggup membayar, maka ia menghapuskan hutang kedua orang itu. Siapakah di antara mereka yang akan terlebih mengasihi dia?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 43, 'Jawab Simon: "Aku kira dia yang paling banyak dihapuskan hutangnya." Kata Yesus kepadanya: "Betul pendapatmu itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 44, 'Dan sambil berpaling kepada perempuan itu, Ia berkata kepada Simon: "Engkau lihat perempuan ini? Aku masuk ke rumahmu, namun engkau tidak memberikan Aku air untuk membasuh kaki-Ku, tetapi dia membasahi kaki-Ku dengan air mata dan menyekanya dengan rambutnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 45, 'Engkau tidak mencium Aku, tetapi sejak Aku masuk ia tiada henti-hentinya mencium kaki-Ku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 46, 'Engkau tidak meminyaki kepala-Ku dengan minyak, tetapi dia meminyaki kaki-Ku dengan minyak wangi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 47, 'Sebab itu Aku berkata kepadamu: Dosanya yang banyak itu telah diampuni, sebab ia telah banyak berbuat kasih. Tetapi orang yang sedikit diampuni, sedikit juga ia berbuat kasih."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 48, 'Lalu Ia berkata kepada perempuan itu: "Dosamu telah diampuni."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 49, 'Dan mereka, yang duduk makan bersama Dia, berpikir dalam hati mereka: "Siapakah Ia ini, sehingga Ia dapat mengampuni dosa?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 7, 50, 'Tetapi Yesus berkata kepada perempuan itu: "Imanmu telah menyelamatkan engkau, pergilah dengan selamat!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 1, 'Tidak lama sesudah itu Yesus berjalan berkeliling dari kota ke kota dan dari desa ke desa memberitakan Injil Kerajaan Allah. Kedua belas murid-Nya bersama-sama dengan Dia,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 2, 'dan juga beberapa orang perempuan yang telah disembuhkan dari roh-roh jahat atau berbagai penyakit, yaitu Maria yang disebut Magdalena, yang telah dibebaskan dari tujuh roh jahat,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 3, 'Yohana isteri Khuza bendahara Herodes, Susana dan banyak perempuan lain. Perempuan-perempuan ini melayani rombongan itu dengan kekayaan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 4, 'Ketika orang banyak berbondong-bondong datang, yaitu orang-orang yang dari kota ke kota menggabungkan diri pada Yesus, berkatalah Ia dalam suatu perumpamaan:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 5, '"Adalah seorang penabur keluar untuk menaburkan benihnya. Pada waktu ia menabur, sebagian benih itu jatuh di pinggir jalan, lalu diinjak orang dan burung-burung di udara memakannya sampai habis.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 6, 'Sebagian jatuh di tanah yang berbatu-batu, dan setelah tumbuh ia menjadi kering karena tidak mendapat air.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 7, 'Sebagian lagi jatuh di tengah semak duri, dan semak itu tumbuh bersama-sama dan menghimpitnya sampai mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 8, 'Dan sebagian jatuh di tanah yang baik, dan setelah tumbuh berbuah seratus kali lipat." Setelah berkata demikian Yesus berseru: "Siapa mempunyai telinga untuk mendengar, hendaklah ia mendengar!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 9, 'Murid-murid-Nya bertanya kepada-Nya, apa maksud perumpamaan itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 10, 'Lalu Ia menjawab: "Kepadamu diberi karunia untuk mengetahui rahasia Kerajaan Allah, tetapi kepada orang-orang lain hal itu diberitakan dalam perumpamaan, supaya sekalipun memandang, mereka tidak melihat dan sekalipun mendengar, mereka tidak mengerti.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 11, 'Inilah arti perumpamaan itu: Benih itu ialah firman Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 12, 'Yang jatuh di pinggir jalan itu ialah orang yang telah mendengarnya; kemudian datanglah Iblis lalu mengambil firman itu dari dalam hati mereka, supaya mereka jangan percaya dan diselamatkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 13, 'Yang jatuh di tanah yang berbatu-batu itu ialah orang, yang setelah mendengar firman itu, menerimanya dengan gembira, tetapi mereka itu tidak berakar, mereka percaya sebentar saja dan dalam masa pencobaan mereka murtad.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 14, 'Yang jatuh dalam semak duri ialah orang yang telah mendengar firman itu, dan dalam pertumbuhan selanjutnya mereka terhimpit oleh kekuatiran dan kekayaan dan kenikmatan hidup, sehingga mereka tidak menghasilkan buah yang matang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 15, 'Yang jatuh di tanah yang baik itu ialah orang, yang setelah mendengar firman itu, menyimpannya dalam hati yang baik dan mengeluarkan buah dalam ketekunan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 16, '"Tidak ada orang yang menyalakan pelita lalu menutupinya dengan tempayan atau menempatkannya di bawah tempat tidur, tetapi ia menempatkannya di atas kaki dian, supaya semua orang yang masuk ke dalam rumah dapat melihat cahayanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 17, 'Sebab tidak ada sesuatu yang tersembunyi yang tidak akan dinyatakan, dan tidak ada sesuatu yang rahasia yang tidak akan diketahui dan diumumkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 18, 'Karena itu, perhatikanlah cara kamu mendengar. Karena siapa yang mempunyai, kepadanya akan diberi, tetapi siapa yang tidak mempunyai, dari padanya akan diambil, juga apa yang ia anggap ada padanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 19, 'Ibu dan saudara-saudara Yesus datang kepada-Nya, tetapi mereka tidak dapat mencapai Dia karena orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 20, 'Orang memberitahukan kepada-Nya: "Ibu-Mu dan saudara-saudara-Mu ada di luar dan ingin bertemu dengan Engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 21, 'Tetapi Ia menjawab mereka: "Ibu-Ku dan saudara-saudara-Ku ialah mereka, yang mendengarkan firman Allah dan melakukannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 22, 'Pada suatu hari Yesus naik ke dalam perahu bersama-sama dengan murid-murid-Nya, dan Ia berkata kepada mereka: "Marilah kita bertolak ke seberang danau." Lalu bertolaklah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 23, 'Dan ketika mereka sedang berlayar, Yesus tertidur. Sekonyong-konyong turunlah taufan ke danau, sehingga perahu itu kemasukan air dan mereka berada dalam bahaya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 24, 'Maka datanglah murid-murid-Nya membangunkan Dia, katanya: "Guru, Guru, kita binasa!" Iapun bangun, lalu menghardik angin dan air yang mengamuk itu. Dan angin dan air itupun reda dan danau itu menjadi teduh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 25, 'Lalu kata-Nya kepada mereka: "Di manakah kepercayaanmu?" Maka takutlah mereka dan heran, lalu berkata seorang kepada yang lain: "Siapa gerangan orang ini, sehingga Ia memberi perintah kepada angin dan air dan mereka taat kepada-Nya?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 26, 'Lalu mendaratlah Yesus dan murid-murid-Nya di tanah orang Gerasa yang terletak di seberang Galilea.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 27, 'Setelah Yesus naik ke darat, datanglah seorang laki-laki dari kota itu menemui Dia; orang itu dirasuki oleh setan-setan dan sudah lama ia tidak berpakaian dan tidak tinggal dalam rumah, tetapi dalam pekuburan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 28, 'Ketika ia melihat Yesus, ia berteriak lalu tersungkur di hadapan-Nya dan berkata dengan suara keras: "Apa urusan-Mu dengan aku, hai Yesus Anak Allah Yang Mahatinggi? Aku memohon kepada-Mu, supaya Engkau jangan menyiksa aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 29, 'Ia berkata demikian sebab Yesus memerintahkan roh jahat itu keluar dari orang itu. Karena sering roh itu menyeret-nyeret dia, maka untuk menjaganya, ia dirantai dan dibelenggu, tetapi ia memutuskan segala pengikat itu dan ia dihalau oleh setan itu ke tempat-tempat yang sunyi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 30, 'Dan Yesus bertanya kepadanya: "Siapakah namamu?" Jawabnya: "Legion," karena ia kerasukan banyak setan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 31, 'Lalu setan-setan itu memohon kepada Yesus, supaya Ia jangan memerintahkan mereka masuk ke dalam jurang maut.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 32, 'Adalah di sana sejumlah besar babi sedang mencari makan di lereng gunung, lalu setan-setan itu meminta kepada Yesus, supaya Ia memperkenankan mereka memasuki babi-babi itu. Yesus mengabulkan permintaan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 33, 'Lalu keluarlah setan-setan itu dari orang itu dan memasuki babi-babi itu. Kawanan babi itu terjun dari tepi jurang ke dalam danau lalu mati lemas.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 34, 'Setelah penjaga-penjaga babi itu melihat apa yang telah terjadi, mereka lari lalu menceritakan hal itu di kota dan di kampung-kampung sekitarnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 35, 'Dan keluarlah orang-orang untuk melihat apa yang telah terjadi. Mereka datang kepada Yesus dan mereka menjumpai orang yang telah ditinggalkan setan-setan itu duduk di kaki Yesus; ia telah berpakaian dan sudah waras. Maka takutlah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 36, 'Orang-orang yang telah melihat sendiri hal itu memberitahukan kepada mereka, bagaimana orang yang dirasuk setan itu telah diselamatkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 37, 'Lalu seluruh penduduk daerah Gerasa meminta kepada Yesus, supaya Ia meninggalkan mereka, sebab mereka sangat ketakutan. Maka naiklah Ia ke dalam perahu, lalu berlayar kembali.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 38, 'Dan orang yang telah ditinggalkan setan-setan itu meminta supaya ia diperkenankan menyertai-Nya. Tetapi Yesus menyuruh dia pergi, kata-Nya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 39, '"Pulanglah ke rumahmu dan ceriterakanlah segala sesuatu yang telah diperbuat Allah atasmu." Orang itupun pergi mengelilingi seluruh kota dan memberitahukan segala apa yang telah diperbuat Yesus atas dirinya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 40, 'Ketika Yesus kembali, orang banyak menyambut Dia sebab mereka semua menanti-nantikan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 41, 'Maka datanglah seorang yang bernama Yairus. Ia adalah kepala rumah ibadat. Sambil tersungkur di depan kaki Yesus ia memohon kepada-Nya, supaya Yesus datang ke rumahnya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 42, 'karena anaknya perempuan yang satu-satunya, yang berumur kira-kira dua belas tahun, hampir mati. Dalam perjalanan ke situ Yesus didesak-desak orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 43, 'Adalah seorang perempuan yang sudah dua belas tahun menderita pendarahan dan yang tidak berhasil disembuhkan oleh siapapun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 44, 'Ia maju mendekati Yesus dari belakang dan menjamah jumbai jubah-Nya, dan seketika itu juga berhentilah pendarahannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 45, 'Lalu kata Yesus: "Siapa yang menjamah Aku?" Dan karena tidak ada yang mengakuinya, berkatalah Petrus: "Guru, orang banyak mengerumuni dan mendesak Engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 46, 'Tetapi Yesus berkata: "Ada seorang yang menjamah Aku, sebab Aku merasa ada kuasa keluar dari diri-Ku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 47, 'Ketika perempuan itu melihat, bahwa perbuatannya itu ketahuan, ia datang dengan gemetar, tersungkur di depan-Nya dan menceriterakan kepada orang banyak apa sebabnya ia menjamah Dia dan bahwa ia seketika itu juga menjadi sembuh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 48, 'Maka kata-Nya kepada perempuan itu: "Hai anak-Ku, imanmu telah menyelamatkan engkau, pergilah dengan selamat!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 49, 'Ketika Yesus masih berbicara, datanglah seorang dari keluarga kepala rumah ibadat itu dan berkata: "Anakmu sudah mati, jangan lagi engkau menyusah-nyusahkan Guru!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 50, 'Tetapi Yesus mendengarnya dan berkata kepada Yairus: "Jangan takut, percaya saja, dan anakmu akan selamat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 51, 'Setibanya di rumah Yairus, Yesus tidak memperbolehkan seorangpun ikut masuk dengan Dia, kecuali Petrus, Yohanes dan Yakobus dan ayah anak itu serta ibunya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 52, 'Semua orang menangis dan meratapi anak itu. Akan tetapi Yesus berkata: "Jangan menangis; ia tidak mati, tetapi tidur."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 53, 'Mereka menertawakan Dia, karena mereka tahu bahwa anak itu telah mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 54, 'Lalu Yesus memegang tangan anak itu dan berseru, kata-Nya: "Hai anak bangunlah!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 55, 'Maka kembalilah roh anak itu dan seketika itu juga ia bangkit berdiri. Lalu Yesus menyuruh mereka memberi anak itu makan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 8, 56, 'Dan takjublah orang tua anak itu, tetapi Yesus melarang mereka memberitahukan kepada siapapun juga apa yang terjadi itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 1, 'Maka Yesus memanggil kedua belas murid-Nya, lalu memberikan tenaga dan kuasa kepada mereka untuk menguasai setan-setan dan untuk menyembuhkan penyakit-penyakit.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 2, 'Dan Ia mengutus mereka untuk memberitakan Kerajaan Allah dan untuk menyembuhkan orang,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 3, 'kata-Nya kepada mereka: "Jangan membawa apa-apa dalam perjalanan, jangan membawa tongkat atau bekal, roti atau uang, atau dua helai baju.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 4, 'Dan apabila kamu sudah diterima dalam suatu rumah, tinggallah di situ sampai kamu berangkat dari situ.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 5, 'Dan kalau ada orang yang tidak mau menerima kamu, keluarlah dari kota mereka dan kebaskanlah debunya dari kakimu sebagai peringatan terhadap mereka."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 6, 'Lalu pergilah mereka dan mereka mengelilingi segala desa sambil memberitakan Injil dan menyembuhkan orang sakit di segala tempat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 7, 'Herodes, raja wilayah, mendengar segala yang terjadi itu dan iapun merasa cemas, sebab ada orang yang mengatakan, bahwa Yohanes telah bangkit dari antara orang mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 8, 'Ada lagi yang mengatakan, bahwa Elia telah muncul kembali, dan ada pula yang mengatakan, bahwa seorang dari nabi-nabi dahulu telah bangkit.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 9, 'Tetapi Herodes berkata: "Yohanes telah kupenggal kepalanya. Siapa gerangan Dia ini, yang kabarnya melakukan hal-hal demikian?" Lalu ia berusaha supaya dapat bertemu dengan Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 10, 'Sekembalinya rasul-rasul itu menceriterakan kepada Yesus apa yang telah mereka kerjakan. Lalu Yesus membawa mereka dan menyingkir ke sebuah kota yang bernama Betsaida, sehingga hanya mereka saja bersama Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 11, 'Akan tetapi orang banyak mengetahuinya, lalu mengikuti Dia. Ia menerima mereka dan berkata-kata kepada mereka tentang Kerajaan Allah dan Ia menyembuhkan orang-orang yang memerlukan penyembuhan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 12, 'Pada waktu hari mulai malam datanglah kedua belas murid-Nya kepada-Nya dan berkata: "Suruhlah orang banyak itu pergi, supaya mereka pergi ke desa-desa dan kampung-kampung sekitar ini untuk mencari tempat penginapan dan makanan, karena di sini kita berada di tempat yang sunyi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 13, 'Tetapi Ia berkata kepada mereka: "Kamu harus memberi mereka makan!" Mereka menjawab: "Yang ada pada kami tidak lebih dari pada lima roti dan dua ikan, kecuali kalau kami pergi membeli makanan untuk semua orang banyak ini."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 14, 'Sebab di situ ada kira-kira lima ribu orang laki-laki. Lalu Ia berkata kepada murid-murid-Nya: "Suruhlah mereka duduk berkelompok-kelompok, kira-kira lima puluh orang sekelompok."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 15, 'Murid-murid melakukannya dan menyuruh semua orang banyak itu duduk.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 16, 'Dan setelah Ia mengambil lima roti dan dua ikan itu, Ia menengadah ke langit, mengucap berkat, lalu memecah-mecahkan roti itu dan memberikannya kepada murid-murid-Nya supaya dibagi-bagikannya kepada orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 17, 'Dan mereka semuanya makan sampai kenyang. Kemudian dikumpulkan potongan-potongan roti yang sisa sebanyak dua belas bakul.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 18, 'Pada suatu kali ketika Yesus berdoa seorang diri, datanglah murid-murid-Nya kepada-Nya. Lalu Ia bertanya kepada mereka: "Kata orang banyak, siapakah Aku ini?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 19, 'Jawab mereka: "Yohanes Pembaptis, ada juga yang mengatakan: Elia, ada pula yang mengatakan, bahwa seorang dari nabi-nabi dahulu telah bangkit."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 20, 'Yesus bertanya kepada mereka: "Menurut kamu, siapakah Aku ini?" Jawab Petrus: "Mesias dari Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 21, 'Lalu Yesus melarang mereka dengan keras, supaya mereka jangan memberitahukan hal itu kepada siapapun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 22, 'Dan Yesus berkata: "Anak Manusia harus menanggung banyak penderitaan dan ditolak oleh tua-tua, imam-imam kepala dan ahli-ahli Taurat, lalu dibunuh dan dibangkitkan pada hari ketiga."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 23, 'Kata-Nya kepada mereka semua: "Setiap orang yang mau mengikut Aku, ia harus menyangkal dirinya, memikul salibnya setiap hari dan mengikut Aku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 24, 'Karena barangsiapa mau menyelamatkan nyawanya, ia akan kehilangan nyawanya; tetapi barangsiapa kehilangan nyawanya karena Aku, ia akan menyelamatkannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 25, 'Apa gunanya seorang memperoleh seluruh dunia, tetapi ia membinasakan atau merugikan dirinya sendiri?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 26, 'Sebab barangsiapa malu karena Aku dan karena perkataan-Ku, Anak Manusia juga akan malu karena orang itu, apabila Ia datang kelak dalam kemuliaan-Nya dan dalam kemuliaan Bapa dan malaikat-malaikat kudus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 27, 'Aku berkata kepadamu: Sesungguhnya di antara orang yang hadir di sini ada yang tidak akan mati sebelum mereka melihat Kerajaan Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 28, 'Kira-kira delapan hari sesudah segala pengajaran itu, Yesus membawa Petrus, Yohanes dan Yakobus, lalu naik ke atas gunung untuk berdoa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 29, 'Ketika Ia sedang berdoa, rupa wajah-Nya berubah dan pakaian-Nya menjadi putih berkilau-kilauan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 30, 'Dan tampaklah dua orang berbicara dengan Dia, yaitu Musa dan Elia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 31, 'Keduanya menampakkan diri dalam kemuliaan dan berbicara tentang tujuan kepergian-Nya yang akan digenapi-Nya di Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 32, 'Sementara itu Petrus dan teman-temannya telah tertidur dan ketika mereka terbangun mereka melihat Yesus dalam kemuliaan-Nya: dan kedua orang yang berdiri di dekat-Nya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 33, 'Dan ketika kedua orang itu hendak meninggalkan Yesus, Petrus berkata kepada-Nya: "Guru, betapa bahagianya kami berada di tempat ini. Baiklah kami dirikan sekarang tiga kemah, satu untuk Engkau, satu untuk Musa dan satu untuk Elia." Tetapi Petrus tidak tahu apa yang dikatakannya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 34, 'Sementara ia berkata demikian, datanglah awan menaungi mereka. Dan ketika mereka masuk ke dalam awan itu, takutlah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 35, 'Maka terdengarlah suara dari dalam awan itu, yang berkata: "Inilah Anak-Ku yang Kupilih, dengarkanlah Dia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 36, 'Ketika suara itu terdengar, nampaklah Yesus tinggal seorang diri. Dan murid-murid itu merahasiakannya, dan pada masa itu mereka tidak menceriterakan kepada siapapun apa yang telah mereka lihat itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 37, 'Pada keesokan harinya ketika mereka turun dari gunung itu, datanglah orang banyak berbondong-bondong menemui Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 38, 'Seorang dari orang banyak itu berseru, katanya: "Guru, aku memohon supaya Engkau menengok anakku, sebab ia adalah satu-satunya anakku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 39, 'Sewaktu-waktu ia diserang roh, lalu mendadak ia berteriak dan roh itu menggoncang-goncangkannya sehingga mulutnya berbusa. Roh itu terus saja menyiksa dia dan hampir-hampir tidak mau meninggalkannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 40, 'Dan aku telah meminta kepada murid-murid-Mu supaya mereka mengusir roh itu, tetapi mereka tidak dapat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 41, 'Maka kata Yesus: "Hai kamu angkatan yang tidak percaya dan yang sesat, berapa lama lagi Aku harus tinggal di antara kamu dan sabar terhadap kamu? Bawa anakmu itu kemari!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 42, 'Dan ketika anak itu mendekati Yesus, setan itu membantingkannya ke tanah dan menggoncang-goncangnya. Tetapi Yesus menegor roh jahat itu dengan keras dan menyembuhkan anak itu, lalu mengembalikannya kepada ayahnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 43, 'Maka takjublah semua orang itu karena kebesaran Allah. (9-43b) Ketika semua orang itu masih heran karena segala yang diperbuat-Nya itu, Yesus berkata kepada murid-murid-Nya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 44, '"Dengarlah dan camkanlah segala perkataan-Ku ini: Anak Manusia akan diserahkan ke dalam tangan manusia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 45, 'Mereka tidak mengerti perkataan itu, sebab artinya tersembunyi bagi mereka, sehingga mereka tidak dapat memahaminya. Dan mereka tidak berani menanyakan arti perkataan itu kepada-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 46, 'Maka timbullah pertengkaran di antara murid-murid Yesus tentang siapakah yang terbesar di antara mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 47, 'Tetapi Yesus mengetahui pikiran mereka. Karena itu Ia mengambil seorang anak kecil dan menempatkannya di samping-Nya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 48, 'dan berkata kepada mereka: "Barangsiapa menyambut anak ini dalam nama-Ku, ia menyambut Aku; dan barangsiapa menyambut Aku, ia menyambut Dia, yang mengutus Aku. Karena yang terkecil di antara kamu sekalian, dialah yang terbesar."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 49, 'Yohanes berkata: "Guru, kami lihat seorang mengusir setan demi nama-Mu, lalu kami cegah orang itu, karena ia bukan pengikut kita."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 50, 'Yesus berkata kepadanya: "Jangan kamu cegah, sebab barangsiapa tidak melawan kamu, ia ada di pihak kamu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 51, 'Ketika hampir genap waktunya Yesus diangkat ke sorga, Ia mengarahkan pandangan-Nya untuk pergi ke Yerusalem,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 52, 'dan Ia mengirim beberapa utusan mendahului Dia. Mereka itu pergi, lalu masuk ke suatu desa orang Samaria untuk mempersiapkan segala sesuatu bagi-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 53, 'Tetapi orang-orang Samaria itu tidak mau menerima Dia, karena perjalanan-Nya menuju Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 54, 'Ketika dua murid-Nya, yaitu Yakobus dan Yohanes, melihat hal itu, mereka berkata: "Tuhan, apakah Engkau mau, supaya kami menyuruh api turun dari langit untuk membinasakan mereka?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 55, 'Akan tetapi Ia berpaling dan menegor mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 56, 'Lalu mereka pergi ke desa yang lain.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 57, 'Ketika Yesus dan murid-murid-Nya melanjutkan perjalanan mereka, berkatalah seorang di tengah jalan kepada Yesus: "Aku akan mengikut Engkau, ke mana saja Engkau pergi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 58, 'Yesus berkata kepadanya: "Serigala mempunyai liang dan burung mempunyai sarang, tetapi Anak Manusia tidak mempunyai tempat untuk meletakkan kepala-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 59, 'Lalu Ia berkata kepada seorang lain: "Ikutlah Aku!" Tetapi orang itu berkata: "Izinkanlah aku pergi dahulu menguburkan bapaku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 9, 60, 'Tetapi Yesus berkata kepadanya: "Biarlah orang mati menguburkan orang mati; tetapi engkau, pergilah dan beritakanlah Kerajaan Allah di mana-mana."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 1, 'Kemudian dari pada itu Tuhan menunjuk tujuh puluh murid yang lain, lalu mengutus mereka berdua-dua mendahului-Nya ke setiap kota dan tempat yang hendak dikunjungi-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 2, 'Kata-Nya kepada mereka: "Tuaian memang banyak, tetapi pekerja sedikit. Karena itu mintalah kepada Tuan yang empunya tuaian, supaya Ia mengirimkan pekerja-pekerja untuk tuaian itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 3, 'Pergilah, sesungguhnya Aku mengutus kamu seperti anak domba ke tengah-tengah serigala.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 4, 'Janganlah membawa pundi-pundi atau bekal atau kasut, dan janganlah memberi salam kepada siapapun selama dalam perjalanan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 5, 'Kalau kamu memasuki suatu rumah, katakanlah lebih dahulu: Damai sejahtera bagi rumah ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 6, 'Dan jikalau di situ ada orang yang layak menerima damai sejahtera, maka salammu itu akan tinggal atasnya. Tetapi jika tidak, salammu itu kembali kepadamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 7, 'Tinggallah dalam rumah itu, makan dan minumlah apa yang diberikan orang kepadamu, sebab seorang pekerja patut mendapat upahnya. Janganlah berpindah-pindah rumah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 8, 'Dan jikalau kamu masuk ke dalam sebuah kota dan kamu diterima di situ, makanlah apa yang dihidangkan kepadamu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 9, 'dan sembuhkanlah orang-orang sakit yang ada di situ dan katakanlah kepada mereka: Kerajaan Allah sudah dekat padamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 10, 'Tetapi jikalau kamu masuk ke dalam sebuah kota dan kamu tidak diterima di situ, pergilah ke jalan-jalan raya kota itu dan serukanlah:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 11, 'Juga debu kotamu yang melekat pada kaki kami, kami kebaskan di depanmu; tetapi ketahuilah ini: Kerajaan Allah sudah dekat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 12, 'Aku berkata kepadamu: pada hari itu Sodom akan lebih ringan tanggungannya dari pada kota itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 13, '"Celakalah engkau Khorazim! Celakalah engkau Betsaida! karena jika di Tirus dan di Sidon terjadi mujizat-mujizat yang telah terjadi di tengah-tengah kamu, sudah lama mereka bertobat dan berkabung.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 14, 'Akan tetapi pada waktu penghakiman, tanggungan Tirus dan Sidon akan lebih ringan dari pada tanggunganmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 15, 'Dan engkau Kapernaum, apakah engkau akan dinaikkan sampai ke langit? Tidak, engkau akan diturunkan sampai ke dunia orang mati!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 16, 'Barangsiapa mendengarkan kamu, ia mendengarkan Aku; dan barangsiapa menolak kamu, ia menolak Aku; dan barangsiapa menolak Aku, ia menolak Dia yang mengutus Aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 17, 'Kemudian ketujuh puluh murid itu kembali dengan gembira dan berkata: "Tuhan, juga setan-setan takluk kepada kami demi nama-Mu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 18, 'Lalu kata Yesus kepada mereka: "Aku melihat Iblis jatuh seperti kilat dari langit.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 19, 'Sesungguhnya Aku telah memberikan kuasa kepada kamu untuk menginjak ular dan kalajengking dan kuasa untuk menahan kekuatan musuh, sehingga tidak ada yang akan membahayakan kamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 20, 'Namun demikian janganlah bersukacita karena roh-roh itu takluk kepadamu, tetapi bersukacitalah karena namamu ada terdaftar di sorga."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 21, 'Pada waktu itu juga bergembiralah Yesus dalam Roh Kudus dan berkata: "Aku bersyukur kepada-Mu, Bapa, Tuhan langit dan bumi, karena semuanya itu Engkau sembunyikan bagi orang bijak dan orang pandai, tetapi Engkau nyatakan kepada orang kecil. Ya Bapa, itulah yang berkenan kepada-Mu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 22, 'Semua telah diserahkan kepada-Ku oleh Bapa-Ku dan tidak ada seorangpun yang tahu siapakah Anak selain Bapa, dan siapakah Bapa selain Anak dan orang yang kepadanya Anak itu berkenan menyatakan hal itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 23, 'Sesudah itu berpalinglah Yesus kepada murid-murid-Nya tersendiri dan berkata: "Berbahagialah mata yang melihat apa yang kamu lihat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 24, 'Karena Aku berkata kepada kamu: Banyak nabi dan raja ingin melihat apa yang kamu lihat, tetapi tidak melihatnya, dan ingin mendengar apa yang kamu dengar, tetapi tidak mendengarnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 25, 'Pada suatu kali berdirilah seorang ahli Taurat untuk mencobai Yesus, katanya: "Guru, apa yang harus kuperbuat untuk memperoleh hidup yang kekal?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 26, 'Jawab Yesus kepadanya: "Apa yang tertulis dalam hukum Taurat? Apa yang kaubaca di sana?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 27, 'Jawab orang itu: "Kasihilah Tuhan, Allahmu, dengan segenap hatimu dan dengan segenap jiwamu dan dengan segenap kekuatanmu dan dengan segenap akal budimu, dan kasihilah sesamamu manusia seperti dirimu sendiri."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 28, 'Kata Yesus kepadanya: "Jawabmu itu benar; perbuatlah demikian, maka engkau akan hidup."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 29, 'Tetapi untuk membenarkan dirinya orang itu berkata kepada Yesus: "Dan siapakah sesamaku manusia?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 30, 'Jawab Yesus: "Adalah seorang yang turun dari Yerusalem ke Yerikho; ia jatuh ke tangan penyamun-penyamun yang bukan saja merampoknya habis-habisan, tetapi yang juga memukulnya dan yang sesudah itu pergi meninggalkannya setengah mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 31, 'Kebetulan ada seorang imam turun melalui jalan itu; ia melihat orang itu, tetapi ia melewatinya dari seberang jalan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 32, 'Demikian juga seorang Lewi datang ke tempat itu; ketika ia melihat orang itu, ia melewatinya dari seberang jalan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 33, 'Lalu datang seorang Samaria, yang sedang dalam perjalanan, ke tempat itu; dan ketika ia melihat orang itu, tergeraklah hatinya oleh belas kasihan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 34, 'Ia pergi kepadanya lalu membalut luka-lukanya, sesudah ia menyiraminya dengan minyak dan anggur. Kemudian ia menaikkan orang itu ke atas keledai tunggangannya sendiri lalu membawanya ke tempat penginapan dan merawatnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 35, 'Keesokan harinya ia menyerahkan dua dinar kepada pemilik penginapan itu, katanya: Rawatlah dia dan jika kaubelanjakan lebih dari ini, aku akan menggantinya, waktu aku kembali.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 36, 'Siapakah di antara ketiga orang ini, menurut pendapatmu, adalah sesama manusia dari orang yang jatuh ke tangan penyamun itu?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 37, 'Jawab orang itu: "Orang yang telah menunjukkan belas kasihan kepadanya." Kata Yesus kepadanya: "Pergilah, dan perbuatlah demikian!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 38, 'Ketika Yesus dan murid-murid-Nya dalam perjalanan, tibalah Ia di sebuah kampung. Seorang perempuan yang bernama Marta menerima Dia di rumahnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 39, 'Perempuan itu mempunyai seorang saudara yang bernama Maria. Maria ini duduk dekat kaki Tuhan dan terus mendengarkan perkataan-Nya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 40, 'sedang Marta sibuk sekali melayani. Ia mendekati Yesus dan berkata: "Tuhan, tidakkah Engkau peduli, bahwa saudaraku membiarkan aku melayani seorang diri? Suruhlah dia membantu aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 41, 'Tetapi Tuhan menjawabnya: "Marta, Marta, engkau kuatir dan menyusahkan diri dengan banyak perkara,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 10, 42, 'tetapi hanya satu saja yang perlu: Maria telah memilih bagian yang terbaik, yang tidak akan diambil dari padanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 1, 'Pada suatu kali Yesus sedang berdoa di salah satu tempat. Ketika Ia berhenti berdoa, berkatalah seorang dari murid-murid-Nya kepada-Nya: "Tuhan, ajarlah kami berdoa, sama seperti yang diajarkan Yohanes kepada murid-muridnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 2, 'Jawab Yesus kepada mereka: "Apabila kamu berdoa, katakanlah: Bapa, dikuduskanlah nama-Mu; datanglah Kerajaan-Mu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 3, 'Berikanlah kami setiap hari makanan kami yang secukupnya', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 4, 'dan ampunilah kami akan dosa kami, sebab kamipun mengampuni setiap orang yang bersalah kepada kami; dan janganlah membawa kami ke dalam pencobaan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 5, 'Lalu kata-Nya kepada mereka: "Jika seorang di antara kamu pada tengah malam pergi ke rumah seorang sahabatnya dan berkata kepadanya: Saudara, pinjamkanlah kepadaku tiga roti,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 6, 'sebab seorang sahabatku yang sedang berada dalam perjalanan singgah ke rumahku dan aku tidak mempunyai apa-apa untuk dihidangkan kepadanya;', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 7, 'masakan ia yang di dalam rumah itu akan menjawab: Jangan mengganggu aku, pintu sudah tertutup dan aku serta anak-anakku sudah tidur; aku tidak dapat bangun dan memberikannya kepada saudara.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 8, 'Aku berkata kepadamu: Sekalipun ia tidak mau bangun dan memberikannya kepadanya karena orang itu adalah sahabatnya, namun karena sikapnya yang tidak malu itu, ia akan bangun juga dan memberikan kepadanya apa yang diperlukannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 9, 'Oleh karena itu Aku berkata kepadamu: Mintalah, maka akan diberikan kepadamu; carilah, maka kamu akan mendapat; ketoklah, maka pintu akan dibukakan bagimu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 10, 'Karena setiap orang yang meminta, menerima dan setiap orang yang mencari, mendapat dan setiap orang yang mengetok, baginya pintu dibukakan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 11, 'Bapa manakah di antara kamu, jika anaknya minta ikan dari padanya, akan memberikan ular kepada anaknya itu ganti ikan?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 12, 'Atau, jika ia minta telur, akan memberikan kepadanya kalajengking?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 13, 'Jadi jika kamu yang jahat tahu memberi pemberian yang baik kepada anak-anakmu, apalagi Bapamu yang di sorga! Ia akan memberikan Roh Kudus kepada mereka yang meminta kepada-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 14, 'Pada suatu kali Yesus mengusir dari seorang suatu setan yang membisukan. Ketika setan itu keluar, orang bisu itu dapat berkata-kata. Maka heranlah orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 15, 'Tetapi ada di antara mereka yang berkata: "Ia mengusir setan dengan kuasa Beelzebul, penghulu setan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 16, 'Ada pula yang meminta suatu tanda dari sorga kepada-Nya, untuk mencobai Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 17, 'Tetapi Yesus mengetahui pikiran mereka lalu berkata: "Setiap kerajaan yang terpecah-pecah pasti binasa, dan setiap rumah tangga yang terpecah-pecah, pasti runtuh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 18, 'Jikalau Iblis itu juga terbagi-bagi dan melawan dirinya sendiri, bagaimanakah kerajaannya dapat bertahan? Sebab kamu berkata, bahwa Aku mengusir setan dengan kuasa Beelzebul.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 19, 'Jadi jika Aku mengusir setan dengan kuasa Beelzebul, dengan kuasa apakah pengikut-pengikutmu mengusirnya? Sebab itu merekalah yang akan menjadi hakimmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 20, 'Tetapi jika Aku mengusir setan dengan kuasa Allah, maka sesungguhnya Kerajaan Allah sudah datang kepadamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 21, 'Apabila seorang yang kuat dan yang lengkap bersenjata menjaga rumahnya sendiri, maka amanlah segala miliknya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 22, 'Tetapi jika seorang yang lebih kuat dari padanya menyerang dan mengalahkannya, maka orang itu akan merampas perlengkapan senjata, yang diandalkannya, dan akan membagi-bagikan rampasannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 23, 'Siapa tidak bersama Aku, ia melawan Aku dan siapa tidak mengumpulkan bersama Aku, ia mencerai-beraikan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 24, '"Apabila roh jahat keluar dari manusia, iapun mengembara ke tempat-tempat yang tandus mencari perhentian, dan karena ia tidak mendapatnya, ia berkata: Aku akan kembali ke rumah yang telah kutinggalkan itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 25, 'Maka pergilah ia dan mendapati rumah itu bersih tersapu dan rapih teratur.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 26, 'Lalu ia keluar dan mengajak tujuh roh lain yang lebih jahat dari padanya, dan mereka masuk dan berdiam di situ. Maka akhirnya keadaan orang itu lebih buruk dari pada keadaannya semula."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 27, 'Ketika Yesus masih berbicara, berserulah seorang perempuan dari antara orang banyak dan berkata kepada-Nya: "Berbahagialah ibu yang telah mengandung Engkau dan susu yang telah menyusui Engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 28, 'Tetapi Ia berkata: "Yang berbahagia ialah mereka yang mendengarkan firman Allah dan yang memeliharanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 29, 'Ketika orang banyak mengerumuni-Nya, berkatalah Yesus: "Angkatan ini adalah angkatan yang jahat. Mereka menghendaki suatu tanda, tetapi kepada mereka tidak akan diberikan tanda selain tanda nabi Yunus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 30, 'Sebab seperti Yunus menjadi tanda untuk orang-orang Niniwe, demikian pulalah Anak Manusia akan menjadi tanda untuk angkatan ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 31, 'Pada waktu penghakiman, ratu dari Selatan itu akan bangkit bersama orang dari angkatan ini dan ia akan menghukum mereka. Sebab ratu ini datang dari ujung bumi untuk mendengarkan hikmat Salomo, dan sesungguhnya yang ada di sini lebih dari pada Salomo!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 32, 'Pada waktu penghakiman, orang-orang Niniwe akan bangkit bersama angkatan ini dan mereka akan menghukumnya. Sebab orang-orang Niniwe itu bertobat waktu mereka mendengarkan pemberitaan Yunus, dan sesungguhnya yang ada di sini lebih dari pada Yunus!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 33, '"Tidak seorangpun yang menyalakan pelita lalu meletakkannya di kolong rumah atau di bawah gantang, melainkan di atas kaki dian, supaya semua orang yang masuk, dapat melihat cahayanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 34, 'Matamu adalah pelita tubuhmu. Jika matamu baik, teranglah seluruh tubuhmu, tetapi jika matamu jahat, gelaplah tubuhmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 35, 'Karena itu perhatikanlah supaya terang yang ada padamu jangan menjadi kegelapan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 36, 'Jika seluruh tubuhmu terang dan tidak ada bagian yang gelap, maka seluruhnya akan terang, sama seperti apabila pelita menerangi engkau dengan cahayanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 37, 'Ketika Yesus selesai mengajar, seorang Farisi mengundang Dia untuk makan di rumahnya. Maka masuklah Ia ke rumah itu, lalu duduk makan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 38, 'Orang Farisi itu melihat hal itu dan ia heran, karena Yesus tidak mencuci tangan-Nya sebelum makan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 39, 'Tetapi Tuhan berkata kepadanya: "Kamu orang-orang Farisi, kamu membersihkan bagian luar dari cawan dan pinggan, tetapi bagian dalammu penuh rampasan dan kejahatan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 40, 'Hai orang-orang bodoh, bukankah Dia yang menjadikan bagian luar, Dia juga yang menjadikan bagian dalam?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 41, 'Akan tetapi, berikanlah isinya sebagai sedekah dan sesungguhnya semuanya akan menjadi bersih bagimu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 42, 'Tetapi celakalah kamu, hai orang-orang Farisi, sebab kamu membayar persepuluhan dari selasih, inggu dan segala jenis sayuran, tetapi kamu mengabaikan keadilan dan kasih Allah. Yang satu harus dilakukan dan yang lain jangan diabaikan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 43, 'Celakalah kamu, hai orang-orang Farisi, sebab kamu suka duduk di tempat terdepan di rumah ibadat dan suka menerima penghormatan di pasar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 44, 'Celakalah kamu, sebab kamu sama seperti kubur yang tidak memakai tanda; orang-orang yang berjalan di atasnya, tidak mengetahuinya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 45, 'Seorang dari antara ahli-ahli Taurat itu menjawab dan berkata kepada-Nya: "Guru, dengan berkata demikian, Engkau menghina kami juga."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 46, 'Tetapi Ia menjawab: "Celakalah kamu juga, hai ahli-ahli Taurat, sebab kamu meletakkan beban-beban yang tak terpikul pada orang, tetapi kamu sendiri tidak menyentuh beban itu dengan satu jaripun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 47, 'Celakalah kamu, sebab kamu membangun makam nabi-nabi, tetapi nenek moyangmu telah membunuh mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 48, 'Dengan demikian kamu mengaku, bahwa kamu membenarkan perbuatan-perbuatan nenek moyangmu, sebab mereka telah membunuh nabi-nabi itu dan kamu membangun makamnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 49, 'Sebab itu hikmat Allah berkata: Aku akan mengutus kepada mereka nabi-nabi dan rasul-rasul dan separuh dari antara nabi-nabi dan rasul-rasul itu akan mereka bunuh dan mereka aniaya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 50, 'supaya dari angkatan ini dituntut darah semua nabi yang telah tertumpah sejak dunia dijadikan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 51, 'mulai dari darah Habel sampai kepada darah Zakharia yang telah dibunuh di antara mezbah dan Rumah Allah. Bahkan, Aku berkata kepadamu: Semuanya itu akan dituntut dari angkatan ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 52, 'Celakalah kamu, hai ahli-ahli Taurat, sebab kamu telah mengambil kunci pengetahuan; kamu sendiri tidak masuk ke dalam dan orang yang berusaha untuk masuk ke dalam kamu halang-halangi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 53, 'Dan setelah Yesus berangkat dari tempat itu, ahli-ahli Taurat dan orang-orang Farisi terus-menerus mengintai dan membanjiri-Nya dengan rupa-rupa soal.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 11, 54, 'Untuk itu mereka berusaha memancing-Nya, supaya mereka dapat menangkap-Nya berdasarkan sesuatu yang diucapkan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 1, 'Sementara itu beribu-ribu orang banyak telah berkerumun, sehingga mereka berdesak-desakan. Lalu Yesus mulai mengajar, pertama-tama kepada murid-murid-Nya, kata-Nya: "Waspadalah terhadap ragi, yaitu kemunafikan orang Farisi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 2, 'Tidak ada sesuatupun yang tertutup yang tidak akan dibuka dan tidak ada sesuatupun yang tersembunyi yang tidak akan diketahui.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 3, 'Karena itu apa yang kamu katakan dalam gelap akan kedengaran dalam terang, dan apa yang kamu bisikkan ke telinga di dalam kamar akan diberitakan dari atas atap rumah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 4, 'Aku berkata kepadamu, hai sahabat-sahabat-Ku, janganlah kamu takut terhadap mereka yang dapat membunuh tubuh dan kemudian tidak dapat berbuat apa-apa lagi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 5, 'Aku akan menunjukkan kepada kamu siapakah yang harus kamu takuti. Takutilah Dia, yang setelah membunuh, mempunyai kuasa untuk melemparkan orang ke dalam neraka. Sesungguhnya Aku berkata kepadamu, takutilah Dia!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 6, 'Bukankah burung pipit dijual lima ekor dua duit? Sungguhpun demikian tidak seekorpun dari padanya yang dilupakan Allah,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 7, 'bahkan rambut kepalamupun terhitung semuanya. Karena itu jangan takut, karena kamu lebih berharga dari pada banyak burung pipit.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 8, 'Aku berkata kepadamu: Setiap orang yang mengakui Aku di depan manusia, Anak Manusia juga akan mengakui dia di depan malaikat-malaikat Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 9, 'Tetapi barangsiapa menyangkal Aku di depan manusia, ia akan disangkal di depan malaikat-malaikat Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 10, 'Setiap orang yang mengatakan sesuatu melawan Anak Manusia, ia akan diampuni; tetapi barangsiapa menghujat Roh Kudus, ia tidak akan diampuni.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 11, 'Apabila orang menghadapkan kamu kepada majelis-majelis atau kepada pemerintah-pemerintah dan penguasa-penguasa, janganlah kamu kuatir bagaimana dan apa yang harus kamu katakan untuk membela dirimu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 12, 'Sebab pada saat itu juga Roh Kudus akan mengajar kamu apa yang harus kamu katakan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 13, 'Seorang dari orang banyak itu berkata kepada Yesus: "Guru, katakanlah kepada saudaraku supaya ia berbagi warisan dengan aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 14, 'Tetapi Yesus berkata kepadanya: "Saudara, siapakah yang telah mengangkat Aku menjadi hakim atau pengantara atas kamu?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 15, 'Kata-Nya lagi kepada mereka: "Berjaga-jagalah dan waspadalah terhadap segala ketamakan, sebab walaupun seorang berlimpah-limpah hartanya, hidupnya tidaklah tergantung dari pada kekayaannya itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 16, 'Kemudian Ia mengatakan kepada mereka suatu perumpamaan, kata-Nya: "Ada seorang kaya, tanahnya berlimpah-limpah hasilnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 17, 'Ia bertanya dalam hatinya: Apakah yang harus aku perbuat, sebab aku tidak mempunyai tempat di mana aku dapat menyimpan hasil tanahku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 18, 'Lalu katanya: Inilah yang akan aku perbuat; aku akan merombak lumbung-lumbungku dan aku akan mendirikan yang lebih besar dan aku akan menyimpan di dalamnya segala gandum dan barang-barangku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 19, 'Sesudah itu aku akan berkata kepada jiwaku: Jiwaku, ada padamu banyak barang, tertimbun untuk bertahun-tahun lamanya; beristirahatlah, makanlah, minumlah dan bersenang-senanglah!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 20, 'Tetapi firman Allah kepadanya: Hai engkau orang bodoh, pada malam ini juga jiwamu akan diambil dari padamu, dan apa yang telah kausediakan, untuk siapakah itu nanti?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 21, 'Demikianlah jadinya dengan orang yang mengumpulkan harta bagi dirinya sendiri, jikalau ia tidak kaya di hadapan Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 22, 'Yesus berkata kepada murid-murid-Nya: "Karena itu Aku berkata kepadamu: Janganlah kuatir akan hidupmu, akan apa yang hendak kamu makan, dan janganlah kuatir pula akan tubuhmu, akan apa yang hendak kamu pakai.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 23, 'Sebab hidup itu lebih penting dari pada makanan dan tubuh itu lebih penting dari pada pakaian.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 24, 'Perhatikanlah burung-burung gagak yang tidak menabur dan tidak menuai dan tidak mempunyai gudang atau lumbung, namun demikian diberi makan oleh Allah. Betapa jauhnya kamu melebihi burung-burung itu!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 25, 'Siapakah di antara kamu yang karena kekuatirannya dapat menambahkan sehasta pada jalan hidupnya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 26, 'Jadi, jikalau kamu tidak sanggup membuat barang yang paling kecil, mengapa kamu kuatir akan hal-hal lain?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 27, 'Perhatikanlah bunga bakung, yang tidak memintal dan tidak menenun, namun Aku berkata kepadamu: Salomo dalam segala kemegahannyapun tidak berpakaian seindah salah satu dari bunga itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 28, 'Jadi, jika rumput di ladang, yang hari ini ada dan besok dibuang ke dalam api demikian didandani Allah, terlebih lagi kamu, hai orang yang kurang percaya!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 29, 'Jadi, janganlah kamu mempersoalkan apa yang akan kamu makan atau apa yang akan kamu minum dan janganlah cemas hatimu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 30, 'Semua itu dicari bangsa-bangsa di dunia yang tidak mengenal Allah. Akan tetapi Bapamu tahu, bahwa kamu memang memerlukan semuanya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 31, 'Tetapi carilah Kerajaan-Nya, maka semuanya itu akan ditambahkan juga kepadamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 32, 'Janganlah takut, hai kamu kawanan kecil! Karena Bapamu telah berkenan memberikan kamu Kerajaan itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 33, 'Juallah segala milikmu dan berikanlah sedekah! Buatlah bagimu pundi-pundi yang tidak dapat menjadi tua, suatu harta di sorga yang tidak akan habis, yang tidak dapat didekati pencuri dan yang tidak dirusakkan ngengat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 34, 'Karena di mana hartamu berada, di situ juga hatimu berada."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 35, '"Hendaklah pinggangmu tetap berikat dan pelitamu tetap menyala.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 36, 'Dan hendaklah kamu sama seperti orang-orang yang menanti-nantikan tuannya yang pulang dari perkawinan, supaya jika ia datang dan mengetok pintu, segera dibuka pintu baginya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 37, 'Berbahagialah hamba-hamba yang didapati tuannya berjaga-jaga ketika ia datang. Aku berkata kepadamu: Sesungguhnya ia akan mengikat pinggangnya dan mempersilakan mereka duduk makan, dan ia akan datang melayani mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 38, 'Dan apabila ia datang pada tengah malam atau pada dinihari dan mendapati mereka berlaku demikian, maka berbahagialah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 39, 'Tetapi ketahuilah ini: Jika tuan rumah tahu pukul berapa pencuri akan datang, ia tidak akan membiarkan rumahnya dibongkar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 40, 'Hendaklah kamu juga siap sedia, karena Anak Manusia datang pada saat yang tidak kamu sangkakan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 41, 'Kata Petrus: "Tuhan, kamikah yang Engkau maksudkan dengan perumpamaan itu atau juga semua orang?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 42, 'Jawab Tuhan: "Jadi, siapakah pengurus rumah yang setia dan bijaksana yang akan diangkat oleh tuannya menjadi kepala atas semua hambanya untuk memberikan makanan kepada mereka pada waktunya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 43, 'Berbahagialah hamba, yang didapati tuannya melakukan tugasnya itu, ketika tuannya itu datang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 44, 'Aku berkata kepadamu: Sesungguhnya tuannya itu akan mengangkat dia menjadi pengawas segala miliknya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 45, 'Akan tetapi, jikalau hamba itu jahat dan berkata di dalam hatinya: Tuanku tidak datang-datang, lalu ia mulai memukul hamba-hamba laki-laki dan hamba-hamba perempuan, dan makan minum dan mabuk,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 46, 'maka tuan hamba itu akan datang pada hari yang tidak disangkakannya, dan pada saat yang tidak diketahuinya, dan akan membunuh dia dan membuat dia senasib dengan orang-orang yang tidak setia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 47, 'Adapun hamba yang tahu akan kehendak tuannya, tetapi yang tidak mengadakan persiapan atau tidak melakukan apa yang dikehendaki tuannya, ia akan menerima banyak pukulan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 48, 'Tetapi barangsiapa tidak tahu akan kehendak tuannya dan melakukan apa yang harus mendatangkan pukulan, ia akan menerima sedikit pukulan. Setiap orang yang kepadanya banyak diberi, dari padanya akan banyak dituntut, dan kepada siapa yang banyak dipercayakan, dari padanya akan lebih banyak lagi dituntut."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 49, '"Aku datang untuk melemparkan api ke bumi dan betapakah Aku harapkan, api itu telah menyala!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 50, 'Aku harus menerima baptisan, dan betapakah susahnya hati-Ku, sebelum hal itu berlangsung!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 51, 'Kamu menyangka, bahwa Aku datang untuk membawa damai di atas bumi? Bukan, kata-Ku kepadamu, bukan damai, melainkan pertentangan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 52, 'Karena mulai dari sekarang akan ada pertentangan antara lima orang di dalam satu rumah, tiga melawan dua dan dua melawan tiga.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 53, 'Mereka akan saling bertentangan, ayah melawan anaknya laki-laki dan anak laki-laki melawan ayahnya, ibu melawan anaknya perempuan, dan anak perempuan melawan ibunya, ibu mertua melawan menantunya perempuan dan menantu perempuan melawan ibu mertuanya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 54, 'Yesus berkata pula kepada orang banyak: "Apabila kamu melihat awan naik di sebelah barat, segera kamu berkata: Akan datang hujan, dan hal itu memang terjadi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 55, 'Dan apabila kamu melihat angin selatan bertiup, kamu berkata: Hari akan panas terik, dan hal itu memang terjadi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 56, 'Hai orang-orang munafik, rupa bumi dan langit kamu tahu menilainya, mengapakah kamu tidak dapat menilai zaman ini?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 57, 'Dan mengapakah engkau juga tidak memutuskan sendiri apa yang benar?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 58, 'Sebab, jikalau engkau dengan lawanmu pergi menghadap pemerintah, berusahalah berdamai dengan dia selama di tengah jalan, supaya jangan engkau diseretnya kepada hakim dan hakim menyerahkan engkau kepada pembantunya dan pembantu itu melemparkan engkau ke dalam penjara.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 12, 59, 'Aku berkata kepadamu: Engkau tidak akan keluar dari sana, sebelum engkau membayar hutangmu sampai lunas."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 1, 'Pada waktu itu datanglah kepada Yesus beberapa orang membawa kabar tentang orang-orang Galilea, yang darahnya dicampurkan Pilatus dengan darah korban yang mereka persembahkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 2, 'Yesus menjawab mereka: "Sangkamu orang-orang Galilea ini lebih besar dosanya dari pada dosa semua orang Galilea yang lain, karena mereka mengalami nasib itu?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 3, 'Tidak! kata-Ku kepadamu. Tetapi jikalau kamu tidak bertobat, kamu semua akan binasa atas cara demikian.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 4, 'Atau sangkamu kedelapan belas orang, yang mati ditimpa menara dekat Siloam, lebih besar kesalahannya dari pada kesalahan semua orang lain yang diam di Yerusalem?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 5, 'Tidak! kata-Ku kepadamu. Tetapi jikalau kamu tidak bertobat, kamu semua akan binasa atas cara demikian."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 6, 'Lalu Yesus mengatakan perumpamaan ini: "Seorang mempunyai pohon ara yang tumbuh di kebun anggurnya, dan ia datang untuk mencari buah pada pohon itu, tetapi ia tidak menemukannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 7, 'Lalu ia berkata kepada pengurus kebun anggur itu: Sudah tiga tahun aku datang mencari buah pada pohon ara ini dan aku tidak menemukannya. Tebanglah pohon ini! Untuk apa ia hidup di tanah ini dengan percuma!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 8, 'Jawab orang itu: Tuan, biarkanlah dia tumbuh tahun ini lagi, aku akan mencangkul tanah sekelilingnya dan memberi pupuk kepadanya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 9, 'mungkin tahun depan ia berbuah; jika tidak, tebanglah dia!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 10, 'Pada suatu kali Yesus sedang mengajar dalam salah satu rumah ibadat pada hari Sabat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 11, 'Di situ ada seorang perempuan yang telah delapan belas tahun dirasuk roh sehingga ia sakit sampai bungkuk punggungnya dan tidak dapat berdiri lagi dengan tegak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 12, 'Ketika Yesus melihat perempuan itu, Ia memanggil dia dan berkata kepadanya: "Hai ibu, penyakitmu telah sembuh."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 13, 'Lalu Ia meletakkan tangan-Nya atas perempuan itu, dan seketika itu juga berdirilah perempuan itu, dan memuliakan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 14, 'Tetapi kepala rumah ibadat gusar karena Yesus menyembuhkan orang pada hari Sabat, lalu ia berkata kepada orang banyak: "Ada enam hari untuk bekerja. Karena itu datanglah pada salah satu hari itu untuk disembuhkan dan jangan pada hari Sabat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 15, 'Tetapi Tuhan menjawab dia, kata-Nya: "Hai orang-orang munafik, bukankah setiap orang di antaramu melepaskan lembunya atau keledainya pada hari Sabat dari kandangnya dan membawanya ke tempat minuman?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 16, 'Bukankah perempuan ini, yang sudah delapan belas tahun diikat oleh Iblis, harus dilepaskan dari ikatannya itu, karena ia adalah keturunan Abraham?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 17, 'Dan waktu Ia berkata demikian, semua lawan-Nya merasa malu dan semua orang banyak bersukacita karena segala perkara mulia, yang telah dilakukan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 18, 'Maka kata Yesus: "Seumpama apakah hal Kerajaan Allah dan dengan apakah Aku akan mengumpamakannya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 19, 'Ia seumpama biji sesawi, yang diambil dan ditaburkan orang di kebunnya; biji itu tumbuh dan menjadi pohon dan burung-burung di udara bersarang pada cabang-cabangnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 20, 'Dan Ia berkata lagi: "Dengan apakah Aku akan mengumpamakan Kerajaan Allah?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 21, 'Ia seumpama ragi yang diambil seorang perempuan dan diadukkan ke dalam tepung terigu tiga sukat sampai khamir seluruhnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 22, 'Kemudian Yesus berjalan keliling dari kota ke kota dan dari desa ke desa sambil mengajar dan meneruskan perjalanan-Nya ke Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 23, 'Dan ada seorang yang berkata kepada-Nya: "Tuhan, sedikit sajakah orang yang diselamatkan?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 24, 'Jawab Yesus kepada orang-orang di situ: "Berjuanglah untuk masuk melalui pintu yang sesak itu! Sebab Aku berkata kepadamu: Banyak orang akan berusaha untuk masuk, tetapi tidak akan dapat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 25, 'Jika tuan rumah telah bangkit dan telah menutup pintu, kamu akan berdiri di luar dan mengetok-ngetok pintu sambil berkata: Tuan, bukakanlah kami pintu! dan Ia akan menjawab dan berkata kepadamu: Aku tidak tahu dari mana kamu datang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 26, 'Maka kamu akan berkata: Kami telah makan dan minum di hadapan-Mu dan Engkau telah mengajar di jalan-jalan kota kami.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 27, 'Tetapi Ia akan berkata kepadamu: Aku tidak tahu dari mana kamu datang, enyahlah dari hadapan-Ku, hai kamu sekalian yang melakukan kejahatan!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 28, 'Di sanalah akan terdapat ratap dan kertak gigi, apabila kamu akan melihat Abraham dan Ishak dan Yakub dan semua nabi di dalam Kerajaan Allah, tetapi kamu sendiri dicampakkan ke luar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 29, 'Dan orang akan datang dari Timur dan Barat dan dari Utara dan Selatan dan mereka akan duduk makan di dalam Kerajaan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 30, 'Dan sesungguhnya ada orang yang terakhir yang akan menjadi orang yang terdahulu dan ada orang yang terdahulu yang akan menjadi orang yang terakhir."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 31, 'Pada waktu itu datanglah beberapa orang Farisi dan berkata kepada Yesus: "Pergilah, tinggalkanlah tempat ini, karena Herodes hendak membunuh Engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 32, 'Jawab Yesus kepada mereka: "Pergilah dan katakanlah kepada si serigala itu: Aku mengusir setan dan menyembuhkan orang, pada hari ini dan besok, dan pada hari yang ketiga Aku akan selesai.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 33, 'Tetapi hari ini dan besok dan lusa Aku harus meneruskan perjalanan-Ku, sebab tidaklah semestinya seorang nabi dibunuh kalau tidak di Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 34, 'Yerusalem, Yerusalem, engkau yang membunuh nabi-nabi dan melempari dengan batu orang-orang yang diutus kepadamu! Berkali-kali Aku rindu mengumpulkan anak-anakmu, sama seperti induk ayam mengumpulkan anak-anaknya di bawah sayapnya, tetapi kamu tidak mau.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 13, 35, 'Sesungguhnya rumahmu ini akan ditinggalkan dan menjadi sunyi. Tetapi Aku berkata kepadamu: Kamu tidak akan melihat Aku lagi hingga pada saat kamu berkata: Diberkatilah Dia yang datang dalam nama Tuhan!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 1, 'Pada suatu hari Sabat Yesus datang ke rumah salah seorang pemimpin dari orang-orang Farisi untuk makan di situ. Semua yang hadir mengamat-amati Dia dengan saksama.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 2, 'Tiba-tiba datanglah seorang yang sakit busung air berdiri di hadapan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 3, 'Lalu Yesus berkata kepada ahli-ahli Taurat dan orang-orang Farisi itu, kata-Nya: "Diperbolehkankah menyembuhkan orang pada hari Sabat atau tidak?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 4, 'Mereka itu diam semuanya. Lalu Ia memegang tangan orang sakit itu dan menyembuhkannya dan menyuruhnya pergi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 5, 'Kemudian Ia berkata kepada mereka: "Siapakah di antara kamu yang tidak segera menarik ke luar anaknya atau lembunya kalau terperosok ke dalam sebuah sumur, meskipun pada hari Sabat?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 6, 'Mereka tidak sanggup membantah-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 7, 'Karena Yesus melihat, bahwa tamu-tamu berusaha menduduki tempat-tempat kehormatan, Ia mengatakan perumpamaan ini kepada mereka:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 8, '"Kalau seorang mengundang engkau ke pesta perkawinan, janganlah duduk di tempat kehormatan, sebab mungkin orang itu telah mengundang seorang yang lebih terhormat dari padamu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 9, 'supaya orang itu, yang mengundang engkau dan dia, jangan datang dan berkata kepadamu: Berilah tempat ini kepada orang itu. Lalu engkau dengan malu harus pergi duduk di tempat yang paling rendah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 10, 'Tetapi, apabila engkau diundang, pergilah duduk di tempat yang paling rendah. Mungkin tuan rumah akan datang dan berkata kepadamu: Sahabat, silakan duduk di depan. Dan dengan demikian engkau akan menerima hormat di depan mata semua tamu yang lain.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 11, 'Sebab barangsiapa meninggikan diri, ia akan direndahkan dan barangsiapa merendahkan diri, ia akan ditinggikan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 12, 'Dan Yesus berkata juga kepada orang yang mengundang Dia: "Apabila engkau mengadakan perjamuan siang atau perjamuan malam, janganlah engkau mengundang sahabat-sahabatmu atau saudara-saudaramu atau kaum keluargamu atau tetangga-tetanggamu yang kaya, karena mereka akan membalasnya dengan mengundang engkau pula dan dengan demikian engkau mendapat balasnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 13, 'Tetapi apabila engkau mengadakan perjamuan, undanglah orang-orang miskin, orang-orang cacat, orang-orang lumpuh dan orang-orang buta.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 14, 'Dan engkau akan berbahagia, karena mereka tidak mempunyai apa-apa untuk membalasnya kepadamu. Sebab engkau akan mendapat balasnya pada hari kebangkitan orang-orang benar."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 15, 'Mendengar itu berkatalah seorang dari tamu-tamu itu kepada Yesus: "Berbahagialah orang yang akan dijamu dalam Kerajaan Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 16, 'Tetapi Yesus berkata kepadanya: "Ada seorang mengadakan perjamuan besar dan ia mengundang banyak orang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 17, 'Menjelang perjamuan itu dimulai, ia menyuruh hambanya mengatakan kepada para undangan: Marilah, sebab segala sesuatu sudah siap.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 18, 'Tetapi mereka bersama-sama meminta maaf. Yang pertama berkata kepadanya: Aku telah membeli ladang dan aku harus pergi melihatnya; aku minta dimaafkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 19, 'Yang lain berkata: Aku telah membeli lima pasang lembu kebiri dan aku harus pergi mencobanya; aku minta dimaafkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 20, 'Yang lain lagi berkata: Aku baru kawin dan karena itu aku tidak dapat datang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 21, 'Maka kembalilah hamba itu dan menyampaikan semuanya itu kepada tuannya. Lalu murkalah tuan rumah itu dan berkata kepada hambanya: Pergilah dengan segera ke segala jalan dan lorong kota dan bawalah ke mari orang-orang miskin dan orang-orang cacat dan orang-orang buta dan orang-orang lumpuh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 22, 'Kemudian hamba itu melaporkan: Tuan, apa yang tuan perintahkan itu sudah dilaksanakan, tetapi sekalipun demikian masih ada tempat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 23, 'Lalu kata tuan itu kepada hambanya: Pergilah ke semua jalan dan lintasan dan paksalah orang-orang, yang ada di situ, masuk, karena rumahku harus penuh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 24, 'Sebab Aku berkata kepadamu: Tidak ada seorangpun dari orang-orang yang telah diundang itu akan menikmati jamuan-Ku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 25, 'Pada suatu kali banyak orang berduyun-duyun mengikuti Yesus dalam perjalanan-Nya. Sambil berpaling Ia berkata kepada mereka:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 26, '"Jikalau seorang datang kepada-Ku dan ia tidak membenci bapanya, ibunya, isterinya, anak-anaknya, saudara-saudaranya laki-laki atau perempuan, bahkan nyawanya sendiri, ia tidak dapat menjadi murid-Ku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 27, 'Barangsiapa tidak memikul salibnya dan mengikut Aku, ia tidak dapat menjadi murid-Ku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 28, 'Sebab siapakah di antara kamu yang kalau mau mendirikan sebuah menara tidak duduk dahulu membuat anggaran biayanya, kalau-kalau cukup uangnya untuk menyelesaikan pekerjaan itu?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 29, 'Supaya jikalau ia sudah meletakkan dasarnya dan tidak dapat menyelesaikannya, jangan-jangan semua orang yang melihatnya, mengejek dia,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 30, 'sambil berkata: Orang itu mulai mendirikan, tetapi ia tidak sanggup menyelesaikannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 31, 'Atau, raja manakah yang kalau mau pergi berperang melawan raja lain tidak duduk dahulu untuk mempertimbangkan, apakah dengan sepuluh ribu orang ia sanggup menghadapi lawan yang mendatanginya dengan dua puluh ribu orang?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 32, 'Jikalau tidak, ia akan mengirim utusan selama musuh itu masih jauh untuk menanyakan syarat-syarat perdamaian.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 33, 'Demikian pulalah tiap-tiap orang di antara kamu, yang tidak melepaskan dirinya dari segala miliknya, tidak dapat menjadi murid-Ku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 34, 'Garam memang baik, tetapi jika garam juga menjadi tawar, dengan apakah ia diasinkan?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 14, 35, 'Tidak ada lagi gunanya baik untuk ladang maupun untuk pupuk, dan orang membuangnya saja. Siapa mempunyai telinga untuk mendengar, hendaklah ia mendengar!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 1, 'Para pemungut cukai dan orang-orang berdosa biasanya datang kepada Yesus untuk mendengarkan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 2, 'Maka bersungut-sungutlah orang-orang Farisi dan ahli-ahli Taurat, katanya: "Ia menerima orang-orang berdosa dan makan bersama-sama dengan mereka."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 3, 'Lalu Ia mengatakan perumpamaan ini kepada mereka:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 4, '"Siapakah di antara kamu yang mempunyai seratus ekor domba, dan jikalau ia kehilangan seekor di antaranya, tidak meninggalkan yang sembilan puluh sembilan ekor di padang gurun dan pergi mencari yang sesat itu sampai ia menemukannya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 5, 'Dan kalau ia telah menemukannya, ia meletakkannya di atas bahunya dengan gembira,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 6, 'dan setibanya di rumah ia memanggil sahabat-sahabat dan tetangga-tetanggan serta berkata kepada mereka: Bersukacitalah bersama-sama dengan aku, sebab dombaku yang hilang itu telah kutemukan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 7, 'Aku berkata kepadamu: Demikian juga akan ada sukacita di sorga karena satu orang berdosa yang bertobat, lebih dari pada sukacita karena sembilan puluh sembilan orang benar yang tidak memerlukan pertobatan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 8, '"Atau perempuan manakah yang mempunyai sepuluh dirham, dan jika ia kehilangan satu di antaranya, tidak menyalakan pelita dan menyapu rumah serta mencarinya dengan cermat sampai ia menemukannya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 9, 'Dan kalau ia telah menemukannya, ia memanggil sahabat-sahabat dan tetangga-tetangganya serta berkata: Bersukacitalah bersama-sama dengan aku, sebab dirhamku yang hilang itu telah kutemukan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 10, 'Aku berkata kepadamu: Demikian juga akan ada sukacita pada malaikat-malaikat Allah karena satu orang berdosa yang bertobat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 11, 'Yesus berkata lagi: "Ada seorang mempunyai dua anak laki-laki.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 12, 'Kata yang bungsu kepada ayahnya: Bapa, berikanlah kepadaku bagian harta milik kita yang menjadi hakku. Lalu ayahnya membagi-bagikan harta kekayaan itu di antara mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 13, 'Beberapa hari kemudian anak bungsu itu menjual seluruh bagiannya itu lalu pergi ke negeri yang jauh. Di sana ia memboroskan harta miliknya itu dengan hidup berfoya-foya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 14, 'Setelah dihabiskannya semuanya, timbullah bencana kelaparan di dalam negeri itu dan iapun mulai melarat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 15, 'Lalu ia pergi dan bekerja pada seorang majikan di negeri itu. Orang itu menyuruhnya ke ladang untuk menjaga babinya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 16, 'Lalu ia ingin mengisi perutnya dengan ampas yang menjadi makanan babi itu, tetapi tidak seorangpun yang memberikannya kepadanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 17, 'Lalu ia menyadari keadaannya, katanya: Betapa banyaknya orang upahan bapaku yang berlimpah-limpah makanannya, tetapi aku di sini mati kelaparan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 18, 'Aku akan bangkit dan pergi kepada bapaku dan berkata kepadanya: Bapa, aku telah berdosa terhadap sorga dan terhadap bapa,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 19, 'aku tidak layak lagi disebutkan anak bapa; jadikanlah aku sebagai salah seorang upahan bapa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 20, 'Maka bangkitlah ia dan pergi kepada bapanya. Ketika ia masih jauh, ayahnya telah melihatnya, lalu tergeraklah hatinya oleh belas kasihan. Ayahnya itu berlari mendapatkan dia lalu merangkul dan mencium dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 21, 'Kata anak itu kepadanya: Bapa, aku telah berdosa terhadap sorga dan terhadap bapa, aku tidak layak lagi disebutkan anak bapa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 22, 'Tetapi ayah itu berkata kepada hamba-hambanya: Lekaslah bawa ke mari jubah yang terbaik, pakaikanlah itu kepadanya dan kenakanlah cincin pada jarinya dan sepatu pada kakinya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 23, 'Dan ambillah anak lembu tambun itu, sembelihlah dia dan marilah kita makan dan bersukacita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 24, 'Sebab anakku ini telah mati dan menjadi hidup kembali, ia telah hilang dan didapat kembali. Maka mulailah mereka bersukaria.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 25, 'Tetapi anaknya yang sulung berada di ladang dan ketika ia pulang dan dekat ke rumah, ia mendengar bunyi seruling dan nyanyian tari-tarian.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 26, 'Lalu ia memanggil salah seorang hamba dan bertanya kepadanya apa arti semuanya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 27, 'Jawab hamba itu: Adikmu telah kembali dan ayahmu telah menyembelih anak lembu tambun, karena ia mendapatnya kembali dengan sehat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 28, 'Maka marahlah anak sulung itu dan ia tidak mau masuk. Lalu ayahnya keluar dan berbicara dengan dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 29, 'Tetapi ia menjawab ayahnya, katanya: Telah bertahun-tahun aku melayani bapa dan belum pernah aku melanggar perintah bapa, tetapi kepadaku belum pernah bapa memberikan seekor anak kambing untuk bersukacita dengan sahabat-sahabatku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 30, 'Tetapi baru saja datang anak bapa yang telah memboroskan harta kekayaan bapa bersama-sama dengan pelacur-pelacur, maka bapa menyembelih anak lembu tambun itu untuk dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 31, 'Kata ayahnya kepadanya: Anakku, engkau selalu bersama-sama dengan aku, dan segala kepunyaanku adalah kepunyaanmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 15, 32, 'Kita patut bersukacita dan bergembira karena adikmu telah mati dan menjadi hidup kembali, ia telah hilang dan didapat kembali."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 1, 'Dan Yesus berkata kepada murid-murid-Nya: "Ada seorang kaya yang mempunyai seorang bendahara. Kepadanya disampaikan tuduhan, bahwa bendahara itu menghamburkan miliknya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 2, 'Lalu ia memanggil bendahara itu dan berkata kepadanya: Apakah yang kudengar tentang engkau? Berilah pertanggungan jawab atas urusanmu, sebab engkau tidak boleh lagi bekerja sebagai bendahara.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 3, 'Kata bendahara itu di dalam hatinya: Apakah yang harus aku perbuat? Tuanku memecat aku dari jabatanku sebagai bendahara. Mencangkul aku tidak dapat, mengemis aku malu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 4, 'Aku tahu apa yang akan aku perbuat, supaya apabila aku dipecat dari jabatanku sebagai bendahara, ada orang yang akan menampung aku di rumah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 5, 'Lalu ia memanggil seorang demi seorang yang berhutang kepada tuannya. Katanya kepada yang pertama: Berapakah hutangmu kepada tuanku?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 6, 'Jawab orang itu: Seratus tempayan minyak. Lalu katanya kepada orang itu: Inilah surat hutangmu, duduklah dan buat surat hutang lain sekarang juga: Lima puluh tempayan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 7, 'Kemudian ia berkata kepada yang kedua: Dan berapakah hutangmu? Jawab orang itu: Seratus pikul gandum. Katanya kepada orang itu: Inilah surat hutangmu, buatlah surat hutang lain: Delapan puluh pikul.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 8, 'Lalu tuan itu memuji bendahara yang tidak jujur itu, karena ia telah bertindak dengan cerdik. Sebab anak-anak dunia ini lebih cerdik terhadap sesamanya dari pada anak-anak terang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 9, 'Dan Aku berkata kepadamu: Ikatlah persahabatan dengan mempergunakan Mamon yang tidak jujur, supaya jika Mamon itu tidak dapat menolong lagi, kamu diterima di dalam kemah abadi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 10, '"Barangsiapa setia dalam perkara-perkara kecil, ia setia juga dalam perkara-perkara besar. Dan barangsiapa tidak benar dalam perkara-perkara kecil, ia tidak benar juga dalam perkara-perkara besar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 11, 'Jadi, jikalau kamu tidak setia dalam hal Mamon yang tidak jujur, siapakah yang akan mempercayakan kepadamu harta yang sesungguhnya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 12, 'Dan jikalau kamu tidak setia dalam harta orang lain, siapakah yang akan menyerahkan hartamu sendiri kepadamu?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 13, 'Seorang hamba tidak dapat mengabdi kepada dua tuan. Karena jika demikian ia akan membenci yang seorang dan mengasihi yang lain, atau ia akan setia kepada yang seorang dan tidak mengindahkan yang lain. Kamu tidak dapat mengabdi kepada Allah dan kepada Mamon."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 14, 'Semuanya itu didengar oleh orang-orang Farisi, hamba-hamba uang itu, dan mereka mencemoohkan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 15, 'Lalu Ia berkata kepada mereka: "Kamu membenarkan diri di hadapan orang, tetapi Allah mengetahui hatimu. Sebab apa yang dikagumi manusia, dibenci oleh Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 16, 'Hukum Taurat dan kitab para nabi berlaku sampai kepada zaman Yohanes; dan sejak waktu itu Kerajaan Allah diberitakan dan setiap orang menggagahinya berebut memasukinya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 17, 'Lebih mudah langit dan bumi lenyap dari pada satu titik dari hukum Taurat batal.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 18, 'Setiap orang yang menceraikan isterinya, lalu kawin dengan perempuan lain, ia berbuat zinah; dan barangsiapa kawin dengan perempuan yang diceraikan suaminya, ia berbuat zinah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 19, '"Ada seorang kaya yang selalu berpakaian jubah ungu dan kain halus, dan setiap hari ia bersukaria dalam kemewahan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 20, 'Dan ada seorang pengemis bernama Lazarus, badannya penuh dengan borok, berbaring dekat pintu rumah orang kaya itu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 21, 'dan ingin menghilangkan laparnya dengan apa yang jatuh dari meja orang kaya itu. Malahan anjing-anjing datang dan menjilat boroknya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 22, 'Kemudian matilah orang miskin itu, lalu dibawa oleh malaikat-malaikat ke pangkuan Abraham.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 23, 'Orang kaya itu juga mati, lalu dikubur. Dan sementara ia menderita sengsara di alam maut ia memandang ke atas, dan dari jauh dilihatnya Abraham, dan Lazarus duduk di pangkuannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 24, 'Lalu ia berseru, katanya: Bapa Abraham, kasihanilah aku. Suruhlah Lazarus, supaya ia mencelupkan ujung jarinya ke dalam air dan menyejukkan lidahku, sebab aku sangat kesakitan dalam nyala api ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 25, 'Tetapi Abraham berkata: Anak, ingatlah, bahwa engkau telah menerima segala yang baik sewaktu hidupmu, sedangkan Lazarus segala yang buruk. Sekarang ia mendapat hiburan dan engkau sangat menderita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 26, 'Selain dari pada itu di antara kami dan engkau terbentang jurang yang tak terseberangi, supaya mereka yang mau pergi dari sini kepadamu ataupun mereka yang mau datang dari situ kepada kami tidak dapat menyeberang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 27, 'Kata orang itu: Kalau demikian, aku minta kepadamu, bapa, supaya engkau menyuruh dia ke rumah ayahku,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 28, 'sebab masih ada lima orang saudaraku, supaya ia memperingati mereka dengan sungguh-sungguh, agar mereka jangan masuk kelak ke dalam tempat penderitaan ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 29, 'Tetapi kata Abraham: Ada pada mereka kesaksian Musa dan para nabi; baiklah mereka mendengarkan kesaksian itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 30, 'Jawab orang itu: Tidak, bapa Abraham, tetapi jika ada seorang yang datang dari antara orang mati kepada mereka, mereka akan bertobat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 16, 31, 'Kata Abraham kepadanya: Jika mereka tidak mendengarkan kesaksian Musa dan para nabi, mereka tidak juga akan mau diyakinkan, sekalipun oleh seorang yang bangkit dari antara orang mati."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 1, 'Yesus berkata kepada murid-murid-Nya: "Tidak mungkin tidak akan ada penyesatan, tetapi celakalah orang yang mengadakannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 2, 'Adalah lebih baik baginya jika sebuah batu kilangan diikatkan pada lehernya, lalu ia dilemparkan ke dalam laut, dari pada menyesatkan salah satu dari orang-orang yang lemah ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 3, 'Jagalah dirimu! Jikalau saudaramu berbuat dosa, tegorlah dia, dan jikalau ia menyesal, ampunilah dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 4, 'Bahkan jikalau ia berbuat dosa terhadap engkau tujuh kali sehari dan tujuh kali ia kembali kepadamu dan berkata: Aku menyesal, engkau harus mengampuni dia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 5, 'Lalu kata rasul-rasul itu kepada Tuhan: "Tambahkanlah iman kami!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 6, 'Jawab Tuhan: "Kalau sekiranya kamu mempunyai iman sebesar biji sesawi saja, kamu dapat berkata kepada pohon ara ini: Terbantunlah engkau dan tertanamlah di dalam laut, dan ia akan taat kepadamu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 7, '"Siapa di antara kamu yang mempunyai seorang hamba yang membajak atau menggembalakan ternak baginya, akan berkata kepada hamba itu, setelah ia pulang dari ladang: Mari segera makan!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 8, 'Bukankah sebaliknya ia akan berkata kepada hamba itu: Sediakanlah makananku. Ikatlah pinggangmu dan layanilah aku sampai selesai aku makan dan minum. Dan sesudah itu engkau boleh makan dan minum.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 9, 'Adakah ia berterima kasih kepada hamba itu, karena hamba itu telah melakukan apa yang ditugaskan kepadanya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 10, 'Demikian jugalah kamu. Apabila kamu telah melakukan segala sesuatu yang ditugaskan kepadamu, hendaklah kamu berkata: Kami adalah hamba-hamba yang tidak berguna; kami hanya melakukan apa yang kami harus lakukan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 11, 'Dalam perjalanan-Nya ke Yerusalem Yesus menyusur perbatasan Samaria dan Galilea.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 12, 'Ketika Ia memasuki suatu desa datanglah sepuluh orang kusta menemui Dia. Mereka tinggal berdiri agak jauh', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 13, 'dan berteriak: "Yesus, Guru, kasihanilah kami!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 14, 'Lalu Ia memandang mereka dan berkata: "Pergilah, perlihatkanlah dirimu kepada imam-imam." Dan sementara mereka di tengah jalan mereka menjadi tahir.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 15, 'Seorang dari mereka, ketika melihat bahwa ia telah sembuh, kembali sambil memuliakan Allah dengan suara nyaring,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 16, 'lalu tersungkur di depan kaki Yesus dan mengucap syukur kepada-Nya. Orang itu adalah seorang Samaria.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 17, 'Lalu Yesus berkata: "Bukankah kesepuluh orang tadi semuanya telah menjadi tahir? Di manakah yang sembilan orang itu?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 18, 'Tidak adakah di antara mereka yang kembali untuk memuliakan Allah selain dari pada orang asing ini?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 19, 'Lalu Ia berkata kepada orang itu: "Berdirilah dan pergilah, imanmu telah menyelamatkan engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 20, 'Atas pertanyaan orang-orang Farisi, apabila Kerajaan Allah akan datang, Yesus menjawab, kata-Nya: "Kerajaan Allah datang tanpa tanda-tanda lahiriah,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 21, 'juga orang tidak dapat mengatakan: Lihat, ia ada di sini atau ia ada di sana! Sebab sesungguhnya Kerajaan Allah ada di antara kamu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 22, 'Dan Ia berkata kepada murid-murid-Nya: "Akan datang waktunya kamu ingin melihat satu dari pada hari-hari Anak Manusia itu dan kamu tidak akan melihatnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 23, 'Dan orang akan berkata kepadamu: Lihat, ia ada di sana; lihat, ia ada di sini! Jangan kamu pergi ke situ, jangan kamu ikut.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 24, 'Sebab sama seperti kilat memancar dari ujung langit yang satu ke ujung langit yang lain, demikian pulalah kelak halnya Anak Manusia pada hari kedatangan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 25, 'Tetapi Ia harus menanggung banyak penderitaan dahulu dan ditolak oleh angkatan ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 26, 'Dan sama seperti terjadi pada zaman Nuh, demikian pulalah halnya kelak pada hari-hari Anak Manusia:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 27, 'mereka makan dan minum, mereka kawin dan dikawinkan, sampai kepada hari Nuh masuk ke dalam bahtera, lalu datanglah air bah dan membinasakan mereka semua.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 28, 'Demikian juga seperti yang terjadi di zaman Lot: mereka makan dan minum, mereka membeli dan menjual, mereka menanam dan membangun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 29, 'Tetapi pada hari Lot pergi keluar dari Sodom turunlah hujan api dan hujan belerang dari langit dan membinasakan mereka semua.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 30, 'Demikianlah halnya kelak pada hari, di mana Anak Manusia menyatakan diri-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 31, 'Barangsiapa pada hari itu sedang di peranginan di atas rumah dan barang-barangnya ada di dalam rumah, janganlah ia turun untuk mengambilnya, dan demikian juga orang yang sedang di ladang, janganlah ia kembali.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 32, 'Ingatlah akan isteri Lot!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 33, 'Barangsiapa berusaha memelihara nyawanya, ia akan kehilangan nyawanya, dan barangsiapa kehilangan nyawanya, ia akan menyelamatkannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 34, 'Aku berkata kepadamu: Pada malam itu ada dua orang di atas satu tempat tidur, yang seorang akan dibawa dan yang lain akan ditinggalkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 35, 'Ada dua orang perempuan bersama-sama mengilang, yang seorang akan dibawa dan yang lain akan ditinggalkan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 36, '(Kalau ada dua orang di ladang, yang seorang akan dibawa dan yang lain akan ditinggalkan.)', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 17, 37, 'Kata mereka kepada Yesus: "Di mana, Tuhan?" Kata-Nya kepada mereka: "Di mana ada mayat, di situ berkerumun burung nasar."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 1, 'Yesus mengatakan suatu perumpamaan kepada mereka untuk menegaskan, bahwa mereka harus selalu berdoa dengan tidak jemu-jemu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 2, 'Kata-Nya: "Dalam sebuah kota ada seorang hakim yang tidak takut akan Allah dan tidak menghormati seorangpun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 3, 'Dan di kota itu ada seorang janda yang selalu datang kepada hakim itu dan berkata: Belalah hakku terhadap lawanku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 4, 'Beberapa waktu lamanya hakim itu menolak. Tetapi kemudian ia berkata dalam hatinya: Walaupun aku tidak takut akan Allah dan tidak menghormati seorangpun,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 5, 'namun karena janda ini menyusahkan aku, baiklah aku membenarkan dia, supaya jangan terus saja ia datang dan akhirnya menyerang aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 6, 'Kata Tuhan: "Camkanlah apa yang dikatakan hakim yang lalim itu!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 7, 'Tidakkah Allah akan membenarkan orang-orang pilihan-Nya yang siang malam berseru kepada-Nya? Dan adakah Ia mengulur-ulur waktu sebelum menolong mereka?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 8, 'Aku berkata kepadamu: Ia akan segera membenarkan mereka. Akan tetapi, jika Anak Manusia itu datang, adakah Ia mendapati iman di bumi?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 9, 'Dan kepada beberapa orang yang menganggap dirinya benar dan memandang rendah semua orang lain, Yesus mengatakan perumpamaan ini:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 10, '"Ada dua orang pergi ke Bait Allah untuk berdoa; yang seorang adalah Farisi dan yang lain pemungut cukai.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 11, 'Orang Farisi itu berdiri dan berdoa dalam hatinya begini: Ya Allah, aku mengucap syukur kepada-Mu, karena aku tidak sama seperti semua orang lain, bukan perampok, bukan orang lalim, bukan pezinah dan bukan juga seperti pemungut cukai ini;', 'id', 'TB')
